def test_structured_pruning_decomposed_rms_norm_wrong_div_numerator_is_declined():
    # Div's own first operand must be confirmed a genuine constant scalar 1.0
    # (`Div`'s own schema is non-commutative, `X / Y` -- inv_std = 1.0 / std)
    # -- any other numerator (here 2.0) computes a different value than
    # RMSNorm's own reciprocal-std, and is declined the same conservative way.
    K, C, Out = 8, 16, 4
    rng = np.random.default_rng(344)
    w1 = rng.standard_normal((K, C)).astype(np.float32)
    weight = rng.standard_normal((C,)).astype(np.float32)
    w2 = rng.standard_normal((C, Out)).astype(np.float32)
    initializer = [
        _f32(w1, "W1"),
        onnx.numpy_helper.from_array(np.array(2.0, dtype=np.float32), "Two"),
        onnx.numpy_helper.from_array(np.array(1e-5, dtype=np.float32), "Eps"),
        onnx.numpy_helper.from_array(np.array(2.0, dtype=np.float32), "NotOne"),
        _f32(weight, "Weight"),
        _f32(w2, "W2"),
    ]
    model = _model(
        f"""
        g (float[batch,{K}] X) => (float[batch,{Out}] Y)
        {{
          x = MatMul(X, W1)
          variance = Pow(x, Two)
          meanvar = ReduceMean<axes=[-1]>(variance)
          vareps = Add(meanvar, Eps)
          std = Sqrt(vareps)
          invstd = Div(NotOne, std)
          scaled = Mul(x, invstd)
          h = Mul(scaled, Weight)
          Y = MatMul(h, W2)
        }}
        """,
        initializer=initializer,
        opset=17,
    )
    onnx.checker.check_model(model)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    assert pruned.SerializeToString() == model.SerializeToString()


def test_structured_pruning_decomposed_rms_norm_non_constant_weight_is_declined():
    # The final Mul's own `weight` operand must be a genuine constant
    # per-channel initializer -- a runtime-computed (graph-input-fed) operand
    # is declined the same conservative way as a missing/non-constant
    # `gamma`/`beta` on the LayerNorm decomposition.
    K, C, Out = 8, 16, 4
    rng = np.random.default_rng(345)
    w1 = rng.standard_normal((K, C)).astype(np.float32)
    w2 = rng.standard_normal((C, Out)).astype(np.float32)
    initializer = [
        _f32(w1, "W1"),
        onnx.numpy_helper.from_array(np.array(2.0, dtype=np.float32), "Two"),
        onnx.numpy_helper.from_array(np.array(1e-5, dtype=np.float32), "Eps"),
        onnx.numpy_helper.from_array(np.array(1.0, dtype=np.float32), "One"),
        _f32(w2, "W2"),
    ]
    model = _model(
        f"""
        g (float[batch,{K}] X, float[{C}] Weight) => (float[batch,{Out}] Y)
        {{
          x = MatMul(X, W1)
          variance = Pow(x, Two)
          meanvar = ReduceMean<axes=[-1]>(variance)
          vareps = Add(meanvar, Eps)
          std = Sqrt(vareps)
          invstd = Div(One, std)
          scaled = Mul(x, invstd)
          h = Mul(scaled, Weight)
          Y = MatMul(h, W2)
        }}
        """,
        initializer=initializer,
        opset=17,
    )
    onnx.checker.check_model(model)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    assert pruned.SerializeToString() == model.SerializeToString()


def test_structured_pruning_decomposed_rms_norm_inv_std_and_x_feed_different_muls_is_declined():
    # `x` (the decomposition's own root) must be read by exactly one `Pow`
    # and one `Mul`, and `inv_std` must feed *that exact same* `Mul` node --
    # here `x`'s own second reader (`combine`) multiplies it by an unrelated
    # constant instead of `invstd`, while `invstd` itself feeds a *different*
    # Mul (`stray`, kept alive via a second graph output) -- not the shape
    # this hop recognizes, so the chain must be left completely untouched,
    # never partially matched.
    K, C, Out = 8, 16, 4
    rng = np.random.default_rng(346)
    w1 = rng.standard_normal((K, C)).astype(np.float32)
    weight = rng.standard_normal((C,)).astype(np.float32)
    w2 = rng.standard_normal((C, Out)).astype(np.float32)
    other = rng.standard_normal((C,)).astype(np.float32)
    other2 = rng.standard_normal((C,)).astype(np.float32)
    initializer = [
        _f32(w1, "W1"),
        onnx.numpy_helper.from_array(np.array(2.0, dtype=np.float32), "Two"),
        onnx.numpy_helper.from_array(np.array(1e-5, dtype=np.float32), "Eps"),
        onnx.numpy_helper.from_array(np.array(1.0, dtype=np.float32), "One"),
        _f32(weight, "Weight"),
        _f32(other, "Other"),
        _f32(other2, "Other2"),
        _f32(w2, "W2"),
    ]
    model = _model(
        f"""
        g (float[batch,{K}] X) => (float[batch,{Out}] Y, float[batch,{C}] Extra)
        {{
          x = MatMul(X, W1)
          variance = Pow(x, Two)
          meanvar = ReduceMean<axes=[-1]>(variance)
          vareps = Add(meanvar, Eps)
          std = Sqrt(vareps)
          invstd = Div(One, std)
          combine = Mul(x, Other)
          stray = Mul(invstd, Other2)
          Extra = Identity(stray)
          h = Mul(combine, Weight)
          Y = MatMul(h, W2)
        }}
        """,
        initializer=initializer,
        opset=17,
    )
    onnx.checker.check_model(model)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    assert pruned.SerializeToString() == model.SerializeToString()


# --- `_constant_map`: a scalar/shape operand fed by a `Constant` node -------
#
# Every hop above (and the Clip/decomposed-LayerNorm/decomposed-GroupNorm
# hops elsewhere in this file) checks its own scalar/shape operand via
# `initializer_map.get(name)` -- but a real `torch.onnx.export`, run through
# onnxsim's own `simplify()`, leaves exactly this kind of operand (a literal
# Python scalar like RMSNorm's `2`/`self.eps`/`1.0`, as opposed to a learned
# `nn.Parameter`) as a plain `Constant` node, never promoted to an
# initializer: `onnxsim.cpp`'s own `SimplifyImpl` always drops onnx-
# optimizer's `extract_constant_to_initializer` pass for exactly this reason
# (see that file's own comment), so `graph.initializer` alone never contains
# it. Confirmed empirically (before `_constant_map` existed) via a real
# `torch.onnx.export` of a hand-rolled `LlamaRMSNorm`-equivalent module, run
# through `onnxsim.simplify()`, then `apply_structured_pruning` on the
# result -- the exact chain below, `Pow`/`Add`/`Div` operands `Constant`-node-
# fed rather than initializer-fed -- came back completely unpruned, purely
# because those operands weren't found in `graph.initializer`, even though
# the *same* logical chain built with those values as initializers (every
# other test in this file) already matched and pruned correctly.
# `_constant_map` closes this once, for every hop that already builds an
# `initializer_map` this way, rather than per hop.


def test_structured_pruning_decomposed_rms_norm_constant_node_operands_matches_oracle():
    # The `_decomposed_rms_norm_model` chain above, rebuilt with `Two`/`Eps`/
    # `One` as `Constant` nodes (the real torch-export shape for a literal
    # Python scalar) instead of initializers -- confirms `_constant_map`
    # resolves them exactly the same way, so this chain prunes exactly like
    # its initializer-fed twin above, not like the still-genuinely-different-
    # shape decline cases elsewhere in this section.
    K, C, Out = 8, 16, 4
    rng = np.random.default_rng(347)
    w1 = rng.standard_normal((K, C)).astype(np.float32)
    weight = rng.standard_normal((C,)).astype(np.float32)
    w2 = rng.standard_normal((C, Out)).astype(np.float32)
    model = _model(
        f"""
        g (float[batch,{K}] X) => (float[batch,{Out}] Y)
        {{
          x = MatMul(X, W1)
          Two = Constant<value = float[1] {{2.0}}>()
          variance = Pow(x, Two)
          meanvar = ReduceMean<axes=[-1]>(variance)
          Eps = Constant<value = float[1] {{1e-05}}>()
          vareps = Add(meanvar, Eps)
          std = Sqrt(vareps)
          One = Constant<value = float[1] {{1.0}}>()
          invstd = Div(One, std)
          scaled = Mul(x, invstd)
          h = Mul(scaled, Weight)
          Y = MatMul(h, W2)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(weight, "Weight"), _f32(w2, "W2")],
        opset=17,
    )
    onnx.checker.check_model(model)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    inits = {t.name: t for t in pruned.graph.initializer}
    keep_count = C // 2
    assert list(inits["W1"].dims) == [K, keep_count]
    assert list(inits["Weight"].dims) == [keep_count]
    assert list(inits["W2"].dims) == [keep_count, Out]
    # The `Constant` nodes themselves are untouched -- nothing to slice.
    assert sorted(n.op_type for n in pruned.graph.node) == sorted(
        n.op_type for n in model.graph.node
    )

    keep = _oracle_keep_indices(w1, keep_count)
    x = np.random.default_rng(348).standard_normal((5, K)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    h_correct = _rms_norm_oracle(x @ w1[:, keep], weight[keep], eps=1e-5)
    y_correct = h_correct @ w2[keep, :]
    np.testing.assert_allclose(y, y_correct, rtol=1e-4, atol=1e-4)


def test_structured_pruning_clip_constant_node_bounds_matches_oracle():
    # A second, independent hop (Conv-chain `Clip`, not MatMul/Gemm-chain
    # RMSNorm) with its own `min`/`max` fed by `Constant` nodes instead of
    # initializers -- confirms `_constant_map`'s fix is not RMSNorm-specific:
    # any hop built on the same `initializer_map.get(name)` pattern benefits.
    Cin, C1, C2 = 3, 16, 8
    rng = np.random.default_rng(349)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    model = _model(
        f"""
        g (float[N,{Cin},10,10] X) => (float[N,{C2},6,6] Y)
        {{
          h = Conv<kernel_shape=[3,3]>(X, W1)
          Min = Constant<value = float[1] {{0.0}}>()
          Max = Constant<value = float[1] {{6.0}}>()
          p = Clip(h, Min, Max)
          Y = Conv<kernel_shape=[3,3]>(p, W2)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(w2, "W2")],
    )
    onnx.checker.check_model(model)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    dims_after = {t.name: list(t.dims) for t in pruned.graph.initializer}
    assert dims_after["W1"][0] == C1 // 2
    assert dims_after["W2"][1] == C1 // 2


def test_structured_pruning_gated_ffn_layer_norm_pass_through_matches_oracle():
    # Composition check: a gated (SwiGLU-style) combine feeding a plain
    # LayerNormalization before the down-projection -- confirms the hop
    # composes correctly through _find_gated_chains's own reuse of
    # _walk_to_consumer, with no crash or mis-slice.
    K, C, Out = 8, 16, 4
    rng = np.random.default_rng(146)
    wg = rng.standard_normal((K, C)).astype(np.float32)
    wu = rng.standard_normal((K, C)).astype(np.float32)
    gamma = (rng.standard_normal((C,)).astype(np.float32)) * 2.0 + 1.0
    beta = rng.standard_normal((C,)).astype(np.float32)
    wd = rng.standard_normal((C, Out)).astype(np.float32)
    model = _model(
        f"""
        g (float[batch,{K}] X) => (float[batch,{Out}] Y)
        {{
          gate = MatMul(X, Wg)
          up = MatMul(X, Wu)
          combined = Mul(gate, up)
          h = LayerNormalization<axis=-1>(combined, Gamma, Beta)
          Y = MatMul(h, Wd)
        }}
        """,
        initializer=[
            _f32(wg, "Wg"),
            _f32(wu, "Wu"),
            _f32(gamma, "Gamma"),
            _f32(beta, "Beta"),
            _f32(wd, "Wd"),
        ],
    )
    onnx.checker.check_model(model)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    inits = {t.name: t for t in pruned.graph.initializer}
    keep_count = C // 2
    assert list(inits["Gamma"].dims) == [keep_count]

    importance = np.sqrt(
        np.square(np.linalg.norm(wg.astype(np.float64), axis=0))
        + np.square(np.linalg.norm(wu.astype(np.float64), axis=0))
    )
    keep = np.sort(np.argsort(-importance)[:keep_count])

    x = rng.standard_normal((5, K)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})

    def _layer_norm(v, g, b, eps=1e-5):
        mean = v.mean(axis=-1, keepdims=True)
        var = v.var(axis=-1, keepdims=True)
        return (v - mean) / np.sqrt(var + eps) * g + b

    combined = (x @ wg[:, keep]) * (x @ wu[:, keep])
    h_correct = _layer_norm(combined, gamma[keep], beta[keep])
    y_correct = h_correct @ wd[keep, :]
    np.testing.assert_allclose(y, y_correct, rtol=1e-4, atol=1e-4)


def test_structured_pruning_residual_add_layer_norm_pass_through_matches_oracle():
    # Composition check: a bare-Add residual merge feeding a plain
    # LayerNormalization before the next projection -- confirms the hop
    # composes correctly through _find_matmul_residual_chains's own reuse of
    # _walk_to_consumer (via _resolve_matmul_fanout_branches), with no crash
    # or mis-slice.
    K, C, Out = 8, 16, 4
    rng = np.random.default_rng(147)
    wf = rng.standard_normal((K, C)).astype(np.float32)
    ws = rng.standard_normal((K, C)).astype(np.float32)
    gamma = (rng.standard_normal((C,)).astype(np.float32)) * 2.0 + 1.0
    beta = rng.standard_normal((C,)).astype(np.float32)
    wd = rng.standard_normal((C, Out)).astype(np.float32)
    model = _model(
        f"""
        g (float[batch,{K}] X) => (float[batch,{Out}] Y)
        {{
          f = MatMul(X, WF)
          s = MatMul(X, WS)
          combined = Add(f, s)
          h = LayerNormalization<axis=-1>(combined, Gamma, Beta)
          Y = MatMul(h, WD)
        }}
        """,
        initializer=[
            _f32(wf, "WF"),
            _f32(ws, "WS"),
            _f32(gamma, "Gamma"),
            _f32(beta, "Beta"),
            _f32(wd, "WD"),
        ],
    )
    onnx.checker.check_model(model)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    inits = {t.name: t for t in pruned.graph.initializer}
    keep_count = C // 2
    assert list(inits["Gamma"].dims) == [keep_count]

    importance = np.sqrt(
        np.square(np.linalg.norm(wf.astype(np.float64), axis=0))
        + np.square(np.linalg.norm(ws.astype(np.float64), axis=0))
    )
    keep = np.sort(np.argsort(-importance)[:keep_count])

    x = rng.standard_normal((5, K)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})

    def _layer_norm(v, g, b, eps=1e-5):
        mean = v.mean(axis=-1, keepdims=True)
        var = v.var(axis=-1, keepdims=True)
        return (v - mean) / np.sqrt(var + eps) * g + b

    combined = (x @ wf[:, keep]) + (x @ ws[:, keep])
    h_correct = _layer_norm(combined, gamma[keep], beta[keep])
    y_correct = h_correct @ wd[keep, :]
    np.testing.assert_allclose(y, y_correct, rtol=1e-4, atol=1e-4)


# --- apply_structured_pruning: gated FFN (SwiGLU/GeGLU) ----------------------


def _combined_keep_indices(w_gate, w_up, keep_count):
    importance = np.sqrt(
        np.square(np.linalg.norm(w_gate.T, axis=1))
        + np.square(np.linalg.norm(w_up.T, axis=1))
    )
    return np.sort(np.argsort(-importance)[:keep_count])


def _swiglu_mlp_model(K=8, H=16, Out=4, gate_activation="Sigmoid", seed=0, opset=21):
    rng = np.random.default_rng(seed)
    wg = rng.standard_normal((K, H)).astype(np.float32)
    wu = rng.standard_normal((K, H)).astype(np.float32)
    wd = rng.standard_normal((H, Out)).astype(np.float32)
    model = _model(
        f"""
        g (float[batch,{K}] X) => (float[batch,{Out}] Y)
        {{
          gate = MatMul(X, Wg)
          gate_act = {gate_activation}(gate)
          up = MatMul(X, Wu)
          h = Mul(gate_act, up)
          Y = MatMul(h, Wd)
        }}
        """,
        initializer=[_f32(wg, "Wg"), _f32(wu, "Wu"), _f32(wd, "Wd")],
        opset=opset,
    )
    return model, wg, wu, wd


def test_structured_pruning_gated_ffn_matches_oracle():
    K, H, Out = 8, 16, 4
    model, wg, wu, wd = _swiglu_mlp_model(K=K, H=H, Out=Out)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    inits = {t.name: t for t in pruned.graph.initializer}
    assert list(inits["Wg"].dims) == [K, H // 2]
    assert list(inits["Wu"].dims) == [K, H // 2]
    assert list(inits["Wd"].dims) == [H // 2, Out]

    keep = _combined_keep_indices(wg, wu, H // 2)
    rng = np.random.default_rng(10)
    x = rng.standard_normal((5, K)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})

    gate = 1.0 / (1.0 + np.exp(-(x @ wg[:, keep])))
    up = x @ wu[:, keep]
    y_oracle = (gate * up) @ wd[keep, :]
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_gated_ffn_prunes_both_branches_to_same_channels():
    # The real bug this pattern risks: gate and up disagreeing on which
    # channels survive, which would silently break the elementwise
    # product's alignment. Assert they select the identical index set,
    # not just that both shrank to the same *count*.
    K, H, Out = 8, 20, 4
    model, wg, wu, _ = _swiglu_mlp_model(K=K, H=H, Out=Out, seed=1)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.3)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    keep = _combined_keep_indices(wg, wu, H - round(H * 0.3))

    np.testing.assert_array_equal(inits["Wg"], wg[:, keep])
    np.testing.assert_array_equal(inits["Wu"], wu[:, keep])


def test_structured_pruning_gelu_gated_ffn_matches_oracle():
    # GeGLU: same gated topology, a different (still-unary) gate activation.
    # Uses Gelu's tanh approximation so the oracle needs no scipy/erf.
    K, H, Out = 8, 16, 4
    rng = np.random.default_rng(11)
    wg = rng.standard_normal((K, H)).astype(np.float32)
    wu = rng.standard_normal((K, H)).astype(np.float32)
    wd = rng.standard_normal((H, Out)).astype(np.float32)
    model = _model(
        f"""
        g (float[batch,{K}] X) => (float[batch,{Out}] Y)
        {{
          gate = MatMul(X, Wg)
          gate_act = Gelu<approximate = "tanh">(gate)
          up = MatMul(X, Wu)
          h = Mul(gate_act, up)
          Y = MatMul(h, Wd)
        }}
        """,
        initializer=[_f32(wg, "Wg"), _f32(wu, "Wu"), _f32(wd, "Wd")],
    )

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    keep = _combined_keep_indices(wg, wu, H // 2)

    x = rng.standard_normal((5, K)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})

    g = x @ wg[:, keep]
    gate = 0.5 * g * (1.0 + np.tanh(np.sqrt(2.0 / np.pi) * (g + 0.044715 * g**3)))
    up = x @ wu[:, keep]
    y_oracle = (gate * up) @ wd[keep, :]
    np.testing.assert_allclose(y, y_oracle, rtol=1e-4, atol=1e-4)


def test_structured_pruning_quick_gelu_gated_ffn_matches_oracle():
    # A gate branch fused into com.microsoft::QuickGelu -- some real
    # gated-FFN model families use this in place of a plain Sigmoid/Gelu
    # gate. QuickGelu is unary (no bias operand at all), so it needed no
    # dedicated gated-chain machinery -- adding it to _UNARY_PASS_THROUGH
    # alone already lets _trace_gate_producer_backward's own unary-only
    # backward trace recognize it, the same way it already recognizes a
    # plain Sigmoid/Gelu gate above. Confirmed here rather than assumed:
    # this module's own docstring explicitly declines the *bias-carrying*
    # BiasGelu/FastGelu fusion on a gate branch (out of scope, see there),
    # but QuickGelu -- bias-free -- is not that case.
    K, H, Out = 8, 16, 4
    rng = np.random.default_rng(129)
    wg = rng.standard_normal((K, H)).astype(np.float32)
    wu = rng.standard_normal((K, H)).astype(np.float32)
    wd = rng.standard_normal((H, Out)).astype(np.float32)
    model = _model(
        f"""
        g (float[batch,{K}] X) => (float[batch,{Out}] Y)
        {{
          gate = MatMul(X, Wg)
          gate_act = com.microsoft.QuickGelu(gate)
          up = MatMul(X, Wu)
          h = Mul(gate_act, up)
          Y = MatMul(h, Wd)
        }}
        """,
        initializer=[_f32(wg, "Wg"), _f32(wu, "Wu"), _f32(wd, "Wd")],
        opset=17,
    )
    model.opset_import.append(onnx.helper.make_opsetid("com.microsoft", 1))

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    keep = _combined_keep_indices(wg, wu, H // 2)

    x = rng.standard_normal((5, K)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})

    g = x @ wg[:, keep]
    gate = _quick_gelu(g)
    up = x @ wu[:, keep]
    y_oracle = (gate * up) @ wd[keep, :]
    np.testing.assert_allclose(y, y_oracle, rtol=1e-4, atol=1e-4)


def test_structured_pruning_swish_gated_ffn_matches_oracle():
    # The SwiGLU-shaped gated MatMul chain with ai.onnx (domain "") Swish
    # (opset 24+) as the gate activation -- the pattern its name literally
    # comes from (Swish-Gated Linear Unit). Swish is unary (alpha is a
    # float attribute, not a second input), so -- exactly like the
    # QuickGelu gated-FFN case above -- it needed no dedicated gated-chain
    # machinery, only joining `_UNARY_PASS_THROUGH`.
    K, H, Out = 8, 16, 4
    model, wg, wu, wd = _swiglu_mlp_model(
        K=K, H=H, Out=Out, gate_activation="Swish", seed=130, opset=24
    )

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    inits = {t.name: t for t in pruned.graph.initializer}
    assert list(inits["Wg"].dims) == [K, H // 2]
    assert list(inits["Wu"].dims) == [K, H // 2]
    assert list(inits["Wd"].dims) == [H // 2, Out]

    keep = _combined_keep_indices(wg, wu, H // 2)
    rng = np.random.default_rng(131)
    x = rng.standard_normal((5, K)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})

    g = x @ wg[:, keep]
    gate = g / (1.0 + np.exp(-g))  # Swish(x) = x * sigmoid(alpha * x), alpha=1.0
    up = x @ wu[:, keep]
    y_oracle = (gate * up) @ wd[keep, :]
    assert np.isfinite(y).all()
    np.testing.assert_allclose(y, y_oracle, rtol=1e-4, atol=1e-4)


def test_structured_pruning_swish_gated_ffn_prunes_same_shape_as_sigmoid_gate():
    # The only difference between a Swish-gated and Sigmoid-gated chain
    # should be the missing-vs-present set membership fixed here -- not
    # some broader gated-chain limitation. Same K/H/Out/seed/sparsity as
    # the Sigmoid-gated `_swiglu_mlp_model` default, so any divergence in
    # which/how many channels survive would show up directly.
    K, H, Out, seed, sparsity = 8, 16, 4, 30, 0.5
    sigmoid_model, wg, wu, wd = _swiglu_mlp_model(
        K=K, H=H, Out=Out, gate_activation="Sigmoid", seed=seed
    )
    swish_model, wg2, wu2, wd2 = _swiglu_mlp_model(
        K=K, H=H, Out=Out, gate_activation="Swish", seed=seed, opset=24
    )
    np.testing.assert_array_equal(wg, wg2)
    np.testing.assert_array_equal(wu, wu2)
    np.testing.assert_array_equal(wd, wd2)

    sigmoid_pruned = onnxsim.apply_structured_pruning(sigmoid_model, sparsity=sparsity)
    swish_pruned = onnxsim.apply_structured_pruning(swish_model, sparsity=sparsity)

    sigmoid_inits = {
        t.name: onnx.numpy_helper.to_array(t) for t in sigmoid_pruned.graph.initializer
    }
    swish_inits = {
        t.name: onnx.numpy_helper.to_array(t) for t in swish_pruned.graph.initializer
    }
    for name in ("Wg", "Wu", "Wd"):
        assert sigmoid_inits[name].shape == swish_inits[name].shape
        np.testing.assert_array_equal(sigmoid_inits[name], swish_inits[name])


def test_structured_pruning_ungated_mul_of_two_producers_still_matches_oracle():
    # No activation at all on either branch -- a plain (unactivated) GLU,
    # both Mul operands are raw producer outputs directly.
    K, H, Out = 8, 12, 4
    rng = np.random.default_rng(2)
    w1 = rng.standard_normal((K, H)).astype(np.float32)
    w2 = rng.standard_normal((K, H)).astype(np.float32)
    w3 = rng.standard_normal((H, Out)).astype(np.float32)
    model = _model(
        f"""
        g (float[batch,{K}] X) => (float[batch,{Out}] Y)
        {{
          a = MatMul(X, W1)
          b = MatMul(X, W2)
          h = Mul(a, b)
          Y = MatMul(h, W3)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(w2, "W2"), _f32(w3, "W3")],
    )

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    keep = _combined_keep_indices(w1, w2, H // 2)

    x = rng.standard_normal((5, K)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    y_oracle = ((x @ w1[:, keep]) * (x @ w2[:, keep])) @ w3[keep, :]
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_gated_mul_against_constant_scale_is_not_a_gate():
    # Mul(a, constant) is the existing per-channel-scale chain continuation
    # (already covered elsewhere), not a two-producer gated pair -- the
    # constant operand must never be mistaken for a second producer.
    K, H, Out = 8, 12, 4
    rng = np.random.default_rng(3)
    w1 = rng.standard_normal((K, H)).astype(np.float32)
    scale = rng.standard_normal((H,)).astype(np.float32)
    w2 = rng.standard_normal((H, Out)).astype(np.float32)
    model = _model(
        f"""
        g (float[batch,{K}] X) => (float[batch,{Out}] Y)
        {{
          a = MatMul(X, W1)
          h = Mul(a, Scale)
          Y = MatMul(h, W2)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(scale, "Scale"), _f32(w2, "W2")],
    )

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    inits = {t.name: t for t in pruned.graph.initializer}
    assert list(inits["W1"].dims) == [K, H // 2]
    assert list(inits["Scale"].dims) == [H // 2]
    assert list(inits["W2"].dims) == [H // 2, Out]


def test_structured_pruning_gated_ffn_skips_when_a_branch_also_feeds_elsewhere():
    # "up" also feeding a second consumer directly means pruning its
    # channels would silently change what that other consumer sees --
    # must be left completely untouched, same bar as the plain-chain case.
    K, H, Out = 8, 12, 4
    rng = np.random.default_rng(4)
    wg = rng.standard_normal((K, H)).astype(np.float32)
    wu = rng.standard_normal((K, H)).astype(np.float32)
    wd = rng.standard_normal((H, Out)).astype(np.float32)
    wother = rng.standard_normal((H, Out)).astype(np.float32)
    model = _model(
        f"""
        g (float[batch,{K}] X) => (float[batch,{Out}] Y1, float[batch,{Out}] Y2)
        {{
          gate = MatMul(X, Wg)
          gate_act = Sigmoid(gate)
          up = MatMul(X, Wu)
          h = Mul(gate_act, up)
          Y1 = MatMul(h, Wd)
          Y2 = MatMul(up, Wother)
        }}
        """,
        initializer=[
            _f32(wg, "Wg"),
            _f32(wu, "Wu"),
            _f32(wd, "Wd"),
            _f32(wother, "Wother"),
        ],
    )

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: t for t in pruned.graph.initializer}
    assert list(inits["Wg"].dims) == [K, H]
    assert list(inits["Wu"].dims) == [K, H]
    assert list(inits["Wd"].dims) == [H, Out]


def test_structured_pruning_native_swiglu_node_prunes_both_producers_together():
    # ONNX's native fused SwiGLU(a, b) = swish(a) * b (opset 28+): the
    # activation lives entirely inside the op, so a/b must be raw producer
    # outputs with no separate activation node in between. Not yet
    # supported by the installed onnx checker/onnxruntime in this
    # environment (opset 28 is still under development upstream), so this
    # verifies the graph surgery directly via tensor values rather than
    # onnx.checker/onnxruntime execution.
    K, H, Out = 8, 16, 4
    rng = np.random.default_rng(5)
    wg = rng.standard_normal((K, H)).astype(np.float32)
    wu = rng.standard_normal((K, H)).astype(np.float32)
    wd = rng.standard_normal((H, Out)).astype(np.float32)
    model = _model(
        f"""
        g (float[batch,{K}] X) => (float[batch,{Out}] Y)
        {{
          gate = MatMul(X, Wg)
          up = MatMul(X, Wu)
          h = SwiGLU(gate, up)
          Y = MatMul(h, Wd)
        }}
        """,
        initializer=[_f32(wg, "Wg"), _f32(wu, "Wu"), _f32(wd, "Wd")],
        opset=28,
    )

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    keep = _combined_keep_indices(wg, wu, H // 2)

    np.testing.assert_array_equal(inits["Wg"], wg[:, keep])
    np.testing.assert_array_equal(inits["Wu"], wu[:, keep])
    np.testing.assert_array_equal(inits["Wd"], wd[keep, :])


# --- Split-merged (fused gate_up_proj) gated FFN chains ------------------
#
# Real Phi-3/Phi-3.5 (onnxruntime-genai) exports use ONE gate_up_proj MatMul
# whose 2*H-wide output is halved by a Split into a gate half and an up half,
# rather than two separate gate_proj/up_proj producers -- see
# onnxsim/pruning.py's own "Split-merged (fused gate_up_proj) gated FFN
# chains" section comment for the full shape and co-selection semantics
# these tests exercise.


def _split_gate_up_keep_indices(w, H, keep_count):
    # The correct paired-importance ranking: combined (root-sum-square)
    # norm of the gate half (columns [0, H)) and the up half (columns
    # [H, 2H)) of the ONE combined weight `w`, mirroring
    # _combined_keep_indices's own formula for the two-separate-producer
    # case above -- the two must agree exactly since both halves represent
    # the very same physical weight tensor's own two-producer analogue.
    gate_half, up_half = w[:, :H], w[:, H:]
    importance = np.sqrt(
        np.square(np.linalg.norm(gate_half.T, axis=1))
        + np.square(np.linalg.norm(up_half.T, axis=1))
    )
    return np.sort(np.argsort(-importance)[:keep_count])


def _split_gate_up_mlp_model(
    K=8,
    H=16,
    Out=4,
    gate_activation="Sigmoid",
    seed=0,
    opset=21,
    split_attrs="axis=-1, num_outputs=2",
):
    rng = np.random.default_rng(seed)
    w = rng.standard_normal((K, 2 * H)).astype(np.float32)
    wd = rng.standard_normal((H, Out)).astype(np.float32)
    split_attr_text = f"<{split_attrs}>" if split_attrs else ""
    model = _model(
        f"""
        g (float[batch,{K}] X) => (float[batch,{Out}] Y)
        {{
          combined = MatMul(X, W)
          gate, up = Split {split_attr_text} (combined)
          gate_act = {gate_activation}(gate)
          h = Mul(gate_act, up)
          Y = MatMul(h, Wd)
        }}
        """,
        initializer=[_f32(w, "W"), _f32(wd, "Wd")],
        opset=opset,
    )
    return model, w, wd


def test_structured_pruning_split_gated_ffn_matches_oracle():
    K, H, Out = 8, 16, 4
    model, w, wd = _split_gate_up_mlp_model(K=K, H=H, Out=Out)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    inits = {t.name: t for t in pruned.graph.initializer}
    assert list(inits["W"].dims) == [K, H]  # 2 * (H // 2)
    assert list(inits["Wd"].dims) == [H // 2, Out]

    keep = _split_gate_up_keep_indices(w, H, H // 2)
    rng = np.random.default_rng(20)
    x = rng.standard_normal((5, K)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})

    gate = 1.0 / (1.0 + np.exp(-(x @ w[:, keep])))
    up = x @ w[:, H + keep]
    y_oracle = (gate * up) @ wd[keep, :]
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_split_gated_ffn_prunes_both_halves_of_one_tensor():
    # The real bug this pattern risks: only one of the two halves getting
    # sliced (or the two halves disagreeing on which columns survive) --
    # assert the SAME index set is dropped from both, out of the single
    # physical weight tensor.
    K, H, Out = 8, 20, 4
    model, w, wd = _split_gate_up_mlp_model(K=K, H=H, Out=Out, seed=1)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.3)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    keep = _split_gate_up_keep_indices(w, H, H - round(H * 0.3))

    np.testing.assert_array_equal(inits["W"][:, : len(keep)], w[:, keep])
    np.testing.assert_array_equal(inits["W"][:, len(keep) :], w[:, H + keep])
    np.testing.assert_array_equal(inits["Wd"], wd[keep, :])


def test_structured_pruning_split_gated_ffn_uses_combined_paired_importance():
    # Adversarial case: gate-half and up-half columns for the SAME neuron
    # index deliberately have very different magnitudes, constructed so
    # that ranking by EITHER half alone (a "sliced/ranked only one half"
    # bug) picks a DIFFERENT keep-set than the correct combined
    # (root-sum-square) ranking of the pair. K=2 with only row 0 non-zero
    # makes each column's own L2 norm exactly its row-0 value, so the
    # desired per-half magnitudes can be set directly and exactly.
    K, H, Out = 2, 5, 3
    gate_vals = np.array([9.0, 1.0, 6.0, 7.0, 0.5], dtype=np.float32)
    up_vals = np.array([1.0, 8.9, 6.0, 0.5, 6.9], dtype=np.float32)
    # combined (root-sum-square) importance per column:
    #   col0: sqrt(9.0^2+1.0^2) = 9.0554  (rank 1)
    #   col1: sqrt(1.0^2+8.9^2) = 8.9556  (rank 2)
    #   col2: sqrt(6.0^2+6.0^2) = 8.4853  (rank 3)
    #   col3: sqrt(7.0^2+0.5^2) = 7.0178  (rank 4)
    #   col4: sqrt(0.5^2+6.9^2) = 6.9181  (rank 5)
    # correct keep (top 3, combined) = [0, 1, 2]; gate-only top 3 would be
    # [0, 2, 3] and up-only top 3 would be [1, 2, 4] -- both wrong.
    w = np.zeros((K, 2 * H), dtype=np.float32)
    w[0, :H] = gate_vals
    w[0, H:] = up_vals
    rng = np.random.default_rng(2)
    wd = rng.standard_normal((H, Out)).astype(np.float32)
    model = _model(
        f"""
        g (float[batch,{K}] X) => (float[batch,{Out}] Y)
        {{
          combined = MatMul(X, W)
          gate, up = Split <axis=-1, num_outputs=2> (combined)
          gate_act = Sigmoid(gate)
          h = Mul(gate_act, up)
          Y = MatMul(h, Wd)
        }}
        """,
        initializer=[_f32(w, "W"), _f32(wd, "Wd")],
    )

    # H=5, sparsity=0.4 -> keep_count = 5 - round(5*0.4) = 3.
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.4)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    correct_keep = np.array([0, 1, 2])
    gate_only_keep = np.array([0, 2, 3])  # what a gate-only-ranked bug would pick
    up_only_keep = np.array([1, 2, 4])  # what an up-only-ranked bug would pick

    np.testing.assert_array_equal(inits["W"][:, :3], w[:, correct_keep])
    np.testing.assert_array_equal(inits["W"][:, 3:], w[:, H + correct_keep])
    assert not np.array_equal(inits["W"][0, :3], w[0, gate_only_keep])
    assert not np.array_equal(inits["W"][0, :3], w[0, up_only_keep])


def test_structured_pruning_split_gated_ffn_swish_activation_matches_oracle():
    # Native ai.onnx Swish(X) = X * Sigmoid(alpha * X), opset 24+ -- the
    # fused-single-node spelling of SiLU real gate_up_proj exports use.
    K, H, Out = 8, 16, 4
    model, w, wd = _split_gate_up_mlp_model(
        K=K, H=H, Out=Out, gate_activation="Swish", seed=3, opset=24
    )
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    keep = _split_gate_up_keep_indices(w, H, H // 2)
    rng = np.random.default_rng(30)
    x = rng.standard_normal((5, K)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})

    g = x @ w[:, keep]
    gate = g * (1.0 / (1.0 + np.exp(-g)))
    up = x @ w[:, H + keep]
    y_oracle = (gate * up) @ wd[keep, :]
    np.testing.assert_allclose(y, y_oracle, rtol=1e-4, atol=1e-4)


def test_structured_pruning_split_gated_ffn_explicit_equal_split_input_matches_oracle():
    # opset 13+'s explicit `split` *input* (rather than the fully-automatic
    # even split) spelled out as literally [H, H] -- the same semantic
    # split, a different spelling; the pruned model's own Split input must
    # be rewritten to the new, still-even [h', h'].
    K, H, Out = 8, 16, 4
    rng = np.random.default_rng(4)
    w = rng.standard_normal((K, 2 * H)).astype(np.float32)
    wd = rng.standard_normal((H, Out)).astype(np.float32)
    sizes = onnx.numpy_helper.from_array(np.array([H, H], dtype=np.int64), name="Sizes")
    model = _model(
        f"""
        g (float[batch,{K}] X) => (float[batch,{Out}] Y)
        {{
          combined = MatMul(X, W)
          gate, up = Split <axis=-1> (combined, Sizes)
          gate_act = Sigmoid(gate)
          h = Mul(gate_act, up)
          Y = MatMul(h, Wd)
        }}
        """,
        initializer=[_f32(w, "W"), _f32(wd, "Wd"), sizes],
    )

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    split_node = next(n for n in pruned.graph.node if n.op_type == "Split")
    sizes_init = next(
        t for t in pruned.graph.initializer if t.name == split_node.input[1]
    )
    assert list(onnx.numpy_helper.to_array(sizes_init)) == [H // 2, H // 2]

    keep = _split_gate_up_keep_indices(w, H, H // 2)
    x = rng.standard_normal((5, K)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    gate = 1.0 / (1.0 + np.exp(-(x @ w[:, keep])))
    up = x @ w[:, H + keep]
    y_oracle = (gate * up) @ wd[keep, :]
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_split_gated_ffn_declines_unequal_explicit_split():
    K, H = 8, 16
    rng = np.random.default_rng(5)
    w = rng.standard_normal((K, 2 * H)).astype(np.float32)
    sizes = onnx.numpy_helper.from_array(
        np.array([H + 2, H - 2], dtype=np.int64), name="Sizes"
    )
    model = _model(
        f"""
        g (float[batch,{K}] X) => (float[batch,{H + 2}] Gate, float[batch,{H - 2}] Up)
        {{
          combined = MatMul(X, W)
          Gate, Up = Split <axis=-1> (combined, Sizes)
        }}
        """,
        initializer=[_f32(w, "W"), sizes],
    )
    before = model.SerializeToString()
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    assert pruned.SerializeToString() == before


def test_structured_pruning_split_gated_ffn_declines_dynamic_split_sizes():
    # A `split` input that is a genuine graph input (not a constant
    # initializer) -- this module has no way to confirm ahead of time it's
    # really [H, H], nor to keep it pruning-consistent afterward.
    K, H, Out = 8, 16, 4
    model, w, wd = _split_gate_up_mlp_model(
        K=K, H=H, Out=Out, seed=6, split_attrs="axis=-1"
    )
    # Rewrite the Split node to take a dynamic `sizes` graph input instead
    # of relying on the automatic even split.
    split_node = next(n for n in model.graph.node if n.op_type == "Split")
    del split_node.input[:]
    split_node.input.extend(["combined", "Sizes"])
    model.graph.input.append(
        onnx.helper.make_tensor_value_info("Sizes", onnx.TensorProto.INT64, [2])
    )
    onnx.checker.check_model(model)

    before = model.SerializeToString()
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    assert pruned.SerializeToString() == before


def test_structured_pruning_split_gated_ffn_declines_decomposed_silu():
    # SiLU decomposed as the self-referencing x * Sigmoid(x) (two nodes)
    # rather than a single Sigmoid/native Swish -- not recognized, the same
    # decline _find_gated_chains's own two-producer case already documents.
    K, H, Out = 8, 16, 4
    rng = np.random.default_rng(7)
    w = rng.standard_normal((K, 2 * H)).astype(np.float32)
    wd = rng.standard_normal((H, Out)).astype(np.float32)
    model = _model(
        f"""
        g (float[batch,{K}] X) => (float[batch,{Out}] Y)
        {{
          combined = MatMul(X, W)
          gate, up = Split <axis=-1, num_outputs=2> (combined)
          gate_sig = Sigmoid(gate)
          gate_act = Mul(gate, gate_sig)
          h = Mul(gate_act, up)
          Y = MatMul(h, Wd)
        }}
        """,
        initializer=[_f32(w, "W"), _f32(wd, "Wd")],
    )
    before = model.SerializeToString()
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    assert pruned.SerializeToString() == before


def test_structured_pruning_split_gated_ffn_declines_bias_add_before_split():
    # A separate MatMul -> Add(bias) -> Split, rather than the producer's
    # raw output feeding Split directly -- out of scope for this first
    # pass (see this module's own section comment).
    K, H, Out = 8, 16, 4
    rng = np.random.default_rng(8)
    w = rng.standard_normal((K, 2 * H)).astype(np.float32)
    bias = rng.standard_normal((2 * H,)).astype(np.float32)
    wd = rng.standard_normal((H, Out)).astype(np.float32)
    model = _model(
        f"""
        g (float[batch,{K}] X) => (float[batch,{Out}] Y)
        {{
          combined = MatMul(X, W)
          combined_b = Add(combined, Bias)
          gate, up = Split <axis=-1, num_outputs=2> (combined_b)
          gate_act = Sigmoid(gate)
          h = Mul(gate_act, up)
          Y = MatMul(h, Wd)
        }}
        """,
        initializer=[_f32(w, "W"), _f32(bias, "Bias"), _f32(wd, "Wd")],
    )
    before = model.SerializeToString()
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    assert pruned.SerializeToString() == before


def test_structured_pruning_split_gated_ffn_declines_three_way_split():
    K, H3 = 8, 6  # 3*H3 total, split into three equal parts
    rng = np.random.default_rng(9)
    w = rng.standard_normal((K, 3 * H3)).astype(np.float32)
    model = _model(
        f"""
        g (float[batch,{K}] X) => (float[batch,{H3}] A, float[batch,{H3}] B, float[batch,{H3}] C)
        {{
          combined = MatMul(X, W)
          A, B, C = Split <axis=-1, num_outputs=3> (combined)
        }}
        """,
        initializer=[_f32(w, "W")],
    )
    before = model.SerializeToString()
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    assert pruned.SerializeToString() == before


def test_structured_pruning_split_gated_ffn_declines_when_axis_defaults_to_zero():
    # Split's own schema default axis is 0, unlike Concat's *required*
    # attribute -- an un-annotated Split here would target the batch axis,
    # not the channel axis, and must be declined, not assumed.
    K, H, Out = 8, 16, 4
    model, w, wd = _split_gate_up_mlp_model(
        K=K, H=H, Out=Out, seed=10, split_attrs="num_outputs=2"
    )
    before = model.SerializeToString()
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    assert pruned.SerializeToString() == before


def test_structured_pruning_global_sparsity_leaves_split_gated_ffn_chain_untouched():
    # Same reasoning as the two-producer gated pair's own identical test
    # above: a single physical tensor's own two-half co-selection must
    # already agree with itself before a second, global layer of agreement
    # is even meaningful -- excluded from global_sparsity's own pool, left
    # completely untouched rather than approximated. Made uniformly tiny so
    # a naive pooled ranking would otherwise be eager to prune it hard.
    K, H, Out = 8, 16, 4
    rng = np.random.default_rng(31)
    w1 = (rng.standard_normal((K, H)) * 50.0).astype(np.float32)
    w2 = rng.standard_normal((H, Out)).astype(np.float32)
    w = (rng.standard_normal((K, 2 * H)) * 0.01).astype(np.float32)
    wd = rng.standard_normal((H, Out)).astype(np.float32)
    model = _model(
        f"""
        g (float[batch,{K}] X) => (float[batch,{Out}] Yplain, float[batch,{Out}] Ygated)
        {{
          h = MatMul(X, W1)
          a = Relu(h)
          Yplain = MatMul(a, W2)
          combined = MatMul(X, W)
          gate, up = Split <axis=-1, num_outputs=2> (combined)
          gate_act = Sigmoid(gate)
          hg = Mul(gate_act, up)
          Ygated = MatMul(hg, Wd)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(w2, "W2"), _f32(w, "W"), _f32(wd, "Wd")],
    )

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5, global_sparsity=True)
    onnx.checker.check_model(pruned)
    inits = {t.name: t for t in pruned.graph.initializer}
    assert list(inits["W1"].dims) != [K, H]  # the eligible plain chain IS pruned
    assert list(inits["W"].dims) == [K, 2 * H]  # the split-gated chain is not
    assert list(inits["Wd"].dims) == [H, Out]


def test_structured_wanda_pruning_split_gated_ffn_matches_plain_fallback_oracle():
    # This family is deliberately ranked by plain weight-magnitude
    # importance only in the calibrated (Wanda) entry point too -- see
    # apply_structured_wanda_pruning's own docstring -- so the result must
    # match the exact same oracle apply_structured_pruning's own test above
    # uses, calibration data notwithstanding.
    K, H, Out = 8, 16, 4
    model, w, wd = _split_gate_up_mlp_model(K=K, H=H, Out=Out, seed=23)

    rng = np.random.default_rng(24)
    x_cal = rng.standard_normal((32, K)).astype(np.float32)
    pruned = onnxsim.apply_structured_wanda_pruning(
        model, calibration_data=[{"X": x_cal}], sparsity=0.5
    )
    onnx.checker.check_model(pruned)

    keep = _split_gate_up_keep_indices(w, H, H // 2)
    x = rng.standard_normal((5, K)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    gate = 1.0 / (1.0 + np.exp(-(x @ w[:, keep])))
    up = x @ w[:, H + keep]
    y_oracle = (gate * up) @ wd[keep, :]
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_split_gated_ffn_prunes_inside_if_branch():
    K, H, Out = 8, 16, 4
    model, w, wd = _split_gate_up_mlp_model(K=K, H=H, Out=Out, seed=7)
    wrapped = _if_wrap(model)

    pruned = onnxsim.apply_structured_pruning(wrapped, sparsity=0.5)
    onnx.checker.check_model(pruned)

    keep = _split_gate_up_keep_indices(w, H, H // 2)
    rng = np.random.default_rng(21)
    x = rng.standard_normal((5, K)).astype(np.float32)
    for cond in (True, False):
        (y,) = _run(pruned, {"X": x, "cond": np.array(cond)})
        gate = 1.0 / (1.0 + np.exp(-(x @ w[:, keep])))
        up = x @ w[:, H + keep]
        y_oracle = (gate * up) @ wd[keep, :]
        np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


# --- Conv2D structured pruning ------------------------------------------


def _conv_pair_model(w1, w2, b1=None, spatial=10, activation="Relu", opset=21):
    Cin, C2 = w1.shape[1], w2.shape[0]
    initializer = [_f32(w1, "W1"), _f32(w2, "W2")]
    if b1 is not None:
        conv1 = "h = Conv<kernel_shape=[3,3]>(X, W1, B1)"
        initializer.append(_f32(b1, "B1"))
    else:
        conv1 = "h = Conv<kernel_shape=[3,3]>(X, W1)"
    out_spatial = spatial - 4  # two valid (no-pad) 3x3 convs
    return _model(
        f"""
        g (float[N,{Cin},{spatial},{spatial}] X) => (float[N,{C2},{out_spatial},{out_spatial}] Y)
        {{
          {conv1}
          a = {activation}(h)
          Y = Conv<kernel_shape=[3,3]>(a, W2)
        }}
        """,
        initializer=initializer,
        opset=opset,
    )


def _conv_model(Cin=3, C1=16, C2=8, bias=True, activation="Relu", seed=0, spatial=10):
    rng = np.random.default_rng(seed)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    b1 = rng.standard_normal((C1,)).astype(np.float32) if bias else None
    return _conv_pair_model(w1, w2, b1=b1, spatial=spatial, activation=activation)


def _oracle_keep_indices_conv(w, keep_count):
    importance = np.linalg.norm(w.reshape(w.shape[0], -1).astype(np.float64), axis=1)
    return np.sort(np.argsort(-importance)[:keep_count])


def _depthwise_pair_model(w1, dw_hops, w2, b1=None, spatial=10, activation="Relu"):
    """The Conv-chain oracle builder, extended with zero or more depthwise
    pass-through hops between producer and consumer: `dw_hops` is a list of
    ``(weight[C1, 1, kH, kW], bias_or_None)`` depthwise Convs (``group`` is
    always `weight.shape[0]`, so slicing `w1`/`dw_hops`/`w2` down together
    -- as every test below does for its own "oracle" call -- keeps every
    depthwise hop's `group` attribute consistent with its sliced weight for
    free). Each hop, like the producer, is followed by `activation`.
    """
    Cin, C2 = w1.shape[1], w2.shape[0]
    initializer = [_f32(w1, "W1"), _f32(w2, "W2")]
    if b1 is not None:
        lines = ["h0 = Conv<kernel_shape=[3,3]>(X, W1, B1)"]
        initializer.append(_f32(b1, "B1"))
    else:
        lines = ["h0 = Conv<kernel_shape=[3,3]>(X, W1)"]
    lines.append(f"a0 = {activation}(h0)")
    cur = "a0"
    n_convs = 1
    for i, (wd, bd) in enumerate(dw_hops):
        group = wd.shape[0]
        w_name, b_name = f"WD{i}", f"BD{i}"
        initializer.append(_f32(wd, w_name))
        if bd is not None:
            initializer.append(_f32(bd, b_name))
            lines.append(
                f"hd{i} = Conv<kernel_shape=[3,3], group={group}>"
                f"({cur}, {w_name}, {b_name})"
            )
        else:
            lines.append(
                f"hd{i} = Conv<kernel_shape=[3,3], group={group}>({cur}, {w_name})"
            )
        lines.append(f"ad{i} = {activation}(hd{i})")
        cur = f"ad{i}"
        n_convs += 1
    lines.append(f"Y = Conv<kernel_shape=[3,3]>({cur}, W2)")
    n_convs += 1
    out_spatial = spatial - 2 * n_convs  # each 3x3 valid conv shrinks by 2
    body = "\n          ".join(lines)
    return _model(
        f"""
        g (float[N,{Cin},{spatial},{spatial}] X) => (float[N,{C2},{out_spatial},{out_spatial}] Y)
        {{
          {body}
        }}
        """,
        initializer=initializer,
    )


def test_structured_pruning_depthwise_pass_through_matches_manual_channel_deletion_exactly():
    # A MobileNet/EfficientNet-style inverted-residual block:
    # Conv(group=1) -> Relu -> DepthwiseConv(group=C1) -> Relu ->
    # Conv(group=1). The depthwise layer mixes no channels at all -- output
    # channel i depends only on input channel i -- so the chain walk must
    # cross it transparently: the same channel-index set the real
    # producer/consumer pair is pruned to also slices the depthwise layer's
    # own weight and bias, and shrinks its `group` attribute to match.
    Cin, C1, C2 = 3, 16, 8
    rng = np.random.default_rng(50)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    b1 = rng.standard_normal((C1,)).astype(np.float32)
    wd = rng.standard_normal((C1, 1, 3, 3)).astype(np.float32)
    bd = rng.standard_normal((C1,)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    model = _depthwise_pair_model(w1, [(wd, bd)], w2, b1=b1)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    assert inits["WD0"].shape == (C1 // 2, 1, 3, 3)
    assert inits["BD0"].shape == (C1 // 2,)
    dw_node = next(n for n in pruned.graph.node if "WD0" in n.input)
    group_attr = next(a for a in dw_node.attribute if a.name == "group")
    assert group_attr.i == C1 // 2

    keep = _oracle_keep_indices_conv(w1, C1 // 2)
    oracle = _depthwise_pair_model(
        w1[keep], [(wd[keep], bd[keep])], w2[:, keep], b1=b1[keep]
    )

    rng_x = np.random.default_rng(51)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_multiple_consecutive_depthwise_pass_through_hops_matches_oracle():
    # Two depthwise Convs back to back (e.g. a wider spatial receptive
    # field built from stacked depthwise layers) -- both must be crossed
    # transparently by the same channel-index set, each sliced and
    # re-grouped independently. The second hop also has no bias, folding in
    # that case too.
    Cin, C1, C2 = 3, 12, 6
    rng = np.random.default_rng(52)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    wd1 = rng.standard_normal((C1, 1, 3, 3)).astype(np.float32)
    bd1 = rng.standard_normal((C1,)).astype(np.float32)
    wd2 = rng.standard_normal((C1, 1, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    model = _depthwise_pair_model(w1, [(wd1, bd1), (wd2, None)], w2, spatial=14)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.25)
    onnx.checker.check_model(pruned)

    keep = _oracle_keep_indices_conv(w1, C1 - round(C1 * 0.25))
    oracle = _depthwise_pair_model(
        w1[keep], [(wd1[keep], bd1[keep]), (wd2[keep], None)], w2[:, keep], spatial=14
    )

    rng_x = np.random.default_rng(53)
    x = rng_x.standard_normal((2, Cin, 14, 14)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_depthwise_pass_through_no_bias_matches_oracle():
    # A depthwise hop with no bias at all -- its own [C1, 1, kH, kW] weight
    # is the only thing that needs slicing for it.
    Cin, C1, C2 = 4, 10, 5
    rng = np.random.default_rng(54)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    wd = rng.standard_normal((C1, 1, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    model = _depthwise_pair_model(w1, [(wd, None)], w2, activation="Sigmoid")

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.3)
    onnx.checker.check_model(pruned)

    keep = _oracle_keep_indices_conv(w1, C1 - round(C1 * 0.3))
    oracle = _depthwise_pair_model(
        w1[keep], [(wd[keep], None)], w2[:, keep], activation="Sigmoid"
    )

    rng_x = np.random.default_rng(55)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_depthwise_pass_through_branch_is_left_untouched():
    # A depthwise Conv whose output feeds more than one consumer (a
    # branch) can't be crossed transparently either -- doing so would mean
    # picking one branch to carry the chain forward while silently leaving
    # the other reading a now-stale channel count. Left untouched, same as
    # any other branching point this pass declines to guess at (the same
    # single-consumer requirement every other hop in this pass already
    # holds every intermediate tensor to).
    Cin, C1 = 3, 8
    rng = np.random.default_rng(56)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    wd = rng.standard_normal((C1, 1, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C1, C1, 3, 3)).astype(np.float32)
    model = _model(
        f"""
        g (float[N,{Cin},10,10] X) => (float[N,{C1},4,4] Y1, float[N,{C1},6,6] Y2)
        {{
          h = Conv<kernel_shape=[3,3]>(X, W1)
          a = Relu(h)
          d = Conv<kernel_shape=[3,3], group={C1}>(a, WD)
          Y1 = Conv<kernel_shape=[3,3]>(d, W2)
          Y2 = Relu(d)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(wd, "WD"), _f32(w2, "W2")],
    )
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1)
    np.testing.assert_array_equal(inits["WD"], wd)
    np.testing.assert_array_equal(inits["W2"], w2)


def test_structured_pruning_conv_chain_shrinks_matched_layers():
    Cin, C1, C2 = 3, 16, 8
    model = _conv_model(Cin=Cin, C1=C1, C2=C2, bias=True)
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    inits = {t.name: t for t in pruned.graph.initializer}
    assert list(inits["W1"].dims) == [C1 // 2, Cin, 3, 3]
    assert list(inits["B1"].dims) == [C1 // 2]
    assert list(inits["W2"].dims) == [C2, C1 // 2, 3, 3]


def test_structured_pruning_conv_chain_matches_manual_channel_deletion_exactly():
    # Same correctness bar as the MatMul/Gemm chain tests: exact
    # equivalence to deleting the same output filters by hand, not just
    # "close to the float model". Conv has no simple numpy one-liner
    # standing in for the op itself, so the oracle is a second, smaller
    # ONNX graph built directly from the same sliced weights and run
    # through onnxruntime, rather than hand-rolled conv math.
    Cin, C1, C2 = 3, 16, 8
    rng = np.random.default_rng(30)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    b1 = rng.standard_normal((C1,)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    model = _conv_pair_model(w1, w2, b1=b1)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    keep = _oracle_keep_indices_conv(w1, C1 // 2)
    oracle = _conv_pair_model(w1[keep], w2[:, keep], b1=b1[keep])

    rng_x = np.random.default_rng(31)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def _auto_pad_conv_pair_model(w1, w2, spatial=10, activation="Relu"):
    # The auto_pad analogue of _conv_pair_model: both Convs keep their own
    # non-default auto_pad="SAME_UPPER" -- neither _match_conv_producer nor
    # _match_conv_consumer (the matchers apply_structured_pruning/
    # apply_structured_wanda_pruning's own producer/consumer chain-walk
    # uses) reads that attribute at all, so this is expected to be matched,
    # sliced, and re-run exactly like the plain _conv_pair_model chain
    # above -- see this module's own docstring for why: channel pruning
    # only ever indexes the weight tensor's own out_channels/in_channels
    # axes, never the spatial receptive-field math auto_pad changes.
    # auto_pad="SAME_UPPER" keeps each Conv's own output spatial size equal
    # to its input's, so the chain composes with no separate out_spatial
    # bookkeeping.
    Cin, C2 = w1.shape[1], w2.shape[0]
    return _model(
        f"""
        g (float[N,{Cin},{spatial},{spatial}] X) => (float[N,{C2},{spatial},{spatial}] Y)
        {{
          h = Conv<kernel_shape=[3,3], auto_pad="SAME_UPPER">(X, W1)
          a = {activation}(h)
          Y = Conv<kernel_shape=[3,3], auto_pad="SAME_UPPER">(a, W2)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(w2, "W2")],
    )


def _dilated_conv_pair_model(w1, w2, dilation=3, spatial=19, activation="Relu"):
    # The dilations analogue of _conv_pair_model, same reasoning as
    # _auto_pad_conv_pair_model above but for a non-unit dilation instead
    # (kept in a separate model/test from auto_pad -- not because
    # apply_structured_pruning/apply_structured_wanda_pruning need it kept
    # separate, but because onnxruntime's own CPU EP rejects a Conv node
    # combining a non-unit dilation with auto_pad SAME_UPPER/SAME_LOWER
    # ("Dilation not supported for AutoPadType::SAME_UPPER or
    # AutoPadType::SAME_LOWER"), discovered empirically while writing this
    # test -- an onnxruntime limitation on the *input* model this pass
    # would be asked to prune, not anything about onnxsim's own pruning
    # logic, but it means a real onnxruntime-executable adversarial model
    # can't combine both non-default attributes in one node). No explicit
    # padding either (`pads` defaults to all-zero, "VALID"-equivalent), so
    # each Conv's own output spatial size shrinks by the dilated kernel's
    # own effective extent.
    Cin, C2 = w1.shape[1], w2.shape[0]
    eff_k = (3 - 1) * dilation + 1
    mid_spatial = spatial - eff_k + 1
    out_spatial = mid_spatial - eff_k + 1
    d = f"dilations=[{dilation},{dilation}]"
    return _model(
        f"""
        g (float[N,{Cin},{spatial},{spatial}] X) => (float[N,{C2},{out_spatial},{out_spatial}] Y)
        {{
          h = Conv<kernel_shape=[3,3], {d}>(X, W1)
          a = {activation}(h)
          Y = Conv<kernel_shape=[3,3], {d}>(a, W2)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(w2, "W2")],
    )


def test_structured_pruning_conv_chain_with_auto_pad_matches_oracle_exactly():
    # Confirms empirically (not just "in principle") that a non-default
    # auto_pad Conv chain is *already* matched and pruned correctly by
    # apply_structured_pruning -- _match_conv_producer/_match_conv_consumer
    # never inspect that attribute at all (see this module's own docstring
    # and _auto_pad_conv_pair_model above), so there is no restriction here
    # to lift, only this regression test locking the already-correct
    # behavior in place. Same oracle bar as
    # test_structured_pruning_conv_chain_matches_manual_channel_deletion_exactly:
    # exact equivalence, via onnxruntime, to deleting the same output
    # filters by hand -- auto_pad itself must also survive onto both the
    # pruned producer and consumer unchanged for this to pass, since the
    # oracle model carries it too.
    Cin, C1, C2 = 3, 16, 8
    rng = np.random.default_rng(230)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    model = _auto_pad_conv_pair_model(w1, w2)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    keep = _oracle_keep_indices_conv(w1, C1 // 2)
    oracle = _auto_pad_conv_pair_model(w1[keep], w2[:, keep])

    rng_x = np.random.default_rng(231)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_conv_chain_with_dilation_matches_oracle_exactly():
    # The dilation analogue of the auto_pad test above -- same "no
    # restriction to lift, only a regression test locking already-correct
    # behavior in place" bar, this time for a non-unit dilations Conv
    # chain.
    Cin, C1, C2 = 3, 16, 8
    rng = np.random.default_rng(232)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
