def test_structured_pruning_conv_chain_erf_gelu_decomposed_declines_on_branch_fanout():
    # `d` (the gate branch's own `Div` output) is *also* read by a second,
    # spurious consumer (`Extra`, tapped as a second graph output) -- the
    # gate branch is no longer a strict single-consumer chain, so
    # `_walk_gate_branch` must decline the whole diamond outright, leaving
    # both weights completely untouched, never guessed at or partially cut.
    Cin, C1, C2 = 3, 16, 8
    rng = np.random.default_rng(507)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    model = _model(
        f"""
        g (float[N,{Cin},10,10] X) => (float[N,{C2},6,6] Y, float[N,{C1},10,10] Extra)
        <float Sqrt2 = {{1.4142135}}, float One = {{1.0}}, float Half = {{0.5}}>
        {{
          h = Conv<kernel_shape=[3,3]>(X, W1)
          d = Div(h, Sqrt2)
          Extra = Identity(d)
          e = Erf(d)
          ao = Add(e, One)
          m = Mul(h, ao)
          a = Mul(m, Half)
          Y = Conv<kernel_shape=[3,3]>(a, W2)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(w2, "W2")],
    )
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1)
    np.testing.assert_array_equal(inits["W2"], w2)


# --- Decomposed tanh-approximate GELU pass-through, Conv chains ----------
#
# `nn.GELU(approximate="tanh")` -- PyTorch's tanh-approximate/"new GELU",
# used by GPT-2, BERT's `gelu_new`, and any `approximate="tanh"` config --
# decomposes to a structurally distinct shape from either case the self-gated
# activation decomposition section above recognizes: the producer's own raw
# output `h` is read *four* times (not two), confirmed live via
# `torch.onnx.export(nn.Linear/Conv -> nn.GELU(approximate="tanh"), ...,
# opset_version=17, dynamo=False)` -- see `onnxsim/pruning.py`'s own
# "Decomposed tanh-approximate GELU pass-through" section comment for the
# exact node shape and how it was verified. The four scalar constants
# (`0.044715`, `sqrt(2/pi)`, `1.0`, `0.5`) are built as `Constant` nodes here,
# not initializers -- the real exporter's own shape for a literal Python
# scalar (see this file's own "_constant_map" section above), confirming
# that helper resolves them here exactly like it already does for decomposed
# RMSNorm/`Clip`.


def _conv_tanh_gelu_decomposed_pair_model(w1, w2, b1=None, spatial=10):
    Cin, C2 = w1.shape[1], w2.shape[0]
    initializer = [_f32(w1, "W1"), _f32(w2, "W2")]
    if b1 is not None:
        conv1 = "h = Conv<kernel_shape=[3,3]>(X, W1, B1)"
        initializer.append(_f32(b1, "B1"))
    else:
        conv1 = "h = Conv<kernel_shape=[3,3]>(X, W1)"
    out_spatial = spatial - 4
    return _model(
        f"""
        g (float[N,{Cin},{spatial},{spatial}] X) => (float[N,{C2},{out_spatial},{out_spatial}] Y)
        {{
          {conv1}
          x2 = Mul(h, h)
          x3 = Mul(h, x2)
          Cube = Constant<value = float[1] {{0.044715}}>()
          m2 = Mul(Cube, x3)
          inner = Add(h, m2)
          Sqrt2OverPi = Constant<value = float[1] {{0.7978845608}}>()
          arg = Mul(Sqrt2OverPi, inner)
          t = Tanh(arg)
          One = Constant<value = float[1] {{1.0}}>()
          onePlusT = Add(One, t)
          gated = Mul(h, onePlusT)
          Half = Constant<value = float[1] {{0.5}}>()
          a = Mul(Half, gated)
          Y = Conv<kernel_shape=[3,3]>(a, W2)
        }}
        """,
        initializer=initializer,
    )


def test_structured_pruning_conv_chain_tanh_gelu_decomposed_matches_oracle_exactly():
    # Before this hop existed, this exact chain came out completely unpruned
    # end to end -- `h`'s own four reads broke the forward walk's
    # single-consumer-per-tensor assumption outright (and its own two-
    # consumer self-gated-activation dispatch doesn't reach a four-read root
    # either), so the walk never even started.
    Cin, C1, C2 = 3, 16, 8
    rng = np.random.default_rng(521)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    b1 = rng.standard_normal((C1,)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    model = _conv_tanh_gelu_decomposed_pair_model(w1, w2, b1=b1)
    onnx.checker.check_model(model)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    inits = {t.name: t for t in pruned.graph.initializer}
    assert list(inits["W1"].dims) == [C1 // 2, Cin, 3, 3]
    assert list(inits["W2"].dims) == [C2, C1 // 2, 3, 3]
    # The diamond's own nodes (Mul/Add/Tanh/Constant) are untouched -- none
    # of them has a per-channel operand to slice.
    pruned_node_types = sorted(n.op_type for n in pruned.graph.node)
    assert pruned_node_types == sorted(n.op_type for n in model.graph.node)

    keep = _oracle_keep_indices_conv(w1, C1 // 2)
    oracle = _conv_tanh_gelu_decomposed_pair_model(w1[keep], w2[:, keep], b1=b1[keep])

    rng_x = np.random.default_rng(522)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    assert np.isfinite(y).all()
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_conv_chain_tanh_gelu_decomposed_declines_on_nonconstant_scalar():
    # `Cube` (the cubic term's own scale) fed by a non-constant node (an
    # `Identity` of a graph input) rather than a genuine constant -- this
    # pass cannot confirm it's a channel-agnostic scalar without evaluating
    # the graph, so the whole diamond must decline outright, leaving both
    # weights completely untouched.
    Cin, C1, C2 = 3, 16, 8
    rng = np.random.default_rng(523)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    model = _model(
        f"""
        g (float[N,{Cin},10,10] X, float CubeIn) => (float[N,{C2},6,6] Y)
        <float Sqrt2OverPi = {{0.7978845608}}, float One = {{1.0}}, float Half = {{0.5}}>
        {{
          h = Conv<kernel_shape=[3,3]>(X, W1)
          x2 = Mul(h, h)
          x3 = Mul(h, x2)
          Cube = Identity(CubeIn)
          m2 = Mul(Cube, x3)
          inner = Add(h, m2)
          arg = Mul(Sqrt2OverPi, inner)
          t = Tanh(arg)
          onePlusT = Add(One, t)
          gated = Mul(h, onePlusT)
          a = Mul(Half, gated)
          Y = Conv<kernel_shape=[3,3]>(a, W2)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(w2, "W2")],
    )
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1)
    np.testing.assert_array_equal(inits["W2"], w2)


# --- Conv1d / Conv3d / ConvTranspose structural pruning ------------------
#
# _match_conv_producer/_match_conv_consumer/_match_depthwise_conv_pass_through
# only ever check the matched weight's own *rank* (>= 3: one output-channel
# axis, one input-channel axis, at least one spatial axis) -- never a
# fixed spatial rank of 2 -- and every slicing/importance computation they
# feed (_slice_producer_weight/_slice_consumer_weight/_producer_weight_nk)
# already only ever touches the channel axis via `...`/`-1`, leaving
# whatever spatial axes are there alone. So a 1-D Conv (`[out, in, k]`) or
# a 3-D Conv (`[out, in, kd, kh, kw]`) is matched, sliced, and re-run by
# exactly the same code path as every 2-D Conv chain test above -- these
# are regression tests locking that already-general behavior in place, the
# same bar test_structured_pruning_conv_chain_with_auto_pad_matches_oracle_exactly/
# test_structured_pruning_conv_chain_with_dilation_matches_oracle_exactly
# hold for auto_pad/dilations.
#
# ConvTranspose support is new machinery, not a side effect of the rank
# relaxation above: its own weight layout is `[in_channels,
# out_channels/group, k1, ..., kn]` -- confirmed live via
# `onnx.defs.get_schema("ConvTranspose")` -- the reverse of Conv's
# `[out_channels, in_channels/group, ...]`, so a ConvTranspose producer's
# own output channels live on axis 1 (not axis 0) and a ConvTranspose
# consumer's own input channels live on axis 0 (not axis 1). Only ordinary
# (`group == 1`) ConvTranspose is matched as a *producer* (see
# _match_conv_transpose_producer's own docstring for why grouped stays
# declined); any `group >= 1` is matched as a *consumer* (see
# _match_conv_transpose_consumer's own docstring for why that side is safe
# unconditionally). Both roles are exercised below, each with deliberately
# distinct channel counts on every axis (`Cin`, `M`, `keep_count` all
# different) so a channel-role-reversal bug -- slicing axis 0 instead of 1,
# or vice versa -- would produce a detectably wrong shape (onnxruntime
# itself would refuse to run the mismatched graph) or wrong numeric values,
# never a silent no-op.


def _conv1d_pair_model(w1, w2, b1=None, spatial=20, activation="Relu"):
    Cin, C2 = w1.shape[1], w2.shape[0]
    initializer = [_f32(w1, "W1"), _f32(w2, "W2")]
    if b1 is not None:
        conv1 = "h = Conv<kernel_shape=[3]>(X, W1, B1)"
        initializer.append(_f32(b1, "B1"))
    else:
        conv1 = "h = Conv<kernel_shape=[3]>(X, W1)"
    out_spatial = spatial - 4  # two valid (no-pad) size-3 convs
    return _model(
        f"""
        g (float[N,{Cin},{spatial}] X) => (float[N,{C2},{out_spatial}] Y)
        {{
          {conv1}
          a = {activation}(h)
          Y = Conv<kernel_shape=[3]>(a, W2)
        }}
        """,
        initializer=initializer,
    )


def test_structured_pruning_conv1d_chain_matches_oracle_exactly():
    Cin, C1, C2 = 3, 16, 8
    rng = np.random.default_rng(340)
    w1 = rng.standard_normal((C1, Cin, 3)).astype(np.float32)
    b1 = rng.standard_normal((C1,)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3)).astype(np.float32)
    model = _conv1d_pair_model(w1, w2, b1=b1)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    inits = {t.name: t for t in pruned.graph.initializer}
    assert list(inits["W1"].dims) == [C1 // 2, Cin, 3]
    assert list(inits["W2"].dims) == [C2, C1 // 2, 3]

    keep = _oracle_keep_indices_conv(w1, C1 // 2)
    oracle = _conv1d_pair_model(w1[keep], w2[:, keep], b1=b1[keep])

    rng_x = np.random.default_rng(341)
    x = rng_x.standard_normal((2, Cin, 20)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def _conv3d_pair_model(w1, w2, spatial=10, activation="Relu"):
    Cin, C2 = w1.shape[1], w2.shape[0]
    out_spatial = spatial - 4  # two valid (no-pad) 3x3x3 convs
    return _model(
        f"""
        g (float[N,{Cin},{spatial},{spatial},{spatial}] X)
            => (float[N,{C2},{out_spatial},{out_spatial},{out_spatial}] Y)
        {{
          h = Conv<kernel_shape=[3,3,3]>(X, W1)
          a = {activation}(h)
          Y = Conv<kernel_shape=[3,3,3]>(a, W2)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(w2, "W2")],
    )


def test_structured_pruning_conv3d_chain_matches_oracle_exactly():
    Cin, C1, C2 = 2, 8, 4
    rng = np.random.default_rng(342)
    w1 = rng.standard_normal((C1, Cin, 3, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3, 3)).astype(np.float32)
    model = _conv3d_pair_model(w1, w2)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    inits = {t.name: t for t in pruned.graph.initializer}
    assert list(inits["W1"].dims) == [C1 // 2, Cin, 3, 3, 3]
    assert list(inits["W2"].dims) == [C2, C1 // 2, 3, 3, 3]

    keep = _oracle_keep_indices_conv(w1, C1 // 2)
    oracle = _conv3d_pair_model(w1[keep], w2[:, keep])

    rng_x = np.random.default_rng(343)
    x = rng_x.standard_normal((2, Cin, 10, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def _conv_transpose_then_conv_model(w_ct, w2, spatial=10):
    # ConvTranspose *producer* -> Conv consumer: w_ct is [Cin, M, kH, kW]
    # (ConvTranspose's own reversed layout), M -- axis 1 -- is what gets
    # pruned. w2 is an ordinary Conv's [Cout, M, kH, kW] weight, consuming
    # M on its own (ordinary) axis 1.
    Cin = w_ct.shape[0]
    Cout = w2.shape[0]
    mid_spatial = spatial + 2  # ConvTranspose, unit stride, valid: in - 1 + k
    out_spatial = mid_spatial - 2  # following Conv, valid 3x3
    return _model(
        f"""
        g (float[N,{Cin},{spatial},{spatial}] X) => (float[N,{Cout},{out_spatial},{out_spatial}] Y)
        {{
          h = ConvTranspose<kernel_shape=[3,3]>(X, WCT)
          a = Relu(h)
          Y = Conv<kernel_shape=[3,3]>(a, W2)
        }}
        """,
        initializer=[_f32(w_ct, "WCT"), _f32(w2, "W2")],
    )


def test_structured_pruning_conv_transpose_producer_matches_oracle_exactly():
    # ConvTranspose acting as a *producer*: its own output channels (M,
    # axis 1 of its [Cin, M, kH, kW] weight -- the reverse of an ordinary
    # Conv producer's axis 0) are pruned and must be sliced off axis 1, not
    # axis 0. Cin, M, and keep_count are all deliberately distinct (5, 8,
    # 4) so a reversed-axis bug -- slicing the wrong, wrongly-sized axis --
    # would produce a shape onnxruntime itself refuses to run the pruned
    # graph with, not a silently-plausible wrong answer.
    Cin, M, Cout = 5, 8, 6
    rng = np.random.default_rng(344)
    w_ct = rng.standard_normal((Cin, M, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((Cout, M, 3, 3)).astype(np.float32)
    model = _conv_transpose_then_conv_model(w_ct, w2)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    keep_count = M - round(M * 0.5)
    inits = {t.name: t for t in pruned.graph.initializer}
    assert list(inits["WCT"].dims) == [Cin, keep_count, 3, 3]
    assert list(inits["W2"].dims) == [Cout, keep_count, 3, 3]

    # Oracle keep-set: ConvTranspose's own "N,K" importance view moves its
    # output-channel axis (1) to the front before ranking, mirroring
    # _producer_weight_nk's own convention.
    w_ct_nk = np.moveaxis(w_ct, 1, 0).reshape(M, -1).astype(np.float64)
    importance = np.linalg.norm(w_ct_nk, axis=1)
    keep = np.sort(np.argsort(-importance)[:keep_count])
    oracle = _conv_transpose_then_conv_model(w_ct[:, keep], w2[:, keep])

    rng_x = np.random.default_rng(345)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def _conv_then_conv_transpose_model(w1, w_ct, spatial=10):
    # Conv producer -> ConvTranspose *consumer*: w1 is an ordinary Conv's
    # [C1, Cin, kH, kW] weight (C1, axis 0, pruned as always); w_ct is
    # ConvTranspose's own reversed [C1, Cout, kH, kW] weight, consuming C1
    # on its own axis 0 -- the reverse of an ordinary Conv consumer's
    # axis 1.
    Cin = w1.shape[1]
    Cout = w_ct.shape[1]
    mid_spatial = spatial - 2  # producer Conv, valid 3x3
    out_spatial = mid_spatial + 2  # ConvTranspose, unit stride, valid
    return _model(
        f"""
        g (float[N,{Cin},{spatial},{spatial}] X) => (float[N,{Cout},{out_spatial},{out_spatial}] Y)
        {{
          h = Conv<kernel_shape=[3,3]>(X, W1)
          a = Relu(h)
          Y = ConvTranspose<kernel_shape=[3,3]>(a, WCT)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(w_ct, "WCT")],
    )


def test_structured_pruning_conv_transpose_consumer_matches_oracle_exactly():
    # ConvTranspose acting as a *consumer*: its own input channels (axis 0
    # of its [C1, Cout, kH, kW] weight -- the reverse of an ordinary Conv
    # consumer's axis 1) must be sliced to match the upstream Conv
    # producer's own kept output channels. Cin, C1, Cout, and keep_count
    # are all deliberately distinct (3, 8, 6, 4) for the same
    # reversed-axis-detectability reason as the producer test above.
    Cin, C1, Cout = 3, 8, 6
    rng = np.random.default_rng(346)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w_ct = rng.standard_normal((C1, Cout, 3, 3)).astype(np.float32)
    model = _conv_then_conv_transpose_model(w1, w_ct)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    keep_count = C1 - round(C1 * 0.5)
    inits = {t.name: t for t in pruned.graph.initializer}
    assert list(inits["W1"].dims) == [keep_count, Cin, 3, 3]
    assert list(inits["WCT"].dims) == [keep_count, Cout, 3, 3]

    keep = _oracle_keep_indices_conv(w1, keep_count)
    oracle = _conv_then_conv_transpose_model(w1[keep], w_ct[keep])

    rng_x = np.random.default_rng(347)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_grouped_conv_transpose_consumer_matches_oracle_exactly():
    # A grouped (group > 1) ConvTranspose consumer is matched for any
    # group (unlike the producer side, restricted to group == 1 -- see
    # _match_conv_transpose_consumer's own docstring): its own
    # input-channel axis (0) already spans the *full* in_channels
    # regardless of group, so pruning it is the same flat `w[keep, ...]`
    # slice as the group == 1 case, with `_apply_chains`'s existing
    # per-group-block top-k (driven by _chain_group, keyed on this
    # ConvTranspose's own `group` attribute) choosing a uniform keep count
    # per block so the pruned node's own `in_channels % group == 0`
    # invariant survives.
    Cin, C1, Cout, group = 3, 8, 6, 2
    rng = np.random.default_rng(348)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w_ct = rng.standard_normal((C1, Cout // group, 3, 3)).astype(np.float32)
    model = _model(
        f"""
        g (float[N,{Cin},10,10] X) => (float[N,{Cout},10,10] Y)
        {{
          h = Conv<kernel_shape=[3,3]>(X, W1)
          a = Relu(h)
          Y = ConvTranspose<kernel_shape=[3,3], group={group}>(a, WCT)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(w_ct, "WCT")],
    )

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    block = C1 // group
    per_group_keep = max(1, round(block * 0.5))
    keep_count = per_group_keep * group
    inits = {t.name: t for t in pruned.graph.initializer}
    assert list(inits["W1"].dims) == [keep_count, Cin, 3, 3]
    assert list(inits["WCT"].dims) == [keep_count, Cout // group, 3, 3]
    ct_node = next(n for n in pruned.graph.node if "WCT" in n.input)
    group_attr = next(a for a in ct_node.attribute if a.name == "group")
    assert group_attr.i == group  # group itself is unchanged by consumer pruning

    importance = np.linalg.norm(w1.reshape(C1, -1).astype(np.float64), axis=1)
    keep = np.sort(
        np.concatenate(
            [
                np.argsort(-importance[g * block : (g + 1) * block])[:per_group_keep]
                + g * block
                for g in range(group)
            ]
        )
    )
    oracle = _model(
        f"""
        g (float[N,{Cin},10,10] X) => (float[N,{Cout},10,10] Y)
        {{
          h = Conv<kernel_shape=[3,3]>(X, W1)
          a = Relu(h)
          Y = ConvTranspose<kernel_shape=[3,3], group={group}>(a, WCT)
        }}
        """,
        initializer=[_f32(w1[keep], "W1"), _f32(w_ct[keep], "WCT")],
    )

    rng_x = np.random.default_rng(349)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_grouped_conv_transpose_producer_is_left_untouched():
    # The mirror image of test_structured_pruning_skips_grouped_producer_conv:
    # a grouped (group > 1) ConvTranspose is never matched as a *producer*
    # (see _match_conv_transpose_producer's own docstring for why -- a
    # scope decision, not an oversight), so a chain that would otherwise
    # look matchable is left completely untouched rather than guessed at.
    Cin, M, group, Cout = 4, 8, 2, 6
    rng = np.random.default_rng(350)
    w_ct = rng.standard_normal((Cin, M // group, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((Cout, M, 3, 3)).astype(np.float32)
    model = _model(
        f"""
        g (float[N,{Cin},10,10] X) => (float[N,{Cout},6,6] Y)
        {{
          h = ConvTranspose<kernel_shape=[3,3], group={group}>(X, WCT)
          a = Relu(h)
          Y = Conv<kernel_shape=[3,3]>(a, W2)
        }}
        """,
        initializer=[_f32(w_ct, "WCT"), _f32(w2, "W2")],
    )
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["WCT"], w_ct)
    np.testing.assert_array_equal(inits["W2"], w2)


def test_structured_wanda_pruning_conv_transpose_producer_matches_oracle_exactly():
    # apply_structured_wanda_pruning shares _apply_chains/_apply_chains_global
    # (and _producer_weight_nk's own is_conv_transpose-aware axis-1 view)
    # with apply_structured_pruning -- this locks in that a ConvTranspose
    # producer chain is ranked and pruned correctly by the calibrated
    # ||W_row||_2 * ||X||_2 metric too, not just plain L2 weight norm.
    Cin, M, Cout = 5, 8, 6
    rng = np.random.default_rng(351)
    w_ct = rng.standard_normal((Cin, M, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((Cout, M, 3, 3)).astype(np.float32)
    model = _conv_transpose_then_conv_model(w_ct, w2)

    probe_model = onnx.ModelProto()
    probe_model.CopyFrom(model)
    probe_model.graph.output.append(
        onnx.helper.make_tensor_value_info("a", onnx.TensorProto.FLOAT, None)
    )
    rng_cal = np.random.default_rng(352)
    x_cal = rng_cal.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    calibration_data = [{"X": x_cal}]

    _, a_cal = _run(probe_model, {"X": x_cal})
    act_norm = np.sqrt(np.mean(np.square(a_cal.astype(np.float64)), axis=(0, 2, 3)))
    w_ct_nk = np.moveaxis(w_ct, 1, 0).reshape(M, -1).astype(np.float64)
    importance = np.linalg.norm(w_ct_nk, axis=1) * np.maximum(act_norm, 1e-8)
    keep_count = M - round(M * 0.5)
    keep = np.sort(np.argsort(-importance)[:keep_count])

    pruned = onnxsim.apply_structured_wanda_pruning(
        model, calibration_data=calibration_data, sparsity=0.5
    )
    onnx.checker.check_model(pruned)

    oracle = _conv_transpose_then_conv_model(w_ct[:, keep], w2[:, keep])
    rng_x = np.random.default_rng(353)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_conv_only_chain_matches_oracle_no_bias():
    # No Conv bias at all, and a non-Relu activation -- a plain
    # Conv -> Sigmoid -> Conv chain.
    Cin, C1, C2 = 4, 12, 6
    rng = np.random.default_rng(32)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    model = _conv_pair_model(w1, w2, activation="Sigmoid")

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.25)
    onnx.checker.check_model(pruned)

    keep = _oracle_keep_indices_conv(w1, C1 - round(C1 * 0.25))
    oracle = _conv_pair_model(w1[keep], w2[:, keep], activation="Sigmoid")

    rng_x = np.random.default_rng(33)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_skips_grouped_producer_conv():
    # A depthwise Conv (group == in_channels == out_channels) is never
    # itself matched as a producer -- it's only ever a transparent
    # pass-through hop the chain walk may cross between two real
    # producer/consumer boundaries (see the "depthwise_pass_through" tests
    # above). With nothing upstream of it here, there's no real producer to
    # anchor a chain at all, so both layers stay completely untouched, even
    # though the topology otherwise looks identical to a matched pair.
    C = 8
    rng = np.random.default_rng(34)
    w1 = rng.standard_normal((C, 1, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C, C, 3, 3)).astype(np.float32)
    model = _model(
        f"""
        g (float[N,{C},10,10] X) => (float[N,{C},6,6] Y)
        {{
          h = Conv<kernel_shape=[3,3], group={C}>(X, W1)
          a = Relu(h)
          Y = Conv<kernel_shape=[3,3]>(a, W2)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(w2, "W2")],
    )
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1)
    np.testing.assert_array_equal(inits["W2"], w2)


def test_structured_pruning_skips_grouped_consumer_conv():
    # A depthwise Conv is likewise never matched as a *consumer* -- when
    # its own output feeds a graph output (as here) rather than a further
    # real Conv, crossing it as a pass-through hop simply runs out of chain
    # to walk (see "depthwise Conv ... last node before a graph output" in
    # this module's own docstring), so the walk finds no real consumer and
    # the whole chain -- producer included -- is left untouched.
    Cin, C1 = 3, 8
    rng = np.random.default_rng(35)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C1, 1, 3, 3)).astype(np.float32)  # depthwise consumer
    model = _model(
        f"""
        g (float[N,{Cin},10,10] X) => (float[N,{C1},6,6] Y)
        {{
          h = Conv<kernel_shape=[3,3]>(X, W1)
          a = Relu(h)
          Y = Conv<kernel_shape=[3,3], group={C1}>(a, W2)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(w2, "W2")],
    )
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1)
    np.testing.assert_array_equal(inits["W2"], w2)


def _grouped_conv_pair_model(
    w1, w2, group1=1, group2=1, b1=None, spatial=10, activation="Relu"
):
    """`_conv_pair_model`, extended with an explicit ``group`` attribute on
    each Conv -- lets the same oracle-comparison-via-onnxruntime pattern
    used throughout this section cover a general grouped Conv producer
    (`group1`) and/or consumer (`group2`), not just the ``group=1`` case
    `_conv_pair_model` builds. `w1`'s shape must already be
    ``[C1, Cin/group1, kH, kW]`` and `w2`'s ``[C2, C1/group2, kH, kW]`` --
    same caller-responsibility convention `_conv_pair_model` already has for
    the two weights' shapes lining up.
    """
    Cin, C2 = w1.shape[1] * group1, w2.shape[0]
    initializer = [_f32(w1, "W1"), _f32(w2, "W2")]
    g1 = f", group={group1}" if group1 != 1 else ""
    g2 = f", group={group2}" if group2 != 1 else ""
    if b1 is not None:
        conv1 = f"h = Conv<kernel_shape=[3,3]{g1}>(X, W1, B1)"
        initializer.append(_f32(b1, "B1"))
    else:
        conv1 = f"h = Conv<kernel_shape=[3,3]{g1}>(X, W1)"
    out_spatial = spatial - 4  # two valid (no-pad) 3x3 convs
    return _model(
        f"""
        g (float[N,{Cin},{spatial},{spatial}] X) => (float[N,{C2},{out_spatial},{out_spatial}] Y)
        {{
          {conv1}
          a = {activation}(h)
          Y = Conv<kernel_shape=[3,3]{g2}>(a, W2)
        }}
        """,
        initializer=initializer,
    )


def _oracle_keep_indices_conv_grouped(w, group, sparsity):
    """The per-group analogue of `_oracle_keep_indices_conv`: ranks each of
    `group` equal-sized blocks of output filters (`w`'s axis 0) by L2 norm
    *independently*, keeping the same count from every block -- a from-
    scratch reimplementation of the production per-group selection in
    `_apply_chains`/`_chain_group`, not a call into it, so this stays a real
    check on the algorithm rather than the algorithm checking itself.
    """
    out_channels = w.shape[0]
    block = out_channels // group
    per_group_keep = max(1, round(block * (1.0 - sparsity)))
    parts = []
    for gi in range(group):
        lo, hi = gi * block, (gi + 1) * block
        parts.append(_oracle_keep_indices_conv(w[lo:hi], per_group_keep) + lo)
    return np.concatenate(parts)


def _oracle_slice_grouped_consumer_conv(w2, keep, group, n_channels):
    """The per-group analogue of the ordinary `w2[:, keep]` consumer slice:
    a grouped consumer's axis 1 is only `n_channels / group` wide and
    per-group-relative (weight column `j` on a filter in output-group `g`
    means global input channel `g * block + j`), so each output-filter
    group needs its own local slice of `keep` -- translated from global
    indices back to that group's own local ones -- rather than one global
    index set applied to the whole axis. A from-scratch reimplementation of
    `_slice_grouped_consumer_conv_weight`, for the same reason
    `_oracle_keep_indices_conv_grouped` reimplements the selection side.
    """
    out_channels = w2.shape[0]
    out_per_group = out_channels // group
    block = n_channels // group
    parts = []
    for gi in range(group):
        lo, hi = gi * block, (gi + 1) * block
        local_keep = keep[(keep >= lo) & (keep < hi)] - lo
        parts.append(w2[gi * out_per_group : (gi + 1) * out_per_group][:, local_keep])
    return np.concatenate(parts, axis=0)


def test_structured_pruning_general_grouped_producer_conv_prunes_per_group_independently():
    # A general grouped Conv producer (group=2, neither 1 nor its own
    # channel count) feeding an ordinary consumer. Per this module's own
    # docstring, a grouped Conv splits its output channels into `group`
    # equal blocks that must each be ranked and pruned *independently*,
    # keeping the same count per block (so `out_channels % group == 0`
    # survives). Engineer block 0's filters (indices 0-3) to all have a far
    # larger L2 norm than every filter in block 1 (indices 4-7): a *global*
    # top-k over all 8 filters would keep every one of block 0's filters and
    # none of block 1's, leaving block 1 with zero survivors -- violating
    # its own group structure. The correct per-group behavior instead keeps
    # each block's own top half, which -- given this engineered disparity
    # -- provably differs from the global top-k.
    Cin, C1, C2, group = 4, 8, 4, 2
    rng = np.random.default_rng(80)
    w1 = rng.standard_normal((C1, Cin // group, 3, 3)).astype(np.float32)
    w1[:4] *= 10.0  # block 0 dominates block 1
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    model = _grouped_conv_pair_model(w1, w2, group1=group)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    keep_grouped = _oracle_keep_indices_conv_grouped(w1, group, 0.5)
    keep_global = _oracle_keep_indices_conv(w1, 4)
    assert list(keep_grouped) != list(keep_global)  # sanity: the engineered
    # disparity really does make per-group and global selection disagree
    assert sum(i < 4 for i in keep_grouped) == 2  # exactly half of block 0 ...
    assert sum(i >= 4 for i in keep_grouped) == 2  # ... and half of block 1

    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1[keep_grouped])
    dw_node = next(n for n in pruned.graph.node if "W1" in n.input)
    group_attr = next(a.i for a in dw_node.attribute if a.name == "group")
    assert group_attr == group  # the group count itself never shrinks

    oracle = _grouped_conv_pair_model(
        w1[keep_grouped], w2[:, keep_grouped], group1=group
    )
    rng_x = np.random.default_rng(81)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_general_grouped_consumer_conv_matches_manual_channel_deletion_exactly():
    # A general grouped Conv consumer (group=2): the shared dimension being
    # pruned is the consumer's own *input* channel axis, but that axis is
    # per-group-relative in a grouped Conv's weight layout ([out_channels,
    # in_channels/group, kH, kW]) -- weight column j on an output filter in
    # group g means global input channel g*(in_channels/group) + j, not
    # global channel j the way an ordinary (group=1) consumer's flat axis
    # works. This is the part of grouped-Conv support that needs real new
    # slicing logic (_slice_grouped_consumer_conv_weight), exercised here
    # with block 0 given a far larger weight norm than block 1 so the two
    # blocks' independently-selected local keep sets aren't trivially
    # identical on both sides.
    Cin, C1, C2, group = 3, 8, 6, 2
    rng = np.random.default_rng(82)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w1[:4] *= 8.0  # block 0 dominates block 1
    w2 = rng.standard_normal((C2, C1 // group, 3, 3)).astype(np.float32)
    model = _grouped_conv_pair_model(w1, w2, group2=group)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    keep = _oracle_keep_indices_conv_grouped(w1, group, 0.5)
    w2_sliced = _oracle_slice_grouped_consumer_conv(w2, keep, group, C1)

    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1[keep])
    np.testing.assert_array_equal(inits["W2"], w2_sliced)

    oracle = _grouped_conv_pair_model(w1[keep], w2_sliced, group2=group)
    rng_x = np.random.default_rng(83)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_both_sides_grouped_matching_group_count_matches_oracle():
    # Both producer and consumer are general grouped Convs, sharing the
    # exact same `group` count -- the one cross-chain composition this pass
    # supports when *both* sides are grouped (see this module's own
    # docstring): the producer's own per-group keep selection (uniform
    # count per block, by construction) already lines up exactly with the
    # consumer's own group boundaries, since both partition the same
    # `n_channels` into the same number of equal contiguous blocks.
    Cin, C1, C2, group = 4, 8, 6, 2
    rng = np.random.default_rng(84)
    w1 = rng.standard_normal((C1, Cin // group, 3, 3)).astype(np.float32)
    w1[:4] *= 6.0
    w2 = rng.standard_normal((C2, C1 // group, 3, 3)).astype(np.float32)
    model = _grouped_conv_pair_model(w1, w2, group1=group, group2=group)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    keep = _oracle_keep_indices_conv_grouped(w1, group, 0.5)
    w2_sliced = _oracle_slice_grouped_consumer_conv(w2, keep, group, C1)
    oracle = _grouped_conv_pair_model(w1[keep], w2_sliced, group1=group, group2=group)

    rng_x = np.random.default_rng(85)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_skips_mismatched_grouped_producer_and_consumer():
    # Producer group=2, consumer group=4: both sides grouped, but with a
    # *different* group count. Per this module's own docstring, both sides
    # grouped is only supported when the group counts match -- otherwise
    # the two sides' block boundaries wouldn't generally align (a channel
    # surviving as "the 2nd of the producer's own group" has no
    # well-defined membership in any of the consumer's differently-sized
    # groups), so this composition is declined outright and the whole
    # chain -- both layers -- is left completely untouched, not partially
    # or incorrectly pruned.
    Cin, C1, C2, gp, gc = 4, 8, 8, 2, 4
    rng = np.random.default_rng(86)
    w1 = rng.standard_normal((C1, Cin // gp, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1 // gc, 3, 3)).astype(np.float32)
    model = _grouped_conv_pair_model(w1, w2, group1=gp, group2=gc)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1)
    np.testing.assert_array_equal(inits["W2"], w2)


def test_structured_pruning_conv_into_non_pass_through_op_is_left_untouched():
    # A `Flatten` reading off a plain Conv's own output, with real spatial
    # extent still present (a 3x3-kernel Conv over a 10x10 input leaves an
    # 8x8 feature map, not collapsed to 1x1 the way `GlobalAveragePool`'s own
    # output always is) -- the *general* `Flatten` shape this module's own
    # docstring and `_CONV_POOL_PASS_THROUGH`'s own comment call out as
    # deliberately excluded: a flattened MatMul's input columns would need to
    # be re-derived through `Flatten`'s exact memory layout, a fundamentally
    # different, harder problem than the plain axis slice every hop here
    # performs, since a flattened column mixes multiple spatial positions of
    # one channel together, not a clean per-channel block. (See
    # `test_structured_pruning_global_average_pool_flatten_gemm_pass_through_matches_oracle_exactly`
    # below for the one narrow case that *is* handled: `Flatten(axis=1)`
    # reading directly off `GlobalAveragePool`'s own output, where every
    # spatial position is already collapsed to size 1 and there is nothing
    # left to re-derive.) So the walk still stops at this `Flatten`, and the
    # Conv producer is left completely untouched rather than matched to the
    # MatMul by coincidence of a downstream reduction dimension.
    Cin, C1, Out = 3, 8, 4
    rng = np.random.default_rng(36)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C1 * 8 * 8, Out)).astype(np.float32)
    model = _model(
        f"""
        g (float[N,{Cin},10,10] X) => (float[N,{Out}] Y)
        {{
          h = Conv<kernel_shape=[3,3]>(X, W1)
          f = Flatten<axis=1>(h)
          Y = MatMul(f, W2)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(w2, "W2")],
    )
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1)
    np.testing.assert_array_equal(inits["W2"], w2)


def test_structured_pruning_conv_chain_scale_between_convs_is_left_untouched():
    # A per-channel Mul (e.g. an un-fused BatchNormalization's scale, or a
    # standalone SE-style gate) between two Convs isn't recognized -- unlike
    # the MatMul/Gemm chain walk, which does allow Add/Mul against a
    # per-channel constant. See this module's own docstring for why Conv
    # chains restrict to unary activations only (a real Conv already
    # carries its own bias, and onnxsim's own default optimization fuses
    # BatchNormalization into the preceding Conv before this pass would
    # ever see it).
    Cin, C1, C2 = 3, 8, 4
    rng = np.random.default_rng(37)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    scale = rng.standard_normal((1, C1, 1, 1)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    model = _model(
        f"""
        g (float[N,{Cin},10,10] X) => (float[N,{C2},6,6] Y)
        {{
          h = Conv<kernel_shape=[3,3]>(X, W1)
          s = Mul(h, Scale)
          a = Relu(s)
          Y = Conv<kernel_shape=[3,3]>(a, W2)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(scale, "Scale"), _f32(w2, "W2")],
    )
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1)
    np.testing.assert_array_equal(inits["W2"], w2)


def _group_norm_conv_pair_model(
    w1, w2, gn_scale, gn_bias, num_groups, group1=1, b1=None, spatial=10
):
    """The mid-chain-``GroupNormalization`` analogue of `_conv_pair_model`/
    `_grouped_conv_pair_model`: a `GroupNormalization` node (opset 21+
    per-channel `scale`/`bias` schema -- `_model`'s own default `opset=21`)
    sits between the two Convs. `group1`, like `_grouped_conv_pair_model`'s
    own parameter of the same name, makes the producer Conv itself a
    general grouped Conv when != 1 (`w1`'s shape must already be
    ``[C1, Cin/group1, kH, kW]``), so the same builder covers both the
    plain pass-through chain and the producer-group/`num_groups` mismatch
    case.
    """
    Cin, C2 = w1.shape[1] * group1, w2.shape[0]
    initializer = [
        _f32(w1, "W1"),
        _f32(w2, "W2"),
        _f32(gn_scale, "GNScale"),
        _f32(gn_bias, "GNBias"),
    ]
    g1 = f", group={group1}" if group1 != 1 else ""
    if b1 is not None:
        conv1 = f"h = Conv<kernel_shape=[3,3]{g1}>(X, W1, B1)"
        initializer.append(_f32(b1, "B1"))
    else:
        conv1 = f"h = Conv<kernel_shape=[3,3]{g1}>(X, W1)"
    out_spatial = spatial - 4  # two valid (no-pad) 3x3 convs
    return _model(
        f"""
        g (float[N,{Cin},{spatial},{spatial}] X) => (float[N,{C2},{out_spatial},{out_spatial}] Y)
        {{
          {conv1}
          gn = GroupNormalization<num_groups={num_groups}, epsilon=1e-05>(h, GNScale, GNBias)
          Y = Conv<kernel_shape=[3,3]>(gn, W2)
        }}
        """,
        initializer=initializer,
    )


def test_structured_pruning_group_norm_pass_through_matches_oracle_exactly():
    # THE key correctness bar for the GroupNorm pass-through hop, same as
    # every other Conv-chain hop's own oracle test: exact equivalence
    # (float32 noise only) to an independently, already-pruned reference
    # model -- not "close", and not "matches the un-pruned model's own
    # output sliced after the fact" (see `_GROUP_NORM_PASS_THROUGH_OP`'s own
    # comment for why the latter genuinely differs and is not the bar this
    # hop is held to). `_oracle_keep_indices_conv_grouped` is the identical
    # per-group L2-norm top-k `_apply_chains`/`_chain_group` itself uses
    # once `num_groups` becomes the chain's own `group` -- reimplemented
    # from scratch here, not called into, so this is a real check on the
    # algorithm.
    Cin, C1, C2, num_groups = 3, 16, 8, 4
    rng = np.random.default_rng(50)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    b1 = rng.standard_normal((C1,)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    gn_scale = rng.standard_normal((C1,)).astype(np.float32)
    gn_bias = rng.standard_normal((C1,)).astype(np.float32)
    model = _group_norm_conv_pair_model(w1, w2, gn_scale, gn_bias, num_groups, b1=b1)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    dims_after = _initializer_dims(pruned)
    # `num_groups` (a node attribute, not a tensor) is unchanged; the
    # surviving channel count must still divide it evenly.
    assert dims_after["W1"][0] % num_groups == 0
    assert dims_after["W1"][0] < C1  # actually pruned, not a no-op

    keep = _oracle_keep_indices_conv_grouped(w1, num_groups, 0.5)
    oracle = _group_norm_conv_pair_model(
        w1[keep], w2[:, keep], gn_scale[keep], gn_bias[keep], num_groups, b1=b1[keep]
    )

    rng_x = np.random.default_rng(51)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_group_norm_num_groups_mismatch_with_grouped_conv_declines():
    # A mid-chain GroupNorm hop's own `num_groups` disagreeing with a
    # same-chain grouped Conv producer's own `group` -- the two partitions'
    # block boundaries wouldn't generally align (uniform-per-block pruning
    # under one partition needn't be uniform-per-block under the other), so
    # the whole chain is declined outright, never guessed at, the same bar
    # a producer_group != consumer_group mismatch already gets.
    Cin, C1, C2, group1, num_groups = 4, 8, 8, 2, 4
    rng = np.random.default_rng(52)
    w1 = rng.standard_normal((C1, Cin // group1, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    gn_scale = rng.standard_normal((C1,)).astype(np.float32)
    gn_bias = rng.standard_normal((C1,)).astype(np.float32)
    model = _group_norm_conv_pair_model(
        w1, w2, gn_scale, gn_bias, num_groups, group1=group1
    )

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1)
    np.testing.assert_array_equal(inits["W2"], w2)
    np.testing.assert_array_equal(inits["GNScale"], gn_scale)
    np.testing.assert_array_equal(inits["GNBias"], gn_bias)


def test_analyze_structured_pruning_group_norm_pass_through_matches_real_call():
    # Dry-run/real-call cross-check for the GroupNorm hop specifically: both
    # `_apply_chains` and its dry-run mirror `_analyze_chains` share
    # `_chain_group` (and, via `_chain_group_norm_consts`, the same
    # touched-role bookkeeping), so a mismatch here would mean the mirror
    # drifted out of sync with the real call -- this module's own
    # established discipline treats that as a real bug.
    Cin, C1, C2, num_groups = 3, 16, 8, 4
    rng = np.random.default_rng(53)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    gn_scale = rng.standard_normal((C1,)).astype(np.float32)
    gn_bias = rng.standard_normal((C1,)).astype(np.float32)
    model = _group_norm_conv_pair_model(w1, w2, gn_scale, gn_bias, num_groups)

    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_structured_pruning, sparsity=0.5
    )
    assert len(report.layers) == 1
    layer = report.layers[0]
    assert layer.family == "conv_plain"
    assert layer.total == C1

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    dims_after = _initializer_dims(pruned)
    kept = C1 - layer.would_drop
    assert dims_after["W1"][0] == kept
    assert dims_after["W2"][1] == kept
    assert dims_after["GNScale"][0] == kept
    assert dims_after["GNBias"][0] == kept


# --- Conv chain: InstanceNormalization pass-through hop ---------------------
#
# `InstanceNormalization` (plain ONNX, standard domain) is a *second*
# mid-chain norm hop, alongside `GroupNormalization` above -- but, unlike
# GroupNorm, carries no `num_groups`/uniform-per-block constraint at all:
# its own mean/variance are computed per instance *per channel*, never
# pooled across a group, so an arbitrary channel subset may be kept/dropped
# with no group-boundary-drift risk to guard against. See
# `_INSTANCE_NORM_PASS_THROUGH_OP`'s own comment for the full reasoning and
# empirical confirmation (`0.0` max abs diff commuting with channel slicing,
# vs. GroupNorm's own ~0.42 divergence for a same-shape example).


def _instance_norm_conv_pair_model(w1, w2, in_scale, in_bias, b1=None, spatial=10):
    """The mid-chain-``InstanceNormalization`` analogue of `_conv_pair_model`/
    `_group_norm_conv_pair_model`: an `InstanceNormalization` node (3
    required inputs; `scale`/`B` both strictly rank-1 ``[C1]``, per
    :func:`onnxsim.pruning._match_instance_norm_pass_through`'s own bar)
    sits between the two Convs. Unlike `_group_norm_conv_pair_model`, there
    is no `num_groups`/producer-`group` parameter to thread through here at
    all -- this hop places no constraint on which channels survive.
    """
    Cin, C2 = w1.shape[1], w2.shape[0]
    initializer = [
        _f32(w1, "W1"),
        _f32(w2, "W2"),
        _f32(in_scale, "INScale"),
        _f32(in_bias, "INBias"),
    ]
    if b1 is not None:
        conv1 = "h = Conv<kernel_shape=[3,3]>(X, W1, B1)"
        initializer.append(_f32(b1, "B1"))
    else:
        conv1 = "h = Conv<kernel_shape=[3,3]>(X, W1)"
    out_spatial = spatial - 4  # two valid (no-pad) 3x3 convs
    return _model(
        f"""
        g (float[N,{Cin},{spatial},{spatial}] X) => (float[N,{C2},{out_spatial},{out_spatial}] Y)
        {{
          {conv1}
          n = InstanceNormalization<epsilon=1e-05>(h, INScale, INBias)
          Y = Conv<kernel_shape=[3,3]>(n, W2)
        }}
        """,
        initializer=initializer,
        opset=22,
    )


def test_structured_pruning_instance_norm_pass_through_matches_oracle_exactly():
    # THE key correctness bar, same as every other Conv-chain hop's own
    # oracle test: exact equivalence (float32 noise only) to an
    # independently, already-pruned reference model -- never "matches the
    # un-pruned model's own output sliced after the fact" (see
    # `_INSTANCE_NORM_PASS_THROUGH_OP`'s own comment for why the latter isn't
    # even the same computation). `_oracle_keep_indices_conv` -- the plain,
    # unconstrained top-k `_apply_chains` itself uses for an ordinary
    # (`group=1`) chain -- is the right oracle here precisely because this
    # hop adds no grouping constraint of its own, unlike the GroupNorm hop's
    # own `_oracle_keep_indices_conv_grouped`.
    Cin, C1, C2 = 3, 16, 8
    rng = np.random.default_rng(60)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    b1 = rng.standard_normal((C1,)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    in_scale = rng.standard_normal((C1,)).astype(np.float32)
    in_bias = rng.standard_normal((C1,)).astype(np.float32)
    model = _instance_norm_conv_pair_model(w1, w2, in_scale, in_bias, b1=b1)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    dims_after = _initializer_dims(pruned)
    assert dims_after["W1"][0] == C1 // 2
    assert dims_after["INScale"][0] == C1 // 2
    assert dims_after["INBias"][0] == C1 // 2

    keep = _oracle_keep_indices_conv(w1, C1 // 2)
    oracle = _instance_norm_conv_pair_model(
        w1[keep], w2[:, keep], in_scale[keep], in_bias[keep], b1=b1[keep]
    )

    rng_x = np.random.default_rng(61)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_instance_norm_tied_scale_bias_declines():
    # `scale`/`B` naming the same initializer -- double-slicing it in
    # `_apply_conv_pass_through_hop` would corrupt it, so the whole chain is
    # declined outright, same as `_match_group_norm_pass_through`'s own
    # tied-name bar.
    Cin, C1, C2 = 3, 8, 4
    rng = np.random.default_rng(62)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    tied = rng.standard_normal((C1,)).astype(np.float32)
    model = _model(
        f"""
        g (float[N,{Cin},10,10] X) => (float[N,{C2},6,6] Y)
        {{
          h = Conv<kernel_shape=[3,3]>(X, W1)
          n = InstanceNormalization<epsilon=1e-05>(h, Tied, Tied)
          Y = Conv<kernel_shape=[3,3]>(n, W2)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(w2, "W2"), _f32(tied, "Tied")],
        opset=22,
    )
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1)
    np.testing.assert_array_equal(inits["W2"], w2)
    np.testing.assert_array_equal(inits["Tied"], tied)


def test_structured_pruning_instance_norm_non_constant_scale_declines():
    # `scale` fed by a runtime value (here, a second graph input) rather than
    # a constant initializer -- this pass cannot know its per-channel values
    # ahead of time, so the whole chain is declined outright, never guessed
    # at, the same "statically-known-constant-only" bar every other
    # per-channel hop in this module already applies.
    Cin, C1, C2 = 3, 8, 4
    rng = np.random.default_rng(63)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    in_bias = rng.standard_normal((C1,)).astype(np.float32)
    model = _model(
        f"""
        g (float[N,{Cin},10,10] X, float[{C1}] Scale) => (float[N,{C2},6,6] Y)
        {{
          h = Conv<kernel_shape=[3,3]>(X, W1)
          n = InstanceNormalization<epsilon=1e-05>(h, Scale, INBias)
          Y = Conv<kernel_shape=[3,3]>(n, W2)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(w2, "W2"), _f32(in_bias, "INBias")],
        opset=22,
    )
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1)
    np.testing.assert_array_equal(inits["W2"], w2)
    np.testing.assert_array_equal(inits["INBias"], in_bias)


def test_structured_pruning_instance_norm_non_1d_scale_declines():
    # A `scale` shaped `[1, C1]` -- `_flat_channel_const`'s own looser
    # "prod(dims) == dims[-1]" bar would admit this (a real GroupNorm/
    # LayerNorm hop reuses that check), but `_match_instance_norm_pass_through`
    # deliberately holds InstanceNorm's own `scale`/`B` to a *strictly*
    # rank-1 bar instead (see its own docstring for why: this hop's `scale`/
    # `B` are carried on a plain `_ConvPassThrough`, whose own slicing always
    # slices axis 0, which is only ever the right axis when rank == 1).
    # Declined outright rather than mis-sliced.
    Cin, C1, C2 = 3, 8, 4
    rng = np.random.default_rng(64)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    in_scale_2d = rng.standard_normal((1, C1)).astype(np.float32)
    in_bias = rng.standard_normal((C1,)).astype(np.float32)
    model = _model(
        f"""
        g (float[N,{Cin},10,10] X) => (float[N,{C2},6,6] Y)
        {{
          h = Conv<kernel_shape=[3,3]>(X, W1)
          n = InstanceNormalization<epsilon=1e-05>(h, INScale, INBias)
          Y = Conv<kernel_shape=[3,3]>(n, W2)
        }}
        """,
        initializer=[
            _f32(w1, "W1"),
            _f32(w2, "W2"),
            _f32(in_scale_2d, "INScale"),
            _f32(in_bias, "INBias"),
        ],
        opset=22,
    )
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1)
    np.testing.assert_array_equal(inits["W2"], w2)
    np.testing.assert_array_equal(inits["INScale"], in_scale_2d)
    np.testing.assert_array_equal(inits["INBias"], in_bias)


def _residual_diamond_instance_norm_model(
    w_f, in_scale, in_bias, w_s, w_out, spatial=10
):
    # The `_residual_diamond_model` shape, extended with an
    # `InstanceNormalization` hop on the `f` branch between its own Conv
    # producer and the `Add` merge -- exercises
    # `_walk_conv_producer_backward`'s own new InstanceNorm branch (not just
    # the forward `_walk_to_conv_consumer` one every other test above already
    # covers), confirming the hop is crossed correctly walking *backward*
    # from the `Add` operand to `f`'s own real Conv producer.
    Cin = w_f.shape[1]
    Cout = w_out.shape[0]
    out_spatial = spatial - 4  # two chained 3x3 valid convs
    return _model(
        f"""
        g (float[N,{Cin},{spatial},{spatial}] X) => (float[N,{Cout},{out_spatial},{out_spatial}] Y)
        {{
          f = Conv<kernel_shape=[3,3]>(X, WF)
          n = InstanceNormalization<epsilon=1e-05>(f, INScale, INBias)
          s = Conv<kernel_shape=[3,3]>(X, WS)
          addr = Add(n, s)
          r = Relu(addr)
          Y = Conv<kernel_shape=[3,3]>(r, WOUT)
        }}
        """,
        initializer=[
            _f32(w_f, "WF"),
            _f32(in_scale, "INScale"),
            _f32(in_bias, "INBias"),
            _f32(w_s, "WS"),
            _f32(w_out, "WOUT"),
        ],
        opset=22,
    )


def test_structured_pruning_conv_residual_add_instance_norm_pass_through_matches_oracle():
    Cin, C, Cout = 3, 16, 8
    rng = np.random.default_rng(65)
    w_f = rng.standard_normal((C, Cin, 3, 3)).astype(np.float32)
    in_scale = rng.standard_normal((C,)).astype(np.float32)
    in_bias = rng.standard_normal((C,)).astype(np.float32)
    w_s = rng.standard_normal((C, Cin, 3, 3)).astype(np.float32)
    w_out = rng.standard_normal((Cout, C, 3, 3)).astype(np.float32)
    model = _residual_diamond_instance_norm_model(w_f, in_scale, in_bias, w_s, w_out)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    dims_after = _initializer_dims(pruned)
    assert dims_after["WF"][0] == C // 2
    assert dims_after["INScale"][0] == C // 2
    assert dims_after["INBias"][0] == C // 2
    assert dims_after["WS"][0] == C // 2

    importance = np.sqrt(
        np.square(np.linalg.norm(w_f.reshape(C, -1).astype(np.float64), axis=1))
        + np.square(np.linalg.norm(w_s.reshape(C, -1).astype(np.float64), axis=1))
    )
    keep = np.sort(np.argsort(-importance)[: C // 2])
    oracle = _residual_diamond_instance_norm_model(
        w_f[keep], in_scale[keep], in_bias[keep], w_s[keep], w_out[:, keep]
    )

    rng_x = np.random.default_rng(66)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_analyze_structured_pruning_instance_norm_pass_through_matches_real_call():
    # Dry-run/real-call cross-check for the InstanceNorm hop specifically,
    # mirroring `test_analyze_structured_pruning_group_norm_pass_through_matches_real_call`
    # above.
    Cin, C1, C2 = 3, 16, 8
    rng = np.random.default_rng(67)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    in_scale = rng.standard_normal((C1,)).astype(np.float32)
    in_bias = rng.standard_normal((C1,)).astype(np.float32)
    model = _instance_norm_conv_pair_model(w1, w2, in_scale, in_bias)

    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_structured_pruning, sparsity=0.5
    )
    assert len(report.layers) == 1
    layer = report.layers[0]
    assert layer.family == "conv_plain"
    assert layer.total == C1

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    dims_after = _initializer_dims(pruned)
    kept = C1 - layer.would_drop
    assert dims_after["W1"][0] == kept
    assert dims_after["W2"][1] == kept
    assert dims_after["INScale"][0] == kept
    assert dims_after["INBias"][0] == kept


# --- Conv chain: decomposed-GroupNorm pass-through hop -----------------------
#
# The fixed 5-node ``Reshape -> InstanceNormalization -> Reshape -> Mul ->
# Add`` sequence PyTorch's own default/legacy (TorchScript-based) ONNX
# exporter emits for `nn.GroupNorm` in place of the native
# `GroupNormalization` node above -- see
# `onnxsim.pruning._match_decomposed_group_norm_pass_through`'s own
# docstring and this module's own top-of-file docstring for the full
# empirical gap confirmation and correctness argument. `_model` can express
# this shape directly (`Reshape`'s own int64 shape and `Shape`'s own dynamic
# second `Reshape` operand are both just ordinary named initializers/nodes in
# the text body -- no `ClearField`/byte-equality escape hatch needed the way
# CLAUDE.md's own "rare case" carve-out anticipates), so no `onnx.helper`
# fallback is needed here despite the `Reshape`/`Shape` dynamic-shape
# dependency.


def _decomposed_group_norm_conv_pair_model(
    w1,
    w2,
    gamma,
    beta,
    num_groups,
    in_scale=None,
    in_bias=None,
    reshape_shape=None,
    group1=1,
    b1=None,
    spatial=10,
):
    """The decomposed analogue of `_group_norm_conv_pair_model`: the fixed
    5-node sequence sits between the two Convs instead of a single native
    `GroupNormalization` node. `in_scale`/`in_bias` (length `num_groups`)
    default to arbitrary, deliberately non-trivial values (never `1.0`/
    `0.0`) -- confirming this hop's own correctness doesn't depend on them
    being the trivial identity a real PyTorch export always emits, the same
    empirical claim this feature's own docstring makes. `reshape_shape`
    defaults to the real, exact shape PyTorch's own exporter emits
    (`[0, num_groups, -1]`); tests that need a *different* shape (to probe
    the matcher's own decline behavior) override it directly.
    """
    C1, C2 = w1.shape[0], w2.shape[0]
    Cin = w1.shape[1] * group1
    if in_scale is None:
        in_scale = np.full(num_groups, 1.7, dtype=np.float32)
    if in_bias is None:
        in_bias = np.full(num_groups, -0.4, dtype=np.float32)
    if reshape_shape is None:
        reshape_shape = [0, num_groups, -1]
    initializer = [
        _f32(w1, "W1"),
        _f32(w2, "W2"),
        onnx.numpy_helper.from_array(
            np.array(reshape_shape, dtype=np.int64), "ReshapeShape"
        ),
        _f32(np.asarray(in_scale), "INScale"),
        _f32(np.asarray(in_bias), "INBias"),
        _f32(np.asarray(gamma).reshape(C1, 1, 1), "Gamma"),
        _f32(np.asarray(beta).reshape(C1, 1, 1), "Beta"),
    ]
    g1 = f", group={group1}" if group1 != 1 else ""
    if b1 is not None:
        conv1 = f"h = Conv<kernel_shape=[3,3]{g1}>(X, W1, B1)"
        initializer.append(_f32(b1, "B1"))
    else:
        conv1 = f"h = Conv<kernel_shape=[3,3]{g1}>(X, W1)"
    out_spatial = spatial - 4  # two valid (no-pad) 3x3 convs
    return _model(
        f"""
        g (float[N,{Cin},{spatial},{spatial}] X) => (float[N,{C2},{out_spatial},{out_spatial}] Y)
        {{
          {conv1}
          reshaped = Reshape(h, ReshapeShape)
          inorm = InstanceNormalization<epsilon=1e-05>(reshaped, INScale, INBias)
          hshape = Shape(h)
          back = Reshape(inorm, hshape)
          scaled = Mul(back, Gamma)
          gn = Add(scaled, Beta)
          Y = Conv<kernel_shape=[3,3]>(gn, W2)
        }}
        """,
        initializer=initializer,
    )


def test_structured_pruning_decomposed_group_norm_pass_through_matches_oracle_exactly():
    # THE key correctness bar, identical to the native-node hop's own test:
    # exact equivalence (float32 noise only) to an independently,
    # already-pruned reference model -- never "matches the un-pruned model's
    # own output sliced after the fact" (confirmed, empirically, to actually
    # diverge -- see `_match_decomposed_group_norm_pass_through`'s own
    # docstring). Also confirms, directly on the pruned model's own
    # initializers, the two claims specific to this hop: `INScale`/`INBias`
    # are left completely untouched (still length `num_groups`, still their
    # original, deliberately non-trivial values), and `Gamma`/`Beta` (the
    # *real* per-channel affine) are co-sliced by the exact same
    # non-contiguous, per-group-uniform `keep` set the producer/consumer
    # weights are.
    Cin, C1, C2, num_groups = 3, 16, 8, 4
    rng = np.random.default_rng(150)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    b1 = rng.standard_normal((C1,)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    gamma = rng.standard_normal((C1,)).astype(np.float32)
    beta = rng.standard_normal((C1,)).astype(np.float32)
    in_scale = (
        rng.standard_normal((num_groups,)).astype(np.float32) + 2.0
    )  # non-trivial
    in_bias = rng.standard_normal((num_groups,)).astype(np.float32)
    model = _decomposed_group_norm_conv_pair_model(
        w1, w2, gamma, beta, num_groups, in_scale=in_scale, in_bias=in_bias, b1=b1
    )

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    dims_after = _initializer_dims(pruned)
    assert dims_after["W1"][0] % num_groups == 0
    assert dims_after["W1"][0] < C1  # actually pruned, not a no-op

    pruned_inits = {
        t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer
    }
    np.testing.assert_array_equal(pruned_inits["INScale"], in_scale)
    np.testing.assert_array_equal(pruned_inits["INBias"], in_bias)

    keep = _oracle_keep_indices_conv_grouped(w1, num_groups, 0.5)
    # Uniform-per-group, but not necessarily contiguous -- confirming this
    # hop's own safety claim isn't accidentally only exercised by a
    # contiguous "keep the first half of every group" special case.
    block = C1 // num_groups
    per_group_counts = {
        gi: int(np.sum((keep >= gi * block) & (keep < (gi + 1) * block)))
        for gi in range(num_groups)
    }
    assert len(set(per_group_counts.values())) == 1  # uniform per group

    np.testing.assert_array_equal(pruned_inits["Gamma"].reshape(-1), gamma[keep])
    np.testing.assert_array_equal(pruned_inits["Beta"].reshape(-1), beta[keep])

    oracle = _decomposed_group_norm_conv_pair_model(
        w1[keep],
        w2[:, keep],
        gamma[keep],
        beta[keep],
        num_groups,
        in_scale=in_scale,
        in_bias=in_bias,
        b1=b1[keep],
    )

    rng_x = np.random.default_rng(151)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_decomposed_group_norm_num_groups_mismatch_with_grouped_conv_declines():
    # The decomposed-hop analogue of
    # `test_structured_pruning_group_norm_num_groups_mismatch_with_grouped_conv_declines`:
    # `num_groups` disagreeing with a same-chain grouped Conv producer's own
    # `group` is declined outright, never guessed at.
    Cin, C1, C2, group1, num_groups = 4, 8, 8, 2, 4
    rng = np.random.default_rng(152)
    w1 = rng.standard_normal((C1, Cin // group1, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    gamma = rng.standard_normal((C1,)).astype(np.float32)
    beta = rng.standard_normal((C1,)).astype(np.float32)
    model = _decomposed_group_norm_conv_pair_model(
        w1, w2, gamma, beta, num_groups, group1=group1
    )

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1)
    np.testing.assert_array_equal(inits["W2"], w2)
    np.testing.assert_array_equal(inits["Gamma"].reshape(-1), gamma)
    np.testing.assert_array_equal(inits["Beta"].reshape(-1), beta)


def test_structured_pruning_decomposed_group_norm_num_groups_not_dividing_declines():
    # `num_groups` not evenly dividing `n_channels` -- declined outright by
    # `_decomposed_group_norm_reshape_num_groups`, mirroring the native
    # hop's own identical `n_channels % num_groups != 0` bar.
    Cin, C1, C2, num_groups = 3, 8, 4, 3  # 8 % 3 != 0
