def test_structured_pruning_decomposed_group_norm_non_channel_gamma_declines():
    # `Gamma`/`Beta` not held to the `[C, 1, ..., 1]` per-channel shape bar
    # `_match_prelu_pass_through`'s own per-channel branch already uses --
    # here, a bare `[C]` (this hop's own matcher, unlike a MatMul/Gemm
    # chain's own last-axis convention, requires at least one trailing
    # size-1 dimension, mirroring `_match_prelu_pass_through`'s own
    # "a bare [C] slope is deliberately not per-channel here" bar) -- is
    # declined outright, the whole chain left unpruned.
    Cin, C1, C2, num_groups = 3, 8, 4, 4
    rng = np.random.default_rng(155)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    gamma = rng.standard_normal((C1,)).astype(np.float32)
    beta = rng.standard_normal((C1,)).astype(np.float32)
    model = _decomposed_group_norm_conv_pair_model(w1, w2, gamma, beta, num_groups)
    # Overwrite `Gamma` with a bare rank-1 `[C1]` shape instead of `[C1,1,1]`.
    for init in model.graph.initializer:
        if init.name == "Gamma":
            init.CopyFrom(_f32(gamma, "Gamma"))

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1)
    np.testing.assert_array_equal(inits["W2"], w2)


def test_structured_pruning_decomposed_group_norm_tied_gamma_beta_declines():
    # A tied `Gamma`/`Beta` (the same initializer used for both) would be
    # double-sliced by `_apply_chains`'s own per-hop loop, corrupting it --
    # declined outright, mirroring `_match_group_norm_pass_through`'s own
    # identical tied-`scale`/`bias` check.
    Cin, C1, C2, num_groups = 3, 8, 4, 4
    rng = np.random.default_rng(156)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    tied = rng.standard_normal((C1,)).astype(np.float32)
    model = _decomposed_group_norm_conv_pair_model(w1, w2, tied, tied, num_groups)
    # Point both Mul's and Add's own per-channel operand at the same name.
    for node in model.graph.node:
        if node.op_type == "Add" and list(node.input) == ["scaled", "Beta"]:
            node.input[1] = "Gamma"

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1)
    np.testing.assert_array_equal(inits["W2"], w2)


def test_structured_pruning_decomposed_group_norm_extra_consumer_on_root_declines():
    # `h` (the producer Conv's own output, this sequence's own root) read by
    # a THIRD consumer beyond the `Reshape`/`Shape` pair this shape expects
    # -- declined outright, the same "no stray fan-out" bar every hop in
    # this module already applies.
    Cin, C1, C2, num_groups = 3, 8, 4, 4
    rng = np.random.default_rng(157)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    gamma = rng.standard_normal((C1,)).astype(np.float32)
    beta = rng.standard_normal((C1,)).astype(np.float32)
    model = _decomposed_group_norm_conv_pair_model(w1, w2, gamma, beta, num_groups)
    extra_out = onnx.helper.make_tensor_value_info(
        "Extra", onnx.TensorProto.FLOAT, None
    )
    model.graph.node.append(onnx.helper.make_node("Relu", ["h"], ["Extra"]))
    model.graph.output.append(extra_out)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1)
    np.testing.assert_array_equal(inits["W2"], w2)


def test_analyze_structured_pruning_decomposed_group_norm_pass_through_matches_real_call():
    # Dry-run/real-call cross-check for the decomposed-hop specifically,
    # mirroring `test_analyze_structured_pruning_group_norm_pass_through_matches_real_call`.
    Cin, C1, C2, num_groups = 3, 16, 8, 4
    rng = np.random.default_rng(158)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    gamma = rng.standard_normal((C1,)).astype(np.float32)
    beta = rng.standard_normal((C1,)).astype(np.float32)
    model = _decomposed_group_norm_conv_pair_model(w1, w2, gamma, beta, num_groups)

    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_structured_pruning, sparsity=0.5
    )
    assert len(report.layers) == 1
    layer = report.layers[0]
    assert layer.family == "conv_plain"
    assert layer.total == C1

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    dims_after = _initializer_dims(pruned)
    kept = C1 - layer.would_drop
    assert dims_after["W1"][0] == kept
    assert dims_after["W2"][1] == kept
    assert dims_after["Gamma"][0] == kept
    assert dims_after["Beta"][0] == kept


def test_structured_pruning_native_and_decomposed_group_norm_still_supported_together():
    # Regression check: the native `GroupNormalization` node (opset 21+) and
    # the bare `InstanceNormalization` shape both remain unaffected by this
    # hop's own addition -- each is a completely different op-type dispatch
    # inside `_walk_to_conv_consumer`, gated by its own
    # `recognize_group_norm`/`recognize_decomposed_group_norm` flag, mutually
    # exclusive per chain (see that function's own docstring) -- confirmed
    # here by running one of each shape through the same call and checking
    # both still prune correctly.
    Cin, C1, C2, num_groups = 3, 16, 8, 4
    rng = np.random.default_rng(159)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    gn_scale = rng.standard_normal((C1,)).astype(np.float32)
    gn_bias = rng.standard_normal((C1,)).astype(np.float32)
    native_model = _group_norm_conv_pair_model(w1, w2, gn_scale, gn_bias, num_groups)
    native_pruned = onnxsim.apply_structured_pruning(native_model, sparsity=0.5)
    native_dims = _initializer_dims(native_pruned)
    assert native_dims["W1"][0] < C1
    assert native_dims["W1"][0] % num_groups == 0

    w1b = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2b = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    in_scale = rng.standard_normal((C1,)).astype(np.float32)
    in_bias = rng.standard_normal((C1,)).astype(np.float32)
    instance_model = _instance_norm_conv_pair_model(w1b, w2b, in_scale, in_bias)
    instance_pruned = onnxsim.apply_structured_pruning(instance_model, sparsity=0.5)
    instance_dims = _initializer_dims(instance_pruned)
    assert instance_dims["W1"][0] < C1


# --- Conv chain: pooling/Resize/Pad pass-through hops -----------------------
#
# `MaxPool`/`AveragePool`/`GlobalAveragePool` (unconditional -- no weight of
# their own, and no cross-channel mixing by schema -- see
# `_CONV_POOL_PASS_THROUGH`'s own comment) and a channel-axis-unaffected
# `Resize`/`Pad` (declined outright, never guessed at, whenever the channel
# axis can't be statically proven untouched -- see
# `_match_resize_channel_pass_through`/`_match_pad_channel_pass_through`).
# These close the two most common CNN backbone shapes this pass previously
# left completely unpruned end to end: a downsampling stage's own
# `Conv -> MaxPool -> Conv` (VGG/AlexNet/ResNet-style) and a decoder's own
# `Conv -> Resize -> Conv`/`-> Concat` (U-Net/diffusion-model-style
# upsampling).


def _pool_conv_pair_model(
    w1, w2, pool_node, b1=None, spatial=10, mid_spatial=None, out_kernel=3
):
    """The pooling analogue of `_conv_pair_model`/`_depthwise_pair_model`:
    `Conv -> {pool_node} -> Conv`, where `pool_node` is the ONNX text
    fragment for the pooling node itself (consuming `h`, the first Conv's
    own output, and producing `p`) -- one builder covers `MaxPool`/
    `AveragePool`/`GlobalAveragePool` alike without needing a dedicated copy
    per op, the same way `_group_norm_conv_pair_model` covers every
    `GroupNormalization`-hop shape with one builder.
    """
    Cin, C2 = w1.shape[1], w2.shape[0]
    initializer = [_f32(w1, "W1"), _f32(w2, "W2")]
    if b1 is not None:
        conv1 = "h = Conv<kernel_shape=[3,3]>(X, W1, B1)"
        initializer.append(_f32(b1, "B1"))
    else:
        conv1 = "h = Conv<kernel_shape=[3,3]>(X, W1)"
    after_conv1_spatial = spatial - 2  # one valid (no-pad) 3x3 conv
    if mid_spatial is None:
        mid_spatial = after_conv1_spatial
    out_spatial = mid_spatial - (out_kernel - 1)
    return _model(
        f"""
        g (float[N,{Cin},{spatial},{spatial}] X) => (float[N,{C2},{out_spatial},{out_spatial}] Y)
        {{
          {conv1}
          {pool_node}
          Y = Conv<kernel_shape=[{out_kernel},{out_kernel}]>(p, W2)
        }}
        """,
        initializer=initializer,
    )


def test_structured_pruning_maxpool_pass_through_matches_oracle_exactly():
    # Conv -> MaxPool -> Conv: the classic VGG/AlexNet/ResNet-style
    # downsampling shape this pass previously left completely unpruned end
    # to end (confirmed empirically, before this hop existed, via
    # `grep -n "MaxPool" onnxsim/pruning.py` inside the Conv-chain-walking
    # section returning zero hits). `kernel_shape=[1,1], strides=[1,1]` keeps
    # the spatial arithmetic trivial (MaxPool becomes a spatial no-op) while
    # still exercising the real op through a real onnxruntime session -- the
    # exact same "must match an independently, already-pruned reference
    # model" bar every other pass-through hop in this module is held to, not
    # a post-hoc slice of the unpruned model's own output.
    Cin, C1, C2 = 3, 16, 8
    rng = np.random.default_rng(60)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    b1 = rng.standard_normal((C1,)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    pool_node = "p = MaxPool<kernel_shape=[1,1], strides=[1,1]>(h)"
    model = _pool_conv_pair_model(w1, w2, pool_node, b1=b1)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    dims_after = _initializer_dims(pruned)
    assert dims_after["W1"][0] == C1 // 2
    assert dims_after["W2"][1] == C1 // 2

    keep = _oracle_keep_indices_conv(w1, C1 // 2)
    oracle = _pool_conv_pair_model(w1[keep], w2[:, keep], pool_node, b1=b1[keep])

    rng_x = np.random.default_rng(61)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_averagepool_pass_through_matches_oracle_exactly():
    Cin, C1, C2 = 3, 16, 8
    rng = np.random.default_rng(62)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    pool_node = "p = AveragePool<kernel_shape=[2,2], strides=[2,2]>(h)"
    model = _pool_conv_pair_model(w1, w2, pool_node, spatial=12, mid_spatial=5)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    dims_after = _initializer_dims(pruned)
    assert dims_after["W1"][0] == C1 // 2
    assert dims_after["W2"][1] == C1 // 2

    keep = _oracle_keep_indices_conv(w1, C1 // 2)
    oracle = _pool_conv_pair_model(
        w1[keep], w2[:, keep], pool_node, spatial=12, mid_spatial=5
    )

    rng_x = np.random.default_rng(63)
    x = rng_x.standard_normal((2, Cin, 12, 12)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_global_average_pool_pass_through_matches_oracle_exactly():
    # A degenerate-but-valid chain shape: `GlobalAveragePool` collapses every
    # spatial position to one, so the only way a *second* Conv can follow it
    # at all is a 1x1 kernel (verified live -- a 3x3 kernel over a 1x1
    # spatial input fails ONNX's own checker). In practice
    # `GlobalAveragePool` almost always feeds `Flatten`/a Gemm classifier
    # head instead -- see
    # `test_structured_pruning_global_average_pool_flatten_gemm_pass_through_matches_oracle_exactly`
    # below for that shape (the narrow `Flatten(axis=1)` case *is* reached;
    # see `_CONV_POOL_PASS_THROUGH`'s own comment and
    # `_match_gap_flatten_matmul_consumer`'s own docstring) -- so this
    # exercises the plain-pass-through hop for genuine correctness (it must
    # still slice cleanly and match a real onnxruntime oracle) without
    # claiming it's the common case.
    Cin, C1, C2 = 3, 16, 8
    rng = np.random.default_rng(64)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 1, 1)).astype(np.float32)
    pool_node = "p = GlobalAveragePool(h)"
    model = _pool_conv_pair_model(w1, w2, pool_node, mid_spatial=1, out_kernel=1)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    dims_after = _initializer_dims(pruned)
    assert dims_after["W1"][0] == C1 // 2
    assert dims_after["W2"][1] == C1 // 2

    keep = _oracle_keep_indices_conv(w1, C1 // 2)
    oracle = _pool_conv_pair_model(
        w1[keep], w2[:, keep], pool_node, mid_spatial=1, out_kernel=1
    )

    rng_x = np.random.default_rng(65)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def _gap_flatten_matmul_model(
    w1,
    w2,
    b1=None,
    b2=None,
    weight_transposed=False,
    activation="Relu",
    spatial=10,
):
    """``Conv -> {activation} -> GlobalAveragePool -> Flatten(axis=1) ->
    {MatMul, vanilla Gemm}`` -- the canonical ResNet/MobileNet/EfficientNet
    image-classifier head: global-average-pool the final feature map,
    flatten to ``[N, C]``, feed a Gemm/MatMul classifier. Per
    `_match_gap_flatten_matmul_consumer`'s own docstring, this `Flatten` is
    a provably trivial 1:1 relabeling of `GlobalAveragePool`'s own
    ``[N, C, 1, 1]`` output, unlike the *general* `Flatten` case (see
    `test_structured_pruning_conv_into_non_pass_through_op_is_left_untouched`),
    so the Conv producer *is* pruned end to end here.

    `weight_transposed` selects which of :func:`_match_matmul_like`'s own
    two branches `w2` takes: ``False`` for a plain `MatMul` (``[C1, Out]``
    weight, the reduction dimension on axis 0), ``True`` for a `transB=1`
    vanilla `Gemm` (``[Out, C1]`` weight, reduction dimension on axis 1 --
    the layout a real ``torch.onnx.export(nn.Linear(...))`` classifier head
    emits). `b2`, when given, is only valid alongside `weight_transposed`
    (plain `MatMul` has no bias input of its own to add).
    """
    Cin = w1.shape[1]
    initializer = [_f32(w1, "W1"), _f32(w2, "W2")]
    if b1 is not None:
        conv1 = "h = Conv<kernel_shape=[3,3]>(X, W1, B1)"
        initializer.append(_f32(b1, "B1"))
    else:
        conv1 = "h = Conv<kernel_shape=[3,3]>(X, W1)"
    if weight_transposed:
        Out = w2.shape[0]
        if b2 is not None:
            gemm = "Y = Gemm<transB=1>(f, W2, B2)"
            initializer.append(_f32(b2, "B2"))
        else:
            gemm = "Y = Gemm<transB=1>(f, W2)"
    else:
        assert b2 is None
        Out = w2.shape[1]
        gemm = "Y = MatMul(f, W2)"
    return _model(
        f"""
        g (float[N,{Cin},{spatial},{spatial}] X) => (float[N,{Out}] Y)
        {{
          {conv1}
          a = {activation}(h)
          p = GlobalAveragePool(a)
          f = Flatten<axis=1>(p)
          {gemm}
        }}
        """,
        initializer=initializer,
    )


def test_structured_pruning_global_average_pool_flatten_gemm_pass_through_matches_oracle_exactly():
    # THE key correctness bar for the new `GlobalAveragePool -> Flatten
    # -> Gemm` hop, same as every other Conv-chain hop's own oracle test:
    # exact equivalence (float32 noise only) to an independently,
    # already-pruned reference model. `transB=1` (`W2` stored `[Out, C1]`)
    # mirrors a real `torch.onnx.export(nn.Linear(...))` classifier head.
    Cin, C1, Out = 3, 16, 5
    rng = np.random.default_rng(70)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    b1 = rng.standard_normal((C1,)).astype(np.float32)
    w2 = rng.standard_normal((Out, C1)).astype(np.float32)
    b2 = rng.standard_normal((Out,)).astype(np.float32)
    model = _gap_flatten_matmul_model(w1, w2, b1=b1, b2=b2, weight_transposed=True)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    dims_after = _initializer_dims(pruned)
    assert dims_after["W1"][0] == C1 // 2  # the Conv IS pruned end to end
    assert dims_after["W2"][1] == C1 // 2  # Gemm's own transB=1 reduction axis

    keep = _oracle_keep_indices_conv(w1, C1 // 2)
    oracle = _gap_flatten_matmul_model(
        w1[keep], w2[:, keep], b1=b1[keep], b2=b2, weight_transposed=True
    )

    rng_x = np.random.default_rng(71)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_global_average_pool_flatten_matmul_pass_through_matches_oracle_exactly():
    # The plain `MatMul` (``[K, N]`` weight, `weight_transposed=False`)
    # branch of the identical hop, exercised separately from the `Gemm`
    # case above since :func:`_match_gap_flatten_matmul_consumer` reuses
    # :func:`_match_matmul_like`'s own `weight_transposed` dispatch and
    # `_slice_consumer_weight` slices a different axis for each.
    Cin, C1, Out = 3, 16, 5
    rng = np.random.default_rng(72)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C1, Out)).astype(np.float32)
    model = _gap_flatten_matmul_model(w1, w2, weight_transposed=False)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    dims_after = _initializer_dims(pruned)
    assert dims_after["W1"][0] == C1 // 2
    assert dims_after["W2"][0] == C1 // 2

    keep = _oracle_keep_indices_conv(w1, C1 // 2)
    oracle = _gap_flatten_matmul_model(w1[keep], w2[keep], weight_transposed=False)

    rng_x = np.random.default_rng(73)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_global_average_pool_flatten_wrong_axis_declines():
    # `Flatten` with a non-default `axis` (here `0`, merging the batch axis
    # into the flattened one rather than keeping it separate) is declined
    # outright: only `axis == 1` is a provably trivial 1:1 relabeling of
    # `GlobalAveragePool`'s own `[N, C, 1, ..., 1]` output -- see
    # `_match_gap_flatten_matmul_consumer`'s own docstring. The whole chain
    # stays completely unpruned, not guessed at.
    Cin, C1, Out = 3, 16, 5
    rng = np.random.default_rng(74)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C1, Out)).astype(np.float32)
    model = _model(
        f"""
        g (float[N,{Cin},10,10] X) => (float[?] Y)
        {{
          h = Conv<kernel_shape=[3,3]>(X, W1)
          p = GlobalAveragePool(h)
          f = Flatten<axis=0>(p)
          Y = MatMul(f, W2)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(w2, "W2")],
    )
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1)
    np.testing.assert_array_equal(inits["W2"], w2)


def _gap_reshape_neg1_matmul_model(
    w1,
    w2,
    b1=None,
    b2=None,
    weight_transposed=False,
    activation="Relu",
    spatial=10,
    via_concat=False,
):
    """`_gap_flatten_matmul_model`'s ``Reshape``-based analogue: ``Conv ->
    {activation} -> GlobalAveragePool -> Reshape([batch, -1]) -> {MatMul,
    vanilla Gemm}`` -- the ``x.view(x.size(0), -1)``/``x.reshape(x.shape[0],
    -1)`` shape a real ``torch.onnx.export`` emits at least as often as an
    explicit ``nn.Flatten()`` after global average pooling (see
    `_match_reshape_batch_neg1_pass_through`'s own docstring for the proof).
    `via_concat` selects which of the two constant-shape forms that matcher
    recognizes: `False` (default) a single whole-constant ``[0, -1]`` shape
    initializer (`0` -- ONNX `Reshape`'s own "copy this dim from the input"
    convention -- stands in for the batch dim, valid for any actual batch
    size); `True` the ``Shape(X) -> Gather(indices=[0]) -> Unsqueeze ->
    Concat(., [-1])`` dynamic-batch-computation shape a real dynamic-batch
    export emits instead.
    """
    Cin = w1.shape[1]
    initializer = [_f32(w1, "W1"), _f32(w2, "W2")]
    if b1 is not None:
        conv1 = "h = Conv<kernel_shape=[3,3]>(X, W1, B1)"
        initializer.append(_f32(b1, "B1"))
    else:
        conv1 = "h = Conv<kernel_shape=[3,3]>(X, W1)"
    if weight_transposed:
        Out = w2.shape[0]
        if b2 is not None:
            gemm = "Y = Gemm<transB=1>(f, W2, B2)"
            initializer.append(_f32(b2, "B2"))
        else:
            gemm = "Y = Gemm<transB=1>(f, W2)"
    else:
        assert b2 is None
        Out = w2.shape[1]
        gemm = "Y = MatMul(f, W2)"

    if via_concat:
        reshape_prefix = """
          bshape = Shape(p)
          b0 = Gather<axis=0>(bshape, GatherIdx)
          b0u = Unsqueeze(b0, UnsqAxes)
          rshape = Concat<axis=0>(b0u, NegOne)
        """
        initializer.append(
            onnx.numpy_helper.from_array(np.array(0, dtype=np.int64), "GatherIdx")
        )
        initializer.append(
            onnx.numpy_helper.from_array(np.array([0], dtype=np.int64), "UnsqAxes")
        )
        initializer.append(
            onnx.numpy_helper.from_array(np.array([-1], dtype=np.int64), "NegOne")
        )
    else:
        reshape_prefix = ""
        initializer.append(
            onnx.numpy_helper.from_array(np.array([0, -1], dtype=np.int64), "rshape")
        )

    return _model(
        f"""
        g (float[N,{Cin},{spatial},{spatial}] X) => (float[N,{Out}] Y)
        {{
          {conv1}
          a = {activation}(h)
          p = GlobalAveragePool(a)
          {reshape_prefix}
          f = Reshape(p, rshape)
          {gemm}
        }}
        """,
        initializer=initializer,
    )


def test_structured_pruning_global_average_pool_reshape_neg1_gemm_pass_through_matches_oracle_exactly():
    # The `Reshape` counterpart of the `Flatten(axis=1)` hop above --
    # `x.view(x.size(0), -1)`'s own exported shape, matched by
    # `_match_reshape_batch_neg1_pass_through`. The constant `[0, -1]` shape
    # form (`0` copies the batch dim from the input, valid for any actual
    # batch size).
    Cin, C1, Out = 3, 16, 5
    rng = np.random.default_rng(170)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    b1 = rng.standard_normal((C1,)).astype(np.float32)
    w2 = rng.standard_normal((Out, C1)).astype(np.float32)
    b2 = rng.standard_normal((Out,)).astype(np.float32)
    model = _gap_reshape_neg1_matmul_model(w1, w2, b1=b1, b2=b2, weight_transposed=True)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    dims_after = _initializer_dims(pruned)
    assert dims_after["W1"][0] == C1 // 2  # the Conv IS pruned end to end
    assert dims_after["W2"][1] == C1 // 2  # Gemm's own transB=1 reduction axis

    keep = _oracle_keep_indices_conv(w1, C1 // 2)
    oracle = _gap_reshape_neg1_matmul_model(
        w1[keep], w2[:, keep], b1=b1[keep], b2=b2, weight_transposed=True
    )

    rng_x = np.random.default_rng(171)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_global_average_pool_reshape_neg1_via_concat_batch_gemm_pass_through_matches_oracle_exactly():
    # The `Concat`-produced shape form: `Shape(X) -> Gather(indices=[0]) ->
    # Unsqueeze -> Concat(., [-1])` computing the batch dim dynamically --
    # the shape a real dynamic-batch `torch.onnx.export` emits (see
    # `_match_reshape_batch_neg1_pass_through`'s own docstring). The
    # `Shape`/`Gather`/`Unsqueeze` prefix is never inspected in any detail by
    # the matcher -- only that `Concat`'s own last input is a constant
    # single-element `[-1]` tensor.
    Cin, C1, Out = 3, 16, 5
    rng = np.random.default_rng(172)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C1, Out)).astype(np.float32)
    model = _gap_reshape_neg1_matmul_model(
        w1, w2, weight_transposed=False, via_concat=True
    )

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    dims_after = _initializer_dims(pruned)
    assert dims_after["W1"][0] == C1 // 2
    assert dims_after["W2"][0] == C1 // 2

    keep = _oracle_keep_indices_conv(w1, C1 // 2)
    oracle = _gap_reshape_neg1_matmul_model(
        w1[keep], w2[keep], weight_transposed=False, via_concat=True
    )

    rng_x = np.random.default_rng(173)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_global_average_pool_reshape_non_neg1_declines():
    # A `Reshape` target NOT ending in `-1` (here a literal, baked-in
    # channel count) is the *general*, harder Reshape problem this module's
    # own docstring calls out as excluded -- declined outright, never
    # guessed at, the same bar as the `Flatten` wrong-axis decline test
    # above.
    Cin, C1, Out = 3, 16, 5
    rng = np.random.default_rng(180)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C1, Out)).astype(np.float32)
    shape_init = onnx.numpy_helper.from_array(
        np.array([0, C1], dtype=np.int64), "rshape"
    )
    model = _model(
        f"""
        g (float[N,{Cin},10,10] X) => (float[?] Y)
        {{
          h = Conv<kernel_shape=[3,3]>(X, W1)
          p = GlobalAveragePool(h)
          f = Reshape(p, rshape)
          Y = MatMul(f, W2)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(w2, "W2"), shape_init],
    )
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1)
    np.testing.assert_array_equal(inits["W2"], w2)


def _gap_squeeze_matmul_model(
    w1,
    w2,
    b1=None,
    b2=None,
    weight_transposed=False,
    activation="Relu",
    spatial=10,
    chained=True,
    opset=21,
):
    """The `Squeeze` counterpart of `_gap_flatten_matmul_model`: ``Conv ->
    {activation} -> GlobalAveragePool -> Squeeze(...) -> {MatMul, vanilla
    Gemm}``. `chained=True` (default): two chained single-axis
    `Squeeze(axes=[-1])` nodes -- the ``x.squeeze(-1).squeeze(-1)`` shape a
    real export emits (opset>=13 constant-input form of `axes`; matched via
    `_squeeze_axis_is_trailing_spatial`'s own `axis == -1` case).
    `chained=False`: a single `Squeeze` covering both trailing axes at once
    (``axes=[2, 3]``), using the opset>=13 constant-input form when
    `opset >= 13` (default) or the opset<13 attribute form otherwise (see
    `_gap_squeeze_axes`'s own docstring for both forms).
    """
    Cin = w1.shape[1]
    initializer = [_f32(w1, "W1"), _f32(w2, "W2")]
    if b1 is not None:
        conv1 = "h = Conv<kernel_shape=[3,3]>(X, W1, B1)"
        initializer.append(_f32(b1, "B1"))
    else:
        conv1 = "h = Conv<kernel_shape=[3,3]>(X, W1)"
    if weight_transposed:
        Out = w2.shape[0]
        if b2 is not None:
            gemm = "Y = Gemm<transB=1>(f, W2, B2)"
            initializer.append(_f32(b2, "B2"))
        else:
            gemm = "Y = Gemm<transB=1>(f, W2)"
    else:
        assert b2 is None
        Out = w2.shape[1]
        gemm = "Y = MatMul(f, W2)"

    if chained:
        squeeze_ops = """
          q1 = Squeeze(p, NegOneAxis)
          f = Squeeze(q1, NegOneAxis)
        """
        initializer.append(
            onnx.numpy_helper.from_array(np.array([-1], dtype=np.int64), "NegOneAxis")
        )
    elif opset >= 13:
        squeeze_ops = "f = Squeeze(p, Axes23)"
        initializer.append(
            onnx.numpy_helper.from_array(np.array([2, 3], dtype=np.int64), "Axes23")
        )
    else:
        squeeze_ops = "f = Squeeze<axes=[2,3]>(p)"

    return _model(
        f"""
        g (float[N,{Cin},{spatial},{spatial}] X) => (float[N,{Out}] Y)
        {{
          {conv1}
          a = {activation}(h)
          p = GlobalAveragePool(a)
          {squeeze_ops}
          {gemm}
        }}
        """,
        initializer=initializer,
        opset=opset,
    )


def test_structured_pruning_global_average_pool_squeeze_chained_gemm_pass_through_matches_oracle_exactly():
    # THE confirmed-by-a-real-export repro: `x.squeeze(-1).squeeze(-1)` in
    # place of an explicit `nn.Flatten()` -- two chained single-axis
    # `Squeeze(axes=[-1])` nodes reading `GlobalAveragePool`'s own
    # `[N, C, 1, 1]` output down to `[N, C]`. See
    # `_squeeze_axis_is_trailing_spatial`'s own docstring for why `axis ==
    # -1`, chained, stays provably within GAP's own trailing axes here.
    Cin, C1, Out = 3, 16, 5
    rng = np.random.default_rng(174)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    b1 = rng.standard_normal((C1,)).astype(np.float32)
    w2 = rng.standard_normal((Out, C1)).astype(np.float32)
    b2 = rng.standard_normal((Out,)).astype(np.float32)
    model = _gap_squeeze_matmul_model(
        w1, w2, b1=b1, b2=b2, weight_transposed=True, chained=True
    )

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    dims_after = _initializer_dims(pruned)
    assert dims_after["W1"][0] == C1 // 2
    assert dims_after["W2"][1] == C1 // 2

    keep = _oracle_keep_indices_conv(w1, C1 // 2)
    oracle = _gap_squeeze_matmul_model(
        w1[keep],
        w2[:, keep],
        b1=b1[keep],
        b2=b2,
        weight_transposed=True,
        chained=True,
    )

    rng_x = np.random.default_rng(175)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


