def test_structured_pruning_global_average_pool_squeeze_channel_axis_declines():
    # A `Squeeze` axis that isn't a trailing spatial one (here `axis=1`, the
    # channel axis) is declined outright -- see
    # `_squeeze_axis_is_trailing_spatial`'s own docstring. The whole chain
    # stays completely unpruned, not guessed at.
    Cin, C1, Out = 3, 16, 5
    rng = np.random.default_rng(181)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C1, Out)).astype(np.float32)
    axes_init = onnx.numpy_helper.from_array(np.array([1], dtype=np.int64), "Axes1")
    model = _model(
        f"""
        g (float[1,{Cin},10,10] X) => (float[?] Y)
        {{
          h = Conv<kernel_shape=[3,3]>(X, W1)
          p = GlobalAveragePool(h)
          f = Squeeze(p, Axes1)
          Y = MatMul(f, W2)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(w2, "W2"), axes_init],
    )
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1)
    np.testing.assert_array_equal(inits["W2"], w2)


def test_analyze_structured_pruning_maxpool_pass_through_matches_real_call():
    # Dry-run/real-call cross-check for the pooling pass-through hops
    # specifically: `_analyze_chains` shares `_find_conv_chains` (and
    # therefore `_walk_to_conv_consumer`) with the real `apply_*` call, so a
    # mismatch here would mean the two genuinely disagree about what got
    # matched -- this module's own established discipline treats that as a
    # real bug, the same cross-check `test_analyze_structured_pruning_group_
    # norm_pass_through_matches_real_call` already runs for the GroupNorm hop.
    Cin, C1, C2 = 3, 16, 8
    rng = np.random.default_rng(66)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    pool_node = "p = MaxPool<kernel_shape=[1,1], strides=[1,1]>(h)"
    model = _pool_conv_pair_model(w1, w2, pool_node)

    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_structured_pruning, sparsity=0.5
    )
    assert len(report.layers) == 1
    layer = report.layers[0]
    assert layer.family == "conv_plain"
    assert layer.total == C1

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    dims_after = _initializer_dims(pruned)
    kept = C1 - layer.would_drop
    assert dims_after["W1"][0] == kept
    assert dims_after["W2"][1] == kept


def _resize_conv_pair_model(w1, w2, scales, b1=None, spatial=8, out_spatial_hw=None):
    """`Conv -> Resize -> Conv`, `scales` the raw 4-element `[N, C, H, W]`
    scale factor array fed as `Resize`'s own `scales` input (`roi` left
    empty, `sizes` omitted -- the common exporter shape)."""
    Cin, C2 = w1.shape[1], w2.shape[0]
    initializer = [
        _f32(w1, "W1"),
        _f32(w2, "W2"),
        onnx.numpy_helper.from_array(np.asarray(scales, dtype=np.float32), "Scales"),
    ]
    if b1 is not None:
        conv1 = "h = Conv<kernel_shape=[3,3]>(X, W1, B1)"
        initializer.append(_f32(b1, "B1"))
    else:
        conv1 = "h = Conv<kernel_shape=[3,3]>(X, W1)"
    after_conv1 = spatial - 2
    if out_spatial_hw is None:
        mid_h = round(after_conv1 * scales[2])
        out_spatial_hw = mid_h - 2
    return _model(
        f"""
        g (float[N,{Cin},{spatial},{spatial}] X) => (float[N,{C2},{out_spatial_hw},{out_spatial_hw}] Y)
        {{
          {conv1}
          p = Resize<mode="nearest">(h, , Scales)
          Y = Conv<kernel_shape=[3,3]>(p, W2)
        }}
        """,
        initializer=initializer,
    )


def test_structured_pruning_resize_channel_safe_pass_through_matches_oracle_exactly():
    # Conv -> Resize(scales=[1,1,2,2], spatial-only upsample) -> Conv: the
    # U-Net/diffusion-model-decoder-style upsampling shape this pass
    # previously left completely unpruned end to end (confirmed empirically,
    # before this hop existed, the same zero-hits `grep` this module's own
    # docstring now records). `scales[1] == 1.0` -- the channel axis -- is
    # confirmed live via `onnx.defs.get_schema("Resize")` and, here, by a
    # real onnxruntime oracle match: channel-axis slicing commutes exactly
    # with this Resize, so pruning across it is safe.
    Cin, C1, C2 = 3, 16, 8
    rng = np.random.default_rng(67)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    b1 = rng.standard_normal((C1,)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    scales = [1.0, 1.0, 2.0, 2.0]
    model = _resize_conv_pair_model(w1, w2, scales, b1=b1)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    dims_after = _initializer_dims(pruned)
    assert dims_after["W1"][0] == C1 // 2
    assert dims_after["W2"][1] == C1 // 2

    keep = _oracle_keep_indices_conv(w1, C1 // 2)
    oracle = _resize_conv_pair_model(w1[keep], w2[:, keep], scales, b1=b1[keep])

    rng_x = np.random.default_rng(68)
    x = rng_x.standard_normal((2, Cin, 8, 8)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_resize_channel_affecting_declines():
    # scales[1] (the channel axis) == 2.0 -- this Resize genuinely resizes
    # the channel axis itself (doubling channel count, confirmed live via a
    # real onnxruntime run: it does NOT commute with channel-axis slicing at
    # all), so it must be declined outright, never guessed at, and the whole
    # chain -- both Convs -- left completely untouched.
    Cin, C1, C2 = 3, 8, 4
    rng = np.random.default_rng(69)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    scales = [1.0, 2.0, 1.0, 1.0]
    w2 = rng.standard_normal((C2, C1 * 2, 3, 3)).astype(np.float32)
    model = _resize_conv_pair_model(w1, w2, scales, out_spatial_hw=4)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1)
    np.testing.assert_array_equal(inits["W2"], w2)


def test_structured_pruning_resize_sizes_driven_declines_unconditionally():
    # The `sizes`-driven variant (rather than `scales`) is declined
    # *unconditionally*, even though `sizes[1] == n_channels` here provably
    # confirms the channel axis is untouched at the *original* channel
    # count: `sizes` names an absolute output size per axis, which would go
    # stale (still naming the pre-prune channel count) the moment this chain
    # is actually pruned, since nothing in this pass rewrites a constant
    # *value* the way it rewrites a depthwise Conv's own `group` attribute --
    # see `_match_resize_channel_pass_through`'s own docstring for the
    # confirmed-by-construction broken-graph failure mode this scope
    # decision avoids (a `sizes`-driven Resize left stale after pruning
    # fails outright at `onnxruntime.InferenceSession.run` with a real
    # channel-count-mismatch error on the very next Conv).
    Cin, C1, C2 = 3, 8, 4
    rng = np.random.default_rng(70)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    sizes = onnx.numpy_helper.from_array(
        np.array([1, C1, 12, 12], dtype=np.int64), "Sizes"
    )
    model = _model(
        f"""
        g (float[N,{Cin},8,8] X) => (float[N,{C2},8,8] Y)
        {{
          h = Conv<kernel_shape=[3,3]>(X, W1)
          p = Resize<mode="nearest">(h, , , Sizes)
          Y = Conv<kernel_shape=[3,3]>(p, W2)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(w2, "W2"), sizes],
    )

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1)
    np.testing.assert_array_equal(inits["W2"], w2)


def _pad_conv_pair_model(w1, w2, pads, b1=None, spatial=8):
    """`Conv -> Pad -> Conv`, `pads` the raw 8-element (`2 * rank` for a
    rank-4 NCHW tensor) ONNX `pads` layout: `[x1_begin, ..., xk_begin,
    x1_end, ..., xk_end]`."""
    Cin, C2 = w1.shape[1], w2.shape[0]
    pads = np.asarray(pads, dtype=np.int64)
    rank = len(pads) // 2
    initializer = [
        _f32(w1, "W1"),
        _f32(w2, "W2"),
        onnx.numpy_helper.from_array(pads, "Pads"),
    ]
    if b1 is not None:
        conv1 = "h = Conv<kernel_shape=[3,3]>(X, W1, B1)"
        initializer.append(_f32(b1, "B1"))
    else:
        conv1 = "h = Conv<kernel_shape=[3,3]>(X, W1)"
    after_conv1 = spatial - 2
    mid_h = after_conv1 + pads[2] + pads[rank + 2]  # axis 2 (H) begin+end pad
    out_spatial = mid_h - 2
    return _model(
        f"""
        g (float[N,{Cin},{spatial},{spatial}] X) => (float[N,{C2},{out_spatial},{out_spatial}] Y)
        {{
          {conv1}
          p = Pad<mode="constant">(h, Pads)
          Y = Conv<kernel_shape=[3,3]>(p, W2)
        }}
        """,
        initializer=initializer,
    )


def test_structured_pruning_pad_channel_safe_pass_through_matches_oracle_exactly():
    # Zero padding on axis 1 (channel), nonzero on the spatial axes --
    # confirmed live via a real onnxruntime run to commute exactly with
    # channel-axis slicing, whatever `Pad`'s own `mode` (`constant` here;
    # `reflect`/`edge`/`wrap` are likewise a pure identity along an axis
    # padded by exactly zero either side -- see
    # `_match_pad_channel_pass_through`'s own docstring).
    Cin, C1, C2 = 3, 16, 8
    rng = np.random.default_rng(72)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    b1 = rng.standard_normal((C1,)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    pads = [0, 0, 1, 1, 0, 0, 1, 1]
    model = _pad_conv_pair_model(w1, w2, pads, b1=b1)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    dims_after = _initializer_dims(pruned)
    assert dims_after["W1"][0] == C1 // 2
    assert dims_after["W2"][1] == C1 // 2

    keep = _oracle_keep_indices_conv(w1, C1 // 2)
    oracle = _pad_conv_pair_model(w1[keep], w2[:, keep], pads, b1=b1[keep])

    rng_x = np.random.default_rng(73)
    x = rng_x.standard_normal((2, Cin, 8, 8)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_pad_channel_affecting_declines():
    # Nonzero padding on axis 1 (channel) -- confirmed live to change the
    # output channel count outright (no commuting with channel-axis slicing
    # at all), so this must be declined, never guessed at, leaving the whole
    # chain untouched.
    Cin, C1, C2 = 3, 8, 4
    rng = np.random.default_rng(74)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    pads = [0, 1, 0, 0, 0, 1, 0, 0]
    w2 = rng.standard_normal((C2, C1 + 2, 3, 3)).astype(np.float32)
    model = _pad_conv_pair_model(w1, w2, pads)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1)
    np.testing.assert_array_equal(inits["W2"], w2)


def test_structured_pruning_resize_dynamic_scales_declines():
    # `scales` computed at runtime (via Shape -> Cast, a plausible
    # "resize to match another tensor's own spatial size" exporter pattern)
    # rather than a constant initializer -- this pass cannot know which axis
    # is affected without evaluating the graph, so it must decline outright,
    # never guessed at, mirroring every other "statically-known-constant-
    # only" bar in this module (e.g. `_match_group_norm_pass_through`'s own
    # `scale`/`bias`).
    Cin, C1, C2 = 3, 8, 4
    rng = np.random.default_rng(75)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    model = _model(
        f"""
        g (float[N,{Cin},8,8] X) => (float[N,{C2},4,4] Y)
        {{
          h = Conv<kernel_shape=[3,3]>(X, W1)
          shp = Shape(h)
          scales_dyn = Cast<to=1>(shp)
          p = Resize<mode="nearest">(h, , scales_dyn)
          Y = Conv<kernel_shape=[3,3]>(p, W2)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(w2, "W2")],
    )
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1)
    np.testing.assert_array_equal(inits["W2"], w2)


def test_structured_pruning_pad_dynamic_pads_declines():
    # `pads` computed at runtime (via a non-constant node output) rather
    # than a constant initializer -- declined outright for the same reason
    # as a dynamic `Resize` `scales`/`sizes` above.
    Cin, C1, C2 = 3, 8, 4
    rng = np.random.default_rng(76)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    model = _model(
        f"""
        g (float[N,{Cin},8,8] X, int64[8] PadsIn) => (float[N,{C2},4,4] Y)
        {{
          h = Conv<kernel_shape=[3,3]>(X, W1)
          pads_dyn = Identity(PadsIn)
          p = Pad<mode="constant">(h, pads_dyn)
          Y = Conv<kernel_shape=[3,3]>(p, W2)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(w2, "W2")],
    )
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1)
    np.testing.assert_array_equal(inits["W2"], w2)


# --- Conv chain: PRelu pass-through hop --------------------------------
#
# `Conv -> PRelu -> Conv`: the MobileFaceNet/ResNet-style face-recognition
# backbone shape this hop exists for (previously left completely unpruned
# end to end -- confirmed empirically, before this hop existed, via
# `grep -n "PRelu" onnxsim/pruning.py` inside the Conv-chain-walking section
# returning zero hits). `slope`'s own shape decides which of
# `_match_prelu_pass_through`'s two cases applies: per-channel
# (`[C1, 1, 1]`, co-sliced) or scalar/single-shared-parameter (`[1, 1, 1]` --
# the real shape a `torch.onnx.export` of `nn.PReLU(1)` emits, confirmed
# live -- left untouched).


def _prelu_conv_pair_model(w1, w2, slope, b1=None, spatial=10):
    Cin, C2 = w1.shape[1], w2.shape[0]
    initializer = [_f32(w1, "W1"), _f32(w2, "W2"), _f32(slope, "Slope")]
    if b1 is not None:
        conv1 = "h = Conv<kernel_shape=[3,3]>(X, W1, B1)"
        initializer.append(_f32(b1, "B1"))
    else:
        conv1 = "h = Conv<kernel_shape=[3,3]>(X, W1)"
    out_spatial = spatial - 4  # two valid (no-pad) 3x3 convs
    return _model(
        f"""
        g (float[N,{Cin},{spatial},{spatial}] X) => (float[N,{C2},{out_spatial},{out_spatial}] Y)
        {{
          {conv1}
          a = PRelu(h, Slope)
          Y = Conv<kernel_shape=[3,3]>(a, W2)
        }}
        """,
        initializer=initializer,
    )


def test_structured_pruning_prelu_per_channel_pass_through_matches_oracle_exactly():
    # THE key correctness bar, same as every other Conv-chain hop's own
    # oracle test: exact equivalence (float32 noise only) to an
    # independently, already-pruned reference model whose own `slope` is
    # sliced to the same kept indices from the start -- not "close", and not
    # "run the original PRelu, then slice its output" after the fact.
    Cin, C1, C2 = 3, 16, 8
    rng = np.random.default_rng(90)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    b1 = rng.standard_normal((C1,)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    slope = rng.standard_normal((C1, 1, 1)).astype(np.float32)
    model = _prelu_conv_pair_model(w1, w2, slope, b1=b1)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    dims_after = _initializer_dims(pruned)
    assert dims_after["W1"][0] == C1 // 2
    assert dims_after["W2"][1] == C1 // 2
    assert dims_after["Slope"] == (C1 // 2, 1, 1)

    keep = _oracle_keep_indices_conv(w1, C1 // 2)
    oracle = _prelu_conv_pair_model(w1[keep], w2[:, keep], slope[keep], b1=b1[keep])

    rng_x = np.random.default_rng(91)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_prelu_scalar_shared_slope_pass_through_matches_oracle_exactly():
    # A scalar/single-shared-parameter `slope` (`nn.PReLU(1)` in torch
    # terms) multiplies every channel identically, so it must be left
    # completely untouched -- unlike the per-channel case, `Slope`'s own
    # shape stays exactly `(1, 1, 1)` after pruning, byte-identical to the
    # original.
    Cin, C1, C2 = 3, 16, 8
    rng = np.random.default_rng(92)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    slope = rng.standard_normal((1, 1, 1)).astype(np.float32)
    model = _prelu_conv_pair_model(w1, w2, slope)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    dims_after = _initializer_dims(pruned)
    assert dims_after["W1"][0] == C1 // 2
    assert dims_after["W2"][1] == C1 // 2
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["Slope"], slope)  # left completely untouched

    keep = _oracle_keep_indices_conv(w1, C1 // 2)
    oracle = _prelu_conv_pair_model(w1[keep], w2[:, keep], slope)

    rng_x = np.random.default_rng(93)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_prelu_mismatched_slope_shape_declines():
    # A `slope` shape that cleanly falls into neither the per-channel
    # (`dims[0] == n_channels`, every other dim size 1) nor the scalar
    # (`prod(dims) == 1`) case -- here, one value per *pair* of channels, a
    # per-group-style shape this hop is not held to guess the semantics of
    # -- must decline the whole chain outright, never mis-sliced.
    Cin, C1, C2 = 3, 8, 4
    rng = np.random.default_rng(94)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    slope = rng.standard_normal((C1 // 2, 1, 1)).astype(np.float32)
    model = _model(
        f"""
        g (float[N,{Cin},10,10] X) => (float[N,{C2},6,6] Y)
        {{
          h = Conv<kernel_shape=[3,3]>(X, W1)
          a = PRelu(h, Slope)
          Y = Conv<kernel_shape=[3,3]>(a, W2)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(w2, "W2"), _f32(slope, "Slope")],
    )
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1)
    np.testing.assert_array_equal(inits["W2"], w2)
    np.testing.assert_array_equal(inits["Slope"], slope)


def test_structured_pruning_prelu_bare_rank1_channel_shape_declines():
    # A bare rank-1 `[C1]` slope -- deliberately *not* treated as
    # per-channel for a Conv chain (unlike a MatMul/Gemm chain's own
    # last-axis-is-channel convention): ONNX's unidirectional broadcasting
    # would align it against the *trailing* (spatial) axis of a rank-4 NCHW
    # tensor, not axis 1, so accepting it here would risk silently mis-
    # slicing a tensor that isn't really per-channel at all. Must decline,
    # leaving the whole chain untouched.
    Cin, C1, C2 = 3, 8, 4
    rng = np.random.default_rng(95)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    slope = rng.standard_normal((C1,)).astype(np.float32)
    model = _model(
        f"""
        g (float[N,{Cin},10,10] X) => (float[N,{C2},6,6] Y)
        {{
          h = Conv<kernel_shape=[3,3]>(X, W1)
          a = PRelu(h, Slope)
          Y = Conv<kernel_shape=[3,3]>(a, W2)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(w2, "W2"), _f32(slope, "Slope")],
    )
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["W1"], w1)
    np.testing.assert_array_equal(inits["W2"], w2)
    np.testing.assert_array_equal(inits["Slope"], slope)


def _residual_diamond_prelu_model(w_f, w_s, w_out, slope, spatial=10):
    # The same "projection shortcut" residual shape as
    # `_residual_diamond_model`, with a per-channel PRelu hop sitting
    # between the `f` branch's own real Conv producer and the `Add` merge --
    # crossed transparently by the *backward* walk
    # (`_walk_conv_producer_backward`, via
    # `_match_prelu_pass_through_self`) on its way from the Add's own `f`
    # operand back to its real Conv producer.
    Cin = w_f.shape[1]
    Cout = w_out.shape[0]
    out_spatial = spatial - 4  # two chained 3x3 valid convs
    return _model(
        f"""
        g (float[N,{Cin},{spatial},{spatial}] X) => (float[N,{Cout},{out_spatial},{out_spatial}] Y)
        {{
          f = Conv<kernel_shape=[3,3]>(X, WF)
          fp = PRelu(f, Slope)
          s = Conv<kernel_shape=[3,3]>(X, WS)
          addr = Add(fp, s)
          r = Relu(addr)
          Y = Conv<kernel_shape=[3,3]>(r, WOUT)
        }}
        """,
        initializer=[
            _f32(w_f, "WF"),
            _f32(w_s, "WS"),
            _f32(w_out, "WOUT"),
            _f32(slope, "Slope"),
        ],
    )


def test_structured_pruning_conv_residual_add_prelu_pass_through_matches_oracle():
    # Exercises the *backward* walk's own PRelu hop
    # (`_match_prelu_pass_through_self`), not just the forward one the tests
    # above cover: a per-channel PRelu sitting between a residual branch's
    # own real Conv producer and the `Add` merge must be crossed
    # transparently and its `Slope` co-sliced by the same combined-
    # importance `keep` set both producers share.
    Cin, C, Cout = 3, 16, 8
    rng = np.random.default_rng(96)
    w_f = rng.standard_normal((C, Cin, 3, 3)).astype(np.float32)
    w_s = rng.standard_normal((C, Cin, 3, 3)).astype(np.float32)
    w_out = rng.standard_normal((Cout, C, 3, 3)).astype(np.float32)
    slope = rng.standard_normal((C, 1, 1)).astype(np.float32)
    model = _residual_diamond_prelu_model(w_f, w_s, w_out, slope)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    dims_after = _initializer_dims(pruned)
    assert dims_after["Slope"] == (C // 2, 1, 1)

    importance = np.sqrt(
        np.square(np.linalg.norm(w_f.reshape(C, -1).astype(np.float64), axis=1))
        + np.square(np.linalg.norm(w_s.reshape(C, -1).astype(np.float64), axis=1))
    )
    keep = np.sort(np.argsort(-importance)[: C // 2])
    oracle = _residual_diamond_prelu_model(
        w_f[keep], w_s[keep], w_out[:, keep], slope[keep]
    )

    rng_x = np.random.default_rng(97)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


# --- MatMul/Gemm chain: PRelu pass-through hop -------------------------


def _mlp_prelu_model(K, H, Out, slope, bias=True, seed=0):
    rng = np.random.default_rng(seed)
    w1 = rng.standard_normal((K, H)).astype(np.float32)
    w2 = rng.standard_normal((H, Out)).astype(np.float32)
    initializer = [_f32(w1, "W1"), _f32(w2, "W2"), _f32(slope, "Slope")]
    if bias:
        b1 = rng.standard_normal((H,)).astype(np.float32)
        gemm1 = "h = Gemm(X, W1, B1)"
        initializer.append(_f32(b1, "B1"))
    else:
        gemm1 = "h = MatMul(X, W1)"
    model = _model(
        f"""
        g (float[batch,{K}] X) => (float[batch,{Out}] Y)
        {{
          {gemm1}
          a = PRelu(h, Slope)
          Y = MatMul(a, W2)
        }}
        """,
        initializer=initializer,
    )
    return model, w1, w2, (b1 if bias else None)


def test_structured_pruning_matmul_prelu_per_channel_pass_through_matches_oracle_exactly():
    # The MatMul/Gemm-chain analogue of the Conv per-channel test above --
    # here `slope`'s per-channel shape is the flat, last-axis-is-channel
    # `[H]` this chain family's own convention uses (`_flat_channel_const`'s
    # own bar), not the Conv walk's `[C, 1, 1]`.
    K, H, Out = 8, 32, 4
    model, w1, w2, b1 = _mlp_prelu_model(
        K, H, Out, slope=np.random.default_rng(98).standard_normal(H).astype(np.float32)
    )
    slope = onnx.numpy_helper.to_array(
        next(t for t in model.graph.initializer if t.name == "Slope")
    )

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    dims_after = _initializer_dims(pruned)
    keep_count = H // 2
    assert dims_after["W1"][1] == keep_count
    assert dims_after["Slope"] == (keep_count,)

    keep = _oracle_keep_indices(w1, keep_count)
    # Built directly (rather than re-invoking `_mlp_prelu_model`, which
    # always draws its own fresh random weights) so the oracle is sliced
    # from these exact same arrays.
    oracle = _model(
        f"""
        g (float[batch,{K}] X) => (float[batch,{Out}] Y)
        {{
          h = Gemm(X, W1, B1)
          a = PRelu(h, Slope)
          Y = MatMul(a, W2)
        }}
        """,
        initializer=[
            _f32(w1[:, keep], "W1"),
            _f32(w2[keep], "W2"),
            _f32(b1[keep], "B1"),
            _f32(slope[keep], "Slope"),
        ],
    )

    rng_x = np.random.default_rng(99)
    x = rng_x.standard_normal((5, K)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_matmul_prelu_scalar_shared_slope_pass_through_matches_oracle_exactly():
    # A scalar/single-shared-parameter `slope` -- left completely untouched,
    # the MatMul/Gemm-chain analogue of the Conv scalar test above.
    K, H, Out = 8, 32, 4
    slope = np.random.default_rng(100).standard_normal(1).astype(np.float32)
    model, w1, w2, b1 = _mlp_prelu_model(K, H, Out, slope=slope)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    dims_after = _initializer_dims(pruned)
    keep_count = H // 2
    assert dims_after["W1"][1] == keep_count
    assert dims_after["Slope"] == (1,)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["Slope"], slope)

    keep = _oracle_keep_indices(w1, keep_count)
    oracle = _model(
        f"""
        g (float[batch,{K}] X) => (float[batch,{Out}] Y)
        {{
          h = Gemm(X, W1, B1)
          a = PRelu(h, Slope)
          Y = MatMul(a, W2)
        }}
        """,
        initializer=[
            _f32(w1[:, keep], "W1"),
            _f32(w2[keep], "W2"),
            _f32(b1[keep], "B1"),
            _f32(slope, "Slope"),
        ],
    )

    rng_x = np.random.default_rng(101)
    x = rng_x.standard_normal((5, K)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_resize_upsample_concat_unet_decoder_matches_oracle_exactly():
    # The real-world shape this backward-walk extension exists for: a U-Net/
    # diffusion-model-style decoder branch (`Conv -> Resize` upsampling the
    # decoder's own spatial size to match the encoder skip branch) merged
    # via a channel-axis `Concat` with a plain encoder skip branch, feeding
    # one shared consumer Conv. This exercises
    # `_walk_conv_producer_backward`'s own new `Resize` hop (used by
    # `_find_conv_concat_chains` to resolve the decoder branch's own operand
    # backward to its real Conv producer), not the forward walk the other
    # tests above exercise.
    Cskip, Cdec, Cout = 4, 6, 5
    rng = np.random.default_rng(77)
    w_skip = rng.standard_normal((Cskip, 3, 3, 3)).astype(np.float32)
    w_dec = rng.standard_normal((Cdec, 3, 3, 3)).astype(np.float32)
    w_out = rng.standard_normal((Cout, Cskip + Cdec, 3, 3)).astype(np.float32)
    scales = [1.0, 1.0, 2.0, 2.0]

    def build(w_skip, w_dec, w_out):
        Cout_ = w_out.shape[0]
        initializer = [
            _f32(w_skip, "Wskip"),
            _f32(w_dec, "Wdec"),
            _f32(w_out, "Wout"),
            onnx.numpy_helper.from_array(
                np.asarray(scales, dtype=np.float32), "Scales"
            ),
        ]
        return _model(
            f"""
            g (float[N,3,10,10] Xskip, float[N,3,6,6] Xdec) => (float[N,{Cout_},6,6] Y)
            {{
              hskip = Conv<kernel_shape=[3,3]>(Xskip, Wskip)
              hdec = Conv<kernel_shape=[3,3]>(Xdec, Wdec)
              pdec = Resize<mode="nearest">(hdec, , Scales)
              merged = Concat<axis=1>(hskip, pdec)
              Y = Conv<kernel_shape=[3,3]>(merged, Wout)
            }}
            """,
            initializer=initializer,
        )

    model = build(w_skip, w_dec, w_out)
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    dims_after = _initializer_dims(pruned)
    assert dims_after["Wdec"][0] < Cdec  # actually pruned, not a no-op
    assert dims_after["Wskip"][0] < Cskip

    keep_skip = _oracle_keep_indices_conv(w_skip, dims_after["Wskip"][0])
    keep_dec = _oracle_keep_indices_conv(w_dec, dims_after["Wdec"][0])
    global_keep = np.concatenate([keep_skip, keep_dec + Cskip])
    oracle = build(w_skip[keep_skip], w_dec[keep_dec], w_out[:, global_keep])

    rng_x = np.random.default_rng(78)
    x_skip = rng_x.standard_normal((2, 3, 10, 10)).astype(np.float32)
    x_dec = rng_x.standard_normal((2, 3, 6, 6)).astype(np.float32)
    (y,) = _run(pruned, {"Xskip": x_skip, "Xdec": x_dec})
    (y_oracle,) = _run(oracle, {"Xskip": x_skip, "Xdec": x_dec})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


# --- Conv chain: Clip (ReLU6) pass-through hop -------------------------------
#
# `Clip` -- the op `torch.nn.ReLU6` lowers to (opset 11+'s `input, min?, max?`
# input-based signature) -- is a pure elementwise clamp with zero channel
# dependence whenever a present `min`/`max` operand is a scalar constant (see
# `_match_clip_channel_pass_through`'s own docstring): unlike `Resize`/`Pad`,
# neither operand is axis-indexed at all, so no axis reasoning -- and no
# dependence on the actual `min`/`max` *value* -- is needed to prove it's
# safe to cross transparently. This closes the ReLU6 activation shape
# MobileNetV2/V3 and EfficientNet-Lite backbones use throughout (confirmed
# empirically, before this hop existed, via `grep -n "\"Clip\""` over this
# Conv-chain-walking section returning zero hits).


def _clip_conv_pair_model(w1, w2, min_val=None, max_val=None, b1=None, spatial=10):
    """`Conv -> Clip -> Conv`, `min_val`/`max_val` (each `None` or a Python
    float) become `Min`/`Max` 0-D float32 scalar initializers -- omitted
    entirely from `Clip`'s own inputs when `None`, exactly like `ReLU6`'s own
    two-sided clamp when both are given, or the one-sided shape some
    exporters emit when only one is (`Clip`'s own schema makes both
    optional)."""
    Cin, C2 = w1.shape[1], w2.shape[0]
    initializer = [_f32(w1, "W1"), _f32(w2, "W2")]
    if b1 is not None:
        conv1 = "h = Conv<kernel_shape=[3,3]>(X, W1, B1)"
        initializer.append(_f32(b1, "B1"))
    else:
        conv1 = "h = Conv<kernel_shape=[3,3]>(X, W1)"
    if min_val is not None:
        initializer.append(
            onnx.numpy_helper.from_array(np.array(min_val, dtype=np.float32), "Min")
        )
    if max_val is not None:
        initializer.append(
            onnx.numpy_helper.from_array(np.array(max_val, dtype=np.float32), "Max")
        )
    if min_val is not None and max_val is not None:
        clip_node = "p = Clip(h, Min, Max)"
    elif min_val is not None:
        clip_node = "p = Clip(h, Min)"
    elif max_val is not None:
        clip_node = "p = Clip(h, , Max)"
    else:
        clip_node = "p = Clip(h)"
    out_spatial = spatial - 4  # two valid (no-pad) 3x3 convs
    return _model(
        f"""
        g (float[N,{Cin},{spatial},{spatial}] X) => (float[N,{C2},{out_spatial},{out_spatial}] Y)
        {{
          {conv1}
          {clip_node}
          Y = Conv<kernel_shape=[3,3]>(p, W2)
        }}
        """,
        initializer=initializer,
    )


def test_structured_pruning_clip_relu6_pass_through_matches_oracle_exactly():
    # Conv -> Clip(min=0, max=6) -> Conv, both bounds plain scalar constant
    # initializers -- exactly `ReLU6`'s own two-sided clamp, and the shape
    # `torch.onnx.export(nn.ReLU6(), ...)` emits live (`Clip` fed by
    # `Constant`-folded scalar `min`/`max`, confirmed by direct export in
    # this feature's own verification). Must be left entirely untouched
    # (only its own `h`/`p` shapes change), weights sliced normally on both
    # sides, output matching an independently, already-pruned reference
    # model -- never a post-hoc slice of the full unpruned model's own
    # output.
    Cin, C1, C2 = 3, 16, 8
    rng = np.random.default_rng(79)
    w1 = rng.standard_normal((C1, Cin, 3, 3)).astype(np.float32)
    b1 = rng.standard_normal((C1,)).astype(np.float32)
    w2 = rng.standard_normal((C2, C1, 3, 3)).astype(np.float32)
    model = _clip_conv_pair_model(w1, w2, min_val=0.0, max_val=6.0, b1=b1)

    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    dims_after = _initializer_dims(pruned)
    assert dims_after["W1"][0] == C1 // 2
    assert dims_after["W2"][1] == C1 // 2
    # The Clip node itself is untouched -- still a plain scalar Min/Max.
    pruned_clip = next(n for n in pruned.graph.node if n.op_type == "Clip")
    pruned_inits = {
        t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer
    }
    np.testing.assert_array_equal(pruned_inits[pruned_clip.input[1]], np.float32(0.0))
    np.testing.assert_array_equal(pruned_inits[pruned_clip.input[2]], np.float32(6.0))

    keep = _oracle_keep_indices_conv(w1, C1 // 2)
    oracle = _clip_conv_pair_model(
        w1[keep], w2[:, keep], min_val=0.0, max_val=6.0, b1=b1[keep]
    )

    rng_x = np.random.default_rng(80)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y, y_oracle, rtol=1e-5, atol=1e-5)


def test_structured_pruning_clip_min_only_pass_through_matches_oracle_exactly():
    # `max` omitted entirely (a one-sided lower-bound clamp -- plain `Relu`
    # with an explicit `Clip` encoding some exporters use) -- both operands
    # are optional per Clip's own schema, so this must still be recognized.
    Cin, C1, C2 = 3, 16, 8
