def test_mha_pruning_diff_v_head_size_matches_oracle_exactly():
    # V's own head_size (Dv) genuinely differs from Q/K's shared one (D) --
    # a shape this op's schema allows (confirmed empirically, see
    # onnxsim/pruning.py's own "Attention-head pruning" section comment) but
    # `GroupQueryAttention` never produces.
    model, cfg = _mha_model(K=8, H=4, D=4, Dv=6, Out=6, seed=20)
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    node = _mha_node(pruned)
    num_heads = _mha_num_heads(node)
    d, dv = cfg["D"], cfg["Dv"]
    keep_heads = _oracle_keep_groups(
        cfg["wq"],
        cfg["wk"],
        cfg["wv"],
        cfg["H"],
        cfg["H"],
        d,
        num_heads,
        v_head_size=dv,
    )
    q_idx = _head_idx(keep_heads, d)
    v_idx = _head_idx(keep_heads, dv)

    oracle, _ = _mha_model(
        K=cfg["K"],
        H=len(keep_heads),
        D=d,
        Dv=dv,
        Out=cfg["Out"],
        seed=20,
        wq=cfg["wq"][:, q_idx],
        wk=cfg["wk"][:, q_idx],
        wv=cfg["wv"][:, v_idx],
        wout=cfg["wout"][v_idx, :],
        batch=cfg["batch"],
        seq=cfg["seq"],
    )
    rng = np.random.default_rng(21)
    x = rng.standard_normal((cfg["batch"], cfg["seq"], cfg["K"])).astype(np.float32)
    (y_pruned,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y_pruned, y_oracle, rtol=1e-4, atol=1e-4)


def test_mha_pruning_packed_qkv_query_input_is_declined():
    # This op's own alternate "packed QKV" calling convention -- `query`
    # alone carrying a packed, rank-5 tensor, `key`/`value` left empty -- is
    # a different tensor layout this pass doesn't attempt to slice (the same
    # schema-level convention `GroupQueryAttention` itself declines -- see
    # `_match_gqa_producer`'s own docstring). Structural-only: `key`/`value`
    # genuinely absent is enough to decline the match, regardless of
    # whether `query` is actually packed-shaped.
    H, D = 4, 4
    K = H * D
    batch, seq = 2, 5
    rng = np.random.default_rng(22)
    wq = rng.standard_normal((K, K)).astype(np.float32)
    model = parser.parse_model(
        f"""
        <
          ir_version: 10,
          opset_import: ["": 17, "com.microsoft": 1]
        >
        g (float[{batch},{seq},{K}] X) => (float[{batch},{seq},{K}] Y)
        {{
          q = MatMul(X, Wq)
          ctx = com.microsoft.MultiHeadAttention <num_heads={H}> (q)
          Y = Identity(ctx)
        }}
        """
    )
    model.graph.initializer.append(_f32(wq, "Wq"))

    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_attention_head_pruning, sparsity=0.5
    )
    assert report.not_eligible == ["MultiHeadAttention 'ctx'"]

    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    node = _mha_node(pruned)
    assert _mha_num_heads(node) == H  # left completely untouched


# --- apply_attention_head_pruning / _wanda_pruning -- MultiHeadAttention,
# cross-attention (Q and K/V from genuinely different source tensors, at
# genuinely different sequence lengths) --------------------------------
#
# Confirmed empirically (see onnxsim/pruning.py's own "Attention-head
# pruning" section comment): unlike `GroupQueryAttention`'s own onnxruntime
# CPU-kernel restriction (equal Q/K-V sequence length unless a non-empty
# past_key/past_value is also supplied), `MultiHeadAttention` has no such
# restriction -- `seq_q`/`seq_kv` genuinely differ below, exactly like the
# plain ai.onnx Attention op's own cross-attention section.


def _mha_cross_model(
    K_dec=8,
    K_enc=6,
    H=4,
    D=4,
    Out=6,
    seed=0,
    batch=2,
    seq_q=5,
    seq_kv=7,
    wq=None,
    wk=None,
    wv=None,
    wout=None,
):
    rng = np.random.default_rng(seed)
    Nq = H * D
    if wq is None:
        wq = rng.standard_normal((K_dec, Nq)).astype(np.float32)
    if wk is None:
        wk = rng.standard_normal((K_enc, Nq)).astype(np.float32)
    if wv is None:
        wv = rng.standard_normal((K_enc, Nq)).astype(np.float32)
    if wout is None:
        wout = rng.standard_normal((Nq, Out)).astype(np.float32)

    initializer = [_f32(wq, "Wq"), _f32(wk, "Wk"), _f32(wv, "Wv"), _f32(wout, "Wout")]

    body = f"""
        g (float[{batch},{seq_q},{K_dec}] Xdec, float[{batch},{seq_kv},{K_enc}] Xenc) => (float[{batch},{seq_q},{Out}] Y)
        {{
          q = MatMul(Xdec, Wq)
          k = MatMul(Xenc, Wk)
          v = MatMul(Xenc, Wv)
          ctx = com.microsoft.MultiHeadAttention <num_heads={H}> (q, k, v)
          Y = MatMul(ctx, Wout)
        }}
        """

    model = parser.parse_model(
        f"""
        <
          ir_version: 10,
          opset_import: ["": 17, "com.microsoft": 1]
        >
        {body}
        """
    )
    model.graph.initializer.extend(initializer)
    return model, dict(
        K_dec=K_dec,
        K_enc=K_enc,
        H=H,
        D=D,
        Out=Out,
        Nq=Nq,
        wq=wq,
        wk=wk,
        wv=wv,
        wout=wout,
        batch=batch,
        seq_q=seq_q,
        seq_kv=seq_kv,
    )


def test_mha_pruning_cross_attention_matches_oracle_exactly():
    # Q's own producer weight (`K_dec` rows) and K/V's own (`K_enc` rows)
    # have genuinely different row counts here -- `_oracle_keep_groups_cross`
    # (sqrt(sum of squared per-block norms), not concatenate-then-norm) is
    # required for exactly the reason `_gqa_group_importance`'s own updated
    # comment in onnxsim/pruning.py explains.
    model, cfg = _mha_cross_model(K_dec=8, K_enc=6, H=8, D=4, Out=6, seed=26)
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    node = _mha_node(pruned)
    num_heads = _mha_num_heads(node)
    d = cfg["D"]
    keep_heads = _oracle_keep_groups_cross(
        cfg["wq"], cfg["wk"], cfg["wv"], cfg["H"], cfg["H"], d, num_heads
    )
    idx = _head_idx(keep_heads, d)

    oracle, _ = _mha_cross_model(
        K_dec=cfg["K_dec"],
        K_enc=cfg["K_enc"],
        H=len(keep_heads),
        D=d,
        Out=cfg["Out"],
        seed=26,
        wq=cfg["wq"][:, idx],
        wk=cfg["wk"][:, idx],
        wv=cfg["wv"][:, idx],
        wout=cfg["wout"][idx, :],
        batch=cfg["batch"],
        seq_q=cfg["seq_q"],
        seq_kv=cfg["seq_kv"],
    )

    rng = np.random.default_rng(27)
    xdec = rng.standard_normal((cfg["batch"], cfg["seq_q"], cfg["K_dec"])).astype(
        np.float32
    )
    xenc = rng.standard_normal((cfg["batch"], cfg["seq_kv"], cfg["K_enc"])).astype(
        np.float32
    )
    (y_pruned,) = _run(pruned, {"Xdec": xdec, "Xenc": xenc})
    (y_oracle,) = _run(oracle, {"Xdec": xdec, "Xenc": xenc})
    np.testing.assert_allclose(y_pruned, y_oracle, rtol=1e-4, atol=1e-4)

    # Sanity: Q and K/V really are independently sourced, at genuinely
    # different sequence lengths -- perturbing Xenc alone (Xdec held fixed)
    # must still change the output.
    (y_pruned2,) = _run(pruned, {"Xdec": xdec, "Xenc": xenc + 1.0})
    assert not np.allclose(y_pruned, y_pruned2)


def test_mha_wanda_pruning_matches_oracle_exactly():
    model, cfg = _mha_model(K=8, H=8, D=4, Out=6, seed=28, combined_bias=True)

    rng = np.random.default_rng(29)
    x_cal = rng.standard_normal((cfg["batch"], cfg["seq"], cfg["K"])).astype(np.float32)
    calibration_data = [{"X": x_cal}]

    pruned = onnxsim.apply_attention_head_wanda_pruning(
        model, calibration_data=calibration_data, sparsity=0.5
    )
    onnx.checker.check_model(pruned)

    probe_model = onnx.ModelProto()
    probe_model.CopyFrom(model)
    probe_model.graph.output.append(onnx.ValueInfoProto(name="ctx"))
    (_, ctx_cal) = _run(probe_model, {"X": x_cal})
    act_norm = np.sqrt(np.mean(np.square(ctx_cal.astype(np.float64)), axis=(0, 1)))

    d = cfg["D"]
    importance = np.zeros(cfg["H"])
    for h in range(cfg["H"]):
        block = np.concatenate(
            [
                cfg["wq"][:, h * d : (h + 1) * d],
                cfg["wk"][:, h * d : (h + 1) * d],
                cfg["wv"][:, h * d : (h + 1) * d],
            ],
            axis=1,
        )
        base = np.linalg.norm(block)
        act_head = np.linalg.norm(act_norm[h * d : (h + 1) * d])
        importance[h] = base * max(act_head, 1e-8)
    keep_heads = np.sort(np.argsort(-importance)[:4])  # max(1, 8 - round(8*0.5))
    idx = _head_idx(keep_heads, d)

    oracle, _ = _mha_model(
        K=cfg["K"],
        H=len(keep_heads),
        D=d,
        Out=cfg["Out"],
        seed=28,
        combined_bias=True,
        wq=cfg["wq"][:, idx],
        wk=cfg["wk"][:, idx],
        wv=cfg["wv"][:, idx],
        bq=cfg["bq"][idx],
        bk=cfg["bk"][idx],
        bv=cfg["bv"][idx],
        wout=cfg["wout"][idx, :],
        batch=cfg["batch"],
        seq=cfg["seq"],
    )

    rng2 = np.random.default_rng(30)
    x = rng2.standard_normal((cfg["batch"], cfg["seq"], cfg["K"])).astype(np.float32)
    (y_pruned,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y_pruned, y_oracle, rtol=1e-4, atol=1e-4)


# --- apply_attention_head_pruning / _wanda_pruning -- DecoderMaskedSelfAttention --
#
# ONNX Runtime's own in-place decode-time rewrite target for
# `com.microsoft::Attention` (`onnxruntime.transformers.convert_generation
# .update_decoder_subgraph_use_decoder_masked_attention`'s own
# `switch_attention` branch literally reassigns an `Attention` node's own
# `op_type` to this) -- see onnxsim/pruning.py's own "Attention-head
# pruning" section comment for the full empirical schema/execution
# investigation this section's tests continue.
#
# **No CPU kernel exists for this op in this environment's onnxruntime at
# all** (confirmed empirically: a minimal, `onnx.checker`-valid
# `DecoderMaskedSelfAttention` node fails `onnxruntime.InferenceSession`
# construction outright with ``NOT_IMPLEMENTED : ... Could not find an
# implementation for DecoderMaskedSelfAttention``) -- so, following this
# module's own `MatMulNBitsMlp`/`MatMulNBitsQkv`/`PagedAttention` precedent
# for a matched op with no executable kernel (see onnxsim/pruning.py's own
# section comments for those), every correctness test below decomposes a
# pruned node's own sliced `weights`/`bias` into an equivalent, genuinely
# executable plain `com.microsoft::Attention` node (same merged-QKV layout,
# `do_rotary=0` -- the only value this pass ever matches for this op
# anyway) and runs *that* through a real CPU-kernel `InferenceSession`,
# compared against a numpy-oracle-equivalent independently-built smaller
# `Attention` model using only the correctly-selected kept heads' own
# original (pre-pruning) weight columns -- never the pruned
# `DecoderMaskedSelfAttention` node itself, and never a comparison against
# the *full, unpruned* model's own output.


def _dmsa_model(
    K=8,
    H=4,
    D=4,
    Out=6,
    seed=0,
    batch=2,
    bias=True,
    wqkv=None,
    bqkv=None,
    wout=None,
    do_rotary=0,
    past="",  # "" (omitted) | "dynamic" | "constant"
):
    rng = np.random.default_rng(seed)
    Nq = Nk = Nv = H * D
    if wqkv is None:
        wqkv = rng.standard_normal((K, Nq + Nk + Nv)).astype(np.float32)
    if wout is None:
        wout = rng.standard_normal((Nv, Out)).astype(np.float32)
    if bias and bqkv is None:
        bqkv = rng.standard_normal((Nq + Nk + Nv,)).astype(np.float32)

    initializer = [_f32(wqkv, "Wqkv"), _f32(wout, "Wout")]
    operands = ["X", "Wqkv"]
    if bias:
        initializer.append(_f32(bqkv, "Bqkv"))
        operands.append("Bqkv")
    else:
        operands.append("")

    extra_graph_inputs = ""
    if past == "constant":
        past_init = rng.standard_normal((2, batch, H, 1, D)).astype(np.float32)
        initializer.append(_f32(past_init, "Past"))
        operands += ["", "Past"]  # mask_index="", past="Past"
    elif past == "dynamic":
        operands += ["", "PastIn"]
        extra_graph_inputs = f", float[2,{batch},{H},1,{D}] PastIn"

    while operands and operands[-1] == "":
        operands.pop()
    qkv_inputs = ", ".join(operands)

    attrs = f"num_heads={H}"
    if do_rotary:
        attrs += f", do_rotary={do_rotary}"

    body = f"""
        g (float[{batch},1,{K}] X{extra_graph_inputs}) => (float[{batch},1,{Out}] Y)
        {{
          ctx = com.microsoft.DecoderMaskedSelfAttention <{attrs}> ({qkv_inputs})
          Y = MatMul(ctx, Wout)
        }}
        """

    model = parser.parse_model(
        f"""
        <
          ir_version: 10,
          opset_import: ["": 17, "com.microsoft": 1]
        >
        {body}
        """
    )
    model.graph.initializer.extend(initializer)
    return model, dict(
        K=K,
        H=H,
        D=D,
        Out=Out,
        Nq=Nq,
        Nk=Nk,
        Nv=Nv,
        wqkv=wqkv,
        bqkv=bqkv,
        wout=wout,
        batch=batch,
    )


def _dmsa_node(model):
    return next(
        n for n in model.graph.node if n.op_type == "DecoderMaskedSelfAttention"
    )


def _dmsa_num_heads(node):
    return next(a.i for a in node.attribute if a.name == "num_heads")


def _dmsa_has_qkv_hidden_sizes(node):
    return any(a.name == "qkv_hidden_sizes" for a in node.attribute)


def test_dmsa_pruning_shrinks_matched_block():
    model, cfg = _dmsa_model(K=8, H=4, D=4, Out=6)
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)

    node = _dmsa_node(pruned)
    assert _dmsa_num_heads(node) == 2  # max(1, 4 - round(4*0.5))
    # No `qkv_hidden_sizes` attribute is ever written back for this op --
    # it doesn't exist on the op's own real schema at all (see
    # onnxsim/pruning.py's own "Attention-head pruning" section comment).
    assert not _dmsa_has_qkv_hidden_sizes(node)

    inits = {t.name: t for t in pruned.graph.initializer}
    assert list(inits["Wqkv"].dims) == [8, 24]  # 2 heads * (4+4+4)
    assert list(inits["Bqkv"].dims) == [24]
    assert list(inits["Wout"].dims) == [8, 6]


def test_dmsa_pruning_zero_sparsity_is_a_no_op():
    model, cfg = _dmsa_model(K=8, H=8, D=4, Out=6, seed=7)
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.0)
    node = _dmsa_node(pruned)
    assert _dmsa_num_heads(node) == cfg["H"]
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["Wqkv"], cfg["wqkv"])


def test_dmsa_pruning_matches_oracle_via_attention_proxy():
    # Even split -- `dq == dk == dv` -- is the *only* shape this matcher
    # ever accepts for this op (no `qkv_hidden_sizes` attribute exists on
    # its own real schema at all, see onnxsim/pruning.py's own
    # "Attention-head pruning" section comment) -- confirmed here by
    # slicing manually and checking the pruned weight's own head-block
    # structure is exactly what a plain `Attention` proxy of the same
    # (now-smaller) head count would expect.
    model, cfg = _dmsa_model(K=8, H=8, D=4, Out=6, seed=1)
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)

    node = _dmsa_node(pruned)
    num_heads = _dmsa_num_heads(node)
    assert num_heads == 4  # max(1, 8 - round(8*0.5))

    d = cfg["D"]
    keep_heads = _oracle_keep_heads(
        cfg["wqkv"], cfg["Nq"], cfg["Nk"], cfg["Nv"], cfg["H"], num_heads
    )
    idx = _head_idx(keep_heads, d)

    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    q_idx = idx
    k_idx = idx + cfg["Nq"]
    v_idx = idx + cfg["Nq"] + cfg["Nk"]
    all_idx = np.concatenate([q_idx, k_idx, v_idx])
    np.testing.assert_array_equal(inits["Wqkv"], cfg["wqkv"][:, all_idx])

    # Decompose the pruned node's own sliced tensors into a genuinely
    # executable plain `Attention` proxy (see this section's own comment
    # above for why) and compare against an independently-built smaller
    # `Attention` oracle sliced straight from the *original* (pre-pruning)
    # weights -- never against the full unpruned model's own output.
    proxy, _ = _attention_model(
        K=cfg["K"],
        H=num_heads,
        D=d,
        Out=cfg["Out"],
        wqkv=inits["Wqkv"],
        bqkv=inits["Bqkv"],
        wout=inits["Wout"],
    )
    oracle, _ = _attention_model(
        K=cfg["K"],
        H=num_heads,
        D=d,
        Out=cfg["Out"],
        wqkv=cfg["wqkv"][:, all_idx],
        bqkv=cfg["bqkv"][all_idx],
        wout=cfg["wout"][idx, :],
    )
    rng = np.random.default_rng(2)
    x = rng.standard_normal((cfg["batch"], 1, cfg["K"])).astype(np.float32)
    (y_proxy,) = _run(proxy, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y_proxy, y_oracle, rtol=1e-4, atol=1e-4)


def test_dmsa_pruning_declines_do_rotary():
    # Fused rotary (computed inside the op, no external cos_cache/sin_cache
    # input on this op's own schema at all) is declined outright: no CPU
    # kernel exists for this op at all in this environment, and the closely
    # related, CPU-kernel-backed `Attention` op's own `do_rotary=1` path is
    # itself confirmed unimplemented in this environment's CPU kernel
    # ("Rotary embedding is not supported in Attention CPU kernel...") --
    # see onnxsim/pruning.py's own "Attention-head pruning" section comment
    # for the full reasoning. `do_rotary=0` (the default) matches fine, see
    # every other test in this section.
    model, cfg = _dmsa_model(K=8, H=4, D=4, Out=6, seed=3, do_rotary=1)
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    node = _dmsa_node(pruned)
    assert _dmsa_num_heads(node) == cfg["H"]  # left completely untouched

    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_attention_head_pruning, sparsity=0.5
    )
    assert report.not_eligible == ["DecoderMaskedSelfAttention 'ctx'"]
    assert report.layers == []


def test_dmsa_pruning_declines_constant_past():
    # `past` is *required* by this op's own schema (unlike `Attention`'s
    # own optional one) and real step-of-1 decode exports always leave it
    # dynamic -- but a hand-built graph could in principle bind a constant
    # there, which this pass has no established slicing path for (unlike
    # the `past_key`/`past_value` *pair* every separate-Q/K/V op in this
    # section already handles) -- so it conservatively declines the whole
    # match rather than leaving a stale-shaped constant behind.
    model, cfg = _dmsa_model(K=8, H=4, D=4, Out=6, seed=4, past="constant")
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    node = _dmsa_node(pruned)
    assert _dmsa_num_heads(node) == cfg["H"]  # left completely untouched

    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_attention_head_pruning, sparsity=0.5
    )
    assert report.not_eligible == ["DecoderMaskedSelfAttention 'ctx'"]


def test_dmsa_pruning_dynamic_past_is_pruned_normally():
    # A *dynamic* `past` (an ordinary graph input, the realistic step-of-1
    # decode shape) is the caller's own runtime state, not a weight this
    # pass could corrupt by leaving untouched -- matches and prunes
    # normally, unlike the constant case above.
    model, cfg = _dmsa_model(K=8, H=4, D=4, Out=6, seed=5, past="dynamic")
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    node = _dmsa_node(pruned)
    assert _dmsa_num_heads(node) == 2  # max(1, 4 - round(4*0.5))


def test_dmsa_pruning_dry_run_matches_real_call():
    model, cfg = _dmsa_model(K=8, H=8, D=4, Out=6, seed=6)
    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_attention_head_pruning, sparsity=0.5
    )
    assert len(report.layers) == 1
    layer = report.layers[0]
    assert layer.family == "attention_head"
    assert layer.total == 8
    assert layer.would_drop == 4  # round(8*0.5)

    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    node = _dmsa_node(pruned)
    assert cfg["H"] - _dmsa_num_heads(node) == layer.would_drop


# --- apply_attention_head_pruning / _wanda_pruning -- DecoderMaskedMultiHeadAttention --
#
# ONNX Runtime's own in-place decode-time rewrite target for
# `com.microsoft::MultiHeadAttention` (`onnxruntime.transformers
# .convert_generation.replace_mha_with_dmmha`'s own literal node
# construction) -- see onnxsim/pruning.py's own "Attention-head pruning"
# section comment for the full empirical schema/execution investigation
# this section's tests continue, including exactly why every input beyond
# `query`/`key`/`value` sits at a different index than `MultiHeadAttention`'s
# own (`mask_index`@3, `attention_bias`@4, `past_key`/`past_value`@5/6,
# `past_sequence_length`/`beam_width`/`cache_indirection`@7/8/9, and a
# combined `bias` moved all the way to index 10).
#
# Unlike `DecoderMaskedSelfAttention` above, a real CPU kernel *does* exist
# for this op in this environment -- every correctness test below runs the
# actual pruned `DecoderMaskedMultiHeadAttention` node through a real
# `onnxruntime.InferenceSession`, matched against a numpy-oracle-equivalent
# independently-built smaller `DecoderMaskedMultiHeadAttention` model using
# only the correctly-selected kept heads' own original (pre-pruning)
# weights -- never against the full unpruned model's own output. This
# environment's own CPU kernel requires query/key/value sequence length to
# be exactly 1 (``"Input sequence length should be 1 to use
# DecoderMaskedMultiHeadAttention"`` otherwise) -- a purely runtime-shape
# constraint invisible to this pass's own static graph matching, but every
# model built below uses `seq_len=1` throughout so it can actually run.


def _dmmha_model(
    K=8,
    H=4,
    D=4,
    Out=6,
    seed=0,
    batch=2,
    combined_bias=False,
    producer_bias=False,
    wq=None,
    wk=None,
    wv=None,
    bq=None,
    bk=None,
    bv=None,
    wout=None,
    attention_bias=None,
    past_kv=None,  # None | "nonempty" | "dynamic"
    past_key=None,
    past_value=None,
    past_seq=3,
    max_seq=8,
):
    rng = np.random.default_rng(seed)
    Nq = Nk = Nv = H * D
    if wq is None:
        wq = rng.standard_normal((K, Nq)).astype(np.float32)
    if wk is None:
        wk = rng.standard_normal((K, Nk)).astype(np.float32)
    if wv is None:
        wv = rng.standard_normal((K, Nv)).astype(np.float32)
    if wout is None:
        wout = rng.standard_normal((Nv, Out)).astype(np.float32)

    initializer = [_f32(wq, "Wq"), _f32(wk, "Wk"), _f32(wv, "Wv"), _f32(wout, "Wout")]
    q_op, k_op, v_op = "MatMul(X, Wq)", "MatMul(X, Wk)", "MatMul(X, Wv)"
    if producer_bias:
        if bq is None:
            bq = rng.standard_normal((Nq,)).astype(np.float32)
        if bk is None:
            bk = rng.standard_normal((Nk,)).astype(np.float32)
        if bv is None:
            bv = rng.standard_normal((Nv,)).astype(np.float32)
        initializer += [_f32(bq, "Bq"), _f32(bk, "Bk"), _f32(bv, "Bv")]
        q_op, k_op, v_op = "Gemm(X, Wq, Bq)", "Gemm(X, Wk, Bk)", "Gemm(X, Wv, Bv)"

    # Fixed-index layout: query, key, value, mask_index, attention_bias,
    # past_key, past_value, past_sequence_length, beam_width,
    # cache_indirection, bias -- see this section's own comment above for
    # why this differs from `MultiHeadAttention`'s own layout.
    operands = ["q", "k", "v", "", "", "", "", "", "", "", ""]
    extra_graph_inputs = ""
    present_outputs = ""
    attrs = f"num_heads={H}"

    if attention_bias is not None:
        initializer.append(_f32(np.asarray(attention_bias), "AttentionBias"))
        operands[4] = "AttentionBias"

    if past_kv == "nonempty":
        if past_key is None:
            past_key = rng.standard_normal((batch, H, past_seq, D)).astype(np.float32)
        if past_value is None:
            past_value = rng.standard_normal((batch, H, past_seq, D)).astype(np.float32)
        pk_buf = np.zeros((batch, H, max_seq, D), dtype=np.float32)
        pv_buf = np.zeros((batch, H, max_seq, D), dtype=np.float32)
        pk_buf[:, :, :past_seq, :] = past_key
        pv_buf[:, :, :past_seq, :] = past_value
        initializer += [_f32(pk_buf, "PastKey"), _f32(pv_buf, "PastValue")]
        initializer.append(
            onnx.numpy_helper.from_array(
                np.array([past_seq], dtype=np.int32), "PastSeqLen"
            )
        )
        operands[5] = "PastKey"
        operands[6] = "PastValue"
        operands[7] = "PastSeqLen"
        present_outputs = ", present_key, present_value"
        attrs += ", past_present_share_buffer=1"
    elif past_kv == "dynamic":
        operands[5] = "PastKeyIn"
        operands[6] = "PastValueIn"
        extra_graph_inputs += (
            f", float[{batch},{H},{past_seq},{D}] PastKeyIn"
            f", float[{batch},{H},{past_seq},{D}] PastValueIn"
        )

    if combined_bias:
        if bq is None:
            bq = rng.standard_normal((Nq,)).astype(np.float32)
        if bk is None:
            bk = rng.standard_normal((Nk,)).astype(np.float32)
        if bv is None:
            bv = rng.standard_normal((Nv,)).astype(np.float32)
        combined = np.concatenate([bq, bk, bv]).astype(np.float32)
        initializer.append(_f32(combined, "Bias"))
        operands[10] = "Bias"

    while operands and operands[-1] == "":
        operands.pop()

    ctx_outputs = "ctx" + present_outputs
    body = f"""
        g (float[{batch},1,{K}] X{extra_graph_inputs}) => (float[{batch},1,{Out}] Y)
        {{
          q = {q_op}
          k = {k_op}
          v = {v_op}
          {ctx_outputs} = com.microsoft.DecoderMaskedMultiHeadAttention <{attrs}> ({", ".join(operands)})
          Y = MatMul(ctx, Wout)
        }}
        """

    model = parser.parse_model(
        f"""
        <
          ir_version: 10,
          opset_import: ["": 17, "com.microsoft": 1]
        >
        {body}
        """
    )
    model.graph.initializer.extend(initializer)
    return model, dict(
        K=K,
        H=H,
        D=D,
        Out=Out,
        Nq=Nq,
        Nk=Nk,
        Nv=Nv,
        wq=wq,
        wk=wk,
        wv=wv,
        bq=bq,
        bk=bk,
        bv=bv,
        wout=wout,
        batch=batch,
        past_key=past_key,
        past_value=past_value,
    )


def _dmmha_node(model):
    return next(
        n for n in model.graph.node if n.op_type == "DecoderMaskedMultiHeadAttention"
    )


def _dmmha_num_heads(node):
    return next(a.i for a in node.attribute if a.name == "num_heads")


def test_dmmha_pruning_shrinks_matched_block():
    model, cfg = _dmmha_model(K=8, H=4, D=4, Out=6)
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    node = _dmmha_node(pruned)
    assert _dmmha_num_heads(node) == 2  # max(1, 4 - round(4*0.5))

    inits = {t.name: t for t in pruned.graph.initializer}
    assert list(inits["Wq"].dims) == [8, 8]
    assert list(inits["Wk"].dims) == [8, 8]
    assert list(inits["Wv"].dims) == [8, 8]
    assert list(inits["Wout"].dims) == [8, 6]

    rng = np.random.default_rng(1)
    x = rng.standard_normal((cfg["batch"], 1, cfg["K"])).astype(np.float32)
    (y,) = _run(pruned, {"X": x})
    assert y.shape == (cfg["batch"], 1, cfg["Out"])


def test_dmmha_pruning_zero_sparsity_is_a_no_op():
    model, cfg = _dmmha_model(K=8, H=8, D=4, Out=6, seed=7)
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.0)
    node = _dmmha_node(pruned)
    assert _dmmha_num_heads(node) == cfg["H"]
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["Wq"], cfg["wq"])
    np.testing.assert_array_equal(inits["Wk"], cfg["wk"])
    np.testing.assert_array_equal(inits["Wv"], cfg["wv"])


def test_dmmha_pruning_matches_oracle_exactly():
    model, cfg = _dmmha_model(K=8, H=8, D=4, Out=6, seed=1, combined_bias=True)
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    node = _dmmha_node(pruned)
    num_heads = _dmmha_num_heads(node)
    assert num_heads == 4  # max(1, 8 - round(8*0.5))

    d = cfg["D"]
    keep_heads = _oracle_keep_groups(
        cfg["wq"], cfg["wk"], cfg["wv"], cfg["H"], cfg["H"], d, num_heads
    )
    idx = _head_idx(keep_heads, d)

    oracle, _ = _dmmha_model(
        K=cfg["K"],
        H=len(keep_heads),
        D=d,
        Out=cfg["Out"],
        seed=1,
        combined_bias=True,
        wq=cfg["wq"][:, idx],
        wk=cfg["wk"][:, idx],
        wv=cfg["wv"][:, idx],
        bq=cfg["bq"][idx],
        bk=cfg["bk"][idx],
        bv=cfg["bv"][idx],
        wout=cfg["wout"][idx, :],
        batch=cfg["batch"],
    )

    rng = np.random.default_rng(2)
    x = rng.standard_normal((cfg["batch"], 1, cfg["K"])).astype(np.float32)
    (y_pruned,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y_pruned, y_oracle, rtol=1e-4, atol=1e-4)


def test_dmmha_pruning_slices_combined_bias_exactly():
    model, cfg = _dmmha_model(K=8, H=4, D=4, Out=6, seed=3, combined_bias=True)
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)

    node = _dmmha_node(pruned)
    num_heads = _dmmha_num_heads(node)
    d = cfg["D"]
    keep_heads = _oracle_keep_groups(
        cfg["wq"], cfg["wk"], cfg["wv"], cfg["H"], cfg["H"], d, num_heads
    )
    idx = _head_idx(keep_heads, d)

    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    expected = np.concatenate([cfg["bq"][idx], cfg["bk"][idx], cfg["bv"][idx]])
    np.testing.assert_array_equal(inits["Bias"], expected)
    # Confirms the combined bias really is read off input index 10 (the
    # node's own *last* input), not index 3 (`MultiHeadAttention`'s own).
    assert node.input[10] == "Bias"


def test_dmmha_pruning_attention_bias_is_sliced_and_matches_oracle():
    # This environment's own CPU kernel additionally requires a connected
    # `attention_bias` to run in the (cached) self-attention mode -- with no
    # `past_key`/`past_value` connected at all it errors outright
    # ("DecoderMaskedMultiHeadAttention does not support attention bias for
    # cross-attention") -- so this test connects a past cache too, and
    # sizes `attention_bias`'s own last axis to `total_sequence_length`
    # (`past_seq + 1`), per this op's own kernel-level shape requirement.
    H, D = 4, 4
    past_seq = 3
    total_seq = past_seq + 1
    rng = np.random.default_rng(16)
    attention_bias = rng.standard_normal((1, H, 1, total_seq)).astype(np.float32)
    model, cfg = _dmmha_model(
        K=8,
        H=H,
        D=D,
        Out=6,
        seed=16,
        attention_bias=attention_bias,
        past_kv="nonempty",
        past_seq=past_seq,
    )
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    node = _dmmha_node(pruned)
    num_heads = _dmmha_num_heads(node)
    keep_heads = _oracle_keep_groups(
        cfg["wq"], cfg["wk"], cfg["wv"], H, H, D, num_heads
    )
    idx = _head_idx(keep_heads, D)

    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["AttentionBias"], attention_bias[:, keep_heads])
    # Confirms the bias really is read off input index 4 (not 5, the
    # position `MultiHeadAttention`'s own analogous input sits at).
    assert node.input[4] == "AttentionBias"

    oracle, _ = _dmmha_model(
        K=cfg["K"],
        H=len(keep_heads),
        D=D,
        Out=cfg["Out"],
        seed=16,
        attention_bias=attention_bias[:, keep_heads],
        past_kv="nonempty",
        past_seq=past_seq,
        past_key=cfg["past_key"][:, keep_heads],
        past_value=cfg["past_value"][:, keep_heads],
        wq=cfg["wq"][:, idx],
        wk=cfg["wk"][:, idx],
        wv=cfg["wv"][:, idx],
        wout=cfg["wout"][idx, :],
        batch=cfg["batch"],
    )
    rng2 = np.random.default_rng(17)
    x = rng2.standard_normal((cfg["batch"], 1, cfg["K"])).astype(np.float32)
    (y_pruned,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y_pruned, y_oracle, rtol=1e-4, atol=1e-4)


def test_dmmha_pruning_nonempty_past_kv_constant_matches_oracle_exactly():
    past_seq = 3
    model, cfg = _dmmha_model(
        K=8, H=4, D=4, Out=6, seed=18, past_kv="nonempty", past_seq=past_seq
    )
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    node = _dmmha_node(pruned)
    num_heads = _dmmha_num_heads(node)
    d = cfg["D"]
    keep_heads = _oracle_keep_groups(
        cfg["wq"], cfg["wk"], cfg["wv"], cfg["H"], cfg["H"], d, num_heads
    )
    idx = _head_idx(keep_heads, d)

    # `inits["PastKey"]`/`["PastValue"]` are already the post-pruning
    # buffer (axis 1 already sliced down to `num_heads`) -- compare its own
    # real (non-padding) `:past_seq` slice against the *original* cache
    # sliced the same way, not re-index it a second time.
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(
        inits["PastKey"][:, :, :past_seq, :], cfg["past_key"][:, keep_heads]
    )
    np.testing.assert_array_equal(
        inits["PastValue"][:, :, :past_seq, :], cfg["past_value"][:, keep_heads]
    )
    # Confirms past_key/past_value really are read off indices 5/6 (not
    # 6/7, `MultiHeadAttention`'s own).
    assert node.input[5] == "PastKey"
    assert node.input[6] == "PastValue"

    oracle, _ = _dmmha_model(
        K=cfg["K"],
        H=len(keep_heads),
        D=d,
        Out=cfg["Out"],
        seed=18,
        past_kv="nonempty",
        past_seq=past_seq,
        past_key=cfg["past_key"][:, keep_heads],
        past_value=cfg["past_value"][:, keep_heads],
        wq=cfg["wq"][:, idx],
        wk=cfg["wk"][:, idx],
        wv=cfg["wv"][:, idx],
        wout=cfg["wout"][idx, :],
        batch=cfg["batch"],
    )
    rng = np.random.default_rng(19)
    x = rng.standard_normal((cfg["batch"], 1, cfg["K"])).astype(np.float32)
    (y_pruned,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y_pruned, y_oracle, rtol=1e-4, atol=1e-4)


def test_dmmha_pruning_dynamic_past_kv_is_left_untouched():
    model, cfg = _dmmha_model(K=8, H=4, D=4, Out=6, seed=21, past_kv="dynamic")
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    node = _dmmha_node(pruned)
    assert _dmmha_num_heads(node) == 2  # still prunes the producer weights
    # The dynamic past_key/past_value graph inputs themselves are the
    # caller's own runtime data -- left completely alone, same names/shapes.
    input_names = {i.name for i in pruned.graph.input}
    assert "PastKeyIn" in input_names
    assert "PastValueIn" in input_names


def test_dmmha_pruning_diff_v_head_size_is_declined():
    # Unlike `MultiHeadAttention` (which genuinely allows V its own
    # head_size), this op's own CPU kernel hard-requires equal Q/K/V
    # head_size -- confirmed empirically ("QK head size should be same as V
    # head size to use DecoderMaskedMultiHeadAttention") -- so
    # `_find_decoder_masked_mha_chains` passes
    # `allow_differing_v_head_size=False` and a node whose V width
    # genuinely differs declines the whole match rather than being pruned
    # into a shape that could never execute anyway.
    K, H, D, Dv, Out = 8, 2, 4, 3, 5
    model, cfg = _dmmha_model(K=K, H=H, D=D, Out=Out, seed=22)
    # Hand-widen V's own weight/Wout to a genuinely different per-head width.
    rng = np.random.default_rng(23)
    wv2 = rng.standard_normal((K, H * Dv)).astype(np.float32)
    wout2 = rng.standard_normal((H * Dv, Out)).astype(np.float32)
    inits = {t.name: t for t in model.graph.initializer}
    inits["Wv"].CopyFrom(_f32(wv2, "Wv"))
    inits["Wout"].CopyFrom(_f32(wout2, "Wout"))

    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    node = _dmmha_node(pruned)
    assert _dmmha_num_heads(node) == H  # left completely untouched

    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_attention_head_pruning, sparsity=0.5
    )
    assert report.not_eligible == ["DecoderMaskedMultiHeadAttention 'ctx'"]


def test_dmmha_pruning_cross_attention_4d_kv_is_not_matched():
    # The real cross-attention calling convention for this op feeds `key`/
    # `value` as a pre-projected rank-4 `(batch, num_heads, kv_seq,
    # head_size)` tensor directly (confirmed empirically -- see
    # onnxsim/pruning.py's own "Attention-head pruning" section comment),
    # not `MultiHeadAttention`'s own rank-3 MatMul-producer-fed convention.
    # That rank-4 tensor is never fed by a MatMul/vanilla-Gemm producer
    # with a 2-D weight at all, so `_find_separate_qkv_chains`'s own
    # `_match_producer` naturally declines it -- confirmed here structurally
    # (this test never claims the resulting model is numerically valid to
    # actually run this way; only that this pass correctly leaves it alone
    # rather than mis-slicing it).
    H, D, K, Out = 4, 8, 8, 6
    kv_seq = 7
    rng = np.random.default_rng(24)
    wq = rng.standard_normal((K, H * D)).astype(np.float32)
    wout = rng.standard_normal((H * D, Out)).astype(np.float32)
    model = parser.parse_model(
        f"""
        <
          ir_version: 10,
          opset_import: ["": 17, "com.microsoft": 1]
        >
        g (float[batch,1,{K}] X, float[batch,{H},{kv_seq},{D}] KeyIn, float[batch,{H},{kv_seq},{D}] ValueIn) => (float[batch,1,{Out}] Y)
        {{
          q = MatMul(X, Wq)
          ctx = com.microsoft.DecoderMaskedMultiHeadAttention <num_heads={H}> (q, KeyIn, ValueIn)
          Y = MatMul(ctx, Wout)
        }}
        """
    )
    model.graph.initializer.extend([_f32(wq, "Wq"), _f32(wout, "Wout")])

    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    node = _dmmha_node(pruned)
    assert _dmmha_num_heads(node) == H  # left completely untouched

    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_attention_head_pruning, sparsity=0.5
    )
    assert report.not_eligible == ["DecoderMaskedMultiHeadAttention 'ctx'"]


def test_dmmha_pruning_runtime_only_inputs_left_untouched():
    # `mask_index`, `past_sequence_length`, `beam_width`, and
    # `cache_indirection` never carry a `num_heads`-sized axis on their own
    # schema docs (confirmed live -- see onnxsim/pruning.py's own
    # "Attention-head pruning" section comment) -- connected as ordinary
    # dynamic graph inputs, they are never inspected or touched by this
    # pass at all.
    K, H, D, Out, batch = 8, 4, 4, 6, 2
    rng = np.random.default_rng(25)
    wq = rng.standard_normal((K, H * D)).astype(np.float32)
    wk = rng.standard_normal((K, H * D)).astype(np.float32)
    wv = rng.standard_normal((K, H * D)).astype(np.float32)
    wout = rng.standard_normal((H * D, Out)).astype(np.float32)
    model = parser.parse_model(
        f"""
        <
          ir_version: 10,
          opset_import: ["": 17, "com.microsoft": 1]
        >
        g (float[{batch},1,{K}] X,
           int32[{batch},1] MaskIndex,
           int32[1] PastSeqLen,
           int32[1] BeamWidth,
           int32[{batch},1,1] CacheIndirection)
          => (float[{batch},1,{Out}] Y)
        {{
          q = MatMul(X, Wq)
          k = MatMul(X, Wk)
          v = MatMul(X, Wv)
          ctx = com.microsoft.DecoderMaskedMultiHeadAttention <num_heads={H}> (q, k, v, MaskIndex, "", "", "", PastSeqLen, BeamWidth, CacheIndirection)
          Y = MatMul(ctx, Wout)
        }}
        """
    )
    model.graph.initializer.extend(
        [_f32(wq, "Wq"), _f32(wk, "Wk"), _f32(wv, "Wv"), _f32(wout, "Wout")]
    )

    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    node = _dmmha_node(pruned)
    assert _dmmha_num_heads(node) == 2  # matched/pruned normally
    # The four runtime-only inputs are untouched -- same names, still
    # present as graph inputs, unchanged.
    assert list(node.input[3:4]) == ["MaskIndex"]
    assert node.input[7:10] == ["PastSeqLen", "BeamWidth", "CacheIndirection"]
    input_names = {i.name for i in pruned.graph.input}
    assert {"MaskIndex", "PastSeqLen", "BeamWidth", "CacheIndirection"} <= input_names


def test_dmmha_pruning_family_string_matches_mha():
    # Reporting reuses `MultiHeadAttention`'s own family string rather than
    # a distinct one -- the granularity is genuinely identical (no separate
    # `kv_num_heads` on this op's own schema either), see
    # onnxsim/pruning.py's own "Attention-head pruning" section comment.
    model, cfg = _dmmha_model(K=8, H=8, D=4, Out=6, seed=26)
    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_attention_head_pruning, sparsity=0.5
    )
    assert len(report.layers) == 1
    assert report.layers[0].family == "attention_mha_head"


def test_dmmha_pruning_dry_run_matches_real_call():
    model, cfg = _dmmha_model(K=8, H=8, D=4, Out=6, seed=27, combined_bias=True)
    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_attention_head_pruning, sparsity=0.5
    )
    assert len(report.layers) == 1
    layer = report.layers[0]
    assert layer.total == 8
    assert layer.would_drop == 4  # round(8*0.5)

    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    node = _dmmha_node(pruned)
    assert cfg["H"] - _dmmha_num_heads(node) == layer.would_drop


def test_dmmha_wanda_pruning_matches_oracle_exactly():
    model, cfg = _dmmha_model(K=8, H=8, D=4, Out=6, seed=28, combined_bias=True)

    rng = np.random.default_rng(29)
    x_cal = rng.standard_normal((cfg["batch"], 1, cfg["K"])).astype(np.float32)
    calibration_data = [{"X": x_cal}]

    pruned = onnxsim.apply_attention_head_wanda_pruning(
        model, calibration_data=calibration_data, sparsity=0.5
    )
    onnx.checker.check_model(pruned)

    probe_model = onnx.ModelProto()
    probe_model.CopyFrom(model)
    probe_model.graph.output.append(onnx.ValueInfoProto(name="ctx"))
    (_, ctx_cal) = _run(probe_model, {"X": x_cal})
    act_norm = np.sqrt(np.mean(np.square(ctx_cal.astype(np.float64)), axis=(0, 1)))

    d = cfg["D"]
    importance = np.zeros(cfg["H"])
    for h in range(cfg["H"]):
        block = np.concatenate(
            [
                cfg["wq"][:, h * d : (h + 1) * d],
                cfg["wk"][:, h * d : (h + 1) * d],
                cfg["wv"][:, h * d : (h + 1) * d],
            ],
            axis=1,
        )
        base = np.linalg.norm(block)
        act_head = np.linalg.norm(act_norm[h * d : (h + 1) * d])
        importance[h] = base * max(act_head, 1e-8)
    keep_heads = np.sort(np.argsort(-importance)[:4])  # max(1, 8 - round(8*0.5))
    idx = _head_idx(keep_heads, d)

    oracle, _ = _dmmha_model(
        K=cfg["K"],
        H=len(keep_heads),
        D=d,
        Out=cfg["Out"],
        seed=28,
        combined_bias=True,
        wq=cfg["wq"][:, idx],
        wk=cfg["wk"][:, idx],
        wv=cfg["wv"][:, idx],
        bq=cfg["bq"][idx],
        bk=cfg["bk"][idx],
        bv=cfg["bv"][idx],
        wout=cfg["wout"][idx, :],
        batch=cfg["batch"],
    )

    rng2 = np.random.default_rng(30)
    x = rng2.standard_normal((cfg["batch"], 1, cfg["K"])).astype(np.float32)
    (y_pruned,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y_pruned, y_oracle, rtol=1e-4, atol=1e-4)


def test_attention_head_pruning_handles_all_three_attention_op_types_in_one_model():
    # Regression check for `_apply_attention_chains`'s per-chain-type
    # dispatch once a third node type shares it: a plain
    # `com.microsoft::Attention` block, a `GroupQueryAttention` block, and a
    # plain `ai.onnx::Attention` block in the same graph, sharing no
    # tensors, must each be pruned correctly and independently -- no chain
    # family may disturb another, extending
    # `test_attention_head_pruning_handles_attention_and_gqa_in_one_model`'s
    # own two-type check to all three now-matched op types.
    K, H, D, Out1 = 8, 4, 4, 6
    Nqkv = H * D
    rng = np.random.default_rng(40)
    wqkv = rng.standard_normal((K, 3 * Nqkv)).astype(np.float32)
    bqkv = rng.standard_normal((3 * Nqkv,)).astype(np.float32)
    wout1 = rng.standard_normal((Nqkv, Out1)).astype(np.float32)

    GH, GKVH, GD, Out2 = 8, 2, 8, 5
    Nq2, Nkv2 = GH * GD, GKVH * GD
    wq2 = rng.standard_normal((K, Nq2)).astype(np.float32)
    wk2 = rng.standard_normal((K, Nkv2)).astype(np.float32)
    wv2 = rng.standard_normal((K, Nkv2)).astype(np.float32)
    wout2 = rng.standard_normal((Nq2, Out2)).astype(np.float32)

    AH, AKVH, AD, Out3 = 8, 2, 4, 7
    Nq3, Nkv3 = AH * AD, AKVH * AD
    wq3 = rng.standard_normal((K, Nq3)).astype(np.float32)
    wk3 = rng.standard_normal((K, Nkv3)).astype(np.float32)
    wv3 = rng.standard_normal((K, Nkv3)).astype(np.float32)
    wout3 = rng.standard_normal((Nq3, Out3)).astype(np.float32)

    batch, seq = 2, 5
    seqlens_k = np.full((batch,), seq - 1, dtype=np.int32)
    total_seq = np.array(seq, dtype=np.int32)

    model = parser.parse_model(
        f"""
        <
          ir_version: 10,
          opset_import: ["": 24, "com.microsoft": 1]
        >
        g (float[{batch},{seq},{K}] X1, float[{batch},{seq},{K}] X2, float[{batch},{seq},{K}] X3) => (float[{batch},{seq},{Out1}] Y1, float[{batch},{seq},{Out2}] Y2, float[{batch},{seq},{Out3}] Y3)
        {{
          ctx1 = com.microsoft.Attention <num_heads={H}, qkv_hidden_sizes=[{Nqkv},{Nqkv},{Nqkv}]> (X1, Wqkv, Bqkv)
          Y1 = MatMul(ctx1, Wout1)
          q2 = MatMul(X2, Wq2)
          k2 = MatMul(X2, Wk2)
          v2 = MatMul(X2, Wv2)
          ctx2, pk, pv = com.microsoft.GroupQueryAttention <num_heads={GH}, kv_num_heads={GKVH}> (q2, k2, v2, , , SeqLensK, TotalSeq)
          Y2 = MatMul(ctx2, Wout2)
          q3 = MatMul(X3, Wq3)
          k3 = MatMul(X3, Wk3)
          v3 = MatMul(X3, Wv3)
          ctx3 = Attention <q_num_heads={AH}, kv_num_heads={AKVH}> (q3, k3, v3)
          Y3 = MatMul(ctx3, Wout3)
        }}
        """
    )
    model.graph.initializer.extend(
        [
            _f32(wqkv, "Wqkv"),
            _f32(bqkv, "Bqkv"),
            _f32(wout1, "Wout1"),
            _f32(wq2, "Wq2"),
            _f32(wk2, "Wk2"),
            _f32(wv2, "Wv2"),
            _f32(wout2, "Wout2"),
            onnx.numpy_helper.from_array(seqlens_k, "SeqLensK"),
            onnx.numpy_helper.from_array(total_seq, "TotalSeq"),
            _f32(wq3, "Wq3"),
            _f32(wk3, "Wk3"),
            _f32(wv3, "Wv3"),
            _f32(wout3, "Wout3"),
        ]
    )

    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    attn_node = next(
        n
        for n in pruned.graph.node
        if n.op_type == "Attention" and n.domain == "com.microsoft"
    )
    gqa_node = next(n for n in pruned.graph.node if n.op_type == "GroupQueryAttention")
    onnx_attn_node = _onnx_attention_node(pruned)
    attn_heads, _ = _attention_attrs(attn_node)
    gqa_heads, gqa_kv_heads = _gqa_attrs(gqa_node)
    onnx_attn_heads, onnx_attn_kv_heads = _onnx_attention_attrs(onnx_attn_node)
    assert attn_heads == 2
    assert gqa_kv_heads == 1
    assert gqa_heads == 4
    assert onnx_attn_kv_heads == 1
    assert onnx_attn_heads == 4

    rng2 = np.random.default_rng(41)
    x1 = rng2.standard_normal((batch, seq, K)).astype(np.float32)
    x2 = rng2.standard_normal((batch, seq, K)).astype(np.float32)
    x3 = rng2.standard_normal((batch, seq, K)).astype(np.float32)
    y1, y2, y3 = _run(pruned, {"X1": x1, "X2": x2, "X3": x3})
    assert y1.shape == (batch, seq, Out1)
    assert y2.shape == (batch, seq, Out2)
    assert y3.shape == (batch, seq, Out3)


# --- apply_attention_head_pruning / _wanda_pruning -- PackedAttention -----
#
# ``onnxruntime.capi.onnxruntime_pybind11_state.get_all_operator_schema()``
# against this environment's installed onnxruntime 1.29.0 confirms:
# `com.microsoft::PackedAttention` -- ONNX Runtime's own "packing mode"
# fusion target for `com.microsoft::Attention`
# (`onnxruntime.transformers.convert_to_packing_mode
# .PackingAttention._replace_attention_with_packing_attention`, read
# directly from the installed `onnxruntime` wheel) -- has `input`/`weights`/
# `bias` at the identical indices 0/1/2 `Attention` itself uses, two new
# inputs `token_offset`/`cumulative_sequence_length` at 3/4 (replacing
# `Attention`'s own `mask_index`/`past` there), and `attention_bias` keeping
# `Attention`'s own index, 5. See onnxsim/pruning.py's own "Attention-head
# pruning" section comment for the full empirical investigation.
#
# **No CPU kernel exists for this op in this environment's onnxruntime at
# all** (confirmed empirically: a minimal, `onnx.checker`-valid
# `PackedAttention` node fails `onnxruntime.InferenceSession` construction
# outright with ``NOT_IMPLEMENTED : ... Could not find an implementation for
# PackedAttention``) -- so, following `DecoderMaskedSelfAttention`'s own
# precedent (see that section's own comment above), every correctness test
# below decomposes a pruned node's own sliced `weights`/`bias` into an
# equivalent, genuinely executable plain `com.microsoft::Attention` node
# (same merged-QKV layout) and runs *that* through a real CPU-kernel
# `InferenceSession`, compared against a numpy-oracle-equivalent
# independently-built smaller `Attention` model using only the
# correctly-selected kept heads' own original (pre-pruning) weight columns
# -- never a comparison against the full, unpruned model's own output.


def _packed_attention_model(
    K=8,
    H=4,
    D=4,
    Out=6,
    seed=0,
    tok=5,
    bias=True,
    wqkv=None,
    bqkv=None,
    wout=None,
    num_heads=None,
    attention_bias=None,  # constant attention_bias array, or None (unconnected)
    attention_bias_dynamic_shape=None,
):
    rng = np.random.default_rng(seed)
    Nq = Nk = Nv = H * D
    if wqkv is None:
        wqkv = rng.standard_normal((K, Nq + Nk + Nv)).astype(np.float32)
    if wout is None:
        wout = rng.standard_normal((Nv, Out)).astype(np.float32)
    if bias and bqkv is None:
        bqkv = rng.standard_normal((Nq + Nk + Nv,)).astype(np.float32)
    heads = H if num_heads is None else num_heads

    # No padding in this single-sequence repro: `token_offset` is the
    # identity mapping (`(1, tok)`, batch_size=1) and
    # `cumulative_sequence_length` is `[0, tok]` -- constant initializers
    # (not graph inputs) purely so their own byte content can be compared
    # before/after pruning directly.
    token_offset = np.arange(tok, dtype=np.int32).reshape(1, tok)
    cum_seq_len = np.array([0, tok], dtype=np.int32)

    initializer = [
        _f32(wqkv, "Wqkv"),
        _f32(wout, "Wout"),
        onnx.numpy_helper.from_array(token_offset, "TokenOffset"),
        onnx.numpy_helper.from_array(cum_seq_len, "CumSeqLen"),
    ]
    operands = ["X", "Wqkv"]
    if bias:
        initializer.append(_f32(bqkv, "Bqkv"))
        operands.append("Bqkv")
    else:
        operands.append("")
    operands += ["TokenOffset", "CumSeqLen"]

    extra_graph_inputs = ""
    if attention_bias is not None:
        initializer.append(_f32(np.asarray(attention_bias), "AttentionBias"))
        operands.append("AttentionBias")
    elif attention_bias_dynamic_shape is not None:
        shape_text = ",".join(str(d) for d in attention_bias_dynamic_shape)
        extra_graph_inputs = f", float[{shape_text}] AttentionBias"
        operands.append("AttentionBias")

    while operands and operands[-1] == "":
        operands.pop()
    qkv_inputs = ", ".join(operands)

    body = f"""
        g (float[{tok},{K}] X{extra_graph_inputs}) => (float[{tok},{Out}] Y)
        {{
          ctx = com.microsoft.PackedAttention <num_heads={heads}, qkv_hidden_sizes=[{Nq},{Nk},{Nv}]> ({qkv_inputs})
          Y = MatMul(ctx, Wout)
        }}
        """

    model = parser.parse_model(
        f"""
        <
          ir_version: 10,
          opset_import: ["": 17, "com.microsoft": 1]
        >
        {body}
        """
    )
    model.graph.initializer.extend(initializer)
    return model, dict(
        K=K,
        H=H,
        D=D,
        Out=Out,
        Nq=Nq,
        Nk=Nk,
        Nv=Nv,
        wqkv=wqkv,
        bqkv=bqkv,
        wout=wout,
        tok=tok,
        token_offset=token_offset,
        cum_seq_len=cum_seq_len,
    )


def _packed_attention_node(model):
    return next(n for n in model.graph.node if n.op_type == "PackedAttention")


def _packed_attention_num_heads(node):
    return next(a.i for a in node.attribute if a.name == "num_heads")


def test_packed_attention_pruning_shrinks_matched_block():
    model, cfg = _packed_attention_model(K=8, H=4, D=4, Out=6)
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    node = _packed_attention_node(pruned)
    assert _packed_attention_num_heads(node) == 2  # max(1, 4 - round(4*0.5))

    inits = {t.name: t for t in pruned.graph.initializer}
    assert list(inits["Wqkv"].dims) == [8, 24]  # keep_count(2) * 3 * D(4)
    assert list(inits["Bqkv"].dims) == [24]
    assert list(inits["Wout"].dims) == [8, 6]


def test_packed_attention_pruning_zero_sparsity_is_a_no_op():
    model, cfg = _packed_attention_model(K=8, H=4, D=4, Out=6)
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.0)
    node = _packed_attention_node(pruned)
    assert _packed_attention_num_heads(node) == cfg["H"]  # left completely untouched


def test_packed_attention_pruning_matches_oracle_via_attention_proxy():
    model, cfg = _packed_attention_model(K=8, H=8, D=4, Out=6, seed=1, tok=5)
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    node = _packed_attention_node(pruned)
    num_heads = _packed_attention_num_heads(node)
    assert num_heads == 4  # max(1, 8 - round(8*0.5))

    d = cfg["D"]
    keep_heads = _oracle_keep_heads(
        cfg["wqkv"], cfg["Nq"], cfg["Nk"], cfg["Nv"], cfg["H"], num_heads
    )
    idx = _head_idx(keep_heads, d)
    q_idx = idx
    k_idx = idx + cfg["Nq"]
    v_idx = idx + cfg["Nq"] + cfg["Nk"]
    all_idx = np.concatenate([q_idx, k_idx, v_idx])

    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["Wqkv"], cfg["wqkv"][:, all_idx])

    # Decompose the pruned node's own sliced tensors into a genuinely
    # executable plain `Attention` proxy (see this section's own comment
    # above for why) and compare against an independently-built smaller
    # `Attention` oracle sliced straight from the *original* (pre-pruning)
    # weights -- never against the full unpruned model's own output.
    proxy, _ = _attention_model(
        K=cfg["K"],
        H=num_heads,
        D=d,
        Out=cfg["Out"],
        wqkv=inits["Wqkv"],
        bqkv=inits["Bqkv"],
        wout=inits["Wout"],
    )
    oracle, _ = _attention_model(
        K=cfg["K"],
        H=num_heads,
        D=d,
        Out=cfg["Out"],
        wqkv=cfg["wqkv"][:, all_idx],
        bqkv=cfg["bqkv"][all_idx],
        wout=cfg["wout"][idx, :],
    )
    rng = np.random.default_rng(2)
    x = rng.standard_normal((1, cfg["tok"], cfg["K"])).astype(np.float32)
    (y_proxy,) = _run(proxy, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y_proxy, y_oracle, rtol=1e-4, atol=1e-4)


def test_packed_attention_pruning_leaves_token_offset_and_cumulative_sequence_length_untouched():
    # `token_offset`/`cumulative_sequence_length` are packing-mode
    # bookkeeping tensors (`(batch_size, sequence_length)`/`(batch_size +
    # 1)`-shaped per this op's own schema doc, no `num_heads`-sized axis
    # anywhere) -- pruning must never touch them, byte-identical before and
    # after.
    model, cfg = _packed_attention_model(K=8, H=4, D=4, Out=6, tok=6)
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)

    before = {t.name: t for t in model.graph.initializer}
    after = {t.name: t for t in pruned.graph.initializer}
    assert after["TokenOffset"].raw_data == before["TokenOffset"].raw_data
    assert after["CumSeqLen"].raw_data == before["CumSeqLen"].raw_data
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(after["TokenOffset"]), cfg["token_offset"]
    )
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(after["CumSeqLen"]), cfg["cum_seq_len"]
    )


def test_packed_attention_pruning_attention_bias_is_sliced_and_matches_oracle():
    H, D = 4, 4
    tok = 5
    rng = np.random.default_rng(20)
    attention_bias = rng.standard_normal((1, H, tok, tok)).astype(np.float32)
    model, cfg = _packed_attention_model(
        K=8, H=H, D=D, Out=6, seed=20, tok=tok, attention_bias=attention_bias
    )
    node_before = _packed_attention_node(model)
    assert list(node_before.input)[5] == "AttentionBias"

    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    node = _packed_attention_node(pruned)
    num_heads = _packed_attention_num_heads(node)
    keep_heads = _oracle_keep_heads(
        cfg["wqkv"], cfg["Nq"], cfg["Nk"], cfg["Nv"], H, num_heads
    )
    idx = _head_idx(keep_heads, D)
    q_idx = idx
    k_idx = idx + cfg["Nq"]
    v_idx = idx + cfg["Nq"] + cfg["Nk"]
    all_idx = np.concatenate([q_idx, k_idx, v_idx])

    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["AttentionBias"], attention_bias[:, keep_heads])

    proxy, _ = _attention_model(
        K=cfg["K"],
        H=num_heads,
        D=D,
        Out=cfg["Out"],
        wqkv=inits["Wqkv"],
        bqkv=inits["Bqkv"],
        wout=inits["Wout"],
        attention_bias=inits["AttentionBias"],
    )
    oracle, _ = _attention_model(
        K=cfg["K"],
        H=num_heads,
        D=D,
        Out=cfg["Out"],
        wqkv=cfg["wqkv"][:, all_idx],
        bqkv=cfg["bqkv"][all_idx],
        wout=cfg["wout"][idx, :],
        attention_bias=attention_bias[:, keep_heads],
    )
    rng2 = np.random.default_rng(21)
    x = rng2.standard_normal((1, tok, cfg["K"])).astype(np.float32)
    (y_proxy,) = _run(proxy, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y_proxy, y_oracle, rtol=1e-4, atol=1e-4)


def test_packed_attention_pruning_declines_dynamic_weight():
    # A non-constant `weights` input (an ordinary graph input, not an
    # initializer) can't be sliced -- the whole match is declined outright,
    # reported by name in `not_eligible`, exactly like every other declined
    # op-type in this module.
    K, H, D, Out, tok = 8, 4, 4, 6, 5
    Nq = Nk = Nv = H * D
    token_offset = np.arange(tok, dtype=np.int32).reshape(1, tok)
    cum_seq_len = np.array([0, tok], dtype=np.int32)
    body = f"""
        g (float[{tok},{K}] X, float[{K},{Nq + Nk + Nv}] Wqkv) => (float[{tok},{Out}] Y)
        {{
          ctx = com.microsoft.PackedAttention <num_heads={H}, qkv_hidden_sizes=[{Nq},{Nk},{Nv}]> (X, Wqkv, , TokenOffset, CumSeqLen)
          Y = MatMul(ctx, Wout)
        }}
        """
    model = parser.parse_model(
        f"""
        <
          ir_version: 10,
          opset_import: ["": 17, "com.microsoft": 1]
        >
        {body}
        """
    )
    rng = np.random.default_rng(22)
    wout = rng.standard_normal((Nv, Out)).astype(np.float32)
    model.graph.initializer.extend(
        [
            _f32(wout, "Wout"),
            onnx.numpy_helper.from_array(token_offset, "TokenOffset"),
            onnx.numpy_helper.from_array(cum_seq_len, "CumSeqLen"),
        ]
    )
    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_attention_head_pruning, sparsity=0.5
    )
    assert report.not_eligible == ["PackedAttention 'ctx'"]
    assert report.layers == []


def test_packed_attention_pruning_dry_run_matches_real_call():
    model, cfg = _packed_attention_model(K=8, H=8, D=4, Out=6, seed=6)
    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_attention_head_pruning, sparsity=0.5
    )
    assert len(report.layers) == 1
    layer = report.layers[0]
    assert layer.family == "attention_head"
    assert layer.total == 8
    assert layer.would_drop == 4  # round(8*0.5)

    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    node = _packed_attention_node(pruned)
    assert cfg["H"] - _packed_attention_num_heads(node) == layer.would_drop


# --- apply_attention_head_pruning / _wanda_pruning -- PackedMultiHeadAttention --
#
# ``onnxruntime.capi.onnxruntime_pybind11_state.get_all_operator_schema()``
# against this environment's installed onnxruntime 1.29.0 confirms:
# `com.microsoft::PackedMultiHeadAttention` -- ONNX Runtime's own "packing
# mode" fusion target for `com.microsoft::MultiHeadAttention`
# (`onnxruntime.transformers.convert_to_packing_mode
# .PackingMultiHeadAttention._replace_attention_with_packing_attention`,
# read directly from the installed `onnxruntime` wheel) -- has `query`/
# `key`/`value`/`bias` at the identical indices 0/1/2/3 `MultiHeadAttention`
# itself uses, and two new inputs `token_offset`/`cumulative_sequence_length`
# at 4/5 (replacing `MultiHeadAttention`'s own single `key_padding_mask` at
# 4). `attention_bias` does **not** keep `MultiHeadAttention`'s own index --
# it moves from 5 to **6**, since one input (`key_padding_mask`) was replaced
# by two. See onnxsim/pruning.py's own "Attention-head pruning" section
# comment for the full empirical investigation.
#
# **No CPU kernel exists for this op in this environment's onnxruntime at
# all** (confirmed empirically: a minimal, `onnx.checker`-valid
# `PackedMultiHeadAttention` node fails `onnxruntime.InferenceSession`
# construction outright with ``NOT_IMPLEMENTED : ... Could not find an
# implementation for PackedMultiHeadAttention``) -- so, following
# `DecoderMaskedSelfAttention`'s own precedent, every correctness test below
# decomposes a pruned node's own sliced Q/K/V weights and combined bias into
# an equivalent, genuinely executable `com.microsoft::MultiHeadAttention`
# node and runs *that* through a real CPU-kernel `InferenceSession`, compared
# against a numpy-oracle-equivalent independently-built smaller
# `MultiHeadAttention` model using only the correctly-selected kept heads'
# own original (pre-pruning) weight columns -- never a comparison against
# the full unpruned model's own output.


def _packed_mha_model(
    K=8,
    H=4,
    D=4,
    Out=6,
    seed=0,
    tok=5,
    combined_bias=False,
    wq=None,
    wk=None,
    wv=None,
    bq=None,
    bk=None,
    bv=None,
    wout=None,
    attention_bias=None,  # constant attention_bias array, or None (unconnected)
    attention_bias_dynamic_shape=None,
):
    rng = np.random.default_rng(seed)
    Nq, Nk, Nv = H * D, H * D, H * D
    if wq is None:
        wq = rng.standard_normal((K, Nq)).astype(np.float32)
    if wk is None:
        wk = rng.standard_normal((K, Nk)).astype(np.float32)
    if wv is None:
        wv = rng.standard_normal((K, Nv)).astype(np.float32)
    if wout is None:
        wout = rng.standard_normal((Nv, Out)).astype(np.float32)

    token_offset = np.arange(tok, dtype=np.int32).reshape(1, tok)
    cum_seq_len = np.array([0, tok], dtype=np.int32)

    initializer = [
        _f32(wq, "Wq"),
        _f32(wk, "Wk"),
        _f32(wv, "Wv"),
        _f32(wout, "Wout"),
        onnx.numpy_helper.from_array(token_offset, "TokenOffset"),
        onnx.numpy_helper.from_array(cum_seq_len, "CumSeqLen"),
    ]
    operands = ["q", "k", "v"]
    if combined_bias:
        if bq is None:
            bq = rng.standard_normal((Nq,)).astype(np.float32)
        if bk is None:
            bk = rng.standard_normal((Nk,)).astype(np.float32)
        if bv is None:
            bv = rng.standard_normal((Nv,)).astype(np.float32)
        combined = np.concatenate([bq, bk, bv]).astype(np.float32)
        initializer.append(_f32(combined, "Bias"))
        operands.append("Bias")
    else:
        operands.append("")
    operands += ["TokenOffset", "CumSeqLen"]

    extra_graph_inputs = ""
    if attention_bias is not None:
        initializer.append(_f32(np.asarray(attention_bias), "AttentionBias"))
        operands.append("AttentionBias")
    elif attention_bias_dynamic_shape is not None:
        shape_text = ",".join(str(d) for d in attention_bias_dynamic_shape)
        extra_graph_inputs = f", float[{shape_text}] AttentionBias"
        operands.append("AttentionBias")

    while operands and operands[-1] == "":
        operands.pop()
    qkv_inputs = ", ".join(operands)

    body = f"""
        g (float[{tok},{K}] X{extra_graph_inputs}) => (float[{tok},{Out}] Y)
        {{
          q = MatMul(X, Wq)
          k = MatMul(X, Wk)
          v = MatMul(X, Wv)
          ctx = com.microsoft.PackedMultiHeadAttention <num_heads={H}> ({qkv_inputs})
          Y = MatMul(ctx, Wout)
        }}
        """

    model = parser.parse_model(
        f"""
        <
          ir_version: 10,
          opset_import: ["": 17, "com.microsoft": 1]
        >
        {body}
        """
    )
    model.graph.initializer.extend(initializer)
    return model, dict(
        K=K,
        H=H,
        D=D,
        Out=Out,
        Nq=Nq,
        Nk=Nk,
        Nv=Nv,
        wq=wq,
        wk=wk,
        wv=wv,
        bq=bq,
        bk=bk,
        bv=bv,
        wout=wout,
        tok=tok,
        token_offset=token_offset,
        cum_seq_len=cum_seq_len,
    )


def _packed_mha_node(model):
    return next(n for n in model.graph.node if n.op_type == "PackedMultiHeadAttention")


def _packed_mha_num_heads(node):
    return next(a.i for a in node.attribute if a.name == "num_heads")


def test_packed_mha_pruning_shrinks_matched_block():
    model, cfg = _packed_mha_model(K=8, H=4, D=4, Out=6, combined_bias=True)
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    node = _packed_mha_node(pruned)
    assert _packed_mha_num_heads(node) == 2  # max(1, 4 - round(4*0.5))

    inits = {t.name: t for t in pruned.graph.initializer}
    assert list(inits["Wq"].dims) == [8, 8]
    assert list(inits["Wk"].dims) == [8, 8]
    assert list(inits["Wv"].dims) == [8, 8]
    assert list(inits["Bias"].dims) == [24]
    assert list(inits["Wout"].dims) == [8, 6]


def test_packed_mha_pruning_zero_sparsity_is_a_no_op():
    model, cfg = _packed_mha_model(K=8, H=4, D=4, Out=6, combined_bias=True)
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.0)
    node = _packed_mha_node(pruned)
    assert _packed_mha_num_heads(node) == cfg["H"]  # left completely untouched


def test_packed_mha_pruning_matches_oracle_via_mha_proxy():
    model, cfg = _packed_mha_model(
        K=8, H=8, D=4, Out=6, seed=1, tok=5, combined_bias=True
    )
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    node = _packed_mha_node(pruned)
    num_heads = _packed_mha_num_heads(node)
    assert num_heads == 4  # max(1, 8 - round(8*0.5))

    d = cfg["D"]
    keep_heads = _oracle_keep_groups(
        cfg["wq"], cfg["wk"], cfg["wv"], cfg["H"], cfg["H"], d, num_heads
    )
    idx = _head_idx(keep_heads, d)

    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["Wq"], cfg["wq"][:, idx])
    np.testing.assert_array_equal(inits["Wk"], cfg["wk"][:, idx])
    np.testing.assert_array_equal(inits["Wv"], cfg["wv"][:, idx])

    oracle_bq = cfg["bq"][idx]
    oracle_bk = cfg["bk"][idx]
    oracle_bv = cfg["bv"][idx]

    # Decompose the pruned node's own sliced tensors into a genuinely
    # executable `MultiHeadAttention` proxy (see this section's own comment
    # above for why) and compare against an independently-built smaller
    # `MultiHeadAttention` oracle sliced straight from the *original*
    # (pre-pruning) weights -- never against the full unpruned model's own
    # output.
    proxy, _ = _mha_model(
        K=cfg["K"],
        H=num_heads,
        D=d,
        Out=cfg["Out"],
        seed=1,
        combined_bias=True,
        wq=inits["Wq"],
        wk=inits["Wk"],
        wv=inits["Wv"],
        bq=oracle_bq,
        bk=oracle_bk,
        bv=oracle_bv,
        wout=inits["Wout"],
        batch=1,
        seq=cfg["tok"],
    )
    oracle, _ = _mha_model(
        K=cfg["K"],
        H=num_heads,
        D=d,
        Out=cfg["Out"],
        seed=1,
        combined_bias=True,
        wq=cfg["wq"][:, idx],
        wk=cfg["wk"][:, idx],
        wv=cfg["wv"][:, idx],
        bq=oracle_bq,
        bk=oracle_bk,
        bv=oracle_bv,
        wout=cfg["wout"][idx, :],
        batch=1,
        seq=cfg["tok"],
    )
    rng = np.random.default_rng(2)
    x = rng.standard_normal((1, cfg["tok"], cfg["K"])).astype(np.float32)
    (y_proxy,) = _run(proxy, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y_proxy, y_oracle, rtol=1e-4, atol=1e-4)


def test_packed_mha_pruning_leaves_token_offset_and_cumulative_sequence_length_untouched():
    model, cfg = _packed_mha_model(K=8, H=4, D=4, Out=6, tok=6, combined_bias=True)
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)

    before = {t.name: t for t in model.graph.initializer}
    after = {t.name: t for t in pruned.graph.initializer}
    assert after["TokenOffset"].raw_data == before["TokenOffset"].raw_data
    assert after["CumSeqLen"].raw_data == before["CumSeqLen"].raw_data
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(after["TokenOffset"]), cfg["token_offset"]
    )
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(after["CumSeqLen"]), cfg["cum_seq_len"]
    )


def test_packed_mha_pruning_attention_bias_is_sliced_and_matches_oracle():
    H, D = 4, 4
    tok = 5
    rng = np.random.default_rng(30)
    attention_bias = rng.standard_normal((1, H, tok, tok)).astype(np.float32)
    model, cfg = _packed_mha_model(
        K=8,
        H=H,
        D=D,
        Out=6,
        seed=30,
        tok=tok,
        combined_bias=True,
        attention_bias=attention_bias,
    )
    node_before = _packed_mha_node(model)
    # `attention_bias` sits at index 6 here, NOT `MultiHeadAttention`'s own
    # index 5 -- see this section's own comment above for why.
    assert list(node_before.input)[6] == "AttentionBias"

    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    node = _packed_mha_node(pruned)
    num_heads = _packed_mha_num_heads(node)
    keep_heads = _oracle_keep_groups(
        cfg["wq"], cfg["wk"], cfg["wv"], H, H, D, num_heads
    )
    idx = _head_idx(keep_heads, D)

    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["AttentionBias"], attention_bias[:, keep_heads])

    oracle_bq = cfg["bq"][idx]
    oracle_bk = cfg["bk"][idx]
    oracle_bv = cfg["bv"][idx]

    proxy, _ = _mha_model(
        K=cfg["K"],
        H=num_heads,
        D=D,
        Out=cfg["Out"],
        seed=30,
        combined_bias=True,
        wq=inits["Wq"],
        wk=inits["Wk"],
        wv=inits["Wv"],
        bq=oracle_bq,
        bk=oracle_bk,
        bv=oracle_bv,
        wout=inits["Wout"],
        batch=1,
        seq=tok,
        attention_bias=inits["AttentionBias"],
    )
    oracle, _ = _mha_model(
        K=cfg["K"],
        H=num_heads,
        D=D,
        Out=cfg["Out"],
        seed=30,
        combined_bias=True,
        wq=cfg["wq"][:, idx],
        wk=cfg["wk"][:, idx],
        wv=cfg["wv"][:, idx],
        bq=oracle_bq,
        bk=oracle_bk,
        bv=oracle_bv,
        wout=cfg["wout"][idx, :],
        batch=1,
        seq=tok,
        attention_bias=attention_bias[:, keep_heads],
    )
    rng2 = np.random.default_rng(31)
    x = rng2.standard_normal((1, tok, cfg["K"])).astype(np.float32)
    (y_proxy,) = _run(proxy, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y_proxy, y_oracle, rtol=1e-4, atol=1e-4)


def test_packed_mha_pruning_declines_packed_qkv_alt_convention():
    # `query` alone carrying a packed, rank-4 `(token_count, num_heads, 3,
    # head_size)` tensor -- `key`/`value` empty -- is a different tensor
    # layout this pass doesn't attempt to slice (mirrors
    # `test_mha_pruning_packed_qkv_query_input_is_declined`'s own
    # `MultiHeadAttention` precedent).
    H, D, tok = 4, 4, 5
    token_offset = np.arange(tok, dtype=np.int32).reshape(1, tok)
    cum_seq_len = np.array([0, tok], dtype=np.int32)
    body = f"""
        g (float[{tok},{H},3,{D}] Qpacked) => (float[{tok},{H * D}] Y)
        {{
          ctx = com.microsoft.PackedMultiHeadAttention <num_heads={H}> (Qpacked, , , , TokenOffset, CumSeqLen)
          Y = Identity(ctx)
        }}
        """
    model = parser.parse_model(
        f"""
        <
          ir_version: 10,
          opset_import: ["": 17, "com.microsoft": 1]
        >
        {body}
        """
    )
    model.graph.initializer.extend(
        [
            onnx.numpy_helper.from_array(token_offset, "TokenOffset"),
            onnx.numpy_helper.from_array(cum_seq_len, "CumSeqLen"),
        ]
    )
    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_attention_head_pruning, sparsity=0.5
    )
    assert report.not_eligible == ["PackedMultiHeadAttention 'ctx'"]
    assert report.layers == []


def test_packed_mha_pruning_dry_run_matches_real_call():
    model, cfg = _packed_mha_model(K=8, H=8, D=4, Out=6, seed=6, combined_bias=True)
    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_attention_head_pruning, sparsity=0.5
    )
    assert len(report.layers) == 1
    layer = report.layers[0]
    assert layer.family == "attention_mha_head"
    assert layer.total == 8
    assert layer.would_drop == 4  # round(8*0.5)

    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    node = _packed_mha_node(pruned)
    assert cfg["H"] - _packed_mha_num_heads(node) == layer.would_drop


# --- importance_norm ("l1" vs "l2") ---------------------------------------
#
# Every importance ranking above defaults to Li et al.'s L2-norm criterion,
# unchanged from this module's own behavior before `importance_norm`
# existed at all -- see the explicit "l2 is the unchanged default" checks
# below (byte-identical serialized output with vs. without the parameter),
# plus the entire pre-existing suite above this section, which this change
# leaves passing untouched. What follows instead targets the genuinely new
# "l1" path: adversarial weight layouts where a channel/head/group with a
# few large entries (high L2, lower total L1) and one with many medium
# entries (lower L2, higher total L1) trade rank depending on which norm is
# asked for -- so a bug that silently keeps computing L2 under the hood
# even when "l1" is requested shows up as the *wrong unit surviving*, not
# merely a slightly-different score that happens to keep the same one.


def test_structured_pruning_l1_norm_favors_total_magnitude_single_producer():
    # Column "concentrated": one entry of magnitude 8, the other 15 entries
    # exactly zero -- L2 == L1 == 8 (a single nonzero entry has no L1/L2 gap
    # at all). Column "spread": all 16 entries equal to 1 -- L2 = sqrt(16) =
    # 4, L1 = 16. So L2 ranks "concentrated" (8) above "spread" (4), while
    # L1 ranks "spread" (16) above "concentrated" (8) -- a genuine
    # disagreement a correct L1 implementation must reproduce. A
    # "filler_high"/"filler_low" pair (dominant/negligible under either
    # norm) pins the other surviving slot so the test turns on only this
    # one comparison.
    K, H, Out = 16, 4, 3
    w1 = np.zeros((K, H), dtype=np.float32)
    w1[0, 0] = 8.0  # "concentrated"
    w1[:, 1] = 1.0  # "spread"
    w1[2, 2] = 1000.0  # "filler_high"
    w1[3, 3] = 0.001  # "filler_low"
    rng = np.random.default_rng(90)
    w2 = rng.standard_normal((H, Out)).astype(np.float32)
    model = _model(
        f"""
        g (float[batch,{K}] X) => (float[batch,{Out}] Y)
        {{
          h = MatMul(X, W1)
          a = Relu(h)
          Y = MatMul(a, W2)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(w2, "W2")],
    )

    pruned_l2 = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    pruned_l1 = onnxsim.apply_structured_pruning(
        model, sparsity=0.5, importance_norm="l1"
    )
    onnx.checker.check_model(pruned_l2)
    onnx.checker.check_model(pruned_l1)

    keep_l2 = np.array([0, 2])  # concentrated, filler_high
    keep_l1 = np.array([1, 2])  # spread, filler_high
    np.testing.assert_array_equal(_kept_columns(pruned_l2, "W1", w1), keep_l2)
    np.testing.assert_array_equal(_kept_columns(pruned_l1, "W1", w1), keep_l1)

    rng2 = np.random.default_rng(91)
    x = rng2.standard_normal((5, K)).astype(np.float32)
    (y_l2,) = _run(pruned_l2, {"X": x})
    (y_l1,) = _run(pruned_l1, {"X": x})

    def _oracle(keep):
        h = np.maximum(x @ w1[:, keep], 0)
        return h @ w2[keep, :]

    np.testing.assert_allclose(y_l2, _oracle(keep_l2), rtol=1e-5, atol=1e-5)
    np.testing.assert_allclose(y_l1, _oracle(keep_l1), rtol=1e-5, atol=1e-5)


def test_structured_pruning_l1_norm_favors_total_magnitude_conv_residual_merge():
    # Same L1-vs-L2 disagreement as the single-producer case above, but now
    # spanning *two* independent Conv producers merged by a residual Add --
    # exercising the multi-producer combination this module documents as a
    # plain *sum* of per-producer L1 norms for "l1" (never any square/sqrt),
    # rather than L2's own root-sum-square. Channel "A" concentrates its
    # magnitude entirely in producer f (vf=10, vs=0): combined L2 = 10,
    # combined L1 = 10 (a single nonzero producer has no L1/L2 gap either,
    # same as the single-entry-column case above). Channel "B" splits evenly
    # across both producers (vf=vs=7): combined L2 = sqrt(98) ~= 9.9,
    # combined L1 = 14. So L2 (10 > 9.9) keeps "A", while L1 (14 > 10) keeps
    # "B" -- exactly the flip a still-secretly-root-sum-square "l1"
    # implementation would fail to reproduce.
    Cin, C, Cout = 1, 4, 3
    w_f = np.zeros((C, Cin, 3, 3), dtype=np.float32)
    w_s = np.zeros((C, Cin, 3, 3), dtype=np.float32)
    # index 0: "A" (concentrated in f), 1: "B" (split evenly f/s), 2:
    # filler_high (dominates either norm), 3: filler_low (negligible either
    # norm).
    w_f[0, 0, 0, 0] = 10.0
    w_f[1, 0, 0, 0] = 7.0
    w_f[2, 0, 0, 0] = 100.0
    w_f[3, 0, 0, 0] = 0.001
    w_s[1, 0, 0, 0] = 7.0
    w_s[2, 0, 0, 0] = 100.0
    w_s[3, 0, 0, 0] = 0.001
    rng = np.random.default_rng(92)
    w_out = rng.standard_normal((Cout, C, 3, 3)).astype(np.float32)
    model = _residual_diamond_model(w_f, w_s, w_out)

    pruned_l2 = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    pruned_l1 = onnxsim.apply_structured_pruning(
        model, sparsity=0.5, importance_norm="l1"
    )
    onnx.checker.check_model(pruned_l2)
    onnx.checker.check_model(pruned_l1)

    keep_l2 = np.array([0, 2])  # A, filler_high
    keep_l1 = np.array([1, 2])  # B, filler_high

    inits_l2 = {
        t.name: onnx.numpy_helper.to_array(t) for t in pruned_l2.graph.initializer
    }
    inits_l1 = {
        t.name: onnx.numpy_helper.to_array(t) for t in pruned_l1.graph.initializer
    }
    np.testing.assert_array_equal(inits_l2["WF"], w_f[keep_l2])
    np.testing.assert_array_equal(inits_l2["WS"], w_s[keep_l2])
    np.testing.assert_array_equal(inits_l1["WF"], w_f[keep_l1])
    np.testing.assert_array_equal(inits_l1["WS"], w_s[keep_l1])

    oracle_l2 = _residual_diamond_model(w_f[keep_l2], w_s[keep_l2], w_out[:, keep_l2])
    oracle_l1 = _residual_diamond_model(w_f[keep_l1], w_s[keep_l1], w_out[:, keep_l1])

    rng_x = np.random.default_rng(93)
    x = rng_x.standard_normal((2, Cin, 10, 10)).astype(np.float32)
    (y_l2,) = _run(pruned_l2, {"X": x})
    (y_oracle_l2,) = _run(oracle_l2, {"X": x})
    (y_l1,) = _run(pruned_l1, {"X": x})
    (y_oracle_l1,) = _run(oracle_l1, {"X": x})
    np.testing.assert_allclose(y_l2, y_oracle_l2, rtol=1e-5, atol=1e-5)
    np.testing.assert_allclose(y_l1, y_oracle_l1, rtol=1e-5, atol=1e-5)


def test_structured_wanda_pruning_l1_norm_uses_l1_weight_term_but_l2_activation_term():
    # Confirms two things at once: (1) importance_norm="l1" changes only the
    # *weight*-magnitude half of Wanda's ||W_row|| * ||X||_2 metric, not the
    # activation-norm half, which stays L2 regardless (per Wanda's own
    # definition, see this module's docstring); (2) the combination is a
    # plain product of that L1 weight term and the L2 activation term. As in
    # the plain-L1 test above, column "concentrated" (L2 == L1 == 8) times
    # its own activation norm (8, engineered via the calibration row below)
    # gives combined 64 under either norm choice. Column "spread" (L2 = 4,
    # L1 = 16) times its own activation norm (10) gives combined 40 under L2
    # (still less than "concentrated"'s 64 -- L2-Wanda keeps
    # "concentrated") but 160 under L1 (now more than "concentrated"'s 64 --
    # L1-Wanda keeps "spread" instead).
    K, H, Out = 16, 4, 3
    w1 = np.zeros((K, H), dtype=np.float32)
    w1[0, 0] = 8.0  # "concentrated"
    w1[:, 1] = 1.0  # "spread"
    w1[2, 2] = 1000.0  # "filler_high"
    w1[3, 3] = 0.001  # "filler_low"
    rng = np.random.default_rng(94)
    w2 = rng.standard_normal((H, Out)).astype(np.float32)
    model = _model(
        f"""
        g (float[batch,{K}] X) => (float[batch,{Out}] Y)
        {{
          h = MatMul(X, W1)
          a = Relu(h)
          Y = MatMul(a, W2)
        }}
        """,
        initializer=[_f32(w1, "W1"), _f32(w2, "W2")],
    )

    # A single calibration row, engineered so the resulting activation norm
    # (computed identically regardless of `importance_norm` -- rms of `a`
    # over calibration samples) comes out to 8/10/1000/~0 for the four
    # columns respectively: only row 0 feeds "concentrated" (act = 8*x0),
    # *every* row feeds "spread" (act = sum of all 16 entries), only row 2
    # feeds "filler_high", only row 3 feeds "filler_low".
    x = np.zeros((1, K), dtype=np.float32)
    x[0, 0] = 1.0  # concentrated: h = 8*1 = 8
    x[0, 1] = 8.0  # spread: h = sum(x) = 1(row0) + 8(row1) + 1(row2) = 10
    x[0, 2] = 1.0  # filler_high: h = 1000*1 = 1000
    x[0, 3] = 0.0  # filler_low: h = 0.001*0 = 0
    calibration_data = [{"X": x}]

    pruned_l2 = onnxsim.apply_structured_wanda_pruning(
        model, calibration_data=calibration_data, sparsity=0.5
    )
    pruned_l1 = onnxsim.apply_structured_wanda_pruning(
        model, calibration_data=calibration_data, sparsity=0.5, importance_norm="l1"
    )
    onnx.checker.check_model(pruned_l2)
    onnx.checker.check_model(pruned_l1)

    keep_l2 = np.array([0, 2])  # concentrated, filler_high
    keep_l1 = np.array([1, 2])  # spread, filler_high
    np.testing.assert_array_equal(_kept_columns(pruned_l2, "W1", w1), keep_l2)
    np.testing.assert_array_equal(_kept_columns(pruned_l1, "W1", w1), keep_l1)

    rng2 = np.random.default_rng(95)
    x_test = rng2.standard_normal((5, K)).astype(np.float32)
    (y_l2,) = _run(pruned_l2, {"X": x_test})
    (y_l1,) = _run(pruned_l1, {"X": x_test})

    def _oracle(keep):
        h = np.maximum(x_test @ w1[:, keep], 0)
        return h @ w2[keep, :]

    np.testing.assert_allclose(y_l2, _oracle(keep_l2), rtol=1e-5, atol=1e-5)
    np.testing.assert_allclose(y_l1, _oracle(keep_l1), rtol=1e-5, atol=1e-5)


def test_attention_head_pruning_l1_norm_favors_total_magnitude():
    # The attention-head analogue of the single-producer test above: each
    # head's combined Q+K+V weight block is ranked by Frobenius (L2) norm by
    # default, by that same block's own entrywise abs-sum (L1) norm instead
    # under `importance_norm="l1"`. Q and K carry small fixed noise, equal
    # across every head (so it shifts every head's block norm by the same
    # amount either way -- both `sqrt(c + v^2)` vs. L2 and `c + |v|` vs. L1
    # are monotonic in `v` for a shared constant `c`, so it can't flip any
    # ranking, only avoids an all-zero QK^T block); only V's own per-head
    # column block carries the actual signal. Head "concentrated" (one
    # nonzero V entry, 16, within its own [K, D] block) has L2 == L1 == 16;
    # head "spread" (every entry of its own [K, D] block == 1, 64 entries)
    # has L2 = sqrt(64) = 8, L1 = 64. Two filler heads (single huge/tiny V
    # entries of their own) pin the other surviving slot the same way as the
    # plain-L1 test above.
    K, H, D, Out = 16, 4, 4, 3
    Nq = Nk = Nv = H * D
    rng_qk = np.random.default_rng(52)
    wqkv = np.zeros((K, Nq + Nk + Nv), dtype=np.float32)
    wqkv[:, :Nq] = rng_qk.standard_normal((K, Nq)).astype(np.float32) * 0.01
    wqkv[:, Nq : Nq + Nk] = rng_qk.standard_normal((K, Nk)).astype(np.float32) * 0.01
    v_offset = Nq + Nk
    wqkv[0, v_offset + 0] = 16.0  # head 0 ("concentrated")
    wqkv[:, v_offset + D : v_offset + 2 * D] = 1.0  # head 1 ("spread")
    wqkv[2, v_offset + 2 * D] = 1000.0  # head 2 ("filler_high")
    wqkv[3, v_offset + 3 * D] = 0.001  # head 3 ("filler_low")
    # A bias-free `com.microsoft::Attention` node crashes this environment's
    # onnxruntime CPU kernel outright (confirmed with plain random weights,
    # unrelated to anything about this test's own values) -- an all-zero
    # bias is mathematically a no-op and sidesteps that entirely.
    bqkv = np.zeros((Nq + Nk + Nv,), dtype=np.float32)

    model, cfg = _attention_model(
        K=K, H=H, D=D, Out=Out, seed=50, bias=True, wqkv=wqkv, bqkv=bqkv
    )

    pruned_l2 = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    pruned_l1 = onnxsim.apply_attention_head_pruning(
        model, sparsity=0.5, importance_norm="l1"
    )
    onnx.checker.check_model(pruned_l2)
    onnx.checker.check_model(pruned_l1)

    keep_l2 = np.array([0, 2])  # concentrated, filler_high
    keep_l1 = np.array([1, 2])  # spread, filler_high

    def _oracle_model(keep):
        qi, ki, vi = (
            _head_idx(keep, D),
            _head_idx(keep, D) + Nq,
            _head_idx(keep, D) + Nq + Nk,
        )
        idx = np.concatenate([qi, ki, vi])
        return _attention_model(
            K=K,
            H=2,
            D=D,
            Out=Out,
            seed=50,
            bias=True,
            wqkv=wqkv[:, idx],
            bqkv=bqkv[idx],
            wout=cfg["wout"][_head_idx(keep, D), :],
            num_heads=2,
        )[0]

    oracle_l2 = _oracle_model(keep_l2)
    oracle_l1 = _oracle_model(keep_l1)

    rng = np.random.default_rng(51)
    x = rng.standard_normal((2, 5, K)).astype(np.float32)
    (y_l2,) = _run(pruned_l2, {"X": x})
    (y_oracle_l2,) = _run(oracle_l2, {"X": x})
    (y_l1,) = _run(pruned_l1, {"X": x})
    (y_oracle_l1,) = _run(oracle_l1, {"X": x})
    np.testing.assert_allclose(y_l2, y_oracle_l2, rtol=1e-4, atol=1e-4)
    np.testing.assert_allclose(y_l1, y_oracle_l1, rtol=1e-4, atol=1e-4)


def test_gqa_pruning_l1_norm_favors_total_magnitude():
    # The GQA analogue: each KV group's combined Q+K+V weight block is
    # ranked by Frobenius norm by default, by entrywise abs-sum (L1) norm
    # instead under `importance_norm="l1"`. Q and K stay entirely zero (see
    # the plain-Attention L1 test above for why that's still a valid,
    # NaN-free block) so only V carries weight: KV group 0's own V slice
    # ([K, D] = [8, 8], 64 entries) concentrates all its magnitude in a
    # single entry (16) -- Frobenius == L1 == 16, no gap, same reasoning as
    # every other single-nonzero-entry case in this file. KV group 1's own V
    # slice spreads magnitude 1 evenly across all 64 entries -- Frobenius =
    # sqrt(64) = 8, L1 = 64. With exactly two KV groups and keep_count = 1,
    # L2 (16 > 8) keeps group 0, L1 (64 > 16) keeps group 1 -- no filler
    # groups needed at all.
    K, H, KVH, D, Out = 8, 4, 2, 8, 3
    Nq, Nkv = H * D, KVH * D
    wq = np.zeros((K, Nq), dtype=np.float32)
    wk = np.zeros((K, Nkv), dtype=np.float32)
    wv = np.zeros((K, Nkv), dtype=np.float32)
    wv[0, 0] = 16.0  # KV group 0's own V slice (columns 0:D) -- concentrated
    wv[:, D : 2 * D] = 1.0  # KV group 1's own V slice (columns D:2D) -- spread

    model, cfg = _gqa_model(
        K=K, H=H, KVH=KVH, D=D, Out=Out, seed=60, wq=wq, wk=wk, wv=wv
    )

    pruned_l2 = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    pruned_l1 = onnxsim.apply_attention_head_pruning(
        model, sparsity=0.5, importance_norm="l1"
    )
    onnx.checker.check_model(pruned_l2)
    onnx.checker.check_model(pruned_l1)

    group_size = H // KVH  # 2 query heads per KV group

    def _oracle_model(keep_group):
        q_idx = np.arange(
            keep_group * group_size * D, (keep_group + 1) * group_size * D
        )
        kv_idx = np.arange(keep_group * D, (keep_group + 1) * D)
        return _gqa_model(
            K=K,
            H=group_size,
            KVH=1,
            D=D,
            Out=Out,
            seed=60,
            wq=wq[:, q_idx],
            wk=wk[:, kv_idx],
            wv=wv[:, kv_idx],
            wout=cfg["wout"][q_idx, :],
        )[0]

    oracle_l2 = _oracle_model(0)
    oracle_l1 = _oracle_model(1)

    node_l2 = _gqa_node(pruned_l2)
    node_l1 = _gqa_node(pruned_l1)
    assert _gqa_attrs(node_l2) == (group_size, 1)
    assert _gqa_attrs(node_l1) == (group_size, 1)

    rng = np.random.default_rng(61)
    x = rng.standard_normal((cfg["batch"], cfg["seq"], K)).astype(np.float32)
    (y_l2,) = _run(pruned_l2, {"X": x})
    (y_oracle_l2,) = _run(oracle_l2, {"X": x})
    (y_l1,) = _run(pruned_l1, {"X": x})
    (y_oracle_l1,) = _run(oracle_l1, {"X": x})
    np.testing.assert_allclose(y_l2, y_oracle_l2, rtol=1e-4, atol=1e-4)
    np.testing.assert_allclose(y_l1, y_oracle_l1, rtol=1e-4, atol=1e-4)


# --- apply_attention_head_pruning / _wanda_pruning -- GroupQueryAttention,
# packed-QKV-then-Split --
#
# A single packed MatMul/Gemm projection feeding a `Split` whose three
# outputs are wired directly into `GroupQueryAttention`'s own three
# separate, still non-empty, query/key/value inputs -- confirmed a real
# onnxruntime-genai model-builder export shape (its fused Q/K-norm GQA
# path), not merely a hypothetical one -- see
# :func:`onnxsim.pruning._match_packed_qkv_split`'s own docstring for the
# exact topology and the export code path that produces it, and this
# module's "Attention-head pruning" section comment for how it differs from
# `GroupQueryAttention`'s own unrelated, still-declined, schema-level
# packed-`query`-input convention.


def _gqa_packed_model(
    K=8,
    H=4,
    KVH=2,
    D=8,
    Out=6,
    seed=0,
    batch=2,
    seq=5,
    bias=False,
    wqkv=None,
    bqkv=None,
    wout=None,
    split_sizes=None,
    split_axis=-1,
    split_outputs=("q", "k", "v"),
    gqa_inputs=None,
):
    # Mirrors `_gqa_model`'s own scaffolding (SeqLensK/TotalSeq bookkeeping
    # inputs; no past_kv/scale support -- not needed by any packed-QKV test
    # below) but replaces its three independent Wq/Wk/Wv MatMul/Gemm
    # producers with one packed MatMul/Gemm producer feeding a `Split`
    # node -- see this section's own comment above.
    rng = np.random.default_rng(seed)
    Nq, Nkv = H * D, KVH * D
    if wqkv is None:
        wqkv = rng.standard_normal((K, Nq + 2 * Nkv)).astype(np.float32)
    if wout is None:
        wout = rng.standard_normal((Nq, Out)).astype(np.float32)

    initializer = [_f32(wqkv, "Wqkv"), _f32(wout, "Wout")]
    qkv_op = "MatMul(X, Wqkv)"
    if bias:
        if bqkv is None:
            bqkv = rng.standard_normal((Nq + 2 * Nkv,)).astype(np.float32)
        initializer.append(_f32(bqkv, "Bqkv"))
        qkv_op = "Gemm(X, Wqkv, Bqkv)"

    if split_sizes is None:
        split_sizes = [Nq, Nkv, Nkv]
    initializer.append(
        onnx.numpy_helper.from_array(
            np.array(split_sizes, dtype=np.int64), "SplitSizes"
        )
    )

    # No past_kv connected here, so `total_seq == seq` -- the same no-cache
    # case `_gqa_model`'s own default (`past_kv=None`) synthesizes.
    initializer.append(
        onnx.numpy_helper.from_array(
            np.full((batch,), seq - 1, dtype=np.int32), "SeqLensK"
        )
    )
    initializer.append(
        onnx.numpy_helper.from_array(np.array(seq, dtype=np.int32), "TotalSeq")
    )

    if gqa_inputs is None:
        gqa_inputs = split_outputs
    split_out = ", ".join(split_outputs)
    gqa_q, gqa_k, gqa_v = gqa_inputs

    body = f"""
        g (float[{batch},{seq},{K}] X) => (float[{batch},{seq},{Out}] Y)
        {{
          qkv = {qkv_op}
          {split_out} = Split <axis = {split_axis}> (qkv, SplitSizes)
          ctx, pk, pv = com.microsoft.GroupQueryAttention <num_heads={H}, kv_num_heads={KVH}> ({gqa_q}, {gqa_k}, {gqa_v}, , , SeqLensK, TotalSeq)
          Y = MatMul(ctx, Wout)
        }}
        """

    model = parser.parse_model(
        f"""
        <
          ir_version: 10,
          opset_import: ["": 17, "com.microsoft": 1]
        >
        {body}
        """
    )
    model.graph.initializer.extend(initializer)
    return model, dict(
        K=K,
        H=H,
        KVH=KVH,
        D=D,
        Out=Out,
        Nq=Nq,
        Nkv=Nkv,
        wqkv=wqkv,
        bqkv=bqkv,
        wout=wout,
        batch=batch,
        seq=seq,
    )


def test_gqa_packed_qkv_split_pruning_matches_oracle_exactly():
    # Q's/K's/V's "own weight" is really one shared packed tensor here,
    # sliced once by a combined index set, with the `Split`'s own
    # split-sizes constant shrunk to match -- verified both directly
    # against a hand-sliced expectation and end-to-end against a real
    # onnxruntime execution of an independently-built oracle model (the
    # ordinary three-separate-producer `_gqa_model`, the same ground truth
    # `test_gqa_pruning_matches_oracle_exactly` uses above).
    K, H, KVH, D, Out = 8, 8, 2, 8, 6
    model, cfg = _gqa_packed_model(K=K, H=H, KVH=KVH, D=D, Out=Out, seed=1)
    assert len(onnxsim.pruning._find_gqa_chains(model.graph)) == 1

    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    node = _gqa_node(pruned)
    num_heads, kv_num_heads = _gqa_attrs(node)
    group_size = H // KVH
    assert kv_num_heads == 1  # max(1, 2 - round(2*0.5))
    assert num_heads == kv_num_heads * group_size

    Nq, Nkv = cfg["Nq"], cfg["Nkv"]
    wqkv = cfg["wqkv"]
    wq, wk, wv = wqkv[:, :Nq], wqkv[:, Nq : Nq + Nkv], wqkv[:, Nq + Nkv :]

    keep_groups = _oracle_keep_groups(wq, wk, wv, H, KVH, D, kv_num_heads)
    keep_q_heads = _group_q_heads(keep_groups, group_size)
    q_idx, kv_idx = _head_idx(keep_q_heads, D), _head_idx(keep_groups, D)

    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    expected_wqkv = np.concatenate([wq[:, q_idx], wk[:, kv_idx], wv[:, kv_idx]], axis=1)
    np.testing.assert_array_equal(inits["Wqkv"], expected_wqkv)
    np.testing.assert_array_equal(
        inits["SplitSizes"],
        np.array([len(q_idx), len(kv_idx), len(kv_idx)], dtype=np.int64),
    )

    oracle, _ = _gqa_model(
        K=K,
        H=num_heads,
        KVH=kv_num_heads,
        D=D,
        Out=Out,
        seed=1,
        wq=wq[:, q_idx],
        wk=wk[:, kv_idx],
        wv=wv[:, kv_idx],
        wout=cfg["wout"][q_idx, :],
        batch=cfg["batch"],
        seq=cfg["seq"],
    )

    rng = np.random.default_rng(2)
    x = rng.standard_normal((cfg["batch"], cfg["seq"], K)).astype(np.float32)
    (y_pruned,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y_pruned, y_oracle, rtol=1e-4, atol=1e-4)


def test_gqa_packed_qkv_split_pruning_zero_sparsity_is_a_no_op():
    model, cfg = _gqa_packed_model(K=8, H=8, KVH=2, D=8, Out=6, seed=7)
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.0)
    node = _gqa_node(pruned)
    num_heads, kv_num_heads = _gqa_attrs(node)
    assert num_heads == cfg["H"]
    assert kv_num_heads == cfg["KVH"]
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["Wqkv"], cfg["wqkv"])
    np.testing.assert_array_equal(
        inits["SplitSizes"],
        np.array([cfg["Nq"], cfg["Nkv"], cfg["Nkv"]], dtype=np.int64),
    )


def test_gqa_packed_qkv_split_pruning_slices_packed_bias():
    # Same reasoning as `test_gqa_pruning_slices_bias_when_producer_has_one`:
    # a bias-carrying Gemm producer -- here, the single packed Gemm feeding
    # the `Split` -- can't sit directly ahead of a rank-3 input in a graph
    # meant to actually run through onnxruntime (Gemm's own schema requires
    # a rank-2 `A`), so this exercises the packed-bias-slicing path
    # directly against the initializers instead.
    K, H, KVH, D, Out = 8, 4, 2, 8, 6
    model, cfg = _gqa_packed_model(K=K, H=H, KVH=KVH, D=D, Out=Out, seed=14, bias=True)
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)

    node = _gqa_node(pruned)
    num_heads, kv_num_heads = _gqa_attrs(node)
    group_size = H // KVH
    assert kv_num_heads == 1
    assert num_heads == group_size

    Nq, Nkv = cfg["Nq"], cfg["Nkv"]
    wqkv, bqkv = cfg["wqkv"], cfg["bqkv"]
    wq, wk, wv = wqkv[:, :Nq], wqkv[:, Nq : Nq + Nkv], wqkv[:, Nq + Nkv :]
    bq, bk, bv = bqkv[:Nq], bqkv[Nq : Nq + Nkv], bqkv[Nq + Nkv :]

    keep_groups = _oracle_keep_groups(wq, wk, wv, H, KVH, D, kv_num_heads)
    keep_q_heads = _group_q_heads(keep_groups, group_size)
    q_idx, kv_idx = _head_idx(keep_q_heads, D), _head_idx(keep_groups, D)

    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    expected_wqkv = np.concatenate([wq[:, q_idx], wk[:, kv_idx], wv[:, kv_idx]], axis=1)
    expected_bqkv = np.concatenate([bq[q_idx], bk[kv_idx], bv[kv_idx]])
    np.testing.assert_array_equal(inits["Wqkv"], expected_wqkv)
    np.testing.assert_array_equal(inits["Bqkv"], expected_bqkv)
    np.testing.assert_array_equal(
        inits["SplitSizes"],
        np.array([len(q_idx), len(kv_idx), len(kv_idx)], dtype=np.int64),
    )


def test_gqa_wanda_packed_qkv_split_pruning_matches_oracle_exactly():
    K, H, KVH, D, Out = 8, 8, 2, 8, 6
    model, cfg = _gqa_packed_model(K=K, H=H, KVH=KVH, D=D, Out=Out, seed=8)

    rng = np.random.default_rng(9)
    x_cal = rng.standard_normal((cfg["batch"], cfg["seq"], K)).astype(np.float32)
    calibration_data = [{"X": x_cal}]

    pruned = onnxsim.apply_attention_head_wanda_pruning(
        model, calibration_data=calibration_data, sparsity=0.5
    )
    onnx.checker.check_model(pruned)

    probe_model = onnx.ModelProto()
    probe_model.CopyFrom(model)
    probe_model.graph.output.append(onnx.ValueInfoProto(name="ctx"))
    (_, ctx_cal) = _run(probe_model, {"X": x_cal})
    act_norm = np.sqrt(np.mean(np.square(ctx_cal.astype(np.float64)), axis=(0, 1)))

    Nq, Nkv = cfg["Nq"], cfg["Nkv"]
    wqkv = cfg["wqkv"]
    wq, wk, wv = wqkv[:, :Nq], wqkv[:, Nq : Nq + Nkv], wqkv[:, Nq + Nkv :]

    group_size = H // KVH
    importance = np.zeros(KVH)
    for kv in range(KVH):
        q_block = np.concatenate(
            [
                wq[:, h * D : (h + 1) * D]
                for h in range(kv * group_size, (kv + 1) * group_size)
            ],
            axis=1,
        )
        k_block = wk[:, kv * D : (kv + 1) * D]
        v_block = wv[:, kv * D : (kv + 1) * D]
        base = np.linalg.norm(np.concatenate([q_block, k_block, v_block], axis=1))
        act_group = np.linalg.norm(
            act_norm[kv * group_size * D : (kv + 1) * group_size * D]
        )
        importance[kv] = base * max(act_group, 1e-8)
    keep_groups = np.sort(np.argsort(-importance)[:1])  # max(1, 2 - round(2*0.5)) == 1

    keep_q_heads = _group_q_heads(keep_groups, group_size)
    q_idx, kv_idx = _head_idx(keep_q_heads, D), _head_idx(keep_groups, D)

    oracle, _ = _gqa_model(
        K=K,
        H=len(keep_q_heads),
        KVH=len(keep_groups),
        D=D,
        Out=Out,
        seed=8,
        wq=wq[:, q_idx],
        wk=wk[:, kv_idx],
        wv=wv[:, kv_idx],
        wout=cfg["wout"][q_idx, :],
        batch=cfg["batch"],
        seq=cfg["seq"],
    )

    x = rng.standard_normal((cfg["batch"], cfg["seq"], K)).astype(np.float32)
    (y_pruned,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y_pruned, y_oracle, rtol=1e-4, atol=1e-4)


def test_gqa_packed_qkv_split_wrong_output_order_is_declined():
    # Adversarial: a `Split` whose own three OUTPUTS aren't literally in
    # Q-then-K-then-V order (here: K's own range comes out of the `Split`
    # first) is declined outright by `_match_packed_qkv_split`'s own
    # ``list(node.output) == [q_name, k_name, v_name]`` check, rather than
    # a naive offset-by-position implementation (assume output 0 is always
    # Q) mis-slicing K's own column range into Q's or vice versa.
    # `GroupQueryAttention` itself is fed `(q_out, k_out, v_out)` --
    # `Split`'s own *second* output as `query`, its *first* as `key` -- so
    # semantically this is a valid (if unusual) GQA graph with Q and K
    # simply swapped, not a malformed one; this pass just can't safely
    # rewrite it, and leaves it completely untouched rather than guessing.
    K, H, KVH, D, Out = 8, 4, 2, 8, 6
    model, cfg = _gqa_packed_model(
        K=K,
        H=H,
        KVH=KVH,
        D=D,
        Out=Out,
        seed=21,
        split_outputs=("k_out", "q_out", "v_out"),
        gqa_inputs=("q_out", "k_out", "v_out"),
    )

    assert onnxsim.pruning._find_gqa_chains(model.graph) == []

    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    assert pruned.SerializeToString() == model.SerializeToString()


def test_gqa_packed_qkv_split_mismatched_total_width_is_declined():
    # The `Split`'s own `SplitSizes` sums to one column short of the packed
    # projection's own real output width -- `_match_packed_qkv_split`'s own
    # ``n_channels != nq + nk + nv`` check declines this rather than
    # pruning against a split-sizes total that doesn't actually describe
    # the packed weight's own shape.
    K, H, KVH, D, Out = 8, 4, 2, 8, 6
    model, cfg = _gqa_packed_model(
        K=K,
        H=H,
        KVH=KVH,
        D=D,
        Out=Out,
        seed=23,
        split_sizes=[H * D, KVH * D, KVH * D - 1],
    )

    assert onnxsim.pruning._find_gqa_chains(model.graph) == []

    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    assert pruned.SerializeToString() == model.SerializeToString()


def test_gqa_native_packed_query_convention_still_declined():
    # `GroupQueryAttention`'s own SCHEMA (not this pass) has its own,
    # different packed-input convention: the whole packed Q/K/V tensor
    # passed as `query` itself, with `key`/`value` left empty -- confirmed
    # via live schema introspection
    # (``onnxruntime.capi.onnxruntime_pybind11_state.get_all_operator_schema()``,
    # `query`'s own doc string: "Query with shape (batch_size,
    # sequence_length, hidden_size), or packed QKV with shape (batch_size,
    # sequence_length, d)"; see this module's own "Attention-head pruning"
    # section comment). This is a different tensor layout from the
    # MatMul-then-Split-into-three-separate-inputs shape
    # `_match_packed_qkv_split` matches above (this model has no `Split`
    # node at all), and `_match_gqa_producer` has always declined it
    # outright, via its own ``not (node.input[0] and node.input[1] and
    # node.input[2])`` check -- confirmed here still holds, unmodified by
    # this module's new packed-`Split` support.
    K, H, KVH, D, Out = 8, 4, 2, 8, 6
    Nq, Nkv = H * D, KVH * D
    rng = np.random.default_rng(22)
    wqkv = rng.standard_normal((K, Nq + 2 * Nkv)).astype(np.float32)
    wout = rng.standard_normal((Nq, Out)).astype(np.float32)
    batch, seq = 2, 5

    initializer = [_f32(wqkv, "Wqkv"), _f32(wout, "Wout")]
    initializer.append(
        onnx.numpy_helper.from_array(
            np.full((batch,), seq - 1, dtype=np.int32), "SeqLensK"
        )
    )
    initializer.append(
        onnx.numpy_helper.from_array(np.array(seq, dtype=np.int32), "TotalSeq")
    )

    body = f"""
        g (float[{batch},{seq},{K}] X) => (float[{batch},{seq},{Out}] Y)
        {{
          qkv = MatMul(X, Wqkv)
          ctx, pk, pv = com.microsoft.GroupQueryAttention <num_heads={H}, kv_num_heads={KVH}> (qkv, , , , , SeqLensK, TotalSeq)
          Y = MatMul(ctx, Wout)
        }}
        """
    model = parser.parse_model(
        f"""
        <
          ir_version: 10,
          opset_import: ["": 17, "com.microsoft": 1]
        >
        {body}
        """
    )
    model.graph.initializer.extend(initializer)

    assert onnxsim.pruning._find_gqa_chains(model.graph) == []

    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    assert pruned.SerializeToString() == model.SerializeToString()


# --- apply_attention_head_pruning / _wanda_pruning -- GroupQueryAttention,
# packed-QKV-then-Split, CPU/DirectML Q/K-norm + RoPE pass-through --
#
# The shape `_match_packed_qkv_split`'s own docstring names as deliberately
# left unmatched by that function alone: onnxruntime-genai's model builder,
# when Q/K-norm is requested but the fused in-op norm path isn't supported
# (CPU/DirectML -- `is_fused_qk_norm_gqa_supported` only allows it on
# CUDA/WebGPU), emits a per-head `Reshape` -> `SimplifiedLayerNormalization`
# -> `Reshape` sandwich (`make_qk_norm`) and, unless RoPE is fused into the
# op itself, a `com.microsoft::RotaryEmbedding` node (`make_rotary_embedding_op`)
# between the packed-QKV `Split`'s own Q/K outputs and `GroupQueryAttention`'s
# own Q/K inputs, norm before RoPE (`make_attention_qk_rope_and_norm`'s own
# "Base order: norm first, then RoPE" comment) -- see
# :func:`onnxsim.pruning._walk_back_through_qk_norm_rope`'s own docstring
# for the exact topology and this module's own "Attention-head pruning"
# section comment for the empirically-confirmed head-independence facts
# (a `SimplifiedLayerNormalization`'s own `scale` and a `RotaryEmbedding`'s
# own `cos_cache`/`sin_cache` never need slicing at all) that make this
# pass-through safe -- the two direct tests immediately below are the
# empirical confirmation that comment refers to; every other test in this
# section builds on top of them via the full matcher/pruning path.


def test_simplified_layer_norm_is_head_independent_for_pruning():
    # Direct confirmation of this section's own head-independence claim for
    # `SimplifiedLayerNormalization`, isolated from the rest of the pruning
    # machinery: a `(batch, seq, num_heads * head_size)` tensor, reshaped to
    # expose `head_size` as the last axis (`make_qk_norm`'s own subgraph
    # shape), normalized with a `[head_size]` `scale` shared identically
    # across every head, reshaped back. Dropping an arbitrary, non-contiguous
    # subset of heads *before* running this norm must give bit-identical
    # results, for the surviving heads, to running it on the full tensor
    # first and dropping those same heads *after* -- exactly the property
    # that makes slicing whole heads out of the packed weight upstream of
    # this norm safe without touching the norm's own `scale` at all.
    def _norm_model(batch, seq, num_heads, head_size, scale):
        hidden = num_heads * head_size
        body = f"""
            g (float[{batch},{seq},{hidden}] X) => (float[{batch},{seq},{hidden}] Y)
            {{
              r1 = Reshape(X, Shape1)
              ln = SimplifiedLayerNormalization <axis=-1, epsilon=1e-6> (r1, Scale)
              Y = Reshape(ln, Shape2)
            }}
            """
        return _model(
            body,
            initializer=[
                onnx.numpy_helper.from_array(
                    np.array([0, -1, head_size], dtype=np.int64), "Shape1"
                ),
                onnx.numpy_helper.from_array(
                    np.array([0, -1, hidden], dtype=np.int64), "Shape2"
                ),
                _f32(scale, "Scale"),
            ],
            opset=17,
        )

    batch, seq, num_heads, head_size = 2, 5, 6, 8
    rng = np.random.default_rng(101)
    scale = rng.standard_normal((head_size,)).astype(np.float32)
    x = rng.standard_normal((batch, seq, num_heads * head_size)).astype(np.float32)

    full_model = _norm_model(batch, seq, num_heads, head_size, scale)
    (y_full,) = _run(full_model, {"X": x})
    y_full_heads = y_full.reshape(batch, seq, num_heads, head_size)

    keep = [0, 2, 3, 5]  # arbitrary, non-contiguous
    x_heads = x.reshape(batch, seq, num_heads, head_size)
    x_sub = x_heads[:, :, keep, :].reshape(batch, seq, len(keep) * head_size)

    sub_model = _norm_model(batch, seq, len(keep), head_size, scale)
    (y_sub,) = _run(sub_model, {"X": x_sub})
    y_sub_heads = y_sub.reshape(batch, seq, len(keep), head_size)

    np.testing.assert_array_equal(y_sub_heads, y_full_heads[:, :, keep, :])


def test_rotary_embedding_is_head_independent_for_pruning():
    # Direct confirmation of this section's own head-independence claim for
    # `com.microsoft::RotaryEmbedding`, isolated from the rest of the
    # pruning machinery, across every `interleaved`/`rotary_embedding_dim`
    # combination this pass supports: dropping an arbitrary,
    # non-contiguous subset of heads before or after this op gives
    # bit-identical results for the surviving heads either way, since
    # `cos_cache`/`sin_cache` are looked up purely by position, never by
    # head index.
    def _rope_model(
        batch, seq, num_heads, head_size, cos, sin, interleaved, rotary_embedding_dim
    ):
        hidden = num_heads * head_size
        body = f"""
            g (float[{batch},{seq},{hidden}] X, int64[{batch},{seq}] PosIds)
              => (float[{batch},{seq},{hidden}] Y)
            {{
              Y = com.microsoft.RotaryEmbedding
                <num_heads={num_heads}, interleaved={interleaved}, rotary_embedding_dim={rotary_embedding_dim}>
                (X, PosIds, Cos, Sin)
            }}
            """
        return _model(
            body,
            initializer=[_f32(cos, "Cos"), _f32(sin, "Sin")],
            opset=17,
        )

    batch, seq, num_heads, head_size = 2, 5, 6, 8
    rng = np.random.default_rng(102)
    max_pos = 16
    keep = [0, 2, 3, 5]  # arbitrary, non-contiguous

    for interleaved, rotary_embedding_dim in ((0, 0), (1, 0), (0, head_size // 2)):
        rot_dim = rotary_embedding_dim if rotary_embedding_dim > 0 else head_size
        half = rot_dim // 2
        cos = rng.standard_normal((max_pos, half)).astype(np.float32)
        sin = rng.standard_normal((max_pos, half)).astype(np.float32)
        x = rng.standard_normal((batch, seq, num_heads * head_size)).astype(np.float32)
        position_ids = rng.integers(0, max_pos, size=(batch, seq)).astype(np.int64)

        full_model = _rope_model(
            batch,
            seq,
            num_heads,
            head_size,
            cos,
            sin,
            interleaved,
            rotary_embedding_dim,
        )
        (y_full,) = _run(full_model, {"X": x, "PosIds": position_ids})
        y_full_heads = y_full.reshape(batch, seq, num_heads, head_size)

        x_heads = x.reshape(batch, seq, num_heads, head_size)
        x_sub = x_heads[:, :, keep, :].reshape(batch, seq, len(keep) * head_size)
        sub_model = _rope_model(
            batch,
            seq,
            len(keep),
            head_size,
            cos,
            sin,
            interleaved,
            rotary_embedding_dim,
        )
        (y_sub,) = _run(sub_model, {"X": x_sub, "PosIds": position_ids})
        y_sub_heads = y_sub.reshape(batch, seq, len(keep), head_size)

        np.testing.assert_array_equal(y_sub_heads, y_full_heads[:, :, keep, :])


def _qk_norm_rope_body(
    prefix,
    raw_name,
    gamma_name,
    reshape1_shape_name,
    reshape2_shape_name,
    with_norm,
    with_rope,
    cos_name="CosCache",
    sin_name="SinCache",
    pos_name="PosIds",
    interleaved=0,
    rotary_embedding_dim=0,
    rotary_num_heads=None,
):
    # Returns a text fragment (per CLAUDE.md's own guidance for a reusable
    # node sequence) plus the name of the final tensor it leaves behind --
    # `raw_name` itself, unchanged, when both `with_norm`/`with_rope` are
    # False.
    lines = []
    cur = raw_name
    if with_norm:
        lines.append(f"{prefix}_r1 = Reshape({cur}, {reshape1_shape_name})")
        lines.append(
            f"{prefix}_ln = SimplifiedLayerNormalization <axis=-1, epsilon=1e-6> "
            f"({prefix}_r1, {gamma_name})"
        )
        lines.append(f"{prefix}_normed = Reshape({prefix}_ln, {reshape2_shape_name})")
        cur = f"{prefix}_normed"
    if with_rope:
        nh = rotary_num_heads if rotary_num_heads is not None else 0
        lines.append(
            f"{prefix}_rot = com.microsoft.RotaryEmbedding "
            f"<num_heads={nh}, interleaved={interleaved}, "
            f"rotary_embedding_dim={rotary_embedding_dim}> "
            f"({cur}, {pos_name}, {cos_name}, {sin_name})"
        )
        cur = f"{prefix}_rot"
    return "\n          ".join(lines), cur


def _gqa_qk_norm_rope_model(
    K=8,
    H=8,
    KVH=2,
    D=8,
    Out=6,
    seed=0,
    batch=2,
    seq=5,
    packed=True,
    with_norm=True,
    with_rope=True,
    interleaved=0,
    rotary_embedding_dim=0,
    q_rotary_num_heads=None,
    k_rotary_num_heads=None,
    wqkv=None,
    wq=None,
    wk=None,
    wv=None,
    wout=None,
    q_gamma=None,
    k_gamma=None,
    cos=None,
    sin=None,
    position_ids=None,
    max_pos=32,
    rope_before_norm=False,
):
    # Mirrors `_gqa_packed_model`'s (`packed=True`) and `_gqa_model`'s
    # (`packed=False`) own scaffolding, with an optional per-head norm +
    # RoPE pass-through -- see this section's own comment above -- spliced
    # in between the raw Q/K branches and `GroupQueryAttention`'s own
    # inputs. `packed=False` builds the ordinary three-independent-producer
    # shape (used here as an *independently*-constructed oracle, the same
    # role `_gqa_model` already plays for the packed tests above), still
    # with the same optional norm/RoPE hop on each of its own Q/K branches.
    rng = np.random.default_rng(seed)
    Nq, Nkv = H * D, KVH * D
    if wout is None:
        wout = rng.standard_normal((Nq, Out)).astype(np.float32)
    initializer = [_f32(wout, "Wout")]

    if packed:
        if wqkv is None:
            wqkv = rng.standard_normal((K, Nq + 2 * Nkv)).astype(np.float32)
        initializer.append(_f32(wqkv, "Wqkv"))
        split_sizes = np.array([Nq, Nkv, Nkv], dtype=np.int64)
        initializer.append(onnx.numpy_helper.from_array(split_sizes, "SplitSizes"))
        producer_body = (
            "qkv = MatMul(X, Wqkv)\n"
            "          q_raw, k_raw, v = Split <axis = -1> (qkv, SplitSizes)"
        )
    else:
        if wq is None:
            wq = rng.standard_normal((K, Nq)).astype(np.float32)
        if wk is None:
            wk = rng.standard_normal((K, Nkv)).astype(np.float32)
        if wv is None:
            wv = rng.standard_normal((K, Nkv)).astype(np.float32)
        initializer += [_f32(wq, "Wq"), _f32(wk, "Wk"), _f32(wv, "Wv")]
        producer_body = (
            "q_raw = MatMul(X, Wq)\n"
            "          k_raw = MatMul(X, Wk)\n"
            "          v = MatMul(X, Wv)"
        )

    initializer.append(
        onnx.numpy_helper.from_array(
            np.full((batch,), seq - 1, dtype=np.int32), "SeqLensK"
        )
    )
    initializer.append(
        onnx.numpy_helper.from_array(np.array(seq, dtype=np.int32), "TotalSeq")
    )

    q_body, k_body, hop_body = "q_raw", "k_raw", ""
    if with_norm or with_rope:
        half = D // 2
        if cos is None:
            cos = rng.standard_normal((max_pos, half)).astype(np.float32)
        if sin is None:
            sin = rng.standard_normal((max_pos, half)).astype(np.float32)
        if position_ids is None:
            position_ids = np.tile(np.arange(seq, dtype=np.int64), (batch, 1))
        initializer += [_f32(cos, "CosCache"), _f32(sin, "SinCache")]
        initializer.append(onnx.numpy_helper.from_array(position_ids, "PosIds"))

        if q_gamma is None:
            q_gamma = rng.standard_normal((D,)).astype(np.float32)
        if k_gamma is None:
            k_gamma = rng.standard_normal((D,)).astype(np.float32)
        initializer += [_f32(q_gamma, "QGamma"), _f32(k_gamma, "KGamma")]
        initializer.append(
            onnx.numpy_helper.from_array(
                np.array([0, -1, D], dtype=np.int64), "QReshape1Shape"
            )
        )
        initializer.append(
            onnx.numpy_helper.from_array(
                np.array([0, -1, Nq], dtype=np.int64), "QReshape2Shape"
            )
        )
        initializer.append(
            onnx.numpy_helper.from_array(
                np.array([0, -1, D], dtype=np.int64), "KReshape1Shape"
            )
        )
        initializer.append(
            onnx.numpy_helper.from_array(
                np.array([0, -1, Nkv], dtype=np.int64), "KReshape2Shape"
            )
        )

        rope_kwargs = dict(
            interleaved=interleaved, rotary_embedding_dim=rotary_embedding_dim
        )
        if not rope_before_norm:
            q_text, q_body = _qk_norm_rope_body(
                "q",
                "q_raw",
                "QGamma",
                "QReshape1Shape",
                "QReshape2Shape",
                with_norm,
                with_rope,
                rotary_num_heads=q_rotary_num_heads,
                **rope_kwargs,
            )
            k_text, k_body = _qk_norm_rope_body(
                "k",
                "k_raw",
                "KGamma",
                "KReshape1Shape",
                "KReshape2Shape",
                with_norm,
                with_rope,
                rotary_num_heads=k_rotary_num_heads,
                **rope_kwargs,
            )
            hop_body = q_text + "\n          " + k_text
        else:
            # Adversarial (see `test_gqa_packed_qkv_rope_before_norm_is_declined`):
            # RoPE applied *before* the norm sandwich -- the reverse of the
            # real exporter's own order -- a shape
            # `_walk_back_through_qk_norm_rope` doesn't recognize (it only
            # ever crosses `RotaryEmbedding` as the *outermost* hop).
            q_rope_text, q_rot = _qk_norm_rope_body(
                "q",
                "q_raw",
                "QGamma",
                "QReshape1Shape",
                "QReshape2Shape",
                False,
                True,
                rotary_num_heads=q_rotary_num_heads,
                **rope_kwargs,
            )
            q_norm_text, q_body = _qk_norm_rope_body(
                "qn",
                q_rot,
                "QGamma",
                "QReshape1Shape",
                "QReshape2Shape",
                True,
                False,
            )
            k_rope_text, k_rot = _qk_norm_rope_body(
                "k",
                "k_raw",
                "KGamma",
                "KReshape1Shape",
                "KReshape2Shape",
                False,
                True,
                rotary_num_heads=k_rotary_num_heads,
                **rope_kwargs,
            )
            k_norm_text, k_body = _qk_norm_rope_body(
                "kn",
                k_rot,
                "KGamma",
                "KReshape1Shape",
                "KReshape2Shape",
                True,
                False,
            )
            hop_body = "\n          ".join(
                [q_rope_text, q_norm_text, k_rope_text, k_norm_text]
            )

    body = f"""
        g (float[{batch},{seq},{K}] X) => (float[{batch},{seq},{Out}] Y)
        {{
          {producer_body}
          {hop_body}
          ctx, pk, pv = com.microsoft.GroupQueryAttention <num_heads={H}, kv_num_heads={KVH}> ({q_body}, {k_body}, v, , , SeqLensK, TotalSeq)
          Y = MatMul(ctx, Wout)
        }}
        """
    model = parser.parse_model(
        f"""
        <
          ir_version: 10,
          opset_import: ["": 17, "com.microsoft": 1]
        >
        {body}
        """
    )
    model.graph.initializer.extend(initializer)
    return model, dict(
        K=K,
        H=H,
        KVH=KVH,
        D=D,
        Out=Out,
        Nq=Nq,
        Nkv=Nkv,
        wqkv=wqkv,
        wq=wq,
        wk=wk,
        wv=wv,
        wout=wout,
        q_gamma=q_gamma,
        k_gamma=k_gamma,
        cos=cos,
        sin=sin,
        position_ids=position_ids,
        batch=batch,
        seq=seq,
    )


def _qk_norm_rope_oracle_and_pruned(
    K, H, KVH, D, Out, seed, sparsity, with_norm, with_rope, **extra
):
    # Shared body for every oracle-comparison test below: builds the packed
    # (to-be-pruned) model, prunes it, and builds an *independently*
    # constructed (`packed=False`) already-correctly-reduced oracle model
    # from the exact same pre-pruning weights/gamma/cos/sin/position_ids --
    # `q_gamma`/`k_gamma`/`cos`/`sin`/`position_ids` reused *verbatim*,
    # unsliced, since none of them has any per-head axis to begin with (the
    # whole point of this section's own head-independence facts) -- mirrors
    # `test_gqa_packed_qkv_split_pruning_matches_oracle_exactly`'s own
    # pattern one section above.
    model, cfg = _gqa_qk_norm_rope_model(
        K=K,
        H=H,
        KVH=KVH,
        D=D,
        Out=Out,
        seed=seed,
        with_norm=with_norm,
        with_rope=with_rope,
        **extra,
    )
    assert len(onnxsim.pruning._find_gqa_chains(model.graph)) == 1

    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=sparsity)

    Nq, Nkv = cfg["Nq"], cfg["Nkv"]
    wqkv = cfg["wqkv"]
    wq, wk, wv = wqkv[:, :Nq], wqkv[:, Nq : Nq + Nkv], wqkv[:, Nq + Nkv :]

    group_size = H // KVH
    keep_count = max(1, KVH - round(KVH * sparsity))
    keep_groups = _oracle_keep_groups(wq, wk, wv, H, KVH, D, keep_count)
    keep_q_heads = _group_q_heads(keep_groups, group_size)
    q_idx, kv_idx = _head_idx(keep_q_heads, D), _head_idx(keep_groups, D)

    oracle_extra = dict(extra)
    oracle_extra.pop("q_rotary_num_heads", None)
    oracle_extra.pop("k_rotary_num_heads", None)
    q_rotary_num_heads = extra.get("q_rotary_num_heads")
    k_rotary_num_heads = extra.get("k_rotary_num_heads")

    oracle, _ = _gqa_qk_norm_rope_model(
        K=K,
        H=len(keep_q_heads),
        KVH=len(keep_groups),
        D=D,
        Out=Out,
        seed=seed,
        packed=False,
        with_norm=with_norm,
        with_rope=with_rope,
        wq=wq[:, q_idx],
        wk=wk[:, kv_idx],
        wv=wv[:, kv_idx],
        wout=cfg["wout"][q_idx, :],
        q_gamma=cfg["q_gamma"],
        k_gamma=cfg["k_gamma"],
        cos=cfg["cos"],
        sin=cfg["sin"],
        position_ids=cfg["position_ids"],
        q_rotary_num_heads=(
            None
            if q_rotary_num_heads is None or q_rotary_num_heads == 0
            else len(keep_q_heads)
        ),
        k_rotary_num_heads=(
            None
            if k_rotary_num_heads is None or k_rotary_num_heads == 0
            else len(keep_groups)
        ),
        **oracle_extra,
    )

    rng = np.random.default_rng(seed + 1000)
    x = rng.standard_normal((cfg["batch"], cfg["seq"], K)).astype(np.float32)
    (y_pruned,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    return pruned, oracle, y_pruned, y_oracle, keep_groups, keep_q_heads


def test_gqa_packed_qkv_qk_norm_rope_pruning_matches_oracle_exactly():
    # The common export shape (see this section's own comment above): both
    # Q's and K's own branch get a per-head `SimplifiedLayerNorm` sandwich
    # *and* `RotaryEmbedding`, `RotaryEmbedding`'s own `num_heads` left at
    # the schema's `0` ("infer from shape") -- confirmed, empirically, to
    # self-adjust to the new post-pruning head count with no attribute
    # rewrite needed at all -- and `interleaved=1` for a bit of extra
    # coverage beyond the default rotate-half layout, both already
    # confirmed head-independent for every combination tried.
    K, H, KVH, D, Out = 8, 8, 2, 8, 6
    pruned, oracle, y_pruned, y_oracle, keep_groups, keep_q_heads = (
        _qk_norm_rope_oracle_and_pruned(
            K,
            H,
            KVH,
            D,
            Out,
            seed=1,
            sparsity=0.5,
            with_norm=True,
            with_rope=True,
            interleaved=1,
        )
    )
    node = _gqa_node(pruned)
    num_heads, kv_num_heads = _gqa_attrs(node)
    assert kv_num_heads == len(keep_groups) == 1
    assert num_heads == len(keep_q_heads) == 4

    rotary_nodes = [n for n in pruned.graph.node if n.op_type == "RotaryEmbedding"]
    assert len(rotary_nodes) == 2
    for n in rotary_nodes:
        nh = next(a.i for a in n.attribute if a.name == "num_heads")
        assert nh == 0  # left at the self-adjusting schema default, unchanged

    np.testing.assert_allclose(y_pruned, y_oracle, rtol=1e-5, atol=1e-5)


def test_gqa_packed_qkv_qk_norm_rope_pruning_updates_explicit_rotary_num_heads():
    # The partial-rotary case (`onnxruntime_genai`'s own
    # `make_rotary_embedding`: "num_heads=0 if partial_rotary_factor == 1.0
    # else num_heads") leaves `RotaryEmbedding`'s own `num_heads` attribute
    # *non*-zero -- the one crossed-hop constant that genuinely does need
    # rewriting post-pruning (see this section's own comment above) --
    # exercised here together with a partial `rotary_embedding_dim` (half
    # of `head_size`), both already confirmed head-independent.
    K, H, KVH, D, Out = 8, 8, 2, 8, 6
    pruned, oracle, y_pruned, y_oracle, keep_groups, keep_q_heads = (
        _qk_norm_rope_oracle_and_pruned(
            K,
            H,
            KVH,
            D,
            Out,
            seed=2,
            sparsity=0.5,
            with_norm=True,
            with_rope=True,
            rotary_embedding_dim=D // 2,
            q_rotary_num_heads=H,
            k_rotary_num_heads=KVH,
        )
    )
    q_rot = next(
        n
        for n in pruned.graph.node
        if n.op_type == "RotaryEmbedding" and n.input[0].startswith("q_")
    )
    k_rot = next(
        n
        for n in pruned.graph.node
        if n.op_type == "RotaryEmbedding" and n.input[0].startswith("k_")
    )
    assert next(a.i for a in q_rot.attribute if a.name == "num_heads") == len(
        keep_q_heads
    )
    assert next(a.i for a in k_rot.attribute if a.name == "num_heads") == len(
        keep_groups
    )

    np.testing.assert_allclose(y_pruned, y_oracle, rtol=1e-5, atol=1e-5)


def test_gqa_packed_qkv_norm_only_pruning_matches_oracle_exactly():
    # Q/K-norm without RoPE (RoPE fused into the attention op itself, or
    # simply absent) -- only the `Reshape` -> `SimplifiedLayerNormalization`
    # -> `Reshape` sandwich is crossed on each of Q's/K's own branch, no
    # `RotaryEmbedding` hop at all.
    K, H, KVH, D, Out = 8, 8, 2, 8, 6
    pruned, oracle, y_pruned, y_oracle, keep_groups, keep_q_heads = (
        _qk_norm_rope_oracle_and_pruned(
            K,
            H,
            KVH,
            D,
            Out,
            seed=3,
            sparsity=0.5,
            with_norm=True,
            with_rope=False,
        )
    )
    assert not any(n.op_type == "RotaryEmbedding" for n in pruned.graph.node)
    assert (
        sum(n.op_type == "SimplifiedLayerNormalization" for n in pruned.graph.node) == 2
    )
    np.testing.assert_allclose(y_pruned, y_oracle, rtol=1e-5, atol=1e-5)


def test_gqa_packed_qkv_rope_only_pruning_matches_oracle_exactly():
    # RoPE without Q/K-norm (no norm requested at all) -- only the
    # `RotaryEmbedding` hop is crossed, applied directly to the `Split`'s
    # own raw Q/K outputs.
    K, H, KVH, D, Out = 8, 8, 2, 8, 6
    pruned, oracle, y_pruned, y_oracle, keep_groups, keep_q_heads = (
        _qk_norm_rope_oracle_and_pruned(
            K,
            H,
            KVH,
            D,
            Out,
            seed=4,
            sparsity=0.5,
            with_norm=False,
            with_rope=True,
        )
    )
    assert not any(
        n.op_type == "SimplifiedLayerNormalization" for n in pruned.graph.node
    )
    assert sum(n.op_type == "RotaryEmbedding" for n in pruned.graph.node) == 2
    np.testing.assert_allclose(y_pruned, y_oracle, rtol=1e-5, atol=1e-5)


def test_gqa_wanda_packed_qkv_qk_norm_rope_pruning_matches_oracle_exactly():
    # The Wanda-calibrated variant shares :func:`_apply_one_gqa_chain` with
    # the data-free path above -- only `compute_group_importance` differs
    # (see `_gqa_group_importance`) -- so this exercises that the new
    # `q_norm_rope`/`k_norm_rope` handling works unchanged under that
    # shared apply path too, not just the data-free default.
    K, H, KVH, D, Out = 8, 8, 2, 8, 6
    model, cfg = _gqa_qk_norm_rope_model(
        K=K, H=H, KVH=KVH, D=D, Out=Out, seed=5, with_norm=True, with_rope=True
    )
    rng = np.random.default_rng(6)
    x_cal = rng.standard_normal((cfg["batch"], cfg["seq"], K)).astype(np.float32)
    calibration_data = [{"X": x_cal}]

    pruned = onnxsim.apply_attention_head_wanda_pruning(
        model, calibration_data=calibration_data, sparsity=0.5
    )

    probe_model = onnx.ModelProto()
    probe_model.CopyFrom(model)
    probe_model.graph.output.append(onnx.ValueInfoProto(name="ctx"))
    (_, ctx_cal) = _run(probe_model, {"X": x_cal})
    act_norm = np.sqrt(np.mean(np.square(ctx_cal.astype(np.float64)), axis=(0, 1)))

    Nq, Nkv = cfg["Nq"], cfg["Nkv"]
    wqkv = cfg["wqkv"]
    wq, wk, wv = wqkv[:, :Nq], wqkv[:, Nq : Nq + Nkv], wqkv[:, Nq + Nkv :]

    group_size = H // KVH
    importance = np.zeros(KVH)
    for kv in range(KVH):
        q_block = np.concatenate(
            [
                wq[:, h * D : (h + 1) * D]
                for h in range(kv * group_size, (kv + 1) * group_size)
            ],
            axis=1,
        )
        k_block = wk[:, kv * D : (kv + 1) * D]
        v_block = wv[:, kv * D : (kv + 1) * D]
        base = np.linalg.norm(np.concatenate([q_block, k_block, v_block], axis=1))
        act_group = np.linalg.norm(
            act_norm[kv * group_size * D : (kv + 1) * group_size * D]
        )
        importance[kv] = base * max(act_group, 1e-8)
    keep_groups = np.sort(np.argsort(-importance)[:1])  # max(1, 2 - round(2*0.5)) == 1
    keep_q_heads = _group_q_heads(keep_groups, group_size)
    q_idx, kv_idx = _head_idx(keep_q_heads, D), _head_idx(keep_groups, D)

    oracle, _ = _gqa_qk_norm_rope_model(
        K=K,
        H=len(keep_q_heads),
        KVH=len(keep_groups),
        D=D,
        Out=Out,
        seed=5,
        packed=False,
        with_norm=True,
        with_rope=True,
        wq=wq[:, q_idx],
        wk=wk[:, kv_idx],
        wv=wv[:, kv_idx],
        wout=cfg["wout"][q_idx, :],
        q_gamma=cfg["q_gamma"],
        k_gamma=cfg["k_gamma"],
        cos=cfg["cos"],
        sin=cfg["sin"],
        position_ids=cfg["position_ids"],
    )

    x = rng.standard_normal((cfg["batch"], cfg["seq"], K)).astype(np.float32)
    (y_pruned,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    np.testing.assert_allclose(y_pruned, y_oracle, rtol=1e-5, atol=1e-5)


def test_gqa_packed_qkv_rope_before_norm_is_declined():
    # Adversarial: RoPE applied *before* the norm sandwich instead of after
    # -- the reverse of onnxruntime-genai's own confirmed order
    # (`make_attention_qk_rope_and_norm`'s own "Base order: norm first,
    # then RoPE" comment) -- is a shape `_walk_back_through_qk_norm_rope`
    # doesn't recognize (it only ever crosses a `RotaryEmbedding` as the
    # *outermost* hop, nearest the attention op's own input): neither Q's
    # nor K's own branch ends up tracing back to the shared `Split`, so the
    # whole chain is declined -- left completely untouched -- rather than
    # silently mis-slicing a shape this pass hasn't verified.
    K, H, KVH, D, Out = 8, 4, 2, 8, 6
    model, cfg = _gqa_qk_norm_rope_model(
        K=K,
        H=H,
        KVH=KVH,
        D=D,
        Out=Out,
        seed=21,
        with_norm=True,
        with_rope=True,
        rope_before_norm=True,
    )
    assert onnxsim.pruning._find_gqa_chains(model.graph) == []

    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    assert pruned.SerializeToString() == model.SerializeToString()


# --- apply_attention_head_pruning -- MRotaryEmbedding/GemmaRotaryEmbedding
#     QK-norm+RoPE pass-through hop --------------------------------------
#
# `com.microsoft::MRotaryEmbedding` ("M-RoPE", the Qwen-VL family's own
# multimodal rotary embedding) and `com.microsoft::GemmaRotaryEmbedding`
# (the Gemma family's own RoPE variant) -- see
# `onnxsim.pruning._walk_back_through_qk_norm_rope`'s own section comment
# for the exact schema facts (pulled live via
# `onnxruntime.capi.onnxruntime_pybind11_state.get_all_operator_schema()`,
# same as every other empirical claim there) and safety arguments for both.


def test_mrotary_embedding_is_head_independent_for_pruning():
    # Direct confirmation of `MRotaryEmbedding`'s own head-independence,
    # isolated from the rest of the pruning machinery, mirroring
    # `test_rotary_embedding_is_head_independent_for_pruning` -- across both
    # `mrope_layout` values this module's own matcher accepts (0 "Sectioned/
    # Chunked", 1 "Interleaved") and a deliberately non-uniform
    # `mrope_section` split: dropping an arbitrary, non-contiguous subset of
    # heads before or after this op must give bit-identical results for the
    # surviving heads either way, since `mrope_section`/`mrope_layout`
    # partition the cos/sin cache's own `half_rotary_embedding_dim` axis --
    # a property of `head_size`, never of head count at all.
    def _mrope_model(batch, seq, num_heads, head_size, cos, sin, section, layout):
        hidden = num_heads * head_size
        section_str = "[" + ", ".join(str(s) for s in section) + "]"
        body = f"""
            g (float[{batch},{seq},{hidden}] X, int64[3,{batch},{seq}] PosIds)
              => (float[{batch},{seq},{hidden}] Y)
            {{
              Y = com.microsoft.MRotaryEmbedding
                <num_heads={num_heads}, mrope_section={section_str}, mrope_layout={layout}>
                (X, PosIds, Cos, Sin)
            }}
            """
        return _model(
            body,
            initializer=[_f32(cos, "Cos"), _f32(sin, "Sin")],
            opset=17,
        )

    batch, seq, num_heads, head_size = 2, 5, 6, 8
    rng = np.random.default_rng(103)
    max_pos = 16
    half = head_size // 2
    section = [2, 1, 1]  # deliberately non-uniform, sums to `half`
    keep = [0, 2, 3, 5]  # arbitrary, non-contiguous

    for layout in (0, 1):
        cos = rng.standard_normal((max_pos, half)).astype(np.float32)
        sin = rng.standard_normal((max_pos, half)).astype(np.float32)
        x = rng.standard_normal((batch, seq, num_heads * head_size)).astype(np.float32)
        posT = rng.integers(0, max_pos, size=(batch, seq)).astype(np.int64)
        posH = rng.integers(0, max_pos, size=(batch, seq)).astype(np.int64)
        posW = rng.integers(0, max_pos, size=(batch, seq)).astype(np.int64)
        position_ids = np.stack([posT, posH, posW], axis=0)

        full_model = _mrope_model(
            batch, seq, num_heads, head_size, cos, sin, section, layout
        )
        (y_full,) = _run(full_model, {"X": x, "PosIds": position_ids})
        y_full_heads = y_full.reshape(batch, seq, num_heads, head_size)

        x_heads = x.reshape(batch, seq, num_heads, head_size)
        x_sub = x_heads[:, :, keep, :].reshape(batch, seq, len(keep) * head_size)
        sub_model = _mrope_model(
            batch, seq, len(keep), head_size, cos, sin, section, layout
        )
        (y_sub,) = _run(sub_model, {"X": x_sub, "PosIds": position_ids})
        y_sub_heads = y_sub.reshape(batch, seq, len(keep), head_size)

        np.testing.assert_array_equal(y_sub_heads, y_full_heads[:, :, keep, :])


def _gqa_mrope_model(
    K=8,
    H=8,
    KVH=2,
    D=8,
    Out=6,
    seed=0,
    batch=2,
    seq=5,
    packed=True,
    mrope_section=(2, 1, 1),
    mrope_layout=0,
    wqkv=None,
    wq=None,
    wk=None,
    wv=None,
    wout=None,
    cos=None,
    sin=None,
    position_ids=None,
    max_pos=32,
    q_rotary_num_heads=None,
    k_rotary_num_heads=None,
):
    # `MRotaryEmbedding` analogue of `_gqa_qk_norm_rope_model` (RoPE-only,
    # no Q/K-norm sandwich -- "basic" coverage per this section's own scope,
    # the norm sandwich's own composition with a rotary hop is already
    # covered for plain `RotaryEmbedding` above and shares the identical
    # `_walk_back_through_qk_norm` code path for every rotary op).
    rng = np.random.default_rng(seed)
    Nq, Nkv = H * D, KVH * D
    half = D // 2
    if wout is None:
        wout = rng.standard_normal((Nq, Out)).astype(np.float32)
    initializer = [_f32(wout, "Wout")]

    if packed:
        if wqkv is None:
            wqkv = rng.standard_normal((K, Nq + 2 * Nkv)).astype(np.float32)
        initializer.append(_f32(wqkv, "Wqkv"))
        split_sizes = np.array([Nq, Nkv, Nkv], dtype=np.int64)
        initializer.append(onnx.numpy_helper.from_array(split_sizes, "SplitSizes"))
        producer_body = (
            "qkv = MatMul(X, Wqkv)\n"
            "          q_raw, k_raw, v = Split <axis = -1> (qkv, SplitSizes)"
        )
    else:
        if wq is None:
            wq = rng.standard_normal((K, Nq)).astype(np.float32)
        if wk is None:
            wk = rng.standard_normal((K, Nkv)).astype(np.float32)
        if wv is None:
            wv = rng.standard_normal((K, Nkv)).astype(np.float32)
        initializer += [_f32(wq, "Wq"), _f32(wk, "Wk"), _f32(wv, "Wv")]
        producer_body = (
            "q_raw = MatMul(X, Wq)\n"
            "          k_raw = MatMul(X, Wk)\n"
            "          v = MatMul(X, Wv)"
        )

    if cos is None:
        cos = rng.standard_normal((max_pos, half)).astype(np.float32)
    if sin is None:
        sin = rng.standard_normal((max_pos, half)).astype(np.float32)
    if position_ids is None:
        p = np.tile(np.arange(seq, dtype=np.int64), (batch, 1))
        position_ids = np.stack([p, p, p], axis=0)
    initializer += [_f32(cos, "Cos"), _f32(sin, "Sin")]
    initializer.append(onnx.numpy_helper.from_array(position_ids, "PosIds"))
    initializer.append(
        onnx.numpy_helper.from_array(
            np.full((batch,), seq - 1, dtype=np.int32), "SeqLensK"
        )
    )
    initializer.append(
        onnx.numpy_helper.from_array(np.array(seq, dtype=np.int32), "TotalSeq")
    )

    # Unlike plain `RotaryEmbedding`, `MRotaryEmbedding`'s own real CPU
    # kernel requires an explicit, nonzero `num_heads` for rank-3 (flat)
    # input -- confirmed empirically ("MRotaryEmbedding: num_heads must be
    # greater than 0 for rank-3 input") -- so `q_rotary_num_heads`/
    # `k_rotary_num_heads` default to this branch's own actual head count
    # rather than the schema's own documented `0` default (which plain
    # `RotaryEmbedding` self-adjusts from but this op's own kernel rejects
    # outright for this input rank).
    q_nh = q_rotary_num_heads if q_rotary_num_heads is not None else H
    k_nh = k_rotary_num_heads if k_rotary_num_heads is not None else KVH
    section_str = "[" + ", ".join(str(s) for s in mrope_section) + "]"
    body = f"""
        g (float[{batch},{seq},{K}] X) => (float[{batch},{seq},{Out}] Y)
        {{
          {producer_body}
          q_rot = com.microsoft.MRotaryEmbedding
            <num_heads={q_nh}, mrope_section={section_str}, mrope_layout={mrope_layout}>
            (q_raw, PosIds, Cos, Sin)
          k_rot = com.microsoft.MRotaryEmbedding
            <num_heads={k_nh}, mrope_section={section_str}, mrope_layout={mrope_layout}>
            (k_raw, PosIds, Cos, Sin)
          ctx, pk, pv = com.microsoft.GroupQueryAttention <num_heads={H}, kv_num_heads={KVH}> (q_rot, k_rot, v, , , SeqLensK, TotalSeq)
          Y = MatMul(ctx, Wout)
        }}
        """
    model = parser.parse_model(
        f"""
        <
          ir_version: 10,
          opset_import: ["": 17, "com.microsoft": 1]
        >
        {body}
        """
    )
    model.graph.initializer.extend(initializer)
    return model, dict(
        K=K,
        H=H,
        KVH=KVH,
        D=D,
        Out=Out,
        Nq=Nq,
        Nkv=Nkv,
        wqkv=wqkv,
        wq=wq,
        wk=wk,
        wv=wv,
        wout=wout,
        cos=cos,
        sin=sin,
        position_ids=position_ids,
        batch=batch,
        seq=seq,
    )


def _mrope_oracle_and_pruned(K, H, KVH, D, Out, seed, sparsity, **extra):
    # Mirrors `_qk_norm_rope_oracle_and_pruned`'s own pattern: builds the
    # packed (to-be-pruned) model, prunes it, and builds an *independently*
    # constructed (`packed=False`) already-correctly-reduced oracle model
    # from the exact same pre-pruning weights/cos/sin/position_ids.
    model, cfg = _gqa_mrope_model(K=K, H=H, KVH=KVH, D=D, Out=Out, seed=seed, **extra)
    assert len(onnxsim.pruning._find_gqa_chains(model.graph)) == 1

    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=sparsity)

    Nq, Nkv = cfg["Nq"], cfg["Nkv"]
    wqkv = cfg["wqkv"]
    wq, wk, wv = wqkv[:, :Nq], wqkv[:, Nq : Nq + Nkv], wqkv[:, Nq + Nkv :]

    group_size = H // KVH
    keep_count = max(1, KVH - round(KVH * sparsity))
    keep_groups = _oracle_keep_groups(wq, wk, wv, H, KVH, D, keep_count)
    keep_q_heads = _group_q_heads(keep_groups, group_size)
    q_idx, kv_idx = _head_idx(keep_q_heads, D), _head_idx(keep_groups, D)

    oracle_extra = dict(extra)
    q_rotary_num_heads = extra.get("q_rotary_num_heads")
    k_rotary_num_heads = extra.get("k_rotary_num_heads")
    oracle_extra["q_rotary_num_heads"] = (
        None
        if q_rotary_num_heads is None or q_rotary_num_heads == 0
        else len(keep_q_heads)
    )
    oracle_extra["k_rotary_num_heads"] = (
        None
        if k_rotary_num_heads is None or k_rotary_num_heads == 0
        else len(keep_groups)
    )

    oracle, _ = _gqa_mrope_model(
        K=K,
        H=len(keep_q_heads),
        KVH=len(keep_groups),
        D=D,
        Out=Out,
        seed=seed,
        packed=False,
        wq=wq[:, q_idx],
        wk=wk[:, kv_idx],
        wv=wv[:, kv_idx],
        wout=cfg["wout"][q_idx, :],
        cos=cfg["cos"],
        sin=cfg["sin"],
        position_ids=cfg["position_ids"],
        **oracle_extra,
    )

    rng = np.random.default_rng(seed + 1000)
    x = rng.standard_normal((cfg["batch"], cfg["seq"], K)).astype(np.float32)
    (y_pruned,) = _run(pruned, {"X": x})
    (y_oracle,) = _run(oracle, {"X": x})
    return pruned, oracle, y_pruned, y_oracle, keep_groups, keep_q_heads


def test_gqa_packed_qkv_mrope_pruning_matches_oracle_exactly():
    # Real end-to-end `InferenceSession` correctness check -- `MRotaryEmbedding`
    # has a genuine CPU kernel in this environment (confirmed empirically,
    # unlike `GemmaRotaryEmbedding` below) -- comparing the pruned model's
    # own output against an *independently* rebuilt, already-reduced oracle
    # model (never the wrong "pruned vs. full unpruned" invariant).
    K, H, KVH, D, Out = 8, 8, 2, 8, 6
    pruned, oracle, y_pruned, y_oracle, keep_groups, keep_q_heads = (
        _mrope_oracle_and_pruned(
            K, H, KVH, D, Out, seed=201, sparsity=0.5, mrope_layout=1
        )
    )
    node = _gqa_node(pruned)
    num_heads, kv_num_heads = _gqa_attrs(node)
    assert kv_num_heads == len(keep_groups) == 1
    assert num_heads == len(keep_q_heads) == 4

    # `_gqa_mrope_model` always gives `MRotaryEmbedding` an explicit,
    # nonzero `num_heads` (its own real CPU kernel rejects the schema's
    # documented `0` "self-adjust" default outright for rank-3 input --
    # confirmed empirically: "MRotaryEmbedding: num_heads must be greater
    # than 0 for rank-3 input", unlike plain `RotaryEmbedding` -- see
    # `_gqa_mrope_model`'s own comment), so this branch's own `num_heads`
    # attribute IS one of the two constants
    # :func:`onnxsim.pruning._walk_back_through_qk_norm_rope` rewrites post-
    # pruning, checked here to be the new post-pruning head/group count on
    # both the Q-side and K-side node.
    q_rot = next(
        n
        for n in pruned.graph.node
        if n.op_type == "MRotaryEmbedding" and n.input[0] == "q_raw"
    )
    k_rot = next(
        n
        for n in pruned.graph.node
        if n.op_type == "MRotaryEmbedding" and n.input[0] == "k_raw"
    )
    for n, expect_heads in ((q_rot, len(keep_q_heads)), (k_rot, len(keep_groups))):
        nh = next(a.i for a in n.attribute if a.name == "num_heads")
        assert nh == expect_heads
        section = next(a.ints for a in n.attribute if a.name == "mrope_section")
        assert list(section) == [2, 1, 1]  # never touched -- head_size-only axis
        layout = next(a.i for a in n.attribute if a.name == "mrope_layout")
        assert layout == 1  # never touched

    np.testing.assert_allclose(y_pruned, y_oracle, rtol=1e-5, atol=1e-5)


def test_gqa_packed_qkv_mrope_pruning_updates_explicit_rotary_num_heads():
    # Mirrors `test_gqa_packed_qkv_qk_norm_rope_pruning_updates_explicit_rotary_num_heads`
    # for `MRotaryEmbedding`'s own identically-named/-semantic `num_heads`
    # attribute (see `_walk_back_through_qk_norm_rope`'s own docstring for
    # why one rewrite site already covers both ops).
    K, H, KVH, D, Out = 8, 8, 2, 8, 6
    pruned, oracle, y_pruned, y_oracle, keep_groups, keep_q_heads = (
        _mrope_oracle_and_pruned(
            K,
            H,
            KVH,
            D,
            Out,
            seed=202,
            sparsity=0.5,
            q_rotary_num_heads=H,
            k_rotary_num_heads=KVH,
        )
    )
    q_rot = next(
        n
        for n in pruned.graph.node
        if n.op_type == "MRotaryEmbedding" and n.input[0] == "q_raw"
    )
    k_rot = next(
        n
        for n in pruned.graph.node
        if n.op_type == "MRotaryEmbedding" and n.input[0] == "k_raw"
    )
    assert next(a.i for a in q_rot.attribute if a.name == "num_heads") == len(
        keep_q_heads
    )
    assert next(a.i for a in k_rot.attribute if a.name == "num_heads") == len(
        keep_groups
    )

    np.testing.assert_allclose(y_pruned, y_oracle, rtol=1e-5, atol=1e-5)


def test_gqa_packed_qkv_mrope_pruning_declines_unsupported_mrope_layout():
    # `mrope_layout` values other than the two the live schema documents (0
    # "Sectioned/Chunked", 1 "Interleaved") have no confirmed semantics --
    # this module doesn't guess at whether they're still head-independent,
    # so the whole chain is declined (left completely untouched) rather
    # than silently mis-slicing a shape/attribute value this pass hasn't
    # verified -- mirrors `test_gqa_packed_qkv_rope_before_norm_is_declined`'s
    # own "whole chain declines" assertion style.
    K, H, KVH, D, Out = 8, 8, 2, 8, 6
    model, cfg = _gqa_mrope_model(
        K=K, H=H, KVH=KVH, D=D, Out=Out, seed=203, mrope_layout=2
    )
    assert onnxsim.pruning._find_gqa_chains(model.graph) == []

    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    assert pruned.SerializeToString() == model.SerializeToString()


def test_analyze_attention_head_pruning_gqa_mrope_matches_real_call():
    # Dry-run (`analyze_pruning_sensitivity`) vs. real-call parity: both
    # share the identical `_find_gqa_chains` matcher this section extends,
    # so the analysis-only preview must predict the exact same post-pruning
    # head/group counts the real call actually produces.
    K, H, KVH, D, Out = 8, 8, 2, 8, 6
    model, cfg = _gqa_mrope_model(K=K, H=H, KVH=KVH, D=D, Out=Out, seed=204)
    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_attention_head_pruning, sparsity=0.5
    )
    assert len(report.layers) == 1
    layer = report.layers[0]
    assert layer.family == "attention_gqa_group"
    assert layer.total == KVH

    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    node = _gqa_node(pruned)
    _, kv_num_heads = _gqa_attrs(node)
    assert kv_num_heads == KVH - layer.would_drop


def _decompose_gemma_rotary_nodes(model):
    # Test-only helper: replaces every `com.microsoft::GemmaRotaryEmbedding`
    # node in `model` with the literal decomposition its own live schema doc
    # string gives (the "onnxscript that was tested" reference -- see
    # `onnxsim.pruning._walk_back_through_gemma_rope_pair`'s own docstring),
    # minus the fp16-mixed-precision `Cast`s (this helper stays in float32
    # throughout, since it exists to check the PRUNING TRANSFORM's own
    # correctness, not to reproduce the real op's fp16 numerics) --
    # `sin_val = Sin(emb); cos_val = Cos(emb)`, unsqueezed at axis 1, then
    # `q_embed = q * cos + q_rot * sin`, `k_embed = k * cos + k_rot * sin`.
    # Needed because `GemmaRotaryEmbedding` itself has no usable CPU kernel
    # in this environment at all (confirmed empirically -- see this
    # section's own comment above for the exact `CastFloat16Transformer`
    # failure) -- every ops this decomposes into (`Sin`/`Cos`/`Unsqueeze`/
    # `Mul`/`Add`) has a real ai.onnx CPU kernel, so the RESULT is directly
    # executable via a real `InferenceSession`, the same
    # decomposed-proxy-topology methodology this module's own
    # `MatMulNBitsMlp`/`MatMulNBitsQkv`/`PagedAttention` sections already
    # established (search `onnxsim/pruning.py` for "decompose a (pruned)
    # fused node's own tensors back into equivalent").
    out = onnx.ModelProto()
    out.CopyFrom(model)
    new_nodes = []
    counter = 0
    for node in out.graph.node:
        if node.op_type != "GemmaRotaryEmbedding" or node.domain != "com.microsoft":
            new_nodes.append(node)
            continue
        counter += 1
        p = f"_gemma_decomp_{counter}"
        emb, q, q_rot, k, k_rot = node.input
        q_embed, k_embed = node.output
        sin_val, cos_val = f"{p}_sin", f"{p}_cos"
        sin_u, cos_u = f"{p}_sin_u", f"{p}_cos_u"
        axes = f"{p}_axes"
        q_cos, q_sin, k_cos, k_sin = (
            f"{p}_q_cos",
            f"{p}_q_sin",
            f"{p}_k_cos",
            f"{p}_k_sin",
        )
        out.graph.initializer.append(
            onnx.numpy_helper.from_array(np.array([1], dtype=np.int64), axes)
        )
        new_nodes.extend(
            [
                onnx.helper.make_node("Sin", [emb], [sin_val], name=f"{p}/Sin"),
                onnx.helper.make_node("Cos", [emb], [cos_val], name=f"{p}/Cos"),
                onnx.helper.make_node(
                    "Unsqueeze", [sin_val, axes], [sin_u], name=f"{p}/UnsqueezeSin"
                ),
                onnx.helper.make_node(
                    "Unsqueeze", [cos_val, axes], [cos_u], name=f"{p}/UnsqueezeCos"
                ),
                onnx.helper.make_node("Mul", [q, cos_u], [q_cos], name=f"{p}/QCos"),
                onnx.helper.make_node("Mul", [q_rot, sin_u], [q_sin], name=f"{p}/QSin"),
                onnx.helper.make_node(
                    "Add", [q_cos, q_sin], [q_embed], name=f"{p}/QEmbed"
                ),
                onnx.helper.make_node("Mul", [k, cos_u], [k_cos], name=f"{p}/KCos"),
                onnx.helper.make_node("Mul", [k_rot, sin_u], [k_sin], name=f"{p}/KSin"),
                onnx.helper.make_node(
                    "Add", [k_cos, k_sin], [k_embed], name=f"{p}/KEmbed"
                ),
            ]
        )
    del out.graph.node[:]
    out.graph.node.extend(new_nodes)
    del out.graph.value_info[:]  # every shape downstream of the fused node is stale
    return out


def test_gemma_rotary_embedding_decomposition_is_head_independent_for_pruning():
    # Direct confirmation of `GemmaRotaryEmbedding`'s own head-independence
    # via its decomposed equivalent (`_decompose_gemma_rotary_nodes`),
    # executed through a real `InferenceSession` against no other oracle --
    # the fused op itself has no usable CPU kernel here at all (see this
    # section's own comment above), so this IS the empirical confirmation,
    # mirroring `test_rotary_embedding_is_head_independent_for_pruning`'s
    # own role for plain `RotaryEmbedding`: dropping an arbitrary,
    # non-contiguous subset of heads before or after this op must give
    # bit-identical results for the surviving heads either way, since
    # neither the `Sin`/`Cos` angle (`emb`, no head axis) nor the
    # elementwise `q`/`q_rot`/`k`/`k_rot` combination ever mixes across
    # heads.
    def _gemma_model(batch, seq, num_heads, head_size):
        # `Emb`'s own last axis is `head_size` -- broadcasting directly
        # against `Q`/`QRot`'s own trailing axis (the onnxscript reference's
        # `Unsqueeze`d `cos`/`sin` multiplies `Q`/`QRot` elementwise, full
        # width -- confirmed empirically: a `head_size // 2`-wide `Emb`
        # fails real `Mul` shape inference outright), unlike plain
        # `RotaryEmbedding`'s own half-width `cos_cache`/`sin_cache`.
        body = f"""
            g (float[{batch},{seq},{head_size}] Emb,
               float[{batch},{num_heads},{seq},{head_size}] Q,
               float[{batch},{num_heads},{seq},{head_size}] QRot,
               float[{batch},{num_heads},{seq},{head_size}] K,
               float[{batch},{num_heads},{seq},{head_size}] KRot)
              => (float[{batch},{num_heads},{seq},{head_size}] QEmbed,
                  float[{batch},{num_heads},{seq},{head_size}] KEmbed)
            {{
              QEmbed, KEmbed = com.microsoft.GemmaRotaryEmbedding (Emb, Q, QRot, K, KRot)
            }}
            """
        return _model(body, opset=17)

    batch, seq, num_heads, head_size = 2, 5, 6, 8
    rng = np.random.default_rng(104)
    keep = [0, 2, 3, 5]  # arbitrary, non-contiguous

    emb = rng.standard_normal((batch, seq, head_size)).astype(np.float32)
    q = rng.standard_normal((batch, num_heads, seq, head_size)).astype(np.float32)
    q_rot = rng.standard_normal((batch, num_heads, seq, head_size)).astype(np.float32)
    k = rng.standard_normal((batch, num_heads, seq, head_size)).astype(np.float32)
    k_rot = rng.standard_normal((batch, num_heads, seq, head_size)).astype(np.float32)

    full_model = _decompose_gemma_rotary_nodes(
        _gemma_model(batch, seq, num_heads, head_size)
    )
    q_embed_full, k_embed_full = _run(
        full_model,
        {"Emb": emb, "Q": q, "QRot": q_rot, "K": k, "KRot": k_rot},
    )

    sub_model = _decompose_gemma_rotary_nodes(
        _gemma_model(batch, seq, len(keep), head_size)
    )
    q_embed_sub, k_embed_sub = _run(
        sub_model,
        {
            "Emb": emb,
            "Q": q[:, keep, :, :],
            "QRot": q_rot[:, keep, :, :],
            "K": k[:, keep, :, :],
            "KRot": k_rot[:, keep, :, :],
        },
    )

    np.testing.assert_array_equal(q_embed_sub, q_embed_full[:, keep, :, :])
    np.testing.assert_array_equal(k_embed_sub, k_embed_full[:, keep, :, :])


def _gqa_gemma_rope_model(
    K=8,
    H=8,
    KVH=2,
    D=8,
    Out=6,
    seed=0,
    batch=2,
    seq=5,
    packed=True,
    wqkv=None,
    wq=None,
    wk=None,
    wv=None,
    wout=None,
    emb=None,
):
    # `GemmaRotaryEmbedding` analogue of `_gqa_mrope_model`: packed-QKV (or
    # separate producers) -> `Reshape`+`Transpose` to 4D BNSH
    # (`_match_bnsh_reshape`) -> `rotate_half` (`_match_rotate_half`) ->
    # `GemmaRotaryEmbedding` -> `Transpose`+`Reshape` back to flat 3D
    # (`_match_reverse_bnsh_reshape`, required for `GroupQueryAttention`'s
    # own 3D-only Q/K input, confirmed empirically -- see
    # `onnxsim.pruning._match_reverse_bnsh_reshape`'s own docstring) ->
    # `GroupQueryAttention`.
    rng = np.random.default_rng(seed)
    Nq, Nkv = H * D, KVH * D
    if wout is None:
        wout = rng.standard_normal((Nq, Out)).astype(np.float32)
    initializer = [_f32(wout, "Wout")]

    if packed:
        if wqkv is None:
            wqkv = rng.standard_normal((K, Nq + 2 * Nkv)).astype(np.float32)
        initializer.append(_f32(wqkv, "Wqkv"))
        split_sizes = np.array([Nq, Nkv, Nkv], dtype=np.int64)
        initializer.append(onnx.numpy_helper.from_array(split_sizes, "SplitSizes"))
        producer_body = (
            "qkv = MatMul(X, Wqkv)\n"
            "          q_raw, k_raw, v = Split <axis = -1> (qkv, SplitSizes)"
        )
    else:
        if wq is None:
            wq = rng.standard_normal((K, Nq)).astype(np.float32)
        if wk is None:
            wk = rng.standard_normal((K, Nkv)).astype(np.float32)
        if wv is None:
            wv = rng.standard_normal((K, Nkv)).astype(np.float32)
        initializer += [_f32(wq, "Wq"), _f32(wk, "Wk"), _f32(wv, "Wv")]
        producer_body = (
            "q_raw = MatMul(X, Wq)\n"
            "          k_raw = MatMul(X, Wk)\n"
            "          v = MatMul(X, Wv)"
        )

    if emb is None:
        # `emb`'s own last axis broadcasts directly against `q`'s/`k`'s own
        # full `head_size` (the onnxscript reference's `Unsqueeze`d
        # `cos`/`sin` multiplies `q`/`q_rot` elementwise) -- `D`, not `D //
        # 2` (that would only broadcast against a half-width cache the way
        # plain `RotaryEmbedding`'s own `cos_cache`/`sin_cache` do, which
        # isn't this op's own shape at all).
        emb = rng.standard_normal((batch, seq, D)).astype(np.float32)
    initializer.append(_f32(emb, "Emb"))
    initializer.append(
        onnx.numpy_helper.from_array(
            np.array([D // 2, D // 2], dtype=np.int64), "HalfSizes"
        )
    )
    initializer.append(
        onnx.numpy_helper.from_array(
            np.array([0, -1, H, D], dtype=np.int64), "QReshapeA"
        )
    )
    initializer.append(
        onnx.numpy_helper.from_array(
            np.array([0, -1, KVH, D], dtype=np.int64), "KReshapeA"
        )
    )
    initializer.append(
        onnx.numpy_helper.from_array(np.array([0, -1, Nq], dtype=np.int64), "QReshapeB")
    )
    initializer.append(
        onnx.numpy_helper.from_array(
            np.array([0, -1, Nkv], dtype=np.int64), "KReshapeB"
        )
    )
    initializer.append(
        onnx.numpy_helper.from_array(
            np.full((batch,), seq - 1, dtype=np.int32), "SeqLensK"
        )
    )
    initializer.append(
        onnx.numpy_helper.from_array(np.array(seq, dtype=np.int32), "TotalSeq")
    )

    body = f"""
        g (float[{batch},{seq},{K}] X) => (float[{batch},{seq},{Out}] Y)
        {{
          {producer_body}
          q_bnsh_in = Reshape(q_raw, QReshapeA)
          q_bnsh = Transpose <perm=[0,2,1,3]> (q_bnsh_in)
          q_x1, q_x2 = Split <axis=-1> (q_bnsh, HalfSizes)
          q_x2n = Neg(q_x2)
          q_rot_in = Concat <axis=-1> (q_x2n, q_x1)
          k_bnsh_in = Reshape(k_raw, KReshapeA)
          k_bnsh = Transpose <perm=[0,2,1,3]> (k_bnsh_in)
          k_x1, k_x2 = Split <axis=-1> (k_bnsh, HalfSizes)
          k_x2n = Neg(k_x2)
          k_rot_in = Concat <axis=-1> (k_x2n, k_x1)
          q_embed, k_embed = com.microsoft.GemmaRotaryEmbedding (Emb, q_bnsh, q_rot_in, k_bnsh, k_rot_in)
          q_flat_bnsh = Transpose <perm=[0,2,1,3]> (q_embed)
          q_flat = Reshape(q_flat_bnsh, QReshapeB)
          k_flat_bnsh = Transpose <perm=[0,2,1,3]> (k_embed)
          k_flat = Reshape(k_flat_bnsh, KReshapeB)
          ctx, pk, pv = com.microsoft.GroupQueryAttention <num_heads={H}, kv_num_heads={KVH}> (q_flat, k_flat, v, , , SeqLensK, TotalSeq)
          Y = MatMul(ctx, Wout)
        }}
        """
    model = parser.parse_model(
        f"""
        <
          ir_version: 10,
          opset_import: ["": 17, "com.microsoft": 1]
        >
        {body}
        """
    )
    model.graph.initializer.extend(initializer)
    return model, dict(
        K=K,
        H=H,
        KVH=KVH,
        D=D,
        Out=Out,
        Nq=Nq,
        Nkv=Nkv,
        wqkv=wqkv,
        wq=wq,
        wk=wk,
        wv=wv,
        wout=wout,
        emb=emb,
        batch=batch,
        seq=seq,
    )


def test_gqa_packed_qkv_gemma_rope_pruning_matches_decomposed_oracle():
    # `GemmaRotaryEmbedding` itself can't be run end to end here (no usable
    # CPU kernel -- confirmed empirically, see this section's own comment
    # above), so, per this module's own `MatMulNBitsMlp`/`MatMulNBitsQkv`/
    # `PagedAttention` precedent, BOTH the pruned model and an
    # *independently* rebuilt, already-reduced oracle model are decomposed
    # (`_decompose_gemma_rotary_nodes`) into an equivalent, genuinely
    # executable topology before being run through a real `InferenceSession`
    # -- never comparing the pruned model against the full unpruned one.
    K, H, KVH, D, Out = 8, 8, 2, 8, 6
    model, cfg = _gqa_gemma_rope_model(K=K, H=H, KVH=KVH, D=D, Out=Out, seed=205)
    assert len(onnxsim.pruning._find_gqa_chains(model.graph)) == 1

    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)

    node = _gqa_node(pruned)
    num_heads, kv_num_heads = _gqa_attrs(node)

    Nq, Nkv = cfg["Nq"], cfg["Nkv"]
    wqkv = cfg["wqkv"]
    wq, wk, wv = wqkv[:, :Nq], wqkv[:, Nq : Nq + Nkv], wqkv[:, Nq + Nkv :]

    group_size = H // KVH
    keep_count = max(1, KVH - round(KVH * 0.5))
    keep_groups = _oracle_keep_groups(wq, wk, wv, H, KVH, D, keep_count)
    keep_q_heads = _group_q_heads(keep_groups, group_size)
    q_idx, kv_idx = _head_idx(keep_q_heads, D), _head_idx(keep_groups, D)

    assert kv_num_heads == len(keep_groups)
    assert num_heads == len(keep_q_heads)

    # The BNSH `Reshape`s' own `num_heads` entries (index -2) and the
    # reverse-hop `Reshape`s' own flat-width entries (index -1) must both
    # have been rewritten to the new post-pruning counts -- structural
    # confirmation alongside the numeric one below.
    for out_name, expect_heads in (
        ("q_bnsh_in", len(keep_q_heads)),
        ("k_bnsh_in", len(keep_groups)),
    ):
        n = next(n for n in pruned.graph.node if n.output and n.output[0] == out_name)
        dims = onnx.numpy_helper.to_array(
            next(i for i in pruned.graph.initializer if i.name == n.input[1])
        )
        assert int(dims[-2]) == expect_heads
    for out_name, expect_width in (
        ("q_flat", len(keep_q_heads) * D),
        ("k_flat", len(keep_groups) * D),
    ):
        n = next(n for n in pruned.graph.node if n.output and n.output[0] == out_name)
        dims = onnx.numpy_helper.to_array(
            next(i for i in pruned.graph.initializer if i.name == n.input[1])
        )
        assert int(dims[-1]) == expect_width

    oracle, _ = _gqa_gemma_rope_model(
        K=K,
        H=len(keep_q_heads),
        KVH=len(keep_groups),
        D=D,
        Out=Out,
        seed=205,
        packed=False,
        wq=wq[:, q_idx],
        wk=wk[:, kv_idx],
        wv=wv[:, kv_idx],
        wout=cfg["wout"][q_idx, :],
        emb=cfg["emb"],
    )

    pruned_decomposed = _decompose_gemma_rotary_nodes(pruned)
    oracle_decomposed = _decompose_gemma_rotary_nodes(oracle)

    rng = np.random.default_rng(seed=1205)
    x = rng.standard_normal((cfg["batch"], cfg["seq"], K)).astype(np.float32)
    (y_pruned,) = _run(pruned_decomposed, {"X": x})
    (y_oracle,) = _run(oracle_decomposed, {"X": x})
    np.testing.assert_allclose(y_pruned, y_oracle, rtol=1e-5, atol=1e-5)


def test_analyze_attention_head_pruning_gqa_gemma_rope_matches_real_call():
    # Dry-run (`analyze_pruning_sensitivity`) vs. real-call parity for the
    # `GemmaRotaryEmbedding` hop, mirroring
    # `test_analyze_attention_head_pruning_gqa_mrope_matches_real_call`.
    K, H, KVH, D, Out = 8, 8, 2, 8, 6
    model, cfg = _gqa_gemma_rope_model(K=K, H=H, KVH=KVH, D=D, Out=Out, seed=206)
    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_attention_head_pruning, sparsity=0.5
    )
    assert len(report.layers) == 1
    layer = report.layers[0]
    assert layer.family == "attention_gqa_group"
    assert layer.total == KVH

    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    node = _gqa_node(pruned)
    _, kv_num_heads = _gqa_attrs(node)
    assert kv_num_heads == KVH - layer.would_drop


