def _bnb4_chain_norm_model(
    K, N1, N2, block_size, quant_type, W1, W2, norm_op, gamma, beta=None
):
    """Like :func:`_bnb4_chain_model`, but with a mid-chain norm node
    (`Gamma`[, `Beta`]) standing in for the plain activation -- the
    Linear -> LayerNorm/RMSNorm -> Linear shape this section's own norm-hop
    fix now recognizes.
    """
    B1, absmax1 = _bnb4_quantize(W1, quant_type, block_size)
    if beta is None:
        norm_call = f"{norm_op}<axis=-1>(h1, Gamma)"
        initializer = [
            onnx.numpy_helper.from_array(B1, name="B1"),
            onnx.numpy_helper.from_array(absmax1, name="absmax1"),
            _f32(W2, "W2"),
            _f32(gamma, "Gamma"),
        ]
    else:
        norm_call = f"{norm_op}<axis=-1>(h1, Gamma, Beta)"
        initializer = [
            onnx.numpy_helper.from_array(B1, name="B1"),
            onnx.numpy_helper.from_array(absmax1, name="absmax1"),
            _f32(W2, "W2"),
            _f32(gamma, "Gamma"),
            _f32(beta, "Beta"),
        ]
    model = _model(
        f"""
        g (float[3,{K}] A) => (float[3,{N2}] Y)
        {{
          h1 = com.microsoft.MatMulBnb4 <K={K}, N={N1}, block_size={block_size}, quant_type={quant_type}> (A, B1, absmax1)
          h1n = {norm_call}
          Y = MatMul(h1n, W2)
        }}
        """,
        initializer=initializer,
        opset=21,
    )
    model.opset_import.append(onnx.helper.make_opsetid("com.microsoft", 1))
    return model


def test_matmul_bnb4_layer_norm_pass_through_is_matched_and_prunes():
    # Before this section's own norm-hop fix (mirroring the just-merged
    # DynamicQuantizeMatMul/MatMulNBits fix), _find_matmul_bnb4_chains
    # returned zero chains for this shape.
    K, N1, N2, block_size = 64, 32, 8, 16
    quant_type = 1  # NF4
    rng = np.random.default_rng(2030)
    W1 = rng.uniform(-1, 1, size=(K, N1)).astype(np.float32)
    W1 = W1 * np.linspace(0.1, 3.0, N1, dtype=np.float32)[None, :]
    W2 = rng.uniform(-1, 1, size=(N1, N2)).astype(np.float32)
    gamma = (rng.standard_normal(N1) * 0.5 + 1.0).astype(np.float32)
    beta = (rng.standard_normal(N1) * 0.1).astype(np.float32)

    model = _bnb4_chain_norm_model(
        K, N1, N2, block_size, quant_type, W1, W2, "LayerNormalization", gamma, beta
    )
    onnx.checker.check_model(model)

    chains = onnxsim.pruning._find_matmul_bnb4_chains(model.graph)
    assert len(chains) == 1
    assert chains[0].n_channels == N1

    pruned = onnxsim.apply_structured_pruning_matmul_bnb4(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    mm1 = next(n for n in pruned.graph.node if n.op_type == "MatMulBnb4")
    assert {a.name: a.i for a in mm1.attribute}["N"] == 16

    col_norms = np.linalg.norm(W1, axis=0)
    keep = np.sort(np.argsort(-col_norms, kind="stable")[:16])
    inits = {t.name: t for t in pruned.graph.initializer}
    assert list(inits["Gamma"].dims) == [16]
    assert list(inits["Beta"].dims) == [16]
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["Gamma"]), gamma[keep]
    )
    np.testing.assert_array_equal(onnx.numpy_helper.to_array(inits["Beta"]), beta[keep])

    ref_model = _bnb4_chain_norm_model(
        K,
        len(keep),
        N2,
        block_size,
        quant_type,
        W1[:, keep],
        W2[keep, :],
        "LayerNormalization",
        gamma[keep],
        beta[keep],
    )
    onnx.checker.check_model(ref_model)

    A = rng.uniform(-1, 1, size=(3, K)).astype(np.float32)
    pruned_out = _run(pruned, {"A": A})[0]
    ref_out = _run(ref_model, {"A": A})[0]
    # Mirrors test_matmul_bnb4_pruning_producer_matches_independently_
    # requantized_subset's own identical byte-identity invariant: a bnb4
    # producer-row-slice is a plain byte-range copy of the original
    # quantizer's own output, so this composes byte-identically with an
    # independently re-quantized/re-sliced reference too.
    np.testing.assert_array_equal(pruned_out, ref_out)


def test_matmul_bnb4_rms_norm_pass_through_is_matched_and_prunes():
    # com.microsoft::SimplifiedLayerNormalization -- no `beta`/`Beta` input
    # at all, unlike LayerNormalization above; onnx.checker's own schema
    # database doesn't know this op under the default domain at all, so
    # check_model is skipped for the unpruned model -- onnxruntime itself
    # still runs it fine, which the byte-identity comparison below actually
    # exercises.
    K, N1, N2, block_size = 64, 32, 8, 16
    quant_type = 0  # FP4
    rng = np.random.default_rng(2040)
    W1 = rng.uniform(-1, 1, size=(K, N1)).astype(np.float32)
    W1 = W1 * np.linspace(0.1, 3.0, N1, dtype=np.float32)[None, :]
    W2 = rng.uniform(-1, 1, size=(N1, N2)).astype(np.float32)
    gamma = (rng.standard_normal(N1) * 0.5 + 1.0).astype(np.float32)

    model = _bnb4_chain_norm_model(
        K, N1, N2, block_size, quant_type, W1, W2, "SimplifiedLayerNormalization", gamma
    )

    chains = onnxsim.pruning._find_matmul_bnb4_chains(model.graph)
    assert len(chains) == 1
    assert chains[0].n_channels == N1

    pruned = onnxsim.apply_structured_pruning_matmul_bnb4(model, sparsity=0.5)

    col_norms = np.linalg.norm(W1, axis=0)
    keep = np.sort(np.argsort(-col_norms, kind="stable")[:16])
    inits = {t.name: t for t in pruned.graph.initializer}
    assert list(inits["Gamma"].dims) == [16]
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["Gamma"]), gamma[keep]
    )

    ref_model = _bnb4_chain_norm_model(
        K,
        len(keep),
        N2,
        block_size,
        quant_type,
        W1[:, keep],
        W2[keep, :],
        "SimplifiedLayerNormalization",
        gamma[keep],
    )

    A = rng.uniform(-1, 1, size=(3, K)).astype(np.float32)
    pruned_out = _run(pruned, {"A": A})[0]
    ref_out = _run(ref_model, {"A": A})[0]
    np.testing.assert_array_equal(pruned_out, ref_out)


# --- MatMulBnb4: mid-chain separate trailing bias Add pass-through ---------
#
# ``MatMulBnb4``'s own live 3-input schema (`A, B, absmax`) has no bias slot
# at all -- unlike ``MatMulNBits``'s own optional 6th input -- so a separate
# trailing `Add` node is the ONLY way a biased ``MatMulBnb4`` layer is EVER
# representable, and a real
# ``onnxruntime.quantization.matmul_bnb4_quantizer.MatMulBnb4Quantizer``
# round trip always emits it this way. `_walk_to_matmul_bnb4_consumer`
# previously recognized only `_UNARY_PASS_THROUGH` activations and
# `_NORM_PASS_THROUGH_OPS` as mid-chain hops, never this per-channel
# bias `Add` (`_BINARY_CHANNEL_OPS`), so a real quantized+biased MatMulBnb4
# layer was silently left completely unpruned.


def _bnb4_chain_bias_add_model(
    K, N1, N2, block_size, quant_type, W1, W2, bias1, activation="Relu"
):
    """Like :func:`_bnb4_chain_model`, but with a separate trailing
    `Add(Bias1)` node between ``MatMulBnb4`` and the following activation --
    the only representation a biased ``MatMulBnb4`` layer can ever take.
    """
    B1, absmax1 = _bnb4_quantize(W1, quant_type, block_size)
    model = _model(
        f"""
        g (float[3,{K}] A) => (float[3,{N2}] Y)
        {{
          h1 = com.microsoft.MatMulBnb4 <K={K}, N={N1}, block_size={block_size}, quant_type={quant_type}> (A, B1, absmax1)
          h1b = Add(h1, Bias1)
          h1_act = {activation}(h1b)
          Y = MatMul(h1_act, W2)
        }}
        """,
        initializer=[
            onnx.numpy_helper.from_array(B1, name="B1"),
            onnx.numpy_helper.from_array(absmax1, name="absmax1"),
            _f32(W2, "W2"),
            _f32(bias1, "Bias1"),
        ],
        opset=21,
    )
    model.opset_import.append(onnx.helper.make_opsetid("com.microsoft", 1))
    return model


def test_matmul_bnb4_separate_trailing_bias_add_is_matched_and_prunes():
    K, N1, N2, block_size = 64, 32, 8, 16
    quant_type = 1  # NF4
    rng = np.random.default_rng(2050)
    W1 = rng.uniform(-1, 1, size=(K, N1)).astype(np.float32)
    W1 = W1 * np.linspace(0.1, 3.0, N1, dtype=np.float32)[None, :]
    W2 = rng.uniform(-1, 1, size=(N1, N2)).astype(np.float32)
    bias1 = (rng.standard_normal(N1) * 0.05).astype(np.float32)

    model = _bnb4_chain_bias_add_model(K, N1, N2, block_size, quant_type, W1, W2, bias1)
    onnx.checker.check_model(model)

    # Before this section's own fix, this returned 0 chains.
    chains = onnxsim.pruning._find_matmul_bnb4_chains(model.graph)
    assert len(chains) == 1
    assert chains[0].n_channels == N1

    pruned = onnxsim.apply_structured_pruning_matmul_bnb4(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    mm1 = next(n for n in pruned.graph.node if n.op_type == "MatMulBnb4")
    assert {a.name: a.i for a in mm1.attribute}["N"] == 16

    col_norms = np.linalg.norm(W1, axis=0)
    keep = np.sort(np.argsort(-col_norms, kind="stable")[:16])
    inits = {t.name: t for t in pruned.graph.initializer}
    assert list(inits["Bias1"].dims) == [16]
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["Bias1"]), bias1[keep]
    )

    ref_model = _bnb4_chain_bias_add_model(
        K, len(keep), N2, block_size, quant_type, W1[:, keep], W2[keep, :], bias1[keep]
    )
    onnx.checker.check_model(ref_model)

    A = rng.uniform(-1, 1, size=(3, K)).astype(np.float32)
    pruned_out = _run(pruned, {"A": A})[0]
    ref_out = _run(ref_model, {"A": A})[0]
    np.testing.assert_array_equal(pruned_out, ref_out)


def test_matmul_bnb4_separate_trailing_bias_add_declines_shared_bias():
    # The same trailing `Bias1` tensor read by two INDEPENDENT MatMulBnb4
    # producer chains' own `Add` nodes -- slicing it to fit one chain's own
    # keep-set would leave the other (declined, left untouched) chain's own
    # consumer fed a wrong-sized tensor. Mirrors
    # `test_matmul_bnb4_pruning_declines_shared_weight`'s own identical
    # tied-tensor concern, but for a mid-chain hop's own constant rather
    # than a producer's own weight -- exercises the `consumers_of` check
    # this fix adds right alongside the new `_BINARY_CHANNEL_OPS` branch.
    K, N1, N2, block_size = 64, 32, 8, 16
    quant_type = 1
    rng = np.random.default_rng(2060)
    W1 = rng.uniform(-1, 1, size=(K, N1)).astype(np.float32)
    W2 = rng.uniform(-1, 1, size=(N1, N2)).astype(np.float32)
    bias = rng.standard_normal(N1).astype(np.float32)
    model = _bnb4_chain_bias_add_model(K, N1, N2, block_size, quant_type, W1, W2, bias)

    # A second, wholly independent MatMulBnb4 producer/consumer chain whose
    # own trailing bias `Add` reuses the exact same `Bias1` initializer.
    K2, N3, N4 = 48, 32, 6
    W3 = rng.uniform(-1, 1, size=(K2, N3)).astype(np.float32)
    W4 = rng.uniform(-1, 1, size=(N3, N4)).astype(np.float32)
    model2 = _bnb4_chain_bias_add_model(
        K2, N3, N4, block_size, quant_type, W3, W4, bias
    )
    for n in model2.graph.node:
        n.name += "_b"
        for i in range(len(n.input)):
            if n.input[i] and n.input[i] != "Bias1":
                n.input[i] += "_b"
        for i in range(len(n.output)):
            n.output[i] += "_b"
    for t in model2.graph.initializer:
        if t.name != "Bias1":
            t.name += "_b"
    model2.graph.input[0].name += "_b"
    model2.graph.output[0].name += "_b"

    model.graph.node.extend(model2.graph.node)
    model.graph.initializer.extend(
        t for t in model2.graph.initializer if t.name != "Bias1"
    )
    model.graph.input.extend(model2.graph.input)
    model.graph.output.extend(model2.graph.output)
    onnx.checker.check_model(model)

    chains = onnxsim.pruning._find_matmul_bnb4_chains(model.graph)
    assert len(chains) == 0  # both declined -- the shared Bias1 blocks both

    pruned = onnxsim.apply_structured_pruning_matmul_bnb4(model, sparsity=0.5)
    assert pruned.SerializeToString() == model.SerializeToString()


@pytest.mark.parametrize("quant_type", [0, 1])
def test_matmul_bnb4_dequantized_matches_real_inference_session(quant_type):
    # Independently re-derives this section's own top-comment round-trip as
    # an executable check: :func:`onnxsim.pruning._matmul_bnb4_dequantized`
    # (the importance-ranking helper, never written back to the graph) must
    # agree with a real MatMulBnb4 kernel's own dequantized weight, read
    # back via the identity-matrix trick (`A = eye(K)`, `transB=1` default
    # recovers dequant_B^T == the original [K, N] weight).
    K, N, block_size = 64, 24, 16
    rng = np.random.default_rng(55)
    W = rng.uniform(-1, 1, size=(K, N)).astype(np.float32)
    B, absmax = _bnb4_quantize(W, quant_type, block_size)

    model = _model(
        f"""
        g (float[{K},{K}] A) => (float[{K},{N}] Y)
        {{
          Y = com.microsoft.MatMulBnb4 <K={K}, N={N}, block_size={block_size}, quant_type={quant_type}> (A, B, absmax)
        }}
        """,
        initializer=[
            onnx.numpy_helper.from_array(B, name="B"),
            onnx.numpy_helper.from_array(absmax, name="absmax"),
        ],
        opset=21,
    )
    model.opset_import.append(onnx.helper.make_opsetid("com.microsoft", 1))

    A = np.eye(K, dtype=np.float32)
    dequant_ort = _run(model, {"A": A})[0]  # [K, N] -- original weight orientation

    initializer_map = {t.name: t for t in model.graph.initializer}
    consumers_of = onnxsim.pruning._consumers_of(model.graph)
    w = onnxsim.pruning._match_matmul_bnb4_producer(
        model.graph.node[0], initializer_map, consumers_of
    )
    assert w is not None
    dequant_mine = onnxsim.pruning._matmul_bnb4_dequantized(w)  # [N, K]

    np.testing.assert_allclose(dequant_mine.T, dequant_ort, atol=1e-6)


# --- apply_structured_pruning_matmul_bnb4: gated (SwiGLU/GeGLU) FFN pair ---
#
# The ``MatMulBnb4`` analogue of the ``MatMulNBits`` section's own
# ``test_matmul_nbits_pruning_gated_ffn_matches_oracle`` and friends (see
# ``onnxsim/pruning.py``'s own ``_find_matmul_bnb4_gated_chains``): a
# gate_proj/up_proj pair -- each independently either a real, quantizer-
# produced ``MatMulBnb4`` node or a plain-float peer -- combined by an
# elementwise ``Mul`` (gate_proj through one activation first), feeding a
# plain-float down_proj consumer. Unlike the ``MatMulNBits`` gated case,
# down_proj is always plain-float here (a ``MatMulBnb4`` node is never
# matched as a chain's CONSUMER at all -- see this module's own section
# comment), so there is no block-alignment question on the consumer side.


def _bnb4_gated_model(
    K, H, Out, block_size, quant_type, W_gate, W_up, W_down, gate_activation="Sigmoid"
):
    """Builds ``X -> gate=MatMulBnb4(Bg) -[gate_activation]-> gate_act,
    up=MatMulBnb4(Bu) -> Mul(gate_act, up) -> Y=MatMul(W_down)`` -- the real
    ``com.microsoft::MatMulBnb4`` gated (SwiGLU/GeGLU) FFN pair, both
    producers quantized via the REAL
    ``onnxruntime.quantization.matmul_bnb4_quantizer.MatMulBnb4Quantizer``
    (:func:`_bnb4_quantize`), feeding a plain-float down_proj consumer.
    """
    Bg, absmax_g = _bnb4_quantize(W_gate, quant_type, block_size)
    Bu, absmax_u = _bnb4_quantize(W_up, quant_type, block_size)
    model = _model(
        f"""
        g (float[3,{K}] X) => (float[3,{Out}] Y)
        {{
          gate = com.microsoft.MatMulBnb4 <K={K}, N={H}, block_size={block_size}, quant_type={quant_type}> (X, Bg, absmax_g)
          gate_act = {gate_activation}(gate)
          up = com.microsoft.MatMulBnb4 <K={K}, N={H}, block_size={block_size}, quant_type={quant_type}> (X, Bu, absmax_u)
          h = Mul(gate_act, up)
          Y = MatMul(h, W_down)
        }}
        """,
        initializer=[
            onnx.numpy_helper.from_array(Bg, name="Bg"),
            onnx.numpy_helper.from_array(absmax_g, name="absmax_g"),
            onnx.numpy_helper.from_array(Bu, name="Bu"),
            onnx.numpy_helper.from_array(absmax_u, name="absmax_u"),
            _f32(W_down, "W_down"),
        ],
        opset=21,
    )
    model.opset_import.append(onnx.helper.make_opsetid("com.microsoft", 1))
    return model


def test_matmul_bnb4_pruning_gated_ffn_matches_oracle():
    # Both gate_proj/up_proj are real MatMulBnb4 nodes -- the exact topology
    # the confirmed gap's repro script built (gate -> Sigmoid -> Mul(with
    # up) -> plain-float down_proj), quantized via the real
    # MatMulBnb4Quantizer. Front 16-of-32 channels scaled up so the combined
    # (root-sum-square) L2 importance keep-set is unambiguous.
    K, H, Out, block_size = 64, 32, 8, 16
    quant_type = 1  # NF4
    rng = np.random.default_rng(300)
    W_gate = (rng.standard_normal((K, H)) * 0.2).astype(np.float32)
    W_gate[:, :16] *= 10.0
    W_up = (rng.standard_normal((K, H)) * 0.2).astype(np.float32)
    W_up[:, :16] *= 10.0
    W_down = (rng.standard_normal((H, Out)) * 0.2).astype(np.float32)

    model = _bnb4_gated_model(K, H, Out, block_size, quant_type, W_gate, W_up, W_down)
    onnx.checker.check_model(model)

    chains = onnxsim.pruning._find_matmul_bnb4_gated_chains(model.graph)
    assert len(chains) == 1
    # The plain single-producer finder must never also match either half of
    # a gated pair (mirrors the MatMulNBits section's own identical
    # non-overlap invariant).
    assert onnxsim.pruning._find_matmul_bnb4_chains(model.graph) == []

    pruned = onnxsim.apply_structured_pruning_matmul_bnb4(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    keep = np.arange(16)
    mm_gate = next(n for n in pruned.graph.node if n.output[0] == "gate")
    mm_up = next(n for n in pruned.graph.node if n.output[0] == "up")
    assert next(a.i for a in mm_gate.attribute if a.name == "N") == 16
    assert next(a.i for a in mm_up.attribute if a.name == "N") == 16
    inits = {t.name: t for t in pruned.graph.initializer}
    assert list(inits["W_down"].dims) == [16, Out]

    # "Slice, don't recompute": each pruned producer's own packed bytes must
    # be byte-identical to independently re-quantizing that row subset
    # directly (the same invariant the non-gated section's own
    # ``test_matmul_bnb4_pruning_producer_bytes_are_byte_identical_to_requantized_subset``
    # establishes).
    Bg_ref, absmax_g_ref = _bnb4_quantize(W_gate[:, keep], quant_type, block_size)
    Bu_ref, absmax_u_ref = _bnb4_quantize(W_up[:, keep], quant_type, block_size)
    np.testing.assert_array_equal(onnx.numpy_helper.to_array(inits["Bg"]), Bg_ref)
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["absmax_g"]), absmax_g_ref
    )
    np.testing.assert_array_equal(onnx.numpy_helper.to_array(inits["Bu"]), Bu_ref)
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["absmax_u"]), absmax_u_ref
    )

    # End-to-end: the pruned model's real output must match a reference
    # built by independently re-quantizing/re-slicing each side directly --
    # exact byte-level equality, not float tolerance (mirrors the non-gated
    # section's own identical-strength check).
    ref_model = _bnb4_gated_model(
        K,
        len(keep),
        Out,
        block_size,
        quant_type,
        W_gate[:, keep],
        W_up[:, keep],
        W_down[keep, :],
    )
    X = rng.uniform(-1, 1, size=(3, K)).astype(np.float32)
    pruned_out = _run(pruned, {"X": X})[0]
    ref_out = _run(ref_model, {"X": X})[0]
    np.testing.assert_array_equal(pruned_out, ref_out)


def test_matmul_bnb4_pruning_gated_ffn_mixed_plain_float_peer_matches_oracle():
    # gate_proj is a real MatMulBnb4 node, up_proj is a plain-float peer --
    # the "at least one side MatMulBnb4" mixed case
    # _find_matmul_bnb4_gated_chains must also recognize (mirrors
    # MatMulNBits's own identical either/or gated-producer flexibility).
    K, H, Out, block_size = 64, 32, 8, 16
    quant_type = 0  # FP4
    rng = np.random.default_rng(302)
    W_gate = (rng.standard_normal((K, H)) * 0.2).astype(np.float32)
    W_gate[:, :16] *= 10.0
    W_up = (rng.standard_normal((K, H)) * 0.2).astype(np.float32)
    W_up[:, :16] *= 10.0
    W_down = (rng.standard_normal((H, Out)) * 0.2).astype(np.float32)

    Bg, absmax_g = _bnb4_quantize(W_gate, quant_type, block_size)
    model = _model(
        f"""
        g (float[3,{K}] X) => (float[3,{Out}] Y)
        {{
          gate = com.microsoft.MatMulBnb4 <K={K}, N={H}, block_size={block_size}, quant_type={quant_type}> (X, Bg, absmax_g)
          gate_act = Sigmoid(gate)
          up = MatMul(X, W_up)
          h = Mul(gate_act, up)
          Y = MatMul(h, W_down)
        }}
        """,
        initializer=[
            onnx.numpy_helper.from_array(Bg, name="Bg"),
            onnx.numpy_helper.from_array(absmax_g, name="absmax_g"),
            _f32(W_up, "W_up"),
            _f32(W_down, "W_down"),
        ],
        opset=21,
    )
    model.opset_import.append(onnx.helper.make_opsetid("com.microsoft", 1))
    onnx.checker.check_model(model)

    chains = onnxsim.pruning._find_matmul_bnb4_gated_chains(model.graph)
    assert len(chains) == 1

    pruned = onnxsim.apply_structured_pruning_matmul_bnb4(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    keep = np.arange(16)
    mm_gate = next(n for n in pruned.graph.node if n.output[0] == "gate")
    assert next(a.i for a in mm_gate.attribute if a.name == "N") == 16
    inits = {t.name: t for t in pruned.graph.initializer}
    assert list(inits["W_up"].dims) == [K, 16]
    assert list(inits["W_down"].dims) == [16, Out]

    Bg_ref, absmax_g_ref = _bnb4_quantize(W_gate[:, keep], quant_type, block_size)
    np.testing.assert_array_equal(onnx.numpy_helper.to_array(inits["Bg"]), Bg_ref)
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["absmax_g"]), absmax_g_ref
    )
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["W_up"]), W_up[:, keep]
    )
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["W_down"]), W_down[keep, :]
    )


def test_matmul_bnb4_pruning_gated_ffn_declines_shared_weight():
    # gate_proj/up_proj sharing the identical B/absmax tensor pair -- the
    # matcher itself (_match_matmul_bnb4_producer's own shared/tied-tensor
    # bar) must decline BOTH nodes as producers, so no gated chain is found
    # at all and the whole model is left byte-unchanged. Mirrors the
    # non-gated section's own ``test_matmul_bnb4_pruning_declines_shared_weight``.
    K, H, Out, block_size = 64, 32, 8, 16
    quant_type = 1
    rng = np.random.default_rng(301)
    W_gate = rng.uniform(-1, 1, size=(K, H)).astype(np.float32)
    W_down = rng.uniform(-1, 1, size=(H, Out)).astype(np.float32)
    Bg, absmax_g = _bnb4_quantize(W_gate, quant_type, block_size)

    model = _model(
        f"""
        g (float[3,{K}] X) => (float[3,{Out}] Y)
        {{
          gate = com.microsoft.MatMulBnb4 <K={K}, N={H}, block_size={block_size}, quant_type={quant_type}> (X, Bg, absmax_g)
          gate_act = Sigmoid(gate)
          up = com.microsoft.MatMulBnb4 <K={K}, N={H}, block_size={block_size}, quant_type={quant_type}> (X, Bg, absmax_g)
          h = Mul(gate_act, up)
          Y = MatMul(h, W_down)
        }}
        """,
        initializer=[
            onnx.numpy_helper.from_array(Bg, name="Bg"),
            onnx.numpy_helper.from_array(absmax_g, name="absmax_g"),
            _f32(W_down, "W_down"),
        ],
        opset=21,
    )
    model.opset_import.append(onnx.helper.make_opsetid("com.microsoft", 1))
    onnx.checker.check_model(model)

    assert onnxsim.pruning._find_matmul_bnb4_gated_chains(model.graph) == []

    pruned = onnxsim.apply_structured_pruning_matmul_bnb4(model, sparsity=0.5)
    assert pruned.SerializeToString() == model.SerializeToString()


def test_analyze_structured_pruning_matmul_bnb4_matches_real_call():
    K, N1, N2, block_size = 64, 32, 8, 16
    rng = np.random.default_rng(21)
    W1 = rng.uniform(-1, 1, size=(K, N1)).astype(np.float32)
    W1 = W1 * np.linspace(0.1, 3.0, N1, dtype=np.float32)[None, :]
    W2 = rng.uniform(-1, 1, size=(N1, N2)).astype(np.float32)
    model = _bnb4_chain_model(K, N1, N2, block_size, 1, W1, W2)

    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_structured_pruning_matmul_bnb4, sparsity=0.5
    )
    assert report.not_eligible == []
    assert len(report.layers) == 1
    layer = report.layers[0]
    assert layer.family == "matmul_bnb4"
    assert layer.total == N1
    assert layer.would_drop == 16

    pruned = onnxsim.apply_structured_pruning_matmul_bnb4(model, sparsity=0.5)
    mm1 = next(n for n in pruned.graph.node if n.op_type == "MatMulBnb4")
    assert {a.name: a.i for a in mm1.attribute}["N"] == N1 - layer.would_drop


def test_analyze_structured_pruning_matmul_bnb4_not_eligible_lists_unmatched_nodes():
    # K=24 not a multiple of block_size=16 -- never enters
    # _find_matmul_bnb4_chains at all, so it's reported via not_eligible,
    # not a would_drop=0 layer row.
    K, N1, N2, block_size = 24, 16, 8, 16
    rng = np.random.default_rng(22)
    W1 = rng.uniform(-1, 1, size=(K, N1)).astype(np.float32)
    W2 = rng.uniform(-1, 1, size=(N1, N2)).astype(np.float32)
    model = _bnb4_chain_model(K, N1, N2, block_size, 1, W1, W2)

    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_structured_pruning_matmul_bnb4, sparsity=0.5
    )
    assert report.layers == []
    assert len(report.not_eligible) == 1
    assert "MatMulBnb4" in report.not_eligible[0]


# --- MatMulBlockQuantizedFp4Weight/MatMulBlockQuantizedFp8Weight test helpers


def _e4m3_view_u8(f8_array):
    """Views a ``ml_dtypes.float8_e4m3fn`` array as its own raw ``uint8``
    bytes (same itemsize, a plain reinterpret, no conversion) -- used to
    build a ``weight_scale`` tensor for ``MatMulBlockQuantizedFp4Weight``,
    which the live schema types plain ``uint8`` in-graph even though its
    bytes are E4M3 codes (see onnxsim/pruning.py's own section comment).
    """
    return f8_array.view(np.uint8)


def _fp8bw_quantize(w, block_size):
    """Independent (onnxsim-code-free) per-block E4M3 quantizer for one
    ``MatMulBlockQuantizedFp8Weight``-style ``[N, K]`` float weight. Scale
    chosen as ``amax(block) / 6.0`` purely so the quantized codes are a
    plausible representation of `w` for these tests -- there is no real
    kernel or reference quantizer to match here (see onnxsim/pruning.py's
    own section comment: no CPU kernel exists for this op at all). Returns
    ``(b_f8 [N, K] ml_dtypes.float8_e4m3fn, b_scale [N, K // block_size]
    float32, dequant [N, K] float64)``.
    """
    n, k = w.shape
    kb = k // block_size
    w_blocks = w.reshape(n, kb, block_size).astype(np.float64)
    amax = np.maximum(np.abs(w_blocks).max(axis=-1), 1e-8)
    scale = (amax / 6.0).astype(np.float32)
    scale_f64 = scale.astype(np.float64)
    scale_expanded = np.repeat(scale_f64, block_size, axis=-1).reshape(
        n, kb, block_size
    )
    b_f8 = (w_blocks / scale_expanded).astype(ml_dtypes.float8_e4m3fn)
    dequant = b_f8.astype(np.float64) * scale_expanded
    return b_f8.reshape(n, k), scale, dequant.reshape(n, k)


def _fp8bw_node(
    name, a_input, out_name, b_name, scale_name, a_scale_name, bias_name, block_size
):
    inputs = [a_input, b_name, scale_name, a_scale_name or "", bias_name or ""]
    while inputs and not inputs[-1]:
        inputs.pop()
    return onnx.helper.make_node(
        "MatMulBlockQuantizedFp8Weight",
        inputs=inputs,
        outputs=[out_name],
        domain="com.microsoft",
        name=name,
        block_size=block_size,
    )


def _fp8bw_model(w, block_size=8, bias=None):
    """Builds ``A -> MatMulBlockQuantizedFp8Weight -> Y`` (single node).
    Returns ``(model, info)`` where `info` carries `b_f8`/`b_scale`/
    `dequant` (the independently-quantized artifacts, unpacked) needed to
    hand-build an oracle.
    """
    n, k = w.shape
    b_f8, scale, dequant = _fp8bw_quantize(w, block_size)
    inits = [
        onnx.numpy_helper.from_array(b_f8, name="B"),
        _f32(scale, "S"),
    ]
    bias_name = None
    if bias is not None:
        inits.append(_f16(bias, "Bias"))
        bias_name = "Bias"
    node = _fp8bw_node("mm", "A", "Y", "B", "S", None, bias_name, block_size)
    graph = onnx.helper.make_graph(
        [node],
        "g",
        [onnx.helper.make_tensor_value_info("A", onnx.TensorProto.FLOAT16, [2, k])],
        [onnx.helper.make_tensor_value_info("Y", onnx.TensorProto.FLOAT16, [2, n])],
        initializer=inits,
    )
    model = onnx.helper.make_model(
        graph,
        opset_imports=[
            onnx.helper.make_opsetid("", 21),
            onnx.helper.make_opsetid("com.microsoft", 1),
        ],
    )
    model.ir_version = 10
    return model, {"b_f8": b_f8, "b_scale": scale, "dequant": dequant}


def _fp8bw_chain_model(N1, K1, N2, block_size, w1, w2):
    """Builds ``A -> MatMulBlockQuantizedFp8Weight(mm1) -> Relu ->
    MatMulBlockQuantizedFp8Weight(mm2) -> Y``, both nodes real.
    """
    assert N1 % block_size == 0  # else the consumer would never match
    b1_f8, s1, dq1 = _fp8bw_quantize(w1, block_size)
    b2_f8, s2, dq2 = _fp8bw_quantize(w2, block_size)
    node1 = _fp8bw_node("mm1", "A", "T", "B1", "S1", None, None, block_size)
    relu = onnx.helper.make_node("Relu", ["T"], ["R"])
    node2 = _fp8bw_node("mm2", "R", "Y", "B2", "S2", None, None, block_size)
    graph = onnx.helper.make_graph(
        [node1, relu, node2],
        "g",
        [onnx.helper.make_tensor_value_info("A", onnx.TensorProto.FLOAT16, [2, K1])],
        [onnx.helper.make_tensor_value_info("Y", onnx.TensorProto.FLOAT16, [2, N2])],
        initializer=[
            onnx.numpy_helper.from_array(b1_f8, name="B1"),
            _f32(s1, "S1"),
            onnx.numpy_helper.from_array(b2_f8, name="B2"),
            _f32(s2, "S2"),
        ],
    )
    model = onnx.helper.make_model(
        graph,
        opset_imports=[
            onnx.helper.make_opsetid("", 21),
            onnx.helper.make_opsetid("com.microsoft", 1),
        ],
    )
    model.ir_version = 10
    return model, {"dequant1": dq1, "dequant2": dq2}


def _fp4bw_node(
    name,
    a_input,
    out_name,
    b_name,
    ws_name,
    ws2_name,
    input_scale_name,
    bias_name,
    block_size,
):
    inputs = [
        a_input,
        b_name,
        ws_name,
        ws2_name,
        input_scale_name or "",
        bias_name or "",
    ]
    while inputs and not inputs[-1]:
        inputs.pop()
    return onnx.helper.make_node(
        "MatMulBlockQuantizedFp4Weight",
        inputs=inputs,
        outputs=[out_name],
        domain="com.microsoft",
        name=name,
        block_size=block_size,
    )


def _fp4bw_model(w, global_scale, block_size=8, bias=None):
    """Builds ``A -> MatMulBlockQuantizedFp4Weight -> Y`` (single node),
    reusing :func:`_qmoe_nvfp4_quantize_channel_blockwise` (this file's own
    QMoE nvfp4 test helper -- identical NVFP4 packing, just no expert axis)
    to build `B`/`weight_scale`. Returns ``(model, info)``.
    """
    n, k = w.shape
    packed, block_scale_f8, dequant = _qmoe_nvfp4_quantize_channel_blockwise(
        w, global_scale, block_size
    )
    inits = [
        onnx.numpy_helper.from_array(packed, name="B"),
        _u8(_e4m3_view_u8(block_scale_f8), "WS"),
        _f32(np.array([global_scale], dtype=np.float32), "WS2"),
    ]
    bias_name = None
    if bias is not None:
        inits.append(_f16(bias, "Bias"))
        bias_name = "Bias"
    node = _fp4bw_node("mm", "A", "Y", "B", "WS", "WS2", None, bias_name, block_size)
    graph = onnx.helper.make_graph(
        [node],
        "g",
        [onnx.helper.make_tensor_value_info("A", onnx.TensorProto.FLOAT16, [2, k])],
        [onnx.helper.make_tensor_value_info("Y", onnx.TensorProto.FLOAT16, [2, n])],
        initializer=inits,
    )
    model = onnx.helper.make_model(
        graph,
        opset_imports=[
            onnx.helper.make_opsetid("", 21),
            onnx.helper.make_opsetid("com.microsoft", 1),
        ],
    )
    model.ir_version = 10
    return model, {
        "packed": packed,
        "block_scale_f8": block_scale_f8,
        "dequant": dequant,
    }


def _fp4bw_chain_model(N1, K1, N2, block_size, w1, gs1, w2, gs2):
    """``Fp4Weight`` analogue of :func:`_fp8bw_chain_model`."""
    assert N1 % block_size == 0
    p1, bs1, dq1 = _qmoe_nvfp4_quantize_channel_blockwise(w1, gs1, block_size)
    p2, bs2, dq2 = _qmoe_nvfp4_quantize_channel_blockwise(w2, gs2, block_size)
    node1 = _fp4bw_node("mm1", "A", "T", "B1", "WS1", "WS21", None, None, block_size)
    relu = onnx.helper.make_node("Relu", ["T"], ["R"])
    node2 = _fp4bw_node("mm2", "R", "Y", "B2", "WS2", "WS22", None, None, block_size)
    graph = onnx.helper.make_graph(
        [node1, relu, node2],
        "g",
        [onnx.helper.make_tensor_value_info("A", onnx.TensorProto.FLOAT16, [2, K1])],
        [onnx.helper.make_tensor_value_info("Y", onnx.TensorProto.FLOAT16, [2, N2])],
        initializer=[
            onnx.numpy_helper.from_array(p1, name="B1"),
            _u8(_e4m3_view_u8(bs1), "WS1"),
            _f32(np.array([gs1], dtype=np.float32), "WS21"),
            onnx.numpy_helper.from_array(p2, name="B2"),
            _u8(_e4m3_view_u8(bs2), "WS2"),
            _f32(np.array([gs2], dtype=np.float32), "WS22"),
        ],
    )
    model = onnx.helper.make_model(
        graph,
        opset_imports=[
            onnx.helper.make_opsetid("", 21),
            onnx.helper.make_opsetid("com.microsoft", 1),
        ],
    )
    model.ir_version = 10
    return model, {"dequant1": dq1, "dequant2": dq2}


# --- apply_structured_pruning_matmul_block_quantized_fp8 --------------------


def test_block_quantized_fp8_matcher_decodes_dequantizes_correctly():
    # _matmul_block_quantized_fp8_dequantized must reproduce the SAME
    # dequantized values the independent test quantizer computed -- proves
    # onnx.numpy_helper's own FLOAT8E4M3FN codec round-trips exactly.
    from onnxsim.pruning import _consumers_of, _match_matmul_block_quantized_fp8

    rng = np.random.default_rng(1)
    w = (rng.standard_normal((8, 32)) * 0.3).astype(np.float32)
    model, info = _fp8bw_model(w, block_size=8)
    initializer_map = {t.name: t for t in model.graph.initializer}
    m = _match_matmul_block_quantized_fp8(
        model.graph.node[0], initializer_map, _consumers_of(model.graph)
    )
    assert m is not None
    from onnxsim.pruning import _matmul_block_quantized_fp8_dequantized

    got = _matmul_block_quantized_fp8_dequantized(m)
    np.testing.assert_array_equal(got, info["dequant"])


def test_block_quantized_fp8_pruning_producer_only_matches_slice_byte_identical():
    # Single producer with no matched consumer (Y is a graph output) -- no
    # chain, so apply_structured_pruning_matmul_block_quantized_fp8 must be
    # a no-op (not_eligible), confirming this pass never touches an
    # unmatched node.
    rng = np.random.default_rng(2)
    w = (rng.standard_normal((8, 32)) * 0.3).astype(np.float32)
    model, _info = _fp8bw_model(w, block_size=8)
    pruned = onnxsim.apply_structured_pruning_matmul_block_quantized_fp8(
        model, sparsity=0.5
    )
    before = {t.name: t.SerializeToString() for t in model.graph.initializer}
    after = {t.name: t.SerializeToString() for t in pruned.graph.initializer}
    assert before == after


def test_block_quantized_fp8_pruning_producer_and_consumer_byte_identical_and_oracle():
    N1, K1, N2, block_size = 16, 32, 8, 8
    rng = np.random.default_rng(3)
    w1 = (rng.standard_normal((N1, K1)) * 0.2).astype(np.float32)
    w1[:8] *= 6.0  # first half of rows clearly more important
    w2 = (rng.standard_normal((N2, N1)) * 0.2).astype(np.float32)
    model, info = _fp8bw_chain_model(N1, K1, N2, block_size, w1, w2)
    onnx.checker.check_model(model)

    pruned = onnxsim.apply_structured_pruning_matmul_block_quantized_fp8(
        model, sparsity=0.5
    )
    b1 = onnx.numpy_helper.to_array(
        next(t for t in pruned.graph.initializer if t.name == "B1")
    )
    s1 = onnx.numpy_helper.to_array(
        next(t for t in pruned.graph.initializer if t.name == "S1")
    )
    b2 = onnx.numpy_helper.to_array(
        next(t for t in pruned.graph.initializer if t.name == "B2")
    )
    assert b1.shape == (8, K1)  # kept the 8 higher-magnitude rows
    assert s1.shape == (8, K1 // block_size)
    assert b2.shape == (N2, 8)  # consumer's own K axis co-pruned

    # byte-identity: the surviving rows of B1/S1 are an EXACT hand-slice of
    # the original quantized codes -- never re-quantized.
    orig_b1 = onnx.numpy_helper.to_array(
        next(t for t in model.graph.initializer if t.name == "B1")
    )
    orig_s1 = onnx.numpy_helper.to_array(
        next(t for t in model.graph.initializer if t.name == "S1")
    )
    np.testing.assert_array_equal(b1.view(np.uint8), orig_b1.view(np.uint8)[:8])
    np.testing.assert_array_equal(s1, orig_s1[:8])

    orig_b2 = onnx.numpy_helper.to_array(
        next(t for t in model.graph.initializer if t.name == "B2")
    )
    np.testing.assert_array_equal(b2.view(np.uint8), orig_b2.view(np.uint8)[:, :8])

    # oracle: the pruned dequantized producer matches a plain slice of the
    # ORIGINAL dequantized reference by the same kept-row indices.
    kept = np.argsort(-np.abs(info["dequant1"]).sum(axis=1))[:8]
    kept = np.sort(kept)
    assert list(kept) == list(range(8))  # first 8 rows are the important ones
    from onnxsim.pruning import (
        _consumers_of,
        _match_matmul_block_quantized_fp8,
        _matmul_block_quantized_fp8_dequantized,
    )

    initializer_map = {t.name: t for t in pruned.graph.initializer}
    m = _match_matmul_block_quantized_fp8(
        pruned.graph.node[0], initializer_map, _consumers_of(pruned.graph)
    )
    got = _matmul_block_quantized_fp8_dequantized(m)
    np.testing.assert_array_equal(got, info["dequant1"][kept])


def test_block_quantized_fp8_pruning_consumer_declines_non_block_aligned():
    # block_size=8 but only 12 (not a multiple of 8) survivors would be
    # kept -- the consumer's own scale table can't represent a partial
    # block, so the whole chain is left untouched.
    N1, K1, N2, block_size = 16, 32, 8, 8
    rng = np.random.default_rng(4)
    w1 = (rng.standard_normal((N1, K1)) * 0.3).astype(np.float32)
    w2 = (rng.standard_normal((N2, N1)) * 0.3).astype(np.float32)
    model, _info = _fp8bw_chain_model(N1, K1, N2, block_size, w1, w2)
    # sparsity=0.25 -> keep_count = 16 - round(16*0.25) = 12, not block-aligned
    pruned = onnxsim.apply_structured_pruning_matmul_block_quantized_fp8(
        model, sparsity=0.25
    )
    before = {t.name: t.SerializeToString() for t in model.graph.initializer}
    after = {t.name: t.SerializeToString() for t in pruned.graph.initializer}
    assert before == after


def test_block_quantized_fp8_pruning_declines_k_not_multiple_of_block_size():
    from onnxsim.pruning import _consumers_of, _match_matmul_block_quantized_fp8

    N, K, block_size = 4, 20, 8  # 20 % 8 == 4 != 0
    b = np.zeros((N, K), dtype=ml_dtypes.float8_e4m3fn)
