def test_paged_attention_pruning_qk_norm_weight_paired_presence_required():
    K, H, KVH, D, Out = 8, 4, 2, 8, 6
    q_norm = np.ones(D, dtype=np.float32)
    # `k_norm_weight` deliberately omitted -- the schema's own "must be
