def test_paged_attention_pruning_qk_norm_weight_both_present_left_unsliced():
    # `q_norm_weight`/`k_norm_weight` are `(head_size,)`-shaped -- constant
    # across heads -- so they never need slicing under whole-head/KV-group
    # pruning: this confirms the pruned model keeps them byte-identical to
    # their pre-pruning values while Wq/Wk/Wv genuinely do shrink.
    K, H, KVH, D, Out = 8, 4, 2, 8, 6
    q_norm = np.arange(D, dtype=np.float32)
    k_norm = np.arange(D, dtype=np.float32) * 2.0
    model, cfg = _paged_attention_model(
        K=K,
        H=H,
        KVH=KVH,
        D=D,
        Out=Out,
        seed=9,
        q_norm_weight=q_norm,
        k_norm_weight=k_norm,
    )
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    node = _paged_node(pruned)
    num_heads, kv_num_heads = _paged_attrs(node)
    assert (num_heads, kv_num_heads) != (H, KVH)  # a real match/prune happened

    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["QNorm"], q_norm.astype(np.float16))
    np.testing.assert_array_equal(inits["KNorm"], k_norm.astype(np.float16))
    assert inits["Wq"].shape[1] < cfg["wq"].shape[1]  # genuinely pruned


def test_paged_attention_pruning_constant_key_cache_is_declined():
    # `key_cache`/`value_cache` are, per this op's own doc, a mutable
    # block-based buffer "updated in place within the op" -- no realistic
    # export bakes either as a constant, and this module has no
    # execution-verified story for what slicing one would even mean here
    # (see `onnxsim/pruning.py`'s own "Attention-head pruning" section
    # comment) -- so a constant one declines the whole match outright.
    K, H, KVH, D, Out = 8, 4, 2, 8, 6
    model, cfg = _paged_attention_model(
        K=K, H=H, KVH=KVH, D=D, Out=Out, seed=10, key_cache_constant=True
    )
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    node = _paged_node(pruned)
    num_heads, kv_num_heads = _paged_attrs(node)
    assert (num_heads, kv_num_heads) == (H, KVH)  # left untouched


def test_paged_attention_pruning_latent_kv_cache_layout_is_declined():
    # ``kv_cache_layout == "LATENT"`` (absorbed Multi-head Latent Attention)
    # is a structurally different shape (no independent V/`value_cache` at
    # all, `kv_num_heads` pinned to 1) this module's own whole-KV-group
    # machinery was never built to handle -- declined outright, out of scope.
    K, H, KVH, D, Out = 8, 4, 1, 8, 6
    model, cfg = _paged_attention_model(
        K=K, H=H, KVH=KVH, D=D, Out=Out, seed=12, kv_cache_layout="LATENT"
    )
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    node = _paged_node(pruned)
    num_heads, kv_num_heads = _paged_attrs(node)
    assert (num_heads, kv_num_heads) == (H, KVH)  # left untouched


def test_paged_attention_pruning_k_scale_v_scale_per_channel_sliced():
    # `k_scale`/`v_scale`'s own PER_CHANNEL shape here is `(kv_num_heads, 1,
    # head_size)` -- rank 3, KV axis at position *0* -- a genuinely
    # different convention from `GroupQueryAttention`'s own rank-4 `[1,
    # kv_num_heads, 1, head_size]` (KV axis at position 1), so this is
    # checked structurally against a numpy reference slice built from the
    # schema's own documented axis convention, not exercisable via the
    # `GroupQueryAttention`-decomposition proxy used elsewhere in this
    # section (see this section's own top comment for why).
    K, H, KVH, D, Out = 8, 8, 4, 8, 6
    rng = np.random.default_rng(13)
    k_scale = rng.uniform(0.1, 2.0, size=(KVH, 1, D)).astype(np.float32)
    v_scale = rng.uniform(0.1, 2.0, size=(KVH, 1, D)).astype(np.float32)
    model, cfg = _paged_attention_model(
        K=K,
        H=H,
        KVH=KVH,
        D=D,
        Out=Out,
        seed=13,
        k_scale=k_scale,
        v_scale=v_scale,
    )
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    node = _paged_node(pruned)
    num_heads, kv_num_heads = _paged_attrs(node)
    assert kv_num_heads == 2

    keep_groups = _oracle_keep_groups(
        cfg["wq"].astype(np.float64),
        cfg["wk"].astype(np.float64),
        cfg["wv"].astype(np.float64),
        H,
        KVH,
        D,
        kv_num_heads,
    )
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["KScale"], k_scale[keep_groups])
    np.testing.assert_array_equal(inits["VScale"], v_scale[keep_groups])


def test_paged_attention_pruning_k_scale_per_tensor_left_untouched():
    K, H, KVH, D, Out = 8, 4, 2, 8, 6
    k_scale = np.array([0.5], dtype=np.float32)  # PER_TENSOR -- no per-head axis
    model, cfg = _paged_attention_model(
        K=K, H=H, KVH=KVH, D=D, Out=Out, seed=14, k_scale=k_scale
    )
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["KScale"], k_scale)


def test_analyze_attention_head_pruning_paged_matches_real_call():
    K, H, KVH, D, Out = 8, 4, 2, 8, 6
    model, cfg = _paged_attention_model(K=K, H=H, KVH=KVH, D=D, Out=Out, seed=15)
    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_attention_head_pruning, sparsity=0.5
    )
    assert len(report.layers) == 1
    layer = report.layers[0]
    assert layer.family == "attention_paged_group"
    assert layer.total == KVH
    assert report.not_eligible == []

    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    dims_after = _initializer_dims(pruned)
    kept_groups = KVH - layer.would_drop
    group_size = H // KVH
    assert dims_after["Wq"][1] == kept_groups * group_size * D
    assert dims_after["Wk"][1] == kept_groups * D
    assert dims_after["Wv"][1] == kept_groups * D


def test_paged_attention_not_eligible_lists_unmatched_node():
    # An orphan `PagedAttention` node (a constant `key_cache` -- see
    # `test_paged_attention_pruning_constant_key_cache_is_declined` -- so it
    # never matches) is reported via `not_eligible`, not silently dropped.
    K, H, KVH, D, Out = 8, 4, 2, 8, 6
    model, cfg = _paged_attention_model(
        K=K, H=H, KVH=KVH, D=D, Out=Out, seed=16, key_cache_constant=True
    )
    node = _paged_node(model)
    node.name = "paged_orphan"
    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_attention_head_pruning, sparsity=0.5
    )
    assert report.layers == []
    assert report.not_eligible == ["PagedAttention 'paged_orphan'"]


# --- CausalConvWithState pass-through (plain ai.onnx, opset 27) ------------
#
# Unlike `PagedAttention` above, this op has a real CPU kernel in this
# environment's onnxruntime 1.29.0 -- see onnxsim/pruning.py's own "Conv/
# pooling/Resize/Pad pass-through" section comment -- so every test here runs
# the real fused op end to end (via `_run27`, since opset 27 is still "under
# development" per onnxruntime's own load-time guard) rather than a
# decomposed-proxy fallback, and every correctness check compares against an
# *independently* pruned oracle model/tensor (never the full, unpruned model
# -- the wrong invariant for pruning).


def _causal_conv_model(C=8, K=6, L=5, kernel=3, seed=0, past_state=None, bias=True):
    # Conv(K -> C, kernel=3) -> CausalConvWithState(C, depthwise, kernel) ->
    # Conv(C -> Out, kernel=1). `past_state`, if given, is a constant
    # ``(1, C, kernel - 1)`` array wired as the op's own 4th input; ``None``
    # leaves it unconnected (needs no slicing at all).
    rng = np.random.default_rng(seed)
    w0 = rng.standard_normal((C, K, 3)).astype(np.float32) * 0.5
    b0 = rng.standard_normal((C,)).astype(np.float32) * 0.1
    w1 = rng.standard_normal((C, 1, kernel)).astype(np.float32) * 0.5
    b1 = rng.standard_normal((C,)).astype(np.float32) * 0.1
    Out = 5
    w2 = rng.standard_normal((Out, C, 1)).astype(np.float32) * 0.5
    b2 = rng.standard_normal((Out,)).astype(np.float32) * 0.1

    initializer = [
        _f32(w0, "W0"),
        _f32(b0, "B0"),
        _f32(w1, "W1"),
        _f32(w2, "W2"),
        _f32(b2, "B2"),
    ]
    cc_inputs = "h0, W1"
    if bias:
        initializer.append(_f32(b1, "B1"))
        cc_inputs += ", B1"
    else:
        cc_inputs += ", "
    if past_state is not None:
        initializer.append(_f32(np.asarray(past_state), "PastState"))
        cc_inputs += ", PastState"

    body = f"""
        g (float[1,{K},{L}] X) => (float[1,{Out},{L}] Y)
        {{
          h0 = Conv<kernel_shape=[3], pads=[1,1]>(X, W0, B0)
          h1, ps = CausalConvWithState<activation="none">({cc_inputs})
          Y = Conv<kernel_shape=[1]>(h1, W2, B2)
        }}
        """
    model = _model(body, opset=27)
    model.graph.initializer.extend(initializer)
    return model, dict(
        C=C,
        K=K,
        L=L,
        kernel=kernel,
        Out=Out,
        w0=w0,
        b0=b0,
        w1=w1,
        b1=b1 if bias else None,
        w2=w2,
        b2=b2,
    )


def _causal_conv_node(model):
    return next(n for n in model.graph.node if n.op_type == "CausalConvWithState")


def test_causal_conv_with_state_pass_through_shrinks_matched_chain_matches_oracle():
    model, cfg = _causal_conv_model(C=8, K=6, L=5, kernel=3, seed=0)
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    # No `group` attribute is ever added to a non-Conv hop node.
    node = _causal_conv_node(pruned)
    assert [a.name for a in node.attribute] == ["activation"]

    dims = _initializer_dims(pruned)
    assert dims["W0"][0] == 4  # C halved
    assert dims["W1"][0] == 4  # depthwise weight follows the same keep set
    assert dims["W2"][1] == 4  # consumer's in_channels axis

    # Independently reconstruct the keep set (L2-norm-of-output-filter
    # ranking, the same criterion apply_structured_pruning documents).
    imp = np.linalg.norm(cfg["w0"].reshape(cfg["C"], -1), axis=1)
    keep = np.sort(np.argsort(-imp)[: cfg["C"] // 2])

    rng = np.random.default_rng(123)
    x = rng.standard_normal((1, cfg["K"], cfg["L"])).astype(np.float32)
    y_pruned = _run27(pruned, {"X": x})[0]

    oracle, _ = _causal_conv_model(
        C=len(keep), K=cfg["K"], L=cfg["L"], kernel=cfg["kernel"]
    )
    oracle_inits = {
        "W0": cfg["w0"][keep],
        "B0": cfg["b0"][keep],
        "W1": cfg["w1"][keep],
        "B1": cfg["b1"][keep],
        "W2": cfg["w2"][:, keep, :],
        "B2": cfg["b2"],
    }
    for init in oracle.graph.initializer:
        init.CopyFrom(onnx.numpy_helper.from_array(oracle_inits[init.name], init.name))
    y_oracle = _run27(oracle, {"X": x})[0]
    np.testing.assert_array_equal(y_pruned, y_oracle)


def test_causal_conv_with_state_pass_through_zero_sparsity_is_a_no_op():
    model, cfg = _causal_conv_model(C=8, K=6, L=5, kernel=3, seed=1)
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.0)
    dims = _initializer_dims(pruned)
    assert dims["W0"][0] == cfg["C"]
    assert dims["W1"][0] == cfg["C"]


def test_causal_conv_with_state_pass_through_constant_past_state_sliced():
    C, kernel = 8, 3
    rng = np.random.default_rng(2)
    past = rng.standard_normal((1, C, kernel - 1)).astype(np.float32)
    model, cfg = _causal_conv_model(
        C=C, K=6, L=5, kernel=kernel, seed=2, past_state=past
    )
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    imp = np.linalg.norm(cfg["w0"].reshape(C, -1), axis=1)
    keep = np.sort(np.argsort(-imp)[: C // 2])

    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["PastState"], past[:, keep, :])


def test_causal_conv_with_state_pass_through_dynamic_past_state_left_as_graph_input():
    # A `past_state` fed by an ordinary graph input (dynamic -- the caller's
    # own runtime data) needs no slicing at all, and never blocks the match.
    C, K, L, kernel = 8, 6, 5, 3
    rng = np.random.default_rng(3)
    w0 = rng.standard_normal((C, K, 3)).astype(np.float32) * 0.5
    b0 = rng.standard_normal((C,)).astype(np.float32) * 0.1
    w1 = rng.standard_normal((C, 1, kernel)).astype(np.float32) * 0.5
    Out = 5
    w2 = rng.standard_normal((Out, C, 1)).astype(np.float32) * 0.5
    b2 = rng.standard_normal((Out,)).astype(np.float32) * 0.1
    body = f"""
        g (float[1,{K},{L}] X, float[1,{C},{kernel - 1}] PastIn) => (float[1,{Out},{L}] Y)
        {{
          h0 = Conv<kernel_shape=[3], pads=[1,1]>(X, W0, B0)
          h1, ps = CausalConvWithState<activation="none">(h0, W1, , PastIn)
          Y = Conv<kernel_shape=[1]>(h1, W2, B2)
        }}
        """
    model = _model(body, opset=27)
    model.graph.initializer.extend(
        [_f32(w0, "W0"), _f32(b0, "B0"), _f32(w1, "W1"), _f32(w2, "W2"), _f32(b2, "B2")]
    )
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    dims = _initializer_dims(pruned)
    assert dims["W0"][0] == C // 2
    assert dims["W1"][0] == C // 2
    # `PastIn` is a graph input, not an initializer -- nothing to check for
    # slicing; the checker above already confirms the graph is still valid
    # (the op's own `channels` count is inferred purely from `W1`'s shape).


def test_causal_conv_with_state_pass_through_no_spurious_group_attribute():
    model, _ = _causal_conv_model(C=8, K=6, L=5, kernel=3, seed=4)
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    node = _causal_conv_node(pruned)
    assert not any(a.name == "group" for a in node.attribute)


def test_analyze_structured_pruning_causal_conv_matches_real_call():
    model, cfg = _causal_conv_model(C=8, K=6, L=5, kernel=3, seed=5)
    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_structured_pruning, sparsity=0.5
    )
    pruned = onnxsim.apply_structured_pruning(model, sparsity=0.5)
    dims = _initializer_dims(pruned)
    matched = [layer for layer in report.layers if layer.total == cfg["C"]]
    assert len(matched) == 1
    assert matched[0].would_drop == cfg["C"] - dims["W1"][0]


# --- LinearAttention head pruning (plain ai.onnx, opset 27) -----------------
#
# Reuses the `GroupQueryAttention`-family's own whole-KV-group machinery
# (`_GQAChain`/`_apply_one_gqa_chain`/`_gqa_group_importance`) -- see
# onnxsim/pruning.py's own "Attention-head pruning" section comment, the
# `LinearAttention` bullet, for the full empirical schema findings and scope
# boundary (a *dynamic* `decay`/`beta` declines the whole match outright).
# This op, like `CausalConvWithState` above, has a real CPU kernel in this
# environment's onnxruntime, so every test runs the real fused op end to end.


def _linear_attention_model(
    Hq=4,
    Hkv=2,
    Dk=4,
    Dv=4,
    K=16,
    update_rule="linear",
    past_state=None,
    decay=None,
    beta=None,
    seed=0,
):
    rng = np.random.default_rng(seed)
    Nq, Nkv_k, Nkv_v = Hq * Dk, Hkv * Dk, Hkv * Dv
    wq = rng.standard_normal((K, Nq)).astype(np.float32) * 0.3
    wk = rng.standard_normal((K, Nkv_k)).astype(np.float32) * 0.3
    wv = rng.standard_normal((K, Nkv_v)).astype(np.float32) * 0.3
    wo = rng.standard_normal((Nq, K)).astype(np.float32) * 0.3

    initializer = [_f32(wq, "Wq"), _f32(wk, "Wk"), _f32(wv, "Wv"), _f32(wo, "Wo")]
    operands = ["q", "k", "v"]
    if past_state is not None or decay is not None or beta is not None:
        if past_state is not None:
            initializer.append(_f32(np.asarray(past_state), "PastState"))
            operands.append("PastState")
        else:
            operands.append("")
    if decay is not None or beta is not None:
        if decay is not None:
            initializer.append(_f32(np.asarray(decay), "Decay"))
            operands.append("Decay")
        else:
            operands.append("")
    if beta is not None:
        initializer.append(_f32(np.asarray(beta), "Beta"))
        operands.append("Beta")

    body = f"""
        g (float[1,3,{K}] X) => (float[1,3,{K}] Y)
        {{
          q = MatMul(X, Wq)
          k = MatMul(X, Wk)
          v = MatMul(X, Wv)
          attn_out, ps = LinearAttention<q_num_heads={Hq}, kv_num_heads={Hkv}, update_rule="{update_rule}">({", ".join(operands)})
          Y = MatMul(attn_out, Wo)
        }}
        """
    model = _model(body, opset=27)
    model.graph.initializer.extend(initializer)
    return model, dict(Hq=Hq, Hkv=Hkv, Dk=Dk, Dv=Dv, K=K, wq=wq, wk=wk, wv=wv, wo=wo)


def _linear_attention_node(model):
    return next(n for n in model.graph.node if n.op_type == "LinearAttention")


def _linear_attention_keep_groups(cfg, sparsity):
    Hq, Hkv, Dk = cfg["Hq"], cfg["Hkv"], cfg["Dk"]
    group_size = Hq // Hkv
    importance = np.zeros(Hkv)
    for g in range(Hkv):
        qc = cfg["wq"][:, g * group_size * Dk : (g + 1) * group_size * Dk]
        kc = cfg["wk"][:, g * Dk : (g + 1) * Dk]
        vc = cfg["wv"][:, g * cfg["Dv"] : (g + 1) * cfg["Dv"]]
        importance[g] = np.sqrt(
            np.linalg.norm(qc) ** 2 + np.linalg.norm(kc) ** 2 + np.linalg.norm(vc) ** 2
        )
    keep_count = max(1, Hkv - round(Hkv * sparsity))
    return np.sort(np.argsort(-importance)[:keep_count])


def _linear_attention_oracle(cfg, keep_groups, update_rule, past_state, decay, beta):
    Hq, Hkv, Dk, Dv, K = cfg["Hq"], cfg["Hkv"], cfg["Dk"], cfg["Dv"], cfg["K"]
    group_size = Hq // Hkv
    keep_q_heads = np.concatenate(
        [np.arange(g * group_size, (g + 1) * group_size) for g in keep_groups]
    )

    def col_idx(heads, width):
        return np.concatenate([np.arange(h * width, (h + 1) * width) for h in heads])

    q_idx = col_idx(keep_q_heads, Dk)
    k_idx = col_idx(keep_groups, Dk)
    v_idx = col_idx(keep_groups, Dv)
    y_idx = col_idx(keep_q_heads, Dv)

    new_ps = (
        None if past_state is None else np.asarray(past_state)[:, keep_groups, :, :]
    )
    new_decay = None
    if decay is not None:
        decay_arr = np.asarray(decay)
        if decay_arr.shape[-1] == Hkv:
            new_decay = decay_arr[:, :, keep_groups]
        else:
            new_decay = decay_arr[:, :, col_idx(keep_groups, Dk)]
    new_beta = None
    if beta is not None:
        beta_arr = np.asarray(beta)
        new_beta = (
            beta_arr[:, :, keep_groups] if beta_arr.shape[-1] == Hkv else beta_arr
        )

    oracle, _ = _linear_attention_model(
        Hq=len(keep_q_heads),
        Hkv=len(keep_groups),
        Dk=Dk,
        Dv=Dv,
        K=K,
        update_rule=update_rule,
        past_state=new_ps,
        decay=new_decay,
        beta=new_beta,
    )
    oracle_vals = {
        "Wq": cfg["wq"][:, q_idx],
        "Wk": cfg["wk"][:, k_idx],
        "Wv": cfg["wv"][:, v_idx],
        "Wo": cfg["wo"][y_idx, :],
    }
    if new_ps is not None:
        oracle_vals["PastState"] = new_ps
    if new_decay is not None:
        oracle_vals["Decay"] = new_decay
    if new_beta is not None:
        oracle_vals["Beta"] = new_beta
    for init in oracle.graph.initializer:
        init.CopyFrom(
            onnx.numpy_helper.from_array(
                np.ascontiguousarray(oracle_vals[init.name]), init.name
            )
        )
    return oracle, (new_ps, new_decay, new_beta)


def test_linear_attention_pruning_linear_mode_shrinks_matched_block_matches_oracle():
    model, cfg = _linear_attention_model(Hq=4, Hkv=2, Dk=4, Dv=4, K=16, seed=0)
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    keep_groups = _linear_attention_keep_groups(cfg, sparsity=0.5)
    node = _linear_attention_node(pruned)
    q_attr = next(a.i for a in node.attribute if a.name == "q_num_heads")
    kv_attr = next(a.i for a in node.attribute if a.name == "kv_num_heads")
    assert kv_attr == len(keep_groups)
    assert q_attr == len(keep_groups) * (cfg["Hq"] // cfg["Hkv"])

    oracle, _ = _linear_attention_oracle(cfg, keep_groups, "linear", None, None, None)
    onnx.checker.check_model(oracle)
    rng = np.random.default_rng(42)
    x = rng.standard_normal((1, 3, cfg["K"])).astype(np.float32)
    y_pruned = _run27(pruned, {"X": x})[0]
    y_oracle = _run27(oracle, {"X": x})[0]
    np.testing.assert_array_equal(y_pruned, y_oracle)


def test_linear_attention_pruning_zero_sparsity_is_a_no_op():
    model, cfg = _linear_attention_model(Hq=4, Hkv=2, Dk=4, Dv=4, K=16, seed=1)
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.0)
    dims = _initializer_dims(pruned)
    assert dims["Wq"][1] == cfg["Hq"] * cfg["Dk"]


def test_linear_attention_pruning_delta_mode_slices_past_state_and_beta_matches_oracle():
    Hq, Hkv, Dk, Dv, K = 4, 2, 4, 4, 16
    rng = np.random.default_rng(2)
    past_state = rng.standard_normal((1, Hkv, Dk, Dv)).astype(np.float32)
    beta = (np.abs(rng.standard_normal((1, 3, Hkv))) * 0.1).astype(np.float32)
    model, cfg = _linear_attention_model(
        Hq=Hq,
        Hkv=Hkv,
        Dk=Dk,
        Dv=Dv,
        K=K,
        update_rule="delta",
        past_state=past_state,
        beta=beta,
        seed=2,
    )
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    keep_groups = _linear_attention_keep_groups(cfg, sparsity=0.5)
    oracle, (new_ps, _, new_beta) = _linear_attention_oracle(
        cfg, keep_groups, "delta", past_state, None, beta
    )
    onnx.checker.check_model(oracle)

    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["PastState"], new_ps)
    np.testing.assert_array_equal(inits["Beta"], new_beta)

    rng2 = np.random.default_rng(43)
    x = rng2.standard_normal((1, 3, K)).astype(np.float32)
    y_pruned = _run27(pruned, {"X": x})[0]
    y_oracle = _run27(oracle, {"X": x})[0]
    np.testing.assert_array_equal(y_pruned, y_oracle)


def test_linear_attention_pruning_gated_mode_slices_gla_decay_matches_oracle():
    # GLA/RWKV-6 mode: decay is per-key-dimension, width kv_num_heads * d_k
    # -- distinct from DeltaNet/RetNet's own per-head-scalar width, and must
    # NOT be conflated with it (see onnxsim/pruning.py's own docstring).
    Hq, Hkv, Dk, Dv, K = 4, 2, 4, 4, 16
    rng = np.random.default_rng(3)
    decay = (-np.abs(rng.standard_normal((1, 3, Hkv * Dk))) * 0.1).astype(np.float32)
    model, cfg = _linear_attention_model(
        Hq=Hq, Hkv=Hkv, Dk=Dk, Dv=Dv, K=K, update_rule="gated", decay=decay, seed=3
    )
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    keep_groups = _linear_attention_keep_groups(cfg, sparsity=0.5)
    oracle, (_, new_decay, _) = _linear_attention_oracle(
        cfg, keep_groups, "gated", None, decay, None
    )
    onnx.checker.check_model(oracle)

    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["Decay"], new_decay)
    assert inits["Decay"].shape[-1] == len(keep_groups) * Dk

    rng2 = np.random.default_rng(44)
    x = rng2.standard_normal((1, 3, K)).astype(np.float32)
    y_pruned = _run27(pruned, {"X": x})[0]
    y_oracle = _run27(oracle, {"X": x})[0]
    np.testing.assert_array_equal(y_pruned, y_oracle)


def test_linear_attention_pruning_dynamic_decay_is_declined():
    # A `decay` fed by anything other than a constant initializer (the
    # realistic shape for a real GLA/DeltaNet export -- e.g. a
    # `LinearAttentionGate` node) declines the whole match outright -- see
    # onnxsim/pruning.py's own docstring for why this is the safe, deliberate
    # scope boundary rather than a guess.
    Hq, Hkv, Dk, Dv, K = 4, 2, 4, 4, 16
    body = f"""
        g (float[1,3,{K}] X, float[1,3,{Hkv}] DecayIn) => (float[1,3,{K}] Y)
        {{
          q = MatMul(X, Wq)
          k = MatMul(X, Wk)
          v = MatMul(X, Wv)
          attn_out, ps = LinearAttention<q_num_heads={Hq}, kv_num_heads={Hkv}, update_rule="gated">(q, k, v, , DecayIn)
          Y = MatMul(attn_out, Wo)
        }}
        """
    rng = np.random.default_rng(4)
    wq = rng.standard_normal((K, Hq * Dk)).astype(np.float32) * 0.3
    wk = rng.standard_normal((K, Hkv * Dk)).astype(np.float32) * 0.3
    wv = rng.standard_normal((K, Hkv * Dv)).astype(np.float32) * 0.3
    wo = rng.standard_normal((Hq * Dk, K)).astype(np.float32) * 0.3
    model = _model(body, opset=27)
    model.graph.initializer.extend(
        [_f32(wq, "Wq"), _f32(wk, "Wk"), _f32(wv, "Wv"), _f32(wo, "Wo")]
    )
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    dims = _initializer_dims(pruned)
    assert dims["Wq"] == (K, Hq * Dk)  # completely untouched -- no match


def test_linear_attention_pruning_dynamic_beta_is_declined():
    Hq, Hkv, Dk, Dv, K = 4, 2, 4, 4, 16
    body = f"""
        g (float[1,3,{K}] X, float[1,3,{Hkv}] BetaIn) => (float[1,3,{K}] Y)
        {{
          q = MatMul(X, Wq)
          k = MatMul(X, Wk)
          v = MatMul(X, Wv)
          attn_out, ps = LinearAttention<q_num_heads={Hq}, kv_num_heads={Hkv}, update_rule="delta">(q, k, v, , , BetaIn)
          Y = MatMul(attn_out, Wo)
        }}
        """
    rng = np.random.default_rng(5)
    wq = rng.standard_normal((K, Hq * Dk)).astype(np.float32) * 0.3
    wk = rng.standard_normal((K, Hkv * Dk)).astype(np.float32) * 0.3
    wv = rng.standard_normal((K, Hkv * Dv)).astype(np.float32) * 0.3
    wo = rng.standard_normal((Hq * Dk, K)).astype(np.float32) * 0.3
    model = _model(body, opset=27)
    model.graph.initializer.extend(
        [_f32(wq, "Wq"), _f32(wk, "Wk"), _f32(wv, "Wv"), _f32(wo, "Wo")]
    )
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    dims = _initializer_dims(pruned)
    assert dims["Wq"] == (K, Hq * Dk)  # completely untouched -- no match


def test_linear_attention_not_eligible_lists_unmatched_node():
    Hq, Hkv, Dk, Dv, K = 4, 2, 4, 4, 16
    body = f"""
        g (float[1,3,{K}] X, float[1,3,{Hkv}] DecayIn) => (float[1,3,{K}] Y)
        {{
          q = MatMul(X, Wq)
          k = MatMul(X, Wk)
          v = MatMul(X, Wv)
          attn_out, ps = LinearAttention<q_num_heads={Hq}, kv_num_heads={Hkv}, update_rule="gated">(q, k, v, , DecayIn)
          Y = MatMul(attn_out, Wo)
        }}
        """
    rng = np.random.default_rng(6)
    wq = rng.standard_normal((K, Hq * Dk)).astype(np.float32) * 0.3
    wk = rng.standard_normal((K, Hkv * Dk)).astype(np.float32) * 0.3
    wv = rng.standard_normal((K, Hkv * Dv)).astype(np.float32) * 0.3
    wo = rng.standard_normal((Hq * Dk, K)).astype(np.float32) * 0.3
    model = _model(body, opset=27)
    model.graph.initializer.extend(
        [_f32(wq, "Wq"), _f32(wk, "Wk"), _f32(wv, "Wv"), _f32(wo, "Wo")]
    )
    node = _linear_attention_node(model)
    node.name = "la_orphan"
    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_attention_head_pruning, sparsity=0.5
    )
    assert report.layers == []
    assert report.not_eligible == ["LinearAttention 'la_orphan'"]


def test_analyze_attention_head_pruning_linear_attention_matches_real_call():
    model, cfg = _linear_attention_model(Hq=4, Hkv=2, Dk=4, Dv=4, K=16, seed=7)
    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_attention_head_pruning, sparsity=0.5
    )
    assert len(report.layers) == 1
    layer = report.layers[0]
    assert layer.family == "linear_attention_group"
    assert layer.total == cfg["Hkv"]
    assert report.not_eligible == []

    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    dims_after = _initializer_dims(pruned)
    kept_groups = cfg["Hkv"] - layer.would_drop
    group_size = cfg["Hq"] // cfg["Hkv"]
    assert dims_after["Wq"][1] == kept_groups * group_size * cfg["Dk"]
    assert dims_after["Wk"][1] == kept_groups * cfg["Dk"]
    assert dims_after["Wv"][1] == kept_groups * cfg["Dv"]


# --- SparseAttention head pruning (com.microsoft, block-sparse-KV attention) ---
#
# Reuses the `GroupQueryAttention`-family's own whole-KV-group machinery
# (`_GQAChain`/`_apply_one_gqa_chain`/`_gqa_group_importance`) -- see
# onnxsim/pruning.py's own "Attention-head pruning" section comment, the
# `SparseAttention` bullet (right above `_match_sparse_attention_producer`),
# for the full empirical schema findings and scope boundary (a *dynamic*
# `block_row_indices`/`block_col_indices` declines the whole match outright,
# and a post-pruning head count that would violate this op's own "num_heads
# divisible by num_layout" invariant declines that block's pruning as a
# no-op). This op has a real CPU kernel in this environment's onnxruntime
# (confirmed live), but its own schema requires `past_key`/`present_key`
# (and `past_value`/`present_value`) to literally share the same memory
# buffer at execution time ("For performance, past_key and present_key
# share same memory buffer") -- verified empirically: an ordinary
# `session.run()` call (which always allocates independent output buffers)
# fails outright ("past_key->DataRaw() == present_key->DataRaw() ... was
# false"). Every execution test here therefore uses onnxruntime's own
# IOBinding API (`_run_sparse_attention`), binding the identical `OrtValue`
# to both the past-cache input and the present-cache output, the same
# buffer-reuse pattern a real onnxruntime-genai-style autoregressive decode
# loop uses.


def _sparse_attention_model(
    K=8,
    H=4,
    KVH=2,
    D=8,
    Out=6,
    seed=0,
    batch=1,
    seq=16,
    sparse_block_size=16,
    num_layout=1,
    wq=None,
    wk=None,
    wv=None,
    wout=None,
    past_key=None,
    past_value=None,
    row_indices=None,
    col_indices=None,
    row_indices_dynamic=False,
):
    # Real ONNX Runtime CPU kernel for SparseAttention requires head_size to
    # be a multiple of 8 (verified empirically, the same constraint
    # GroupQueryAttention's own CPU kernel has -- see `_gqa_model`'s own
    # comment), so D defaults to 8. `past_key`/`past_value` are declared as
    # genuine graph inputs *and* given an initializer of the same name (the
    # standard ONNX "optional input with a default constant" idiom, legal
    # per `onnx.checker.check_model` -- confirmed below) so a caller can
    # execute the model through onnxruntime's own IOBinding API (binding the
    # same buffer to the input and the `present_key`/`present_value`
    # output), while this module's own matcher/slicer still sees a genuine
    # constant to prune (`initializer_map` reads `graph.initializer`, not
    # `graph.input`).
    rng = np.random.default_rng(seed)
    Nq, Nkv = H * D, KVH * D
    if wq is None:
        wq = rng.standard_normal((K, Nq)).astype(np.float32) * 0.1
    if wk is None:
        wk = rng.standard_normal((K, Nkv)).astype(np.float32) * 0.1
    if wv is None:
        wv = rng.standard_normal((K, Nkv)).astype(np.float32) * 0.1
    if wout is None:
        wout = rng.standard_normal((Nq, Out)).astype(np.float32) * 0.1
    if past_key is None:
        past_key = rng.standard_normal((batch, KVH, seq, D)).astype(np.float32) * 0.1
    if past_value is None:
        past_value = rng.standard_normal((batch, KVH, seq, D)).astype(np.float32) * 0.1
    past_key = np.ascontiguousarray(past_key, dtype=np.float32)
    past_value = np.ascontiguousarray(past_value, dtype=np.float32)

    initializer = [
        _f32(wq, "Wq"),
        _f32(wk, "Wk"),
        _f32(wv, "Wv"),
        _f32(wout, "Wout"),
        onnx.numpy_helper.from_array(past_key, "PastKey"),
        onnx.numpy_helper.from_array(past_value, "PastValue"),
    ]

    # A trivially "dense" single-row-block CSR mask (`seq == sparse_block_size`
    # by default, exactly one query/key block, that one block attending
    # fully to itself -- this op's own real unidirectional/causal masking is
    # applied internally regardless), `num_layout` identical copies stacked
    # along axis 0. This module never inspects `block_row_indices`'/
    # `block_col_indices`' own *content* at all, only their shared leading
    # `num_layout` dimension (see `_match_sparse_attention_producer`'s own
    # docstring) -- confirmed via a real onnxruntime CPU-kernel run
    # (`_run_sparse_attention`) that this minimal mask executes correctly.
    if row_indices is None:
        row_indices = np.tile(np.array([0, 1], dtype=np.int32), (num_layout, 1))
    if col_indices is None:
        col_indices = np.tile(np.array([0], dtype=np.int32), (num_layout, 1))
    extra_inputs = ""
    if row_indices_dynamic:
        extra_inputs = f", int32[{row_indices.shape[0]},{row_indices.shape[1]}] RowIdx"
    else:
        initializer.append(onnx.numpy_helper.from_array(row_indices, "RowIdx"))
    initializer.append(onnx.numpy_helper.from_array(col_indices, "ColIdx"))
    initializer.append(
        onnx.numpy_helper.from_array(np.array(seq, dtype=np.int32), "TotalSeq")
    )
    initializer.append(
        onnx.numpy_helper.from_array(
            np.full((batch,), seq, dtype=np.int32), "KeyTotalSeq"
        )
    )

    # PastKey/PastValue/PresentKey/PresentValue declare a symbolic `kvh`
    # dim, not a concrete `{KVH}`, for their own `kv_num_heads` axis: this
    # module's own pruning only resizes the *initializer*'s real shape (the
    # constant this pass actually slices), not this static graph-level
    # ValueInfo declaration -- a concrete dim here would go stale the moment
    # `KVH` is pruned down, and onnxruntime's own loader rejects an
    # initializer whose shape no longer matches its declared graph input
    # (confirmed empirically: "Shape of initializer PastValue does not
    # match").
    body = f"""
        g (float[{batch},{seq},{K}] X, float[{batch},kvh,{seq},{D}] PastKey, float[{batch},kvh,{seq},{D}] PastValue{extra_inputs}) => (float[{batch},{seq},{Out}] Y, float[{batch},kvh,{seq},{D}] PresentKey, float[{batch},kvh,{seq},{D}] PresentValue)
        {{
          q = MatMul(X, Wq)
          k = MatMul(X, Wk)
          v = MatMul(X, Wv)
          attn, PresentKey, PresentValue = com.microsoft.SparseAttention <num_heads={H}, kv_num_heads={KVH}, sparse_block_size={sparse_block_size}> (q, k, v, PastKey, PastValue, RowIdx, ColIdx, TotalSeq, KeyTotalSeq)
          Y = MatMul(attn, Wout)
        }}
        """
    model = parser.parse_model(
        f"""
        <
          ir_version: 10,
          opset_import: ["": 18, "com.microsoft": 1]
        >
        {body}
        """
    )
    model.graph.initializer.extend(initializer)
    return model, dict(
        K=K,
        H=H,
        KVH=KVH,
        D=D,
        Out=Out,
        Nq=Nq,
        Nkv=Nkv,
        wq=wq,
        wk=wk,
        wv=wv,
        wout=wout,
        batch=batch,
        seq=seq,
        sparse_block_size=sparse_block_size,
        num_layout=num_layout,
        past_key=past_key,
        past_value=past_value,
    )


def _sparse_attention_node(model):
    return next(n for n in model.graph.node if n.op_type == "SparseAttention")


def _sparse_attention_attrs(node):
    num_heads = next(a.i for a in node.attribute if a.name == "num_heads")
    kv_num_heads = next(a.i for a in node.attribute if a.name == "kv_num_heads")
    return num_heads, kv_num_heads


def _run_sparse_attention(model, x, past_key, past_value):
    # See this section's own top comment for why plain `session.run()` (or
    # this file's own `_run`) can't be used here: `present_key`/
    # `present_value` must be bound to the exact same `OrtValue` as
    # `past_key`/`past_value`.
    sess = ort.InferenceSession(
        model.SerializeToString(), providers=["CPUExecutionProvider"]
    )
    past_key_ov = ort.OrtValue.ortvalue_from_numpy(np.ascontiguousarray(past_key))
    past_value_ov = ort.OrtValue.ortvalue_from_numpy(np.ascontiguousarray(past_value))
    io = sess.io_binding()
    io.bind_cpu_input("X", np.ascontiguousarray(x))
    io.bind_ortvalue_input("PastKey", past_key_ov)
    io.bind_ortvalue_input("PastValue", past_value_ov)
    io.bind_output("Y", "cpu")
    io.bind_ortvalue_output("PresentKey", past_key_ov)
    io.bind_ortvalue_output("PresentValue", past_value_ov)
    sess.run_with_iobinding(io)
    outs = io.copy_outputs_to_cpu()
    return outs[0]


def test_sparse_attention_pruning_shrinks_matched_block():
    model, cfg = _sparse_attention_model(K=8, H=4, KVH=4, D=8, Out=6)
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    node = _sparse_attention_node(pruned)
    num_heads, kv_num_heads = _sparse_attention_attrs(node)
    assert num_heads == 2
    assert kv_num_heads == 2

    inits = {t.name: t for t in pruned.graph.initializer}
    assert list(inits["Wq"].dims) == [8, 16]
    assert list(inits["Wk"].dims) == [8, 16]
    assert list(inits["Wv"].dims) == [8, 16]
    assert list(inits["Wout"].dims) == [16, 6]
    assert list(inits["PastKey"].dims) == [1, 2, 16, 8]
    assert list(inits["PastValue"].dims) == [1, 2, 16, 8]


def test_sparse_attention_pruning_zero_sparsity_is_a_no_op():
    model, cfg = _sparse_attention_model(K=8, H=8, KVH=2, D=8, Out=6, seed=7)
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.0)
    node = _sparse_attention_node(pruned)
    num_heads, kv_num_heads = _sparse_attention_attrs(node)
    assert num_heads == cfg["H"]
    assert kv_num_heads == cfg["KVH"]
    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["Wq"], cfg["wq"])
    np.testing.assert_array_equal(inits["Wk"], cfg["wk"])
    np.testing.assert_array_equal(inits["Wv"], cfg["wv"])


def test_sparse_attention_pruning_matches_oracle_exactly():
    # End-to-end correctness against an independently-reconstructed,
    # already-pruned reference model -- this module's own established
    # invariant (comparing against the *unpruned* model's own output has
    # been a real, caught mistake in an earlier round of this project) --
    # run through a real onnxruntime CPU kernel via `_run_sparse_attention`,
    # not merely a shape check. Also directly exercises `past_key`/
    # `past_value` (required, not optional, on this op's own schema) being
    # sliced along their own `kv_num_heads` axis by the identical
    # `keep_groups` index set K's/V's own producer weights are sliced by.
    model, cfg = _sparse_attention_model(K=8, H=8, KVH=2, D=8, Out=6, seed=1)
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)

    node = _sparse_attention_node(pruned)
    num_heads, kv_num_heads = _sparse_attention_attrs(node)
    group_size = cfg["H"] // cfg["KVH"]
    assert kv_num_heads == 1  # max(1, 2 - round(2*0.5))
    assert num_heads == kv_num_heads * group_size

    keep_groups = _oracle_keep_groups(
        cfg["wq"], cfg["wk"], cfg["wv"], cfg["H"], cfg["KVH"], cfg["D"], kv_num_heads
    )
    keep_q_heads = _group_q_heads(keep_groups, group_size)
    d = cfg["D"]
    q_idx, kv_idx = _head_idx(keep_q_heads, d), _head_idx(keep_groups, d)

    inits = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    np.testing.assert_array_equal(inits["Wq"], cfg["wq"][:, q_idx])
    np.testing.assert_array_equal(inits["Wk"], cfg["wk"][:, kv_idx])
    np.testing.assert_array_equal(inits["Wv"], cfg["wv"][:, kv_idx])
    np.testing.assert_array_equal(inits["Wout"], cfg["wout"][q_idx, :])
    np.testing.assert_array_equal(
        inits["PastKey"], cfg["past_key"][:, keep_groups, :, :]
    )
    np.testing.assert_array_equal(
        inits["PastValue"], cfg["past_value"][:, keep_groups, :, :]
    )

    oracle, _ = _sparse_attention_model(
        K=cfg["K"],
        H=num_heads,
        KVH=kv_num_heads,
        D=d,
        Out=cfg["Out"],
        seed=1,
        batch=cfg["batch"],
        seq=cfg["seq"],
        sparse_block_size=cfg["sparse_block_size"],
        wq=cfg["wq"][:, q_idx],
        wk=cfg["wk"][:, kv_idx],
        wv=cfg["wv"][:, kv_idx],
        wout=cfg["wout"][q_idx, :],
        past_key=cfg["past_key"][:, keep_groups, :, :],
        past_value=cfg["past_value"][:, keep_groups, :, :],
    )
    onnx.checker.check_model(oracle)

    rng = np.random.default_rng(2)
    x = (
        rng.standard_normal((cfg["batch"], cfg["seq"], cfg["K"])).astype(np.float32)
        * 0.1
    )
    pruned_past_key = cfg["past_key"][:, keep_groups, :, :]
    pruned_past_value = cfg["past_value"][:, keep_groups, :, :]
    y_pruned = _run_sparse_attention(pruned, x, pruned_past_key, pruned_past_value)
    y_oracle = _run_sparse_attention(oracle, x, pruned_past_key, pruned_past_value)
    np.testing.assert_allclose(y_pruned, y_oracle, rtol=1e-4, atol=1e-4)


def test_sparse_attention_pruning_dynamic_block_row_indices_is_declined():
    # `block_row_indices` (and, by the same reasoning, `block_col_indices`)
    # must be a *constant* for this pass to know `num_layout` and re-verify
    # this op's own "num_heads divisible by num_layout" invariant once
    # pruning's post-pruning head count is known -- a real block-sparse
    # layout is a fixed structure baked at export time, never genuine
    # runtime data the way GroupQueryAttention's own past_key/past_value
    # legitimately can be, so a *dynamic* one declines the whole match
    # outright (see `_match_sparse_attention_producer`'s own docstring).
    model, cfg = _sparse_attention_model(
        K=8, H=4, KVH=2, D=8, Out=6, seed=3, row_indices_dynamic=True
    )
    before = {
        t.name: onnx.numpy_helper.to_array(t).copy() for t in model.graph.initializer
    }
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    after = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    for name in ("Wq", "Wk", "Wv", "Wout"):
        np.testing.assert_array_equal(before[name], after[name])
    node = _sparse_attention_node(pruned)
    num_heads, kv_num_heads = _sparse_attention_attrs(node)
    assert (num_heads, kv_num_heads) == (cfg["H"], cfg["KVH"])


def test_sparse_attention_pruning_num_layout_divisibility_declined():
    # H=4, KVH=4 (group_size=1, ordinary per-head groups), num_layout=2: at
    # sparsity=0.75, keep_count == max(1, 4 - round(4*0.75)) == 1, so the
    # post-pruning query head count would be 1 -- not divisible by
    # num_layout == 2, which would silently break this op's own "num_heads
    # is divisible by num_layout" invariant even though it held before
    # pruning. Declined as a no-op for this block (the same "sparsity
    # rounds to no groups dropped" outcome, from a different cause) rather
    # than emitting an invalid node -- see `_apply_one_gqa_chain`'s own
    # `is_sparse_attention` branch.
    model, cfg = _sparse_attention_model(
        K=8, H=4, KVH=4, D=8, Out=6, seed=5, num_layout=2
    )
    before = {
        t.name: onnx.numpy_helper.to_array(t).copy() for t in model.graph.initializer
    }
    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.75)
    onnx.checker.check_model(pruned)
    after = {t.name: onnx.numpy_helper.to_array(t) for t in pruned.graph.initializer}
    for name in ("Wq", "Wk", "Wv", "Wout"):
        np.testing.assert_array_equal(before[name], after[name])
    node = _sparse_attention_node(pruned)
    num_heads, kv_num_heads = _sparse_attention_attrs(node)
    assert (num_heads, kv_num_heads) == (cfg["H"], cfg["KVH"])


def test_sparse_attention_not_eligible_lists_unmatched_node():
    model, cfg = _sparse_attention_model(
        K=8, H=4, KVH=2, D=8, Out=6, seed=6, row_indices_dynamic=True
    )
    node = _sparse_attention_node(model)
    node.name = "sa_orphan"
    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_attention_head_pruning, sparsity=0.5
    )
    assert report.layers == []
    assert report.not_eligible == ["SparseAttention 'sa_orphan'"]


def test_analyze_attention_head_pruning_sparse_attention_matches_real_call():
    model, cfg = _sparse_attention_model(K=8, H=8, KVH=2, D=8, Out=6, seed=7)
    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_attention_head_pruning, sparsity=0.5
    )
    assert len(report.layers) == 1
    layer = report.layers[0]
    assert layer.family == "attention_sparse_group"
    assert layer.total == cfg["KVH"]
    assert report.not_eligible == []

    pruned = onnxsim.apply_attention_head_pruning(model, sparsity=0.5)
    dims_after = {t.name: list(t.dims) for t in pruned.graph.initializer}
    kept_groups = cfg["KVH"] - layer.would_drop
    group_size = cfg["H"] // cfg["KVH"]
    assert dims_after["Wq"][1] == kept_groups * group_size * cfg["D"]
    assert dims_after["Wk"][1] == kept_groups * cfg["D"]
    assert dims_after["Wv"][1] == kept_groups * cfg["D"]


# --- QOperator (QLinearConv/QLinearMatMul/QGemm) structured pruning tests --
#
# QLinearConv/QLinearMatMul/QGemm carry their own quantized weight/scale/
# zero-point/bias directly as node inputs -- there is no DequantizeLinear
# node to build through parser text the way the QDQ tests above do, and the
# scale/zero-point/int32-bias tensors need real int8/uint8/int32 array data
# a parser text literal can't spell out (the parser only encodes float
# literals as `float_data`) -- so, mirroring this file's own established
# fallback for exactly this reason (see the MatMulNBits/QDQ/
# MatMulBlockQuantizedFp4Weight/Fp8Weight test helpers above), these models
# are built directly via `onnx.helper`, with real numpy-quantized tensors
# attached as initializers.


def _i32(array, name):
    return onnx.numpy_helper.from_array(array.astype(np.int32), name)


def _qop_quantize_per_channel_i8(w, axis, seed=0):
    """Independent (onnxsim-code-free) symmetric per-channel INT8
    quantizer -- `axis` is the output-channel axis. Returns
    ``(q, scale, zero_point)`` with `zero_point` all-zero (symmetric),
    matching this repo's own `quantize_qoperator`/`quantize_qoperator_gemm`
    convention confirmed empirically (see onnxsim/pruning.py's own "
    QOperator" section comment).
    """
    absmax = np.max(np.abs(w), axis=tuple(i for i in range(w.ndim) if i != axis))
    absmax = np.maximum(absmax, 1e-6)
    scale = (absmax / 127.0).astype(np.float32)
    shp = [1] * w.ndim
    shp[axis] = -1
    q = np.clip(np.round(w / scale.reshape(shp)), -127, 127).astype(np.int8)
    zp = np.zeros_like(scale, dtype=np.int8)
    return q, scale, zp


def _qop_quantize_per_tensor_u8(x):
    """Independent per-tensor asymmetric UINT8 quantizer -- the common
    activation-quantization convention every real exporter this
    investigation found actually emits (see section comment).
    """
    lo, hi = float(x.min()), float(x.max())
    if hi <= lo:
        hi = lo + 1.0
    scale = np.float32((hi - lo) / 255.0)
    zp = np.uint8(np.clip(round(-lo / scale), 0, 255))
    q = np.clip(np.round(x / scale + zp), 0, 255).astype(np.uint8)
    return q, scale, zp


def _qop_dequant(q, scale, zero_point, axis):
    q = q.astype(np.float64)
    scale = scale.astype(np.float64)
    zp = zero_point.astype(np.float64)
    if scale.ndim >= 1 and scale.size > 1:
        shape = [1] * q.ndim
        shape[axis] = -1
        scale = scale.reshape(shape)
        zp = zp.reshape(shape)
    return (q - zp) * scale


def _qlinearconv_node(
    name,
    x,
    y,
    w,
    w_scale,
    w_zp,
    y_scale,
    y_zp,
    bias,
    x_scale="x_scale",
    x_zp="x_zp",
    **attrs,
):
    inputs = [x, x_scale, x_zp, w, w_scale, w_zp, y_scale, y_zp]
    if bias is not None:
        inputs.append(bias)
    return onnx.helper.make_node("QLinearConv", inputs, [y], name=name, **attrs)


def _qlinearconv_chain_model(
    N1=6, C1=3, N2=4, kh=3, kw=3, bias=True, per_channel=True, seed=0
):
    """Builds ``QLinearConv(n1) -> QLinearConv(n2)`` -- a same-family
    QOperator chain -- with real, independently-quantized weights. Returns
    ``(model, info)`` where `info` carries every float/quantized array
    needed to hand-build an "already pruned" oracle.
    """
    rng = np.random.default_rng(seed)
    W1 = rng.standard_normal((N1, C1, kh, kw)).astype(np.float32) * 0.3
    W2 = rng.standard_normal((N2, N1, 1, 1)).astype(np.float32) * 0.3
    B1f = (rng.standard_normal(N1).astype(np.float32) * 0.05) if bias else None
    B2f = (rng.standard_normal(N2).astype(np.float32) * 0.05) if bias else None

    x_scale = np.float32(0.02)
    x_zp = np.uint8(120)

    if per_channel:
        W1q, W1s, W1zp = _qop_quantize_per_channel_i8(W1, axis=0)
        W2q, W2s, W2zp = _qop_quantize_per_channel_i8(W2, axis=0)
    else:
        w1q_flat, w1s_flat, w1zp_flat = _qop_quantize_per_channel_i8(
            W1.reshape(1, -1), axis=0
        )
        W1q, W1s, W1zp = w1q_flat.reshape(W1.shape), w1s_flat[0], w1zp_flat[0]
        w2q_flat, w2s_flat, w2zp_flat = _qop_quantize_per_channel_i8(
            W2.reshape(1, -1), axis=0
        )
        W2q, W2s, W2zp = w2q_flat.reshape(W2.shape), w2s_flat[0], w2zp_flat[0]

    y1_scale = np.float32(0.03)
    y1_zp = np.uint8(120)
    y2_scale = np.float32(0.04)
    y2_zp = np.uint8(120)

    B1q = None
    if B1f is not None:
        b1_dequant_scale = x_scale.astype(np.float64) * W1s.astype(np.float64)
        B1q = np.round(B1f.astype(np.float64) / b1_dequant_scale).astype(np.int32)
    B2q = None
    if B2f is not None:
        b2_dequant_scale = y1_scale.astype(np.float64) * W2s.astype(np.float64)
        B2q = np.round(B2f.astype(np.float64) / b2_dequant_scale).astype(np.int32)

    inits = [
        _f32(np.array(x_scale), "x_scale"),
        _u8(np.array(x_zp), "x_zp"),
        onnx.numpy_helper.from_array(W1q, "W1"),
        _f32(np.atleast_1d(W1s) if per_channel else np.array(W1s), "W1_scale"),
        _i8(np.atleast_1d(W1zp) if per_channel else np.array(W1zp), "W1_zp"),
        _f32(np.array(y1_scale), "y1_scale"),
        _u8(np.array(y1_zp), "y1_zp"),
        onnx.numpy_helper.from_array(W2q, "W2"),
        _f32(np.atleast_1d(W2s) if per_channel else np.array(W2s), "W2_scale"),
        _i8(np.atleast_1d(W2zp) if per_channel else np.array(W2zp), "W2_zp"),
        _f32(np.array(y2_scale), "y2_scale"),
        _u8(np.array(y2_zp), "y2_zp"),
    ]
    if B1q is not None:
        inits.append(_i32(B1q, "B1"))
    if B2q is not None:
        inits.append(_i32(B2q, "B2"))

    n1 = _qlinearconv_node(
        "n1",
        "x_q",
        "y1_q",
        "W1",
        "W1_scale",
        "W1_zp",
        "y1_scale",
        "y1_zp",
        "B1" if B1q is not None else None,
        kernel_shape=[kh, kw],
        pads=[0, 0, 0, 0],
    )
    n2 = _qlinearconv_node(
        "n2",
        "y1_q",
        "y2_q",
        "W2",
        "W2_scale",
        "W2_zp",
        "y2_scale",
        "y2_zp",
        "B2" if B2q is not None else None,
        x_scale="y1_scale",
        x_zp="y1_zp",
        kernel_shape=[1, 1],
        pads=[0, 0, 0, 0],
    )
    spatial = 8
    out_spatial = spatial - kh + 1
    graph = onnx.helper.make_graph(
        [n1, n2],
        "g",
        [
            onnx.helper.make_tensor_value_info(
                "x_q", onnx.TensorProto.UINT8, [1, C1, spatial, spatial]
            )
        ],
        [
            onnx.helper.make_tensor_value_info(
                "y2_q", onnx.TensorProto.UINT8, [1, N2, out_spatial, out_spatial]
            )
        ],
        initializer=inits,
    )
    model = onnx.helper.make_model(
        graph, opset_imports=[onnx.helper.make_opsetid("", 17)]
    )
    model.ir_version = 10
    return model, {
        "W1": W1q,
        "W1_scale": W1s,
        "W1_zp": W1zp,
        "B1": B1q,
        "W2": W2q,
        "W2_scale": W2s,
        "W2_zp": W2zp,
        "B2": B2q,
        "x_scale": x_scale,
        "x_zp": x_zp,
        "y1_scale": y1_scale,
        "y1_zp": y1_zp,
        "spatial": spatial,
        "C1": C1,
    }


def test_qlinearconv_chain_is_matched_and_prunes():
    model, info = _qlinearconv_chain_model(N1=6, C1=3, N2=4, seed=1)
    onnx.checker.check_model(model)
    chains = onnxsim.pruning._find_qop_chains(model.graph)
    assert len(chains) == 1
    assert chains[0].n_channels == 6

    pruned = onnxsim.apply_structured_pruning_qoperator(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    inits = {t.name: t for t in pruned.graph.initializer}
    assert list(inits["W1"].dims) == [3, info["C1"], 3, 3]
    assert list(inits["W1_scale"].dims) == [3]
    assert list(inits["W1_zp"].dims) == [3]
    assert list(inits["B1"].dims) == [3]
    assert list(inits["W2"].dims) == [4, 3, 1, 1]


def test_qlinearconv_producer_matches_independent_oracle_via_real_inference_session():
    N1, C1, N2 = 6, 3, 4
    model, info = _qlinearconv_chain_model(N1=N1, C1=C1, N2=N2, seed=2)

    w1_dequant = _qop_dequant(info["W1"], info["W1_scale"], info["W1_zp"], axis=0)
    w1_nk = w1_dequant.reshape(N1, -1)
    keep = np.sort(np.argsort(-np.linalg.norm(w1_nk, axis=1))[: N1 // 2])

    pruned = onnxsim.apply_structured_pruning_qoperator(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    inits = {t.name: t for t in pruned.graph.initializer}

    # byte-identity: the pruned graph's own quantized codes/scale/zero_point/
    # bias are EXACTLY a hand-slice of the original ones -- "slice, don't
    # recompute" -- never a re-quantization.
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["W1"]), info["W1"][keep]
    )
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["W1_scale"]), info["W1_scale"][keep]
    )
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["W1_zp"]), info["W1_zp"][keep]
    )
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["B1"]), info["B1"][keep]
    )
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["W2"]), info["W2"][:, keep]
    )

    # Independently reconstructed "already pruned" reference model (its own
    # smaller tensors built directly, not a post-hoc slice of the unpruned
    # model's own output) -- both run through a real onnxruntime
    # InferenceSession, per this task's own correctness bar.
    ref_model, _ = _qlinearconv_chain_model(N1=len(keep), C1=C1, N2=N2, seed=1234567)
    ref_inits = {t.name: t for t in ref_model.graph.initializer}
    ref_inits["W1"].CopyFrom(onnx.numpy_helper.from_array(info["W1"][keep], "W1"))
    ref_inits["W1_scale"].CopyFrom(
        onnx.numpy_helper.from_array(info["W1_scale"][keep], "W1_scale")
    )
    ref_inits["W1_zp"].CopyFrom(
        onnx.numpy_helper.from_array(info["W1_zp"][keep], "W1_zp")
    )
    ref_inits["B1"].CopyFrom(onnx.numpy_helper.from_array(info["B1"][keep], "B1"))
    ref_inits["W2"].CopyFrom(onnx.numpy_helper.from_array(info["W2"][:, keep], "W2"))
    ref_inits["W2_scale"].CopyFrom(
        onnx.numpy_helper.from_array(info["W2_scale"], "W2_scale")
    )
    ref_inits["W2_zp"].CopyFrom(onnx.numpy_helper.from_array(info["W2_zp"], "W2_zp"))
    ref_inits["B2"].CopyFrom(onnx.numpy_helper.from_array(info["B2"], "B2"))

    rng = np.random.default_rng(11)
    spatial = info["spatial"]
    xq = rng.integers(0, 255, size=(1, C1, spatial, spatial)).astype(np.uint8)

    (y_pruned,) = _run(pruned, {"x_q": xq})
    (y_ref,) = _run(ref_model, {"x_q": xq})
    np.testing.assert_array_equal(y_pruned, y_ref)


def test_qlinearconv_per_tensor_scale_left_untouched():
    model, info = _qlinearconv_chain_model(N1=6, C1=3, N2=4, per_channel=False, seed=3)
    onnx.checker.check_model(model)
    pruned = onnxsim.apply_structured_pruning_qoperator(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    inits = {t.name: t for t in pruned.graph.initializer}
    # per-tensor scale/zero-point are scalars -- never sliced, regardless of
    # channel count
    assert list(inits["W1_scale"].dims) == []
    assert list(inits["W1_zp"].dims) == []
    assert list(inits["W1"].dims) == [3, 3, 3, 3]
    assert list(inits["B1"].dims) == [3]  # bias always co-sliced regardless


def test_qlinearconv_grouped_is_declined():
    model, _info = _qlinearconv_chain_model(N1=6, C1=3, N2=4, seed=4)
    for node in model.graph.node:
        if node.name == "n1":
            node.attribute.append(onnx.helper.make_attribute("group", 3))
    chains = onnxsim.pruning._find_qop_chains(model.graph)
    assert chains == []
    report = onnxsim.analyze_pruning_sensitivity(
        model, onnxsim.apply_structured_pruning_qoperator, sparsity=0.5
    )
    assert report.layers == []
    assert any("n1" in ne for ne in report.not_eligible)


def test_qlinearconv_non_scalar_activation_scale_is_declined():
    model, _info = _qlinearconv_chain_model(N1=6, C1=3, N2=4, seed=5)
    inits = {t.name: t for t in model.graph.initializer}
    inits["y1_scale"].CopyFrom(
        _f32(np.array([0.03, 0.03, 0.03, 0.03, 0.03, 0.03]), "y1_scale")
    )
    chains = onnxsim.pruning._find_qop_chains(model.graph)
    assert chains == []


def test_qlinearconv_tied_weight_is_declined():
    model, _info = _qlinearconv_chain_model(N1=6, C1=3, N2=4, seed=6)
    # a second, unrelated node also reads W1 -- shared/tied, can't be sliced
    extra = onnx.helper.make_node("Identity", ["W1"], ["W1_alias"], name="alias")
    model.graph.node.append(extra)
    model.graph.output.append(
        onnx.helper.make_tensor_value_info(
            "W1_alias", onnx.TensorProto.INT8, [6, 3, 3, 3]
        )
    )
    chains = onnxsim.pruning._find_qop_chains(model.graph)
    assert chains == []


# --- QLinearMatMul --------------------------------------------------------


def _qlinearmatmul_node(
    name, a, y, b, b_scale, b_zp, y_scale, y_zp, a_scale="a_scale", a_zp="a_zp"
):
    return onnx.helper.make_node(
        "QLinearMatMul",
        [a, a_scale, a_zp, b, b_scale, b_zp, y_scale, y_zp],
        [y],
        name=name,
    )


def _qlinearmatmul_chain_model(K=8, H=6, Out=4, seed=0):
    """Builds ``QLinearMatMul(n1) -> QLinearMatMul(n2)`` -- both real,
    per-channel INT8 weights, matching this repo's own
    ``quantize_qoperator`` convention (`b` stored ``[K, N]``, `b_scale`/
    `b_zero_point` per-column).
    """
    rng = np.random.default_rng(seed)
    W1 = rng.standard_normal((K, H)).astype(np.float32) * 0.3
    W2 = rng.standard_normal((H, Out)).astype(np.float32) * 0.3
    W1q, W1s, W1zp = _qop_quantize_per_channel_i8(W1, axis=1)
    W2q, W2s, W2zp = _qop_quantize_per_channel_i8(W2, axis=1)

    a_scale = np.float32(0.02)
    a_zp = np.uint8(120)
    y1_scale = np.float32(0.03)
    y1_zp = np.uint8(120)
    y2_scale = np.float32(0.04)
    y2_zp = np.uint8(120)

    inits = [
        _f32(np.array(a_scale), "a_scale"),
        _u8(np.array(a_zp), "a_zp"),
        onnx.numpy_helper.from_array(W1q, "W1"),
        _f32(W1s, "W1_scale"),
        _i8(W1zp, "W1_zp"),
        _f32(np.array(y1_scale), "y1_scale"),
        _u8(np.array(y1_zp), "y1_zp"),
        onnx.numpy_helper.from_array(W2q, "W2"),
        _f32(W2s, "W2_scale"),
        _i8(W2zp, "W2_zp"),
        _f32(np.array(y2_scale), "y2_scale"),
        _u8(np.array(y2_zp), "y2_zp"),
    ]
    n1 = _qlinearmatmul_node(
        "n1", "x_q", "y1_q", "W1", "W1_scale", "W1_zp", "y1_scale", "y1_zp"
    )
    n2 = _qlinearmatmul_node(
        "n2",
        "y1_q",
        "y2_q",
        "W2",
        "W2_scale",
        "W2_zp",
        "y2_scale",
        "y2_zp",
        a_scale="y1_scale",
        a_zp="y1_zp",
    )
    graph = onnx.helper.make_graph(
        [n1, n2],
        "g",
        [onnx.helper.make_tensor_value_info("x_q", onnx.TensorProto.UINT8, [2, K])],
        [onnx.helper.make_tensor_value_info("y2_q", onnx.TensorProto.UINT8, [2, Out])],
        initializer=inits,
    )
    model = onnx.helper.make_model(
        graph, opset_imports=[onnx.helper.make_opsetid("", 21)]
    )
    model.ir_version = 10
    return model, {
        "W1": W1q,
        "W1_scale": W1s,
        "W1_zp": W1zp,
        "W2": W2q,
        "W2_scale": W2s,
        "W2_zp": W2zp,
    }


def test_qlinearmatmul_producer_matches_independent_oracle():
    K, H, Out = 8, 6, 4
    model, info = _qlinearmatmul_chain_model(K, H, Out, seed=10)
    onnx.checker.check_model(model)

    w1_dequant = _qop_dequant(info["W1"], info["W1_scale"], info["W1_zp"], axis=1)
    keep = np.sort(np.argsort(-np.linalg.norm(w1_dequant.T, axis=1))[: H // 2])

    pruned = onnxsim.apply_structured_pruning_qoperator(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    inits = {t.name: t for t in pruned.graph.initializer}
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["W1"]), info["W1"][:, keep]
    )
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["W1_scale"]), info["W1_scale"][keep]
    )
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["W2"]), info["W2"][keep, :]
    )

    ref_model, _ = _qlinearmatmul_chain_model(K, len(keep), Out, seed=999)
    ref_inits = {t.name: t for t in ref_model.graph.initializer}
    ref_inits["W1"].CopyFrom(onnx.numpy_helper.from_array(info["W1"][:, keep], "W1"))
    ref_inits["W1_scale"].CopyFrom(
        onnx.numpy_helper.from_array(info["W1_scale"][keep], "W1_scale")
    )
    ref_inits["W1_zp"].CopyFrom(
        onnx.numpy_helper.from_array(info["W1_zp"][keep], "W1_zp")
    )
    ref_inits["W2"].CopyFrom(onnx.numpy_helper.from_array(info["W2"][keep, :], "W2"))
    ref_inits["W2_scale"].CopyFrom(
        onnx.numpy_helper.from_array(info["W2_scale"], "W2_scale")
    )
    ref_inits["W2_zp"].CopyFrom(onnx.numpy_helper.from_array(info["W2_zp"], "W2_zp"))

    rng = np.random.default_rng(12)
    xq = rng.integers(0, 255, size=(2, K)).astype(np.uint8)
    (y_pruned,) = _run(pruned, {"x_q": xq})
    (y_ref,) = _run(ref_model, {"x_q": xq})
    np.testing.assert_array_equal(y_pruned, y_ref)


def test_qlinearmatmul_no_flatten_crossing_conv_producer_is_declined():
    # The real onnxruntime.quantization.quantize_static(quant_format=
    # QOperator) round trip this section's own top comment reproduces
    # emits exactly QLinearConv -> Flatten -> QLinearMatMul -- confirmed
    # NOT matched here (same-family-only walk, mirroring the QDQ section's
    # own identical, pre-existing gap for Flatten-crossing chains).
    conv_model, conv_info = _qlinearconv_chain_model(N1=6, C1=3, N2=4, seed=20)
    # Reuse just the first QLinearConv node/initializers, then Flatten into
    # a QLinearMatMul consumer.
    n1 = [n for n in conv_model.graph.node if n.name == "n1"][0]
    keep_inits = [
        t
        for t in conv_model.graph.initializer
        if t.name
        in ("x_scale", "x_zp", "W1", "W1_scale", "W1_zp", "y1_scale", "y1_zp", "B1")
    ]
    spatial = conv_info["spatial"]
    out_spatial = spatial - 3 + 1
    flat_dim = 6 * out_spatial * out_spatial
    Kmm, Out = flat_dim, 4
    rng = np.random.default_rng(21)
    Wmm = rng.standard_normal((Kmm, Out)).astype(np.float32) * 0.3
    Wmmq, Wmms, Wmmzp = _qop_quantize_per_channel_i8(Wmm, axis=1)
    flatten = onnx.helper.make_node("Flatten", ["y1_q"], ["flat_q"], axis=1)
    mm = _qlinearmatmul_node(
        "mm",
        "flat_q",
        "y_q",
        "Wmm",
        "Wmm_scale",
        "Wmm_zp",
        "y2_scale",
        "y2_zp",
        a_scale="y1_scale",
        a_zp="y1_zp",
    )
    inits = list(keep_inits) + [
        onnx.numpy_helper.from_array(Wmmq, "Wmm"),
        _f32(Wmms, "Wmm_scale"),
        _i8(Wmmzp, "Wmm_zp"),
        _f32(np.array(0.05, dtype=np.float32), "y2_scale"),
        _u8(np.array(120, dtype=np.uint8), "y2_zp"),
    ]
    graph = onnx.helper.make_graph(
        [n1, flatten, mm],
        "g",
        [
            onnx.helper.make_tensor_value_info(
                "x_q", onnx.TensorProto.UINT8, [1, 3, spatial, spatial]
            )
        ],
        [onnx.helper.make_tensor_value_info("y_q", onnx.TensorProto.UINT8, [1, Out])],
        initializer=inits,
    )
    model = onnx.helper.make_model(
        graph, opset_imports=[onnx.helper.make_opsetid("", 17)]
    )
    model.ir_version = 10
    onnx.checker.check_model(model)

    chains = onnxsim.pruning._find_qop_chains(model.graph)
    assert chains == []  # declined -- see this test's own comment above
    pruned = onnxsim.apply_structured_pruning_qoperator(model, sparsity=0.5)
    # nothing changes -- no matched chain to prune
    assert list([t for t in pruned.graph.initializer if t.name == "W1"][0].dims) == [
        6,
        3,
        3,
        3,
    ]


# --- QGemm ------------------------------------------------------------


def _qgemm_node(name, a, y, b, b_scale, b_zp, c, y_scale, y_zp, **attrs):
    inputs = [a, "a_scale", "a_zp", b, b_scale, b_zp]
    inputs.append(c or "")
    inputs.append(y_scale or "")
    inputs.append(y_zp or "")
    while inputs and not inputs[-1]:
        inputs.pop()
    return onnx.helper.make_node(
        "QGemm", inputs, [y], domain="com.microsoft", name=name, **attrs
    )


def _qgemm_chain_model(K=8, H=6, Out=4, transB1=0, transB2=0, bias=True, seed=0):
    rng = np.random.default_rng(seed)
    W1f = rng.standard_normal((H, K) if transB1 else (K, H)).astype(np.float32) * 0.3
    W2f = (
        rng.standard_normal((Out, H) if transB2 else (H, Out)).astype(np.float32) * 0.3
    )
    axis1 = 0 if transB1 else 1
    axis2 = 0 if transB2 else 1
    W1q, W1s, W1zp = _qop_quantize_per_channel_i8(W1f, axis=axis1)
    W2q, W2s, W2zp = _qop_quantize_per_channel_i8(W2f, axis=axis2)

    a_scale = np.float32(0.02)
    a_zp = np.uint8(120)
    y1_scale = np.float32(0.03)
    y1_zp = np.uint8(120)
    y2_scale = np.float32(0.04)
    y2_zp = np.uint8(120)

    C1f = (rng.standard_normal(H).astype(np.float32) * 0.05) if bias else None
    C2f = (rng.standard_normal(Out).astype(np.float32) * 0.05) if bias else None
    C1q = None
    if C1f is not None:
        c1_scale = a_scale.astype(np.float64) * W1s.astype(np.float64)
        C1q = np.round(C1f.astype(np.float64) / c1_scale).astype(np.int32)
    C2q = None
    if C2f is not None:
        c2_scale = y1_scale.astype(np.float64) * W2s.astype(np.float64)
        C2q = np.round(C2f.astype(np.float64) / c2_scale).astype(np.int32)

    inits = [
        _f32(np.array(a_scale), "a_scale"),
        _u8(np.array(a_zp), "a_zp"),
        onnx.numpy_helper.from_array(W1q, "W1"),
        _f32(W1s, "W1_scale"),
        _i8(W1zp, "W1_zp"),
        _f32(np.array(y1_scale), "y1_scale"),
        _u8(np.array(y1_zp), "y1_zp"),
        onnx.numpy_helper.from_array(W2q, "W2"),
        _f32(W2s, "W2_scale"),
        _i8(W2zp, "W2_zp"),
        _f32(np.array(y2_scale), "y2_scale"),
        _u8(np.array(y2_zp), "y2_zp"),
    ]
    if C1q is not None:
        inits.append(_i32(C1q, "C1"))
    if C2q is not None:
        inits.append(_i32(C2q, "C2"))

    n1 = _qgemm_node(
        "n1",
        "x_q",
        "y1_q",
        "W1",
        "W1_scale",
        "W1_zp",
        "C1" if C1q is not None else None,
        "y1_scale",
        "y1_zp",
        transB=transB1,
    )
    n2 = _qgemm_node(
        "n2",
        "y1_q",
        "y2_q",
        "W2",
        "W2_scale",
        "W2_zp",
        "C2" if C2q is not None else None,
        "y2_scale",
        "y2_zp",
        transB=transB2,
    )
    n2.input[1] = "y1_scale"
    n2.input[2] = "y1_zp"
    graph = onnx.helper.make_graph(
        [n1, n2],
        "g",
        [onnx.helper.make_tensor_value_info("x_q", onnx.TensorProto.UINT8, [2, K])],
        [onnx.helper.make_tensor_value_info("y2_q", onnx.TensorProto.UINT8, [2, Out])],
        initializer=inits,
    )
    model = onnx.helper.make_model(
        graph,
        opset_imports=[
            onnx.helper.make_opsetid("", 17),
            onnx.helper.make_opsetid("com.microsoft", 1),
        ],
    )
    model.ir_version = 10
    return model, {
        "W1": W1q,
        "W1_scale": W1s,
        "W1_zp": W1zp,
        "C1": C1q,
        "W2": W2q,
        "W2_scale": W2s,
        "W2_zp": W2zp,
        "C2": C2q,
        "transB1": transB1,
        "transB2": transB2,
    }


@pytest.mark.parametrize("transB1,transB2", [(0, 0), (1, 0), (0, 1), (1, 1)])
def test_qgemm_producer_consumer_transb_matches_independent_oracle(transB1, transB2):
    K, H, Out = 8, 6, 4
    model, info = _qgemm_chain_model(
        K, H, Out, transB1=transB1, transB2=transB2, seed=30
    )
    onnx.checker.check_model(model)

    axis1 = 0 if transB1 else 1
    w1_dequant = _qop_dequant(info["W1"], info["W1_scale"], info["W1_zp"], axis=axis1)
    w1_nk = w1_dequant if transB1 else w1_dequant.T
    keep = np.sort(np.argsort(-np.linalg.norm(w1_nk, axis=1))[: H // 2])

    pruned = onnxsim.apply_structured_pruning_qoperator(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    inits = {t.name: t for t in pruned.graph.initializer}

    w1_expected = info["W1"][keep, :] if transB1 else info["W1"][:, keep]
    w2_expected = info["W2"][:, keep] if transB2 else info["W2"][keep, :]
    np.testing.assert_array_equal(onnx.numpy_helper.to_array(inits["W1"]), w1_expected)
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["W1_scale"]), info["W1_scale"][keep]
    )
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["C1"]), info["C1"][keep]
    )
    np.testing.assert_array_equal(onnx.numpy_helper.to_array(inits["W2"]), w2_expected)

    ref_model, _ = _qgemm_chain_model(
        K, len(keep), Out, transB1=transB1, transB2=transB2, seed=555
    )
    ref_inits = {t.name: t for t in ref_model.graph.initializer}
    ref_inits["W1"].CopyFrom(onnx.numpy_helper.from_array(w1_expected, "W1"))
    ref_inits["W1_scale"].CopyFrom(
        onnx.numpy_helper.from_array(info["W1_scale"][keep], "W1_scale")
    )
    ref_inits["W1_zp"].CopyFrom(
        onnx.numpy_helper.from_array(info["W1_zp"][keep], "W1_zp")
    )
    ref_inits["C1"].CopyFrom(onnx.numpy_helper.from_array(info["C1"][keep], "C1"))
    ref_inits["W2"].CopyFrom(onnx.numpy_helper.from_array(w2_expected, "W2"))
    ref_inits["W2_scale"].CopyFrom(
        onnx.numpy_helper.from_array(info["W2_scale"], "W2_scale")
    )
    ref_inits["W2_zp"].CopyFrom(onnx.numpy_helper.from_array(info["W2_zp"], "W2_zp"))
    ref_inits["C2"].CopyFrom(onnx.numpy_helper.from_array(info["C2"], "C2"))

    rng = np.random.default_rng(31)
    xq = rng.integers(0, 255, size=(2, K)).astype(np.uint8)
    (y_pruned,) = _run(pruned, {"x_q": xq})
    (y_ref,) = _run(ref_model, {"x_q": xq})
    np.testing.assert_array_equal(y_pruned, y_ref)


