# --- QLinearConv -> QLinearGlobalAveragePool -> classifier head -----------
#
# The classifier-head hop `_walk_to_qop_consumer` gained, mirroring the
# plain-float Conv chain's own `recognize_gap_flatten_matmul_consumer` hop
# and the `ConvInteger` section's own analogous one: a `QLinearConv`
# producer's logical output feeding
# `com.microsoft::QLinearGlobalAveragePool -> {Flatten(axis=1), Reshape to
# [batch, -1], Squeeze-of-trailing-axes} -> {QLinearMatMul, QGemm}` directly
# is now matched and pruned. Unlike the `ConvInteger` section's identical
# hop (whose matched classifier consumer is always plain float, since that
# section's own rescale `Mul`/`Cast` pair already produced a plain float
# logical output before this point), the tensor reaching
# `QLinearGlobalAveragePool` here is still quantized int8/uint8 throughout,
# so the matched consumer is a real `QLinearMatMul`/`QGemm` -- a `_QOpWeight`
# exactly like this section's own ordinary same-family consumer, needing no
# dedicated side-channel field on `_QOpChain` at all.


def _qlinear_gap_node(x, x_scale, x_zp, y_scale, y_zp, y, name="gap", **attrs):
    return onnx.helper.make_node(
        "QLinearGlobalAveragePool",
        [x, x_scale, x_zp, y_scale, y_zp],
        [y],
        domain="com.microsoft",
        name=name,
        **attrs,
    )


def _qlinearconv_gap_flatten_qgemm_model(
    N1=6, C1=3, N2=4, Out=5, kh=3, kw=3, spatial=8, seed=0
):
    """Builds ``QLinearConv(n1) -> QLinearConv(n2) ->
    QLinearGlobalAveragePool -> Flatten(axis=1) -> QGemm`` -- the real shape
    ``onnxruntime.quantization.quantize_static(quant_format=QuantFormat
    .QOperator)`` emits for a ``Conv -> Conv -> GlobalAveragePool ->
    Flatten -> Gemm`` classifier head (confirmed live -- see this section's
    own top comment). `n2`'s own logical output (`y2_q`) feeds
    `QLinearGlobalAveragePool` directly, whose own `x_scale`/`x_zero_point`
    are the SAME `y2_scale`/`y2_zero_point` initializers `n2` itself
    produces -- exactly the tied-initializer shape a real exporter emits
    (`QGlobalAveragePool`'s own quantizer source just reuses its input's
    existing quantized-value scale/zero-point when none is calibrated
    separately for the pooled output)."""
    rng = np.random.default_rng(seed)
    W1 = rng.standard_normal((N1, C1, kh, kw)).astype(np.float32) * 0.3
    W2 = rng.standard_normal((N2, N1, 1, 1)).astype(np.float32) * 0.3
    Wfc = rng.standard_normal((Out, N2)).astype(np.float32) * 0.3
    Bfc = rng.standard_normal(Out).astype(np.float32) * 0.05

    x_scale = np.float32(0.02)
    x_zp = np.uint8(120)
    W1q, W1s, W1zp = _qop_quantize_per_channel_i8(W1, axis=0)
    W2q, W2s, W2zp = _qop_quantize_per_channel_i8(W2, axis=0)
    y1_scale = np.float32(0.03)
    y1_zp = np.uint8(120)
    y2_scale = np.float32(0.04)
    y2_zp = np.uint8(120)
    gap_scale = np.float32(0.05)
    gap_zp = np.uint8(118)
    y_scale = np.float32(0.06)
    y_zp = np.uint8(120)

    # QGemm's own `B` is stored `[K, N]` here (transB=0), matching this
    # section's own `_qgemm_chain_model` default convention.
    WfcT = Wfc.T  # (N2, Out) == (K, Out)
    Wfcq, Wfcs, Wfczp = _qop_quantize_per_channel_i8(WfcT, axis=1)
    Cfc_dequant_scale = gap_scale.astype(np.float64) * Wfcs.astype(np.float64)
    Cfcq = np.round(Bfc.astype(np.float64) / Cfc_dequant_scale).astype(np.int32)

    inits = [
        _f32(np.array(x_scale), "x_scale"),
        _u8(np.array(x_zp), "x_zp"),
        onnx.numpy_helper.from_array(W1q, "W1"),
        _f32(np.atleast_1d(W1s), "W1_scale"),
        _i8(np.atleast_1d(W1zp), "W1_zp"),
        _f32(np.array(y1_scale), "y1_scale"),
        _u8(np.array(y1_zp), "y1_zp"),
        onnx.numpy_helper.from_array(W2q, "W2"),
        _f32(np.atleast_1d(W2s), "W2_scale"),
        _i8(np.atleast_1d(W2zp), "W2_zp"),
        _f32(np.array(y2_scale), "y2_scale"),
        _u8(np.array(y2_zp), "y2_zp"),
        _f32(np.array(gap_scale), "gap_scale"),
        _u8(np.array(gap_zp), "gap_zp"),
        onnx.numpy_helper.from_array(Wfcq, "Wfc"),
        _f32(Wfcs, "Wfc_scale"),
        _i8(Wfczp, "Wfc_zp"),
        _i32(Cfcq, "Cfc"),
        _f32(np.array(y_scale), "y_scale"),
        _u8(np.array(y_zp), "y_zp"),
    ]
    n1 = _qlinearconv_node(
        "n1",
        "x_q",
        "y1_q",
        "W1",
        "W1_scale",
        "W1_zp",
        "y1_scale",
        "y1_zp",
        None,
        kernel_shape=[kh, kw],
        pads=[0, 0, 0, 0],
    )
    n2 = _qlinearconv_node(
        "n2",
        "y1_q",
        "y2_q",
        "W2",
        "W2_scale",
        "W2_zp",
        "y2_scale",
        "y2_zp",
        None,
        x_scale="y1_scale",
        x_zp="y1_zp",
        kernel_shape=[1, 1],
        pads=[0, 0, 0, 0],
    )
    gap = _qlinear_gap_node("y2_q", "y2_scale", "y2_zp", "gap_scale", "gap_zp", "gap_q")
    flatten = onnx.helper.make_node("Flatten", ["gap_q"], ["flat_q"], axis=1)
    gemm = _qgemm_node(
        "mm", "flat_q", "y_q", "Wfc", "Wfc_scale", "Wfc_zp", "Cfc", "y_scale", "y_zp"
    )
    # `_qgemm_node` hardcodes its own `a_scale`/`a_zero_point` inputs to the
    # literal names ``"a_scale"``/``"a_zp"`` -- overridden here to this
    # consumer's real `a` operand's own scale/zero-point (`gap_scale`/
    # `gap_zp`, the `QLinearGlobalAveragePool`'s own output pair), mirroring
    # `_qgemm_chain_model`'s own identical post-hoc override for its second
    # `QGemm` node.
    gemm.input[1] = "gap_scale"
    gemm.input[2] = "gap_zp"
    graph = onnx.helper.make_graph(
        [n1, n2, gap, flatten, gemm],
        "g",
        [
            onnx.helper.make_tensor_value_info(
                "x_q", onnx.TensorProto.UINT8, [1, C1, spatial, spatial]
            )
        ],
        [onnx.helper.make_tensor_value_info("y_q", onnx.TensorProto.UINT8, [1, Out])],
        initializer=inits,
    )
    model = onnx.helper.make_model(
        graph,
        opset_imports=[
            onnx.helper.make_opsetid("", 17),
            onnx.helper.make_opsetid("com.microsoft", 1),
        ],
    )
    model.ir_version = 10
    return model, {
        "W1": W1q,
        "W1_scale": W1s,
        "W1_zp": W1zp,
        "W2": W2q,
        "W2_scale": W2s,
        "W2_zp": W2zp,
        "Wfc": Wfcq,
        "Wfc_scale": Wfcs,
        "Wfc_zp": Wfczp,
        "Cfc": Cfcq,
        "spatial": spatial,
        "C1": C1,
        "N1": N1,
        "N2": N2,
        "Out": Out,
    }


def test_qlinear_gap_flatten_qgemm_is_matched_and_prunes():
    N1, C1, N2, Out = 6, 3, 8, 5
    model, info = _qlinearconv_gap_flatten_qgemm_model(
        N1=N1, C1=C1, N2=N2, Out=Out, seed=60
    )
    onnx.checker.check_model(model)

    chains = onnxsim.pruning._find_qop_chains(model.graph)
    assert len(chains) == 2
    gap_chain = next(ch for ch in chains if ch.consumer.op_kind == "gemm")
    assert gap_chain.producer.node.name == "n2"
    assert gap_chain.n_channels == N2
    assert [n.op_type for n in gap_chain.chain_ops] == [
        "QLinearGlobalAveragePool",
        "Flatten",
    ]

    # `n2` legitimately plays BOTH roles across the two chains -- consumer
    # (its own `K`/`N1` axis, sliced first, in `graph.node` order) of the
    # `n1` producer chain, then producer (its own `N`/`N2` axis, importance
    # ranked on the ALREADY consumer-sliced array) of this new classifier-
    # head chain -- exactly the same sequential mutation order this
    # section's `ConvInteger` analogue's own identical test documents.
    w1_dequant = _qop_dequant(info["W1"], info["W1_scale"], info["W1_zp"], axis=0)
    keep1 = np.sort(
        np.argsort(-np.linalg.norm(w1_dequant.reshape(N1, -1), axis=1))[: N1 // 2]
    )
    w2_after_consumer_slice = info["W2"][:, keep1]
    w2_dequant = _qop_dequant(
        w2_after_consumer_slice, info["W2_scale"], info["W2_zp"], axis=0
    )
    keep2 = np.sort(
        np.argsort(-np.linalg.norm(w2_dequant.reshape(N2, -1), axis=1))[: N2 // 2]
    )
    w2_final = w2_after_consumer_slice[keep2]

    pruned = onnxsim.apply_structured_pruning_qoperator(model, sparsity=0.5)
    onnx.checker.check_model(pruned)
    inits = {t.name: t for t in pruned.graph.initializer}

    # byte-identity: "slice, don't recompute" -- the second QLinearConv's own
    # output-channel axis and the QGemm's own matching input (reduction)
    # axis are both an exact hand-slice of the originals.
    np.testing.assert_array_equal(onnx.numpy_helper.to_array(inits["W2"]), w2_final)
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["W2_scale"]), info["W2_scale"][keep2]
    )
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["W2_zp"]), info["W2_zp"][keep2]
    )
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["Wfc"]), info["Wfc"][keep2, :]
    )
    # QGemm's own consumer-role slicing never touches scale/zero-point/bias
    # -- none of them are indexed by the reduction axis (see this module's
    # own "QOperator" section top comment).
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["Wfc_scale"]), info["Wfc_scale"]
    )
    np.testing.assert_array_equal(onnx.numpy_helper.to_array(inits["Cfc"]), info["Cfc"])

    # Independently reconstructed "already pruned" reference model, run
    # through a real InferenceSession alongside the pruned one -- mirrors
    # `test_qlinearconv_producer_matches_independent_oracle_via_real_inference_session`'s
    # own identical pattern.
    ref_model, _ = _qlinearconv_gap_flatten_qgemm_model(
        N1=len(keep1), C1=C1, N2=len(keep2), Out=Out, seed=999
    )
    ref_inits = {t.name: t for t in ref_model.graph.initializer}
    ref_inits["W1"].CopyFrom(onnx.numpy_helper.from_array(info["W1"][keep1], "W1"))
    ref_inits["W1_scale"].CopyFrom(
        onnx.numpy_helper.from_array(info["W1_scale"][keep1], "W1_scale")
    )
    ref_inits["W1_zp"].CopyFrom(
        onnx.numpy_helper.from_array(info["W1_zp"][keep1], "W1_zp")
    )
    ref_inits["W2"].CopyFrom(onnx.numpy_helper.from_array(w2_final, "W2"))
    ref_inits["W2_scale"].CopyFrom(
        onnx.numpy_helper.from_array(info["W2_scale"][keep2], "W2_scale")
    )
    ref_inits["W2_zp"].CopyFrom(
        onnx.numpy_helper.from_array(info["W2_zp"][keep2], "W2_zp")
    )
    ref_inits["Wfc"].CopyFrom(
        onnx.numpy_helper.from_array(info["Wfc"][keep2, :], "Wfc")
    )
    ref_inits["Wfc_scale"].CopyFrom(
        onnx.numpy_helper.from_array(info["Wfc_scale"], "Wfc_scale")
    )
    ref_inits["Wfc_zp"].CopyFrom(onnx.numpy_helper.from_array(info["Wfc_zp"], "Wfc_zp"))
    ref_inits["Cfc"].CopyFrom(onnx.numpy_helper.from_array(info["Cfc"], "Cfc"))

    rng = np.random.default_rng(61)
    xq = rng.integers(0, 255, size=(1, C1, info["spatial"], info["spatial"])).astype(
        np.uint8
    )
    (y_pruned,) = _run(pruned, {"x_q": xq})
    (y_ref,) = _run(ref_model, {"x_q": xq})
    np.testing.assert_array_equal(y_pruned, y_ref)


def test_qlinear_gap_non_scalar_activation_scale_is_declined():
    # A non-scalar `x_scale` on `QLinearGlobalAveragePool` -- never confirmed
    # emitted by any real exporter (see this section's own top comment) --
    # is declined outright, ending that hop's own chain unmatched rather
    # than guessed at.
    N1, C1, N2, Out = 6, 3, 4, 5
    model, _info = _qlinearconv_gap_flatten_qgemm_model(N1=N1, C1=C1, N2=N2, Out=Out)
    gap_node = next(n for n in model.graph.node if n.name == "gap")
    bad_scale = onnx.numpy_helper.from_array(
        np.array([0.05, 0.05], dtype=np.float32), "y2_scale_bad"
    )
    model.graph.initializer.append(bad_scale)
    gap_node.input[1] = "y2_scale_bad"

    chains = onnxsim.pruning._find_qop_chains(model.graph)
    assert len(chains) == 1  # only the ordinary QLinearConv->QLinearConv chain
    assert chains[0].producer.node.name == "n1"


def test_qlinear_gap_channels_last_nonzero_is_declined():
    # `channels_last=1` (NHWC) is never confirmed emitted by any real
    # exporter -- declined outright rather than assumed safe.
    N1, C1, N2, Out = 6, 3, 4, 5
    model, _info = _qlinearconv_gap_flatten_qgemm_model(N1=N1, C1=C1, N2=N2, Out=Out)
    gap_node = next(n for n in model.graph.node if n.name == "gap")
    gap_node.attribute.append(onnx.helper.make_attribute("channels_last", 1))

    chains = onnxsim.pruning._find_qop_chains(model.graph)
    assert len(chains) == 1
    assert chains[0].producer.node.name == "n1"


def test_qlinear_gap_flatten_wrong_axis_is_declined():
    # `Flatten` with a non-default `axis` merges more than one non-batch
    # axis (or part of the batch axis) into the channel one -- the *general*
    # Flatten problem this hop doesn't attempt (mirrors the plain-float/
    # ConvInteger sections' own identical decline).
    N1, C1, N2, Out = 6, 3, 4, 5
    model, _info = _qlinearconv_gap_flatten_qgemm_model(N1=N1, C1=C1, N2=N2, Out=Out)
    flatten_node = next(n for n in model.graph.node if n.op_type == "Flatten")
    for attr in list(flatten_node.attribute):
        flatten_node.attribute.remove(attr)
    flatten_node.attribute.append(onnx.helper.make_attribute("axis", 0))

    chains = onnxsim.pruning._find_qop_chains(model.graph)
    assert len(chains) == 1
    assert chains[0].producer.node.name == "n1"


def test_qlinear_gap_flatten_qgemm_real_quantize_static_pipeline_end_to_end():
    # The full end-to-end pipeline: runs the REAL
    # ``onnxruntime.quantization.quantize_static(quant_format=QuantFormat
    # .QOperator)`` tool on a plain float `Conv -> Relu -> Conv -> Relu ->
    # GlobalAveragePool -> Flatten(axis=1) -> Gemm` model, then confirms the
    # SECOND (widest) Conv layer -- the one feeding the classifier head
    # through `QLinearGlobalAveragePool` -- is matched and prunable, together
    # with the QGemm classifier consumer's matching input channels. This is
    # the exact real-world gap this round's task fixes: before this change,
    # `_find_qop_chains` matched only the FIRST QLinearConv->QLinearConv
    # chain, leaving the last, widest backbone layer completely untouched.
    from onnxruntime.quantization import (
        CalibrationDataReader,
        QuantFormat,
        QuantType,
        quantize_static,
    )

    N, c, spatial = 1, 3, 8
    m1, m2, out = 6, 8, 5
    rng = np.random.default_rng(70)
    w0 = (rng.standard_normal((m1, c, 3, 3)) * 0.3).astype(np.float32)
    w1 = (rng.standard_normal((m2, m1, 3, 3)) * 0.3).astype(np.float32)
    w2 = (rng.standard_normal((out, m2)) * 0.3).astype(np.float32)
    float_model = _model(
        f"""
        g (float[{N},{c},{spatial},{spatial}] x) => (float[{N},{out}] y)
        {{
          h0 = Conv<kernel_shape=[3,3], pads=[1,1,1,1]>(x, W0)
          h0a = Relu(h0)
          h1 = Conv<kernel_shape=[3,3], pads=[1,1,1,1]>(h0a, W1)
          h1a = Relu(h1)
          p = GlobalAveragePool(h1a)
          f = Flatten<axis=1>(p)
          y = Gemm<transB=1>(f, W2)
        }}
        """,
        initializer=[_f32(w0, "W0"), _f32(w1, "W1"), _f32(w2, "W2")],
        opset=17,
    )

    class _CDR(CalibrationDataReader):
        def __init__(self):
            rng2 = np.random.default_rng(71)
            self._data = iter(
                [
                    {
                        "x": rng2.standard_normal((N, c, spatial, spatial)).astype(
                            np.float32
                        )
                    }
                    for _ in range(5)
                ]
            )

        def get_next(self):
            return next(self._data, None)

    with tempfile.TemporaryDirectory() as d:
        src_path = os.path.join(d, "src.onnx")
        quant_path = os.path.join(d, "quant.onnx")
        onnx.save(float_model, src_path)
        quantize_static(
            src_path,
            quant_path,
            _CDR(),
            quant_format=QuantFormat.QOperator,
            weight_type=QuantType.QInt8,
            activation_type=QuantType.QUInt8,
        )
        quantized = onnx.load(quant_path)

    op_types = [n.op_type for n in quantized.graph.node]
    assert op_types.count("QLinearConv") == 2
    assert "QLinearGlobalAveragePool" in op_types
    assert op_types.count("QGemm") == 1

    chains = onnxsim.pruning._find_qop_chains(quantized.graph)
    assert len(chains) == 2
    gap_chain = next(ch for ch in chains if ch.consumer.op_kind == "gemm")
    assert gap_chain.n_channels == m2
    assert [n.op_type for n in gap_chain.chain_ops] == [
        "QLinearGlobalAveragePool",
        "Flatten",
    ]

    pruned = onnxsim.apply_structured_pruning_qoperator(quantized, sparsity=0.5)
    onnx.checker.check_model(pruned)
    pruned_inits = {t.name: list(t.dims) for t in pruned.graph.initializer}
    conv_nodes = [n for n in pruned.graph.node if n.op_type == "QLinearConv"]
    # The SECOND (widest) QLinearConv's own output-channel axis is pruned --
    # the last, widest backbone layer a human would most want prunable.
    last_conv_weight = conv_nodes[-1].input[3]
    assert pruned_inits[last_conv_weight][0] == m2 - round(m2 * 0.5)
    gemm_node = next(n for n in pruned.graph.node if n.op_type == "QGemm")
    gemm_weight = gemm_node.input[3]
    trans_b = any(a.name == "transB" and a.i for a in gemm_node.attribute)
    k_axis = 1 if trans_b else 0  # QGemm stores B [N, K] when transB else [K, N]
    assert pruned_inits[gemm_weight][k_axis] == m2 - round(m2 * 0.5)

    # The pruned graph's own top-level input is still the original float
    # graph input `x` (`QuantizeLinear`'s own first input) -- a real
    # end-to-end numeric sanity check through the full quantized pipeline.
    x = rng.standard_normal((N, c, spatial, spatial)).astype(np.float32)
    (y_pruned,) = _run(pruned, {"x": x})
    assert y_pruned.shape == (N, out)
    assert np.all(np.isfinite(y_pruned))


# --- DynamicQuantizeMatMul / MatMulIntegerToFloat --------------------------
#
# ``com.microsoft::DynamicQuantizeMatMul``/``MatMulIntegerToFloat`` are ONNX
# Runtime graph-optimizer FUSIONS of the dynamic-quantization MatMul pattern
# ``onnxruntime.quantization.quantize_dynamic()`` emits
# (``DynamicQuantizeLinear -> MatMulInteger -> Cast -> Mul``) -- see
# onnxsim/pruning.py's own "DynamicQuantizeMatMul / MatMulIntegerToFloat"
# section comment for the full empirical investigation this pass's scope
# was reached from (live schema introspection, the real fused node
# sequences reproduced via a genuine ``quantize_dynamic`` ->
# ``InferenceSession``-optimize round trip, and why every scope boundary is
# drawn where it is).
#
# Fixture weights are quantized via the REAL
# ``onnxruntime.quantization.quantize_dynamic`` tool -- never a hand-rolled
# re-implementation of the quantization scheme -- by wrapping each weight in
# a minimal ``Y = MatMul(X, W)`` model, running the real tool on it, and
# reading back its own emitted ``W_quantized``/``W_scale``/``W_zero_point``
# initializers (:func:`_quantize_dynamic_weight`). The graph skeleton
# actually under test is then built directly via ``onnx.parser.parse_model``
# (this file's own ``_model`` helper) with those genuine quantized tensors
# attached programmatically afterward -- the same "real quantizer for
# fixtures, parser for graph structure" pattern this repo's own CLAUDE.md
# and the MatMulBnb4-round tests above establish (the scale/zero-point/int8
# tensors need real array data a parser text literal can't spell out).
#
# One test below (`test_dynamic_quantize_matmul_real_quantize_dynamic_pipeline_end_to_end`)
# goes further still: it runs the REAL ``quantize_dynamic`` tool on a plain
# float model AND a real ``InferenceSession``'s default graph optimization
# on the result -- the exact same two-step reproduction this section's own
# top comment describes -- so that test's own fixture is not merely
# *quantized* by real tooling but *fused* by it too, the strongest
# confirmation available that this pass matches what a real deployment
# graph actually looks like.


def _quantize_dynamic_weight(W, per_channel=True):
    """Runs the REAL ``onnxruntime.quantization.quantize_dynamic`` tool on a
    minimal ``Y = MatMul(X, W)`` wrapper model and returns the genuine
    quantized ``(W_int8[K,N], W_scale, W_zero_point)`` triple it emits for
    `W` -- never a hand-rolled re-implementation of the quantization
    scheme.
    """
    from onnxruntime.quantization import QuantType, quantize_dynamic

    K, N = W.shape
    src = _model(
        f"""
        g (float[1,{K}] X) => (float[1,{N}] Y)
        {{
          Y = MatMul(X, W)
        }}
        """,
        initializer=[_f32(W, "W")],
        opset=21,
    )
    with tempfile.TemporaryDirectory() as d:
        src_path = os.path.join(d, "src.onnx")
        dst_path = os.path.join(d, "dst.onnx")
        onnx.save(src, src_path)
        quantize_dynamic(
            src_path, dst_path, per_channel=per_channel, weight_type=QuantType.QInt8
        )
        q = onnx.load(dst_path)
    inits = {t.name: t for t in q.graph.initializer}
    Wq = onnx.numpy_helper.to_array(inits["W_quantized"]).copy()
    Wscale = onnx.numpy_helper.to_array(inits["W_scale"]).copy()
    Wzp = onnx.numpy_helper.to_array(inits["W_zero_point"]).copy()
    return Wq, Wscale, Wzp


def _dqmm_model_from_weights(
    K, N1, N2, W1f, W2f, per_channel=True, activation="Relu", B1f=None, seed=0
):
    """Builds ``DynamicQuantizeMatMul(mm1) -> activation ->
    DynamicQuantizeMatMul(mm2)`` -- a same-family chain -- from explicit
    float weights, quantized via the real tool (:func:`_quantize_dynamic_weight`).
    Returns ``(model, info)`` where `info` carries every float/quantized
    array needed to hand-build an "already pruned" oracle.
    """
    W1q, W1s, W1zp = _quantize_dynamic_weight(W1f, per_channel)
    W2q, W2s, W2zp = _quantize_dynamic_weight(W2f, per_channel)

    bias_arg = ", B1" if B1f is not None else ""
    body = f"""
    g (float[1,{K}] X) => (float[1,{N2}] Y)
    {{
      h1 = com.microsoft.DynamicQuantizeMatMul(X, W1, W1_scale, W1_zero_point{bias_arg})
      h1_act = {activation}(h1)
      Y = com.microsoft.DynamicQuantizeMatMul(h1_act, W2, W2_scale, W2_zero_point)
    }}
    """
    inits = [
        onnx.numpy_helper.from_array(W1q, "W1"),
        onnx.numpy_helper.from_array(W1s, "W1_scale"),
        onnx.numpy_helper.from_array(W1zp, "W1_zero_point"),
        onnx.numpy_helper.from_array(W2q, "W2"),
        onnx.numpy_helper.from_array(W2s, "W2_scale"),
        onnx.numpy_helper.from_array(W2zp, "W2_zero_point"),
    ]
    if B1f is not None:
        inits.append(_f32(B1f, "B1"))
    model = _model(body, initializer=inits, opset=21)
    model.opset_import.append(onnx.helper.make_opsetid("com.microsoft", 1))
    return model, {
        "W1f": W1f,
        "W2f": W2f,
        "B1f": B1f,
        "W1q": W1q,
        "W1s": W1s,
        "W1zp": W1zp,
        "W2q": W2q,
        "W2s": W2s,
        "W2zp": W2zp,
    }


def _dqmm_chain_model(
    K, N1, N2, per_channel=True, activation="Relu", bias1=False, seed=0
):
    rng = np.random.default_rng(seed)
    W1f = (rng.standard_normal((K, N1)) * 0.3).astype(np.float32)
    W2f = (rng.standard_normal((N1, N2)) * 0.3).astype(np.float32)
    B1f = (rng.standard_normal(N1) * 0.05).astype(np.float32) if bias1 else None
    return _dqmm_model_from_weights(
        K, N1, N2, W1f, W2f, per_channel=per_channel, activation=activation, B1f=B1f
    )


def _dqmm_mixed_model(K, N1, N2, per_channel=True, quantized="producer", seed=0):
    """`quantized="producer"`: ``DynamicQuantizeMatMul(mm1) -> Relu ->
    plain MatMul(mm2)``. `quantized="consumer"`: ``plain MatMul(mm1) ->
    Relu -> DynamicQuantizeMatMul(mm2)``. Mirrors the real partial-
    quantization shape confirmed via `quantize_dynamic`'s own
    `nodes_to_exclude` (see onnxsim/pruning.py's own section comment).
    """
    rng = np.random.default_rng(seed)
    W1f = (rng.standard_normal((K, N1)) * 0.3).astype(np.float32)
    W2f = (rng.standard_normal((N1, N2)) * 0.3).astype(np.float32)
    if quantized == "producer":
        W1q, W1s, W1zp = _quantize_dynamic_weight(W1f, per_channel)
        body = f"""
        g (float[1,{K}] X) => (float[1,{N2}] Y)
        {{
          h1 = com.microsoft.DynamicQuantizeMatMul(X, W1, W1_scale, W1_zero_point)
          h1_act = Relu(h1)
          Y = MatMul(h1_act, W2)
        }}
        """
        inits = [
            onnx.numpy_helper.from_array(W1q, "W1"),
            onnx.numpy_helper.from_array(W1s, "W1_scale"),
            onnx.numpy_helper.from_array(W1zp, "W1_zero_point"),
            _f32(W2f, "W2"),
        ]
        info = {"W1f": W1f, "W1q": W1q, "W1s": W1s, "W1zp": W1zp, "W2f": W2f}
    else:
        W2q, W2s, W2zp = _quantize_dynamic_weight(W2f, per_channel)
        body = f"""
        g (float[1,{K}] X) => (float[1,{N2}] Y)
        {{
          h1 = MatMul(X, W1)
          h1_act = Relu(h1)
          Y = com.microsoft.DynamicQuantizeMatMul(h1_act, W2, W2_scale, W2_zero_point)
        }}
        """
        inits = [
            _f32(W1f, "W1"),
            onnx.numpy_helper.from_array(W2q, "W2"),
            onnx.numpy_helper.from_array(W2s, "W2_scale"),
            onnx.numpy_helper.from_array(W2zp, "W2_zero_point"),
        ]
        info = {"W1f": W1f, "W2f": W2f, "W2q": W2q, "W2s": W2s, "W2zp": W2zp}
    model = _model(body, initializer=inits, opset=21)
    model.opset_import.append(onnx.helper.make_opsetid("com.microsoft", 1))
    return model, info


def _m2f_model(K, N1, N2, per_channel=True, seed=0):
    """``MatMulIntegerToFloat(mm1) -> Relu -> plain MatMul(mm2)``, `A`
    pre-quantized as a genuine uint8 graph input. `a_scale`/`a_zero_point`
    are supplied as plain constants -- never touched by this pass (see
    this module's own section comment for why: they are never constant
    initializers in a real fusion output at all, but that doesn't matter
    here since nothing about this pass reads them).
    """
    rng = np.random.default_rng(seed)
    W1f = (rng.standard_normal((K, N1)) * 0.3).astype(np.float32)
    W2f = (rng.standard_normal((N1, N2)) * 0.3).astype(np.float32)
    W1q, W1s, W1zp = _quantize_dynamic_weight(W1f, per_channel)
    body = f"""
    g (uint8[1,{K}] Xq) => (float[1,{N2}] Y)
    {{
      h1 = com.microsoft.MatMulIntegerToFloat(Xq, W1, x_scale, W1_scale, x_zero_point, W1_zero_point)
      h1_act = Relu(h1)
      Y = MatMul(h1_act, W2)
    }}
    """
    inits = [
        _f32(np.array(0.01), "x_scale"),
        _u8(np.array(120), "x_zero_point"),
        onnx.numpy_helper.from_array(W1q, "W1"),
        onnx.numpy_helper.from_array(W1s, "W1_scale"),
        onnx.numpy_helper.from_array(W1zp, "W1_zero_point"),
        _f32(W2f, "W2"),
    ]
    model = _model(body, initializer=inits, opset=21)
    model.opset_import.append(onnx.helper.make_opsetid("com.microsoft", 1))
    return model, {"W1f": W1f, "W1q": W1q, "W1s": W1s, "W1zp": W1zp, "W2f": W2f}


def _dqmm_importance_keep(W_q, W_s, W_zp, keep_count):
    w_dequant = (
        W_q.astype(np.float64) - W_zp.astype(np.float64)[None, :]
    ) * W_s.astype(np.float64)[None, :]
    importance = np.linalg.norm(w_dequant, axis=0)  # per output channel
    return np.sort(np.argsort(-importance, kind="stable")[:keep_count])


def test_dynamic_quantize_matmul_chain_is_matched_and_prunes():
    K, N1, N2 = 16, 24, 12
    model, _info = _dqmm_chain_model(K, N1, N2, per_channel=True, seed=1)
    onnx.checker.check_model(model)
    chains = onnxsim.pruning._find_dynquant_chains(model.graph)
    assert len(chains) == 1
    assert chains[0].n_channels == N1

    pruned = onnxsim.apply_structured_pruning_dynamic_quantize_matmul(
        model, sparsity=0.5
    )
    onnx.checker.check_model(pruned)
    inits = {t.name: t for t in pruned.graph.initializer}
    assert list(inits["W1"].dims) == [K, N1 // 2]
    assert list(inits["W1_scale"].dims) == [N1 // 2]
    assert list(inits["W1_zero_point"].dims) == [N1 // 2]
    assert list(inits["W2"].dims) == [N1 // 2, N2]


def test_dynamic_quantize_matmul_producer_matches_independently_requantized_subset():
    # The core correctness invariant this project's earlier rounds
    # established: a pruned model's output must match a reference built by
    # quantizing the already-column-subset weight directly via the REAL
    # quantizer -- NOT the full unpruned model's own output. Per-channel
    # quantization is column-independent (confirmed empirically, see this
    # module's own section comment), so slicing the original quantized
    # codes and independently re-quantizing the float subset are
    # byte-identical -- this test checks both.
    K, N1, N2 = 16, 24, 12
    model, info = _dqmm_chain_model(K, N1, N2, per_channel=True, seed=2)
    keep = _dqmm_importance_keep(info["W1q"], info["W1s"], info["W1zp"], N1 // 2)

    pruned = onnxsim.apply_structured_pruning_dynamic_quantize_matmul(
        model, sparsity=0.5
    )
    onnx.checker.check_model(pruned)
    inits = {t.name: t for t in pruned.graph.initializer}

    # "slice, don't recompute": the pruned graph's own quantized codes/
    # scale/zero_point are EXACTLY a hand-slice of the original ones.
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["W1"]), info["W1q"][:, keep]
    )
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["W1_scale"]), info["W1s"][keep]
    )
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["W1_zero_point"]), info["W1zp"][keep]
    )
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["W2"]), info["W2q"][keep, :]
    )

    # Independently reconstructed "already pruned" reference model: the
    # PRODUCER's kept-column weight is quantized FRESH via the real
    # quantizer (per-channel quantization is column-independent, confirmed
    # byte-identical to slicing above). The CONSUMER's own weight is NEVER
    # requantized here -- a fresh quantization of a *row*-sliced weight
    # would generally compute a DIFFERENT per-column scale than the
    # original (each column's own scale is an aggregate over exactly the
    # rows being sliced), so, mirroring the QOperator family's own
    # identical oracle-construction pattern
    # (`test_qlinearconv_producer_matches_independent_oracle_via_real_inference_session`),
    # the consumer's own quantized CODES are sliced directly and its
    # scale/zero-point copied UNCHANGED from the original -- exactly what
    # the consumer role itself does (see this module's own section
    # comment: the consumer role never touches scale/zero-point at all).
    ref_model, _ = _dqmm_model_from_weights(
        K,
        len(keep),
        N2,
        info["W1f"][:, keep],
        info["W2f"][keep, :],  # shape placeholder only -- overwritten below
        per_channel=True,
        seed=987654,
    )
    ref_inits = {t.name: t for t in ref_model.graph.initializer}
    ref_inits["W2"].CopyFrom(onnx.numpy_helper.from_array(info["W2q"][keep, :], "W2"))
    ref_inits["W2_scale"].CopyFrom(
        onnx.numpy_helper.from_array(info["W2s"], "W2_scale")
    )
    ref_inits["W2_zero_point"].CopyFrom(
        onnx.numpy_helper.from_array(info["W2zp"], "W2_zero_point")
    )

    rng = np.random.default_rng(11)
    x = rng.standard_normal((1, K)).astype(np.float32)
    (y_pruned,) = _run(pruned, {"X": x})
    (y_ref,) = _run(ref_model, {"X": x})
    np.testing.assert_array_equal(y_pruned, y_ref)


# --- DynamicQuantizeMatMul: mid-chain LayerNorm/RMSNorm pass-through -------
#
# Regression coverage for the gap the task that added this section closed:
# `_walk_to_dynquant_consumer` previously recognized only
# `_UNARY_PASS_THROUGH` activations as a mid-chain hop, never a
# `_NORM_PASS_THROUGH_OPS` node -- so a real
# ``DynamicQuantizeMatMul(W1) -> LayerNormalization -> DynamicQuantizeMatMul(W2)``
# block (the single most common pre-LN transformer sub-block shape, now
# quantized) was silently left completely unpruned: `_find_dynquant_chains`
# returned zero chains for it. Mirrors `_walk_to_consumer`'s own established
# norm-hop tests (see this file's own "mid-chain LayerNorm/RMSNorm
# pass-through" section far above) but through a genuinely quantized
# producer/consumer pair, weights quantized via the real `quantize_dynamic`
# tool exactly like every other test in this section.


def _dqmm_norm_model_from_weights(
    K, N1, N2, W1f, W2f, norm_op, gamma, beta=None, per_channel=True, axis=-1
):
    """Builds ``DynamicQuantizeMatMul(mm1) -> norm_op(Gamma[, Beta]) ->
    DynamicQuantizeMatMul(mm2)`` -- the norm-pass-through chain shape --
    from explicit float weights, quantized via the real tool
    (:func:`_quantize_dynamic_weight`). Mirrors
    :func:`_dqmm_model_from_weights` exactly, just with a mid-chain norm
    node (`LayerNormalization`/`SimplifiedLayerNormalization`) standing in
    for the plain activation.
    """
    W1q, W1s, W1zp = _quantize_dynamic_weight(W1f, per_channel)
    W2q, W2s, W2zp = _quantize_dynamic_weight(W2f, per_channel)

    if beta is None:
        norm_call = f"{norm_op}<axis={axis}>(h1, Gamma)"
        norm_inits = [_f32(gamma, "Gamma")]
    else:
        norm_call = f"{norm_op}<axis={axis}>(h1, Gamma, Beta)"
        norm_inits = [_f32(gamma, "Gamma"), _f32(beta, "Beta")]

    body = f"""
    g (float[1,{K}] X) => (float[1,{N2}] Y)
    {{
      h1 = com.microsoft.DynamicQuantizeMatMul(X, W1, W1_scale, W1_zero_point)
      h1n = {norm_call}
      Y = com.microsoft.DynamicQuantizeMatMul(h1n, W2, W2_scale, W2_zero_point)
    }}
    """
    inits = [
        onnx.numpy_helper.from_array(W1q, "W1"),
        onnx.numpy_helper.from_array(W1s, "W1_scale"),
        onnx.numpy_helper.from_array(W1zp, "W1_zero_point"),
        *norm_inits,
        onnx.numpy_helper.from_array(W2q, "W2"),
        onnx.numpy_helper.from_array(W2s, "W2_scale"),
        onnx.numpy_helper.from_array(W2zp, "W2_zero_point"),
    ]
    model = _model(body, initializer=inits, opset=21)
    model.opset_import.append(onnx.helper.make_opsetid("com.microsoft", 1))
    return model, {
        "W1f": W1f,
        "W2f": W2f,
        "gamma": gamma,
        "beta": beta,
        "W1q": W1q,
        "W1s": W1s,
        "W1zp": W1zp,
        "W2q": W2q,
        "W2s": W2s,
        "W2zp": W2zp,
    }


def test_dynamic_quantize_matmul_layer_norm_pass_through_is_matched_and_prunes():
    K, N1, N2 = 16, 24, 12
    rng = np.random.default_rng(41)
    W1f = (rng.standard_normal((K, N1)) * 0.3).astype(np.float32)
    W2f = (rng.standard_normal((N1, N2)) * 0.3).astype(np.float32)
    gamma = (rng.standard_normal(N1) * 0.5 + 1.0).astype(np.float32)
    beta = (rng.standard_normal(N1) * 0.1).astype(np.float32)
    model, info = _dqmm_norm_model_from_weights(
        K, N1, N2, W1f, W2f, "LayerNormalization", gamma, beta, per_channel=True
    )
    onnx.checker.check_model(model)

    # Before this section's own fix, this returned 0 chains (the confirmed
    # bug this task closes) -- a norm node mid-chain silently defeated the
    # walk entirely.
    chains = onnxsim.pruning._find_dynquant_chains(model.graph)
    assert len(chains) == 1
    assert chains[0].n_channels == N1

    pruned = onnxsim.apply_structured_pruning_dynamic_quantize_matmul(
        model, sparsity=0.5
    )
    onnx.checker.check_model(pruned)
    keep_count = N1 - round(N1 * 0.5)
    keep = _dqmm_importance_keep(info["W1q"], info["W1s"], info["W1zp"], keep_count)

    inits = {t.name: t for t in pruned.graph.initializer}
    assert list(inits["W1"].dims) == [K, keep_count]
    assert list(inits["Gamma"].dims) == [keep_count]
    assert list(inits["Beta"].dims) == [keep_count]
    assert list(inits["W2"].dims) == [keep_count, N2]
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["Gamma"]), gamma[keep]
    )
    np.testing.assert_array_equal(onnx.numpy_helper.to_array(inits["Beta"]), beta[keep])

    # Independently reconstructed "already pruned" reference model, the same
    # pattern this section's own oracle test above uses: the producer's
    # kept-column weight is quantized FRESH via the real quantizer
    # (per-channel quantization is column-independent, so this is
    # byte-identical to slicing); the consumer's own codes are sliced
    # directly and its scale/zero-point copied UNCHANGED.
    ref_model, _ = _dqmm_norm_model_from_weights(
        K,
        keep_count,
        N2,
        W1f[:, keep],
        W2f[keep, :],  # shape placeholder only -- overwritten below
        "LayerNormalization",
        gamma[keep],
        beta[keep],
        per_channel=True,
    )
    ref_inits = {t.name: t for t in ref_model.graph.initializer}
    ref_inits["W2"].CopyFrom(onnx.numpy_helper.from_array(info["W2q"][keep, :], "W2"))
    ref_inits["W2_scale"].CopyFrom(
        onnx.numpy_helper.from_array(info["W2s"], "W2_scale")
    )
    ref_inits["W2_zero_point"].CopyFrom(
        onnx.numpy_helper.from_array(info["W2zp"], "W2_zero_point")
    )

    rng2 = np.random.default_rng(42)
    x = rng2.standard_normal((1, K)).astype(np.float32)
    (y_pruned,) = _run(pruned, {"X": x})
    (y_ref,) = _run(ref_model, {"X": x})
    np.testing.assert_array_equal(y_pruned, y_ref)


def test_dynamic_quantize_matmul_rms_norm_pass_through_is_matched_and_prunes():
    # `SimplifiedLayerNormalization` -- onnxruntime's own RMSNorm-equivalent
    # fused op, registered under the *default* ONNX domain (see this file's
    # own "mid-chain LayerNorm/RMSNorm pass-through" section comment far
    # above) -- has no `bias`/`Beta` input at all, unlike `LayerNormalization`.
    # `onnx.checker`'s own schema database doesn't know this op under the
    # default domain at all (an onnxruntime-only registration, not a plain-
    # ONNX one -- see `test_structured_pruning_simplified_layer_norm_pass_through_matches_oracle`'s
    # own identical note), so `onnx.checker.check_model` is skipped here;
    # onnxruntime itself still runs it fine, which the oracle comparison
    # below actually exercises.
    K, N1, N2 = 16, 24, 12
    rng = np.random.default_rng(43)
    W1f = (rng.standard_normal((K, N1)) * 0.3).astype(np.float32)
    W2f = (rng.standard_normal((N1, N2)) * 0.3).astype(np.float32)
    gamma = (rng.standard_normal(N1) * 0.5 + 1.0).astype(np.float32)
    model, info = _dqmm_norm_model_from_weights(
        K,
        N1,
        N2,
        W1f,
        W2f,
        "SimplifiedLayerNormalization",
        gamma,
        beta=None,
        per_channel=True,
    )

    chains = onnxsim.pruning._find_dynquant_chains(model.graph)
    assert len(chains) == 1
    assert chains[0].n_channels == N1

    pruned = onnxsim.apply_structured_pruning_dynamic_quantize_matmul(
        model, sparsity=0.5
    )
    keep_count = N1 - round(N1 * 0.5)
    keep = _dqmm_importance_keep(info["W1q"], info["W1s"], info["W1zp"], keep_count)

    inits = {t.name: t for t in pruned.graph.initializer}
    assert list(inits["W1"].dims) == [K, keep_count]
    assert list(inits["Gamma"].dims) == [keep_count]
    assert list(inits["W2"].dims) == [keep_count, N2]
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["Gamma"]), gamma[keep]
    )

    ref_model, _ = _dqmm_norm_model_from_weights(
        K,
        keep_count,
        N2,
        W1f[:, keep],
        W2f[keep, :],  # shape placeholder only -- overwritten below
        "SimplifiedLayerNormalization",
        gamma[keep],
        beta=None,
        per_channel=True,
    )
    ref_inits = {t.name: t for t in ref_model.graph.initializer}
    ref_inits["W2"].CopyFrom(onnx.numpy_helper.from_array(info["W2q"][keep, :], "W2"))
    ref_inits["W2_scale"].CopyFrom(
        onnx.numpy_helper.from_array(info["W2s"], "W2_scale")
    )
    ref_inits["W2_zero_point"].CopyFrom(
        onnx.numpy_helper.from_array(info["W2zp"], "W2_zero_point")
    )

    rng2 = np.random.default_rng(44)
    x = rng2.standard_normal((1, K)).astype(np.float32)
    (y_pruned,) = _run(pruned, {"X": x})
    (y_ref,) = _run(ref_model, {"X": x})
    np.testing.assert_array_equal(y_pruned, y_ref)


def test_dynamic_quantize_matmul_per_tensor_scale_left_untouched():
    K, N1, N2 = 16, 24, 12
    model, _info = _dqmm_chain_model(K, N1, N2, per_channel=False, seed=3)
    onnx.checker.check_model(model)
    pruned = onnxsim.apply_structured_pruning_dynamic_quantize_matmul(
        model, sparsity=0.5
    )
    onnx.checker.check_model(pruned)
    inits = {t.name: t for t in pruned.graph.initializer}
    # per-tensor scale/zero-point are scalars -- never sliced, regardless
    # of channel count
    assert list(inits["W1_scale"].dims) == []
    assert list(inits["W1_zero_point"].dims) == []
    assert list(inits["W1"].dims) == [K, N1 // 2]


def test_dynamic_quantize_matmul_per_tensor_reuses_original_scale_not_a_resampled_one():
    # For a per-tensor (scalar) scale, "slice, don't recompute" means the
    # pruned model must reuse the ORIGINAL, full-weight scale/zero-point --
    # NOT a scale independently re-derived from just the kept columns. This
    # is a real, confirmed distinction (unlike the per-channel case just
    # above): a per-tensor scale is a function of the WHOLE weight's
    # absmax, so re-quantizing a column subset from scratch gives a
    # genuinely DIFFERENT scale whenever the dropped columns held the
    # tensor's own max magnitude.
    #
    # Forced deliberately below: column 0 holds a single K=64-row spike
    # (one entry 8.0, the rest ~0) -- large enough to set the WHOLE
    # tensor's per-tensor absmax to 8.0, but, spread over only one row out
    # of 64, still a smaller L2 NORM (~8.0) than the other 7 columns (each
    # filled with a moderate ~2.0 magnitude across all 64 rows, L2 norm
    # ~16.0) -- so column 0 is this pass's own least-important, first-
    # dropped column, while still being the one that set the original
    # scale.
    K, N1, N2 = 64, 8, 4
    rng = np.random.default_rng(4)
    W1f = (
        rng.uniform(1.8, 2.2, size=(K, N1)) * rng.choice([-1, 1], size=(K, N1))
    ).astype(np.float32)
    W1f[:, 0] = 0.0
    W1f[0, 0] = 8.0  # dominates the full tensor's absmax
    W2f = (rng.standard_normal((N1, N2)) * 0.3).astype(np.float32)

    model, info = _dqmm_model_from_weights(K, N1, N2, W1f, W2f, per_channel=False)
    keep = _dqmm_importance_keep(
        info["W1q"], np.atleast_1d(info["W1s"]), np.atleast_1d(info["W1zp"]), N1 // 2
    )
    assert 0 not in keep  # confirms column 0 is indeed dropped

    # An independently fresh-requantized subset gives a DIFFERENT scale --
    # confirming this isn't a vacuous check.
    _, W1s_resampled, _ = _quantize_dynamic_weight(W1f[:, keep], per_channel=False)
    assert float(W1s_resampled) != pytest.approx(float(info["W1s"]))

    pruned = onnxsim.apply_structured_pruning_dynamic_quantize_matmul(
        model, sparsity=0.5
    )
    onnx.checker.check_model(pruned)
    inits = {t.name: t for t in pruned.graph.initializer}
    # the ORIGINAL scale/zero-point survive untouched, not a resampled one.
    assert onnx.numpy_helper.to_array(inits["W1_scale"]) == pytest.approx(
        float(info["W1s"])
    )
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["W1"]), info["W1q"][:, keep]
    )

    rng2 = np.random.default_rng(12)
    x = rng2.standard_normal((1, K)).astype(np.float32)
    (y_pruned,) = _run(pruned, {"X": x})
    assert y_pruned.shape == (1, N2)
    assert np.all(np.isfinite(y_pruned))


def test_dynamic_quantize_matmul_bias_is_sliced_as_plain_float():
    K, N1, N2 = 16, 24, 12
    model, info = _dqmm_chain_model(K, N1, N2, per_channel=True, bias1=True, seed=8)
    onnx.checker.check_model(model)
    keep = _dqmm_importance_keep(info["W1q"], info["W1s"], info["W1zp"], N1 // 2)

    pruned = onnxsim.apply_structured_pruning_dynamic_quantize_matmul(
        model, sparsity=0.5
    )
    onnx.checker.check_model(pruned)
    inits = {t.name: t for t in pruned.graph.initializer}
    assert inits["B1"].data_type == onnx.TensorProto.FLOAT
    assert list(inits["B1"].dims) == [N1 // 2]
    # bias values are UNCHANGED (plain float, never quantized/rescaled) --
    # unlike QGemm/QLinearConv's own quantized int32 bias.
    np.testing.assert_array_equal(
        onnx.numpy_helper.to_array(inits["B1"]), info["B1f"][keep]
    )


